export const CostPanel: React.FC = () => {
    const { t } = useTranslation();
    const [inputRate, setInputRate] = useState(0.10); // Default $0.10 / 1M tokens (Gemini 2.5 Flash approx)
    const [outputRate, setOutputRate] = useState(0.40); // Default $0.40 / 1M tokens
    const [analyses, setAnalyses] = useState<Analysis[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isUpdating, setIsUpdating] = useState(false);

    const loadData = async () => {
        setIsLoading(true);
        const savedInput = await getSetting('inputTokenRate', 0.10);
        const savedOutput = await getSetting('outputTokenRate', 0.40);
        setInputRate(savedInput);
        setOutputRate(savedOutput);

        const allAnalyses = await getAnalyses();
        setAnalyses(allAnalyses);
        setIsLoading(false);
    };

    useEffect(() => {
        loadData();
    }, []);

    const handleSaveAndRecalculate = async () => {
        setIsUpdating(true);
        await setSetting('inputTokenRate', inputRate);
        await setSetting('outputTokenRate', outputRate);
        await recalculateAllCosts(inputRate, outputRate);
        const updatedAnalyses = await getAnalyses();
        setAnalyses(updatedAnalyses);
        setIsUpdating(false);
        alert(t('costsRecalculated'));
    };

    const totals = React.useMemo(() => {
        return analyses.reduce((acc, a) => {
            if (a.costInfo) {
                acc.input += a.costInfo.inputTokens;
                acc.output += a.costInfo.outputTokens;
                acc.cost += a.costInfo.cost;
            }
            return acc;
        }, { input: 0, output: 0, cost: 0 });
    }, [analyses]);

    if (isLoading) {
        return (
            <div className="flex justify-center items-center h-full">
                <SpinnerIcon className="w-12 h-12 text-lime-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-6xl mx-auto">
            {/* Header & Configuration */}
            <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2 mb-6">
                    <CalculatorIcon className="w-6 h-6 text-lime-600" />
                    {t('costs')}
                </h2>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-end">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t('inputTokenRate')} ($ / 1M)</label>
                        <input 
                            type="number" 
                            step="0.01"
                            className="block w-full rounded-md border-gray-300 shadow-sm focus:border-lime-500 focus:ring-lime-500 sm:text-sm"
                            value={inputRate}
                            onChange={e => setInputRate(parseFloat(e.target.value))}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t('outputTokenRate')} ($ / 1M)</label>
                        <input 
                            type="number" 
                            step="0.01"
                            className="block w-full rounded-md border-gray-300 shadow-sm focus:border-lime-500 focus:ring-lime-500 sm:text-sm"
                            value={outputRate}
                            onChange={e => setOutputRate(parseFloat(e.target.value))}
                        />
                    </div>
                    <button 
                        onClick={handleSaveAndRecalculate}
                        disabled={isUpdating}
                        className="flex items-center justify-center gap-2 px-4 py-2 bg-lime-600 text-white rounded-md hover:bg-lime-700 font-semibold transition-colors disabled:bg-gray-400"
                    >
                        {isUpdating ? <SpinnerIcon className="w-4 h-4" /> : <ArrowPathIcon className="w-4 h-4" />}
                        {t('saveAndRecalculate')}
                    </button>
                </div>
            </div>

            {/* Stats Dashboard */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 text-center">
                    <div className="bg-blue-50 w-10 h-10 rounded-full flex items-center justify-center mx-auto mb-3">
                        <CircleStackIcon className="w-5 h-5 text-blue-600" />
                    </div>
                    <p className="text-2xl font-bold text-gray-900">{totals.input.toLocaleString()}</p>
                    <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('totalInputTokens')}</p>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 text-center">
                    <div className="bg-purple-50 w-10 h-10 rounded-full flex items-center justify-center mx-auto mb-3">
                        <CircleStackIcon className="w-5 h-5 text-purple-600" />
                    </div>
                    <p className="text-2xl font-bold text-gray-900">{totals.output.toLocaleString()}</p>
                    <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('totalOutputTokens')}</p>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 text-center border-b-4 border-b-lime-500">
                    <div className="bg-lime-50 w-10 h-10 rounded-full flex items-center justify-center mx-auto mb-3">
                        <TagIcon className="w-5 h-5 text-lime-600" />
                    </div>
                    <p className="text-2xl font-bold text-lime-600">${totals.cost.toFixed(4)}</p>
                    <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('totalInvested')}</p>
                </div>
            </div>

            {/* History Table */}
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
                <div className="p-4 border-b border-gray-100 bg-gray-50 flex justify-between items-center">
                    <h3 className="font-bold text-gray-800">{t('analysisHistory')}</h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t('date')}</th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">{t('analysisName')}</th>
