export const bulkUpdateCatalogEntries = async (ids: number[], changes: Partial<ProductCatalogEntry>): Promise<number> => {
    return await (db as any).transaction('rw', db.product_catalog, async () => {
        let updatedCount = 0;
        for (const id of ids) {
            const result = await db.product_catalog.update(id, changes);
            updatedCount += result;
        }
        return updatedCount;
    });
};

export const bulkDeleteCatalogEntries = async (ids: number[]): Promise<void> => {
    await db.product_catalog.bulkDelete(ids);
};

export const searchAnalyses = async (term: string): Promise<SearchResult[]> => {
    if (!term || term.trim().length < 2) return [];
    const results = await db.analyses.filter(a => a.name.toLowerCase().includes(term.toLowerCase())).toArray();
    return results.map(a => ({ analysis: a, matches: [{ type: 'analysis_name', context: a.name }] }));
};

export const findProductByAlias = async (name: string): Promise<ProductCatalogEntry | undefined> => {
    return await db.product_catalog.where('canonicalName').equals(name).or('aliases').equals(name).first();
};

export const addOrUpdateProductCorrection = async (originalName: string, newName: string): Promise<void> => {
    const entry = await findProductByAlias(newName);
    if (entry) {
        if (!entry.aliases.includes(originalName)) {
            entry.aliases.push(originalName);
            await db.product_catalog.put(entry);
        }
    } else {
        await db.product_catalog.add({ canonicalName: newName, aliases: [originalName] });
    }
};

export const populateCatalogFromAnalysis = async (analysis: { images: any[] }): Promise<void> => {
    for (const image of analysis.images) {
        if (image.analysisResult?.products) {
            for (const p of image.analysisResult.products) {
                const existing = await findProductByAlias(p.name);
                if (!existing) {
                    await db.product_catalog.add({ canonicalName: p.name, aliases: [], manufacturer: p.brand });
                }
            }
        }
    }
};

