import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n';
import type { BrandClassifications } from '../types';
import { CloseIcon, CheckCircleIcon, SearchIcon, UsersIcon, UserCircleIcon } from './Icons';
import { getBrandMemory, saveBrandClassification } from '../db';

interface BrandDefinitionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (classifications: BrandClassifications) => void;
  allBrands: string[];
}

export const BrandDefinitionModal: React.FC<BrandDefinitionModalProps> = ({ isOpen, onClose, onConfirm, allBrands }) => {
  const { t } = useTranslation();
  const [selectedOurBrands, setSelectedOurBrands] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (isOpen) {
        const initialize = async () => {
            const memory = await getBrandMemory();
            const knownOur = memory
                .filter(m => m.classification === 'our')
                .map(m => m.brand);

            // Len tie z aktuálne detegovaných, ktoré sú v pamäti ako "naše"
            const initialOur = new Set<string>();
            allBrands.forEach(brand => {
                if (knownOur.includes(brand)) {
                    initialOur.add(brand);
                }
            });

            setSelectedOurBrands(initialOur);
        };
        initialize();
    }
  }, [isOpen, allBrands]);

  const filteredBrands = useMemo(() => {
    return allBrands.filter(b => b.toLowerCase().includes(searchTerm.toLowerCase())).sort();
  }, [allBrands, searchTerm]);

  const toggleBrand = (brand: string) => {
    setSelectedOurBrands(prev => {
        const next = new Set(prev);
        if (next.has(brand)) next.delete(brand);
        else next.add(brand);
        return next;
    });
  };

  const handleConfirm = async () => {
    const ourBrandsList = Array.from(selectedOurBrands);
    const competitorBrandsList = allBrands.filter(b => !selectedOurBrands.has(b));

    // Uložiť do pamäte
    for (const brand of allBrands) {
        const classification = selectedOurBrands.has(brand) ? 'our' : 'competitor';
        await saveBrandClassification(brand, classification);
    }

    onConfirm({ ourBrands: ourBrandsList, competitorBrands: competitorBrandsList });
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-gray-900 bg-opacity-75 flex items-center justify-center z-50 p-4 animate-fade-in" role="dialog" aria-modal="true">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl transform transition-all max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-6 border-b border-gray-100 flex justify-between items-start bg-gray-50">
          <div>
            <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                <UsersIcon className="w-6 h-6 text-lime-600" />
                {t('defineBrandsTitle')}
            </h2>
            <p className="text-sm text-gray-500 mt-1">{t('defineBrandsDescription')}</p>
          </div>
          <button onClick={onClose} className="p-2 rounded-full text-gray-400 hover:bg-gray-200 hover:text-gray-600 transition-colors" aria-label={t('close')}>
            <CloseIcon className="w-5 h-5" />
          </button>
        </div>

        {/* Search Bar */}
        <div className="px-6 py-4 border-b border-gray-50">
            <div className="relative">
                <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input 
                    type="text"
                    placeholder={t('searchBrand')}
                    className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-xl text-sm focus:ring-2 focus:ring-lime-500"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
        </div>

        {/* Brand Grid */}
        <div className="p-6 flex-grow overflow-y-auto bg-white">
            {filteredBrands.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                    {filteredBrands.map(brand => {
                        const isOur = selectedOurBrands.has(brand);
                        return (
                            <button
                                key={brand}
                                onClick={() => toggleBrand(brand)}
                                className={`group relative p-4 rounded-2xl border-2 transition-all duration-200 text-left flex flex-col justify-between h-24 ${
                                    isOur 
                                    ? 'border-lime-500 bg-lime-50 shadow-md ring-1 ring-lime-500' 
                                    : 'border-gray-100 bg-gray-50 hover:border-gray-300 hover:bg-white'
                                }`}
                            >
                                <div className="flex justify-between items-start">
                                    <div className={`p-1.5 rounded-lg ${isOur ? 'bg-lime-500 text-white' : 'bg-gray-200 text-gray-400'}`}>
                                        <UserCircleIcon className="w-4 h-4" />
                                    </div>
                                    {isOur && <CheckCircleIcon className="w-5 h-5 text-lime-600" />}
                                </div>
                                <span className={`text-sm font-bold truncate mt-2 ${isOur ? 'text-lime-900' : 'text-gray-700'}`}>
                                    {brand}
                                </span>
                                <span className={`text-[10px] uppercase tracking-wider font-bold ${isOur ? 'text-lime-600' : 'text-gray-400'}`}>
                                    {isOur ? t('ourBrands') : t('competitorBrands')}
                                </span>
                            </button>
                        );
                    })}
                </div>
            ) : (
                <div className="text-center py-20">
                    <p className="text-gray-400 italic">{t('noResultsFound')}</p>
                </div>
            )}
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-gray-100 bg-gray-50 flex flex-col sm:flex-row justify-between items-center gap-4">
          <div className="text-sm font-medium text-gray-500">
             {t('selectedItems', { count: selectedOurBrands.size })} {t('ourBrands').toLowerCase()}
          </div>
          <div className="flex gap-3 w-full sm:w-auto">
            <button
                onClick={() => { setSelectedOurBrands(new Set()); }}
                className="flex-1 sm:flex-none px-6 py-2.5 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-xl transition-colors"
