function extractFirstJson(text: string): string {
    const markdownMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    let cleanText = text;
    if (markdownMatch && markdownMatch[1]) {
        cleanText = markdownMatch[1].trim();
    }

    const firstBrace = cleanText.indexOf('{');
    const firstBracket = cleanText.indexOf('[');
    let startIndex = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIndex = firstBrace;
    } else if (firstBracket !== -1) {
        startIndex = firstBracket;
    } else {
        throw new Error("No JSON object or array found in the response text.");
    }

    const stack: string[] = [];
    let inString = false;
    let isEscaped = false;
    let lastSafeIndex = -1;

    for (let i = startIndex; i < cleanText.length; i++) {
        const char = cleanText[i];

        if (inString) {
            if (isEscaped) {
                isEscaped = false;
            } else if (char === '\\') {
                isEscaped = true;
            } else if (char === '"') {
                inString = false;
            }
        } else {
            if (char === '"') {
                inString = true;
            } else if (char === '{' || char === '[') {
                stack.push(char);
            } else if (char === '}' || char === ']') {
                const expected = char === '}' ? '{' : '[';
                if (stack.length > 0 && stack[stack.length - 1] === expected) {
                    stack.pop();
                    if (char === '}' && stack.length > 0 && stack[stack.length - 1] === '[') {
                        lastSafeIndex = i;
                    }
                    if (char === ']' && stack.length > 0 && stack[stack.length - 1] === '{') {
                        lastSafeIndex = i;
                    }
                }
            }
        }

        if (!inString && stack.length === 0) {
             return cleanText.substring(startIndex, i + 1);
        }
    }

    if (lastSafeIndex !== -1) {
        let repaired = cleanText.substring(startIndex, lastSafeIndex + 1);
        const repairStack: string[] = [];
        let repairInString = false;
        let repairEscaped = false;
        for (let j = 0; j < repaired.length; j++) {
             const c = repaired[j];
             if (repairInString) {
                 if (repairEscaped) repairEscaped = false;
                 else if (c === '\\') repairEscaped = true;
                 else if (c === '"') repairInString = false;
             } else {
                 if (c === '"') repairInString = true;
                 else if (c === '{' || c === '[') repairStack.push(c);
                 else if (c === '}' || c === ']') repairStack.pop();
             }
        }
        while (repairStack.length > 0) {
            const type = repairStack.pop();
            if (type === '{') repaired += '}';
            if (type === '[') repaired += ']';
        }
        return repaired;
    }
    throw new Error("Unrepairable JSON truncation.");
}

function parseMinifiedPriceString(priceString: string | undefined): PriceInfo[] {
  if (!priceString) return [];
  const prices: PriceInfo[] = [];
  const parts = priceString.split(';');

  parts.forEach(part => {
    const trimmedPart = part.trim();
    if (trimmedPart) {
      const match = trimmedPart.match(/([\d.,]+)\s*([RP€])/i);
      if (match) {
        const value = match[1];
        const type = match[2].toUpperCase() === 'P' ? 'PROMO' : 'REGULAR';
        prices.push({ value, type });
      }
    }
  });
  return prices;
}

function parseMinifiedResponse(minifiedResponse: any): AnalysisResult {
  const products: DetectedProduct[] = [];
  const storeInfo: StoreInfo = {};

  if (minifiedResponse.products && Array.isArray(minifiedResponse.products)) {
    minifiedResponse.products.forEach((group: any) => {
      const name = group.n;
      const confidence = group.c || 0.9;
      const prices = parseMinifiedPriceString(group.p);

      if (typeof group.b === 'string' && group.b) {
        const boxStrings = group.b.split('|');
        boxStrings.forEach((boxString: string) => {
          const coords = boxString.split(',').map(Number);
          if (coords.length === 4 && !coords.some(isNaN)) {
            const ymin = coords[0] / 1000.0;
            const xmin = coords[1] / 1000.0;
            const ymax = coords[2] / 1000.0;
            const xmax = coords[3] / 1000.0;
            const y = ymin;
            const x = xmin;
            const height = ymax - ymin;
            const width = xmax - xmin;

            const brandMatch = name.match(/^(\S+)/);
            const brand = brandMatch ? brandMatch[1] : '';

            products.push({
              id: `${name}-${Math.random().toString(36).substring(7)}`,
              name,
              brand,
              prices,
              boundingBox: { x, y, width, height },
              confidence,
            });
          }
        });
      }
    });
  }

  if (minifiedResponse.info) {
    if (minifiedResponse.info.chn) storeInfo.chain = minifiedResponse.info.chn;
    if (minifiedResponse.info.adr) storeInfo.address = minifiedResponse.info.adr;
  }

  return { products, storeInfo, modelName: MODEL_NAME };
}


export async function analyzeImageWithGemini(
  base64Image: string, 
  defaultPromptText: string, 
  defaultSystemInstruction: string,
  category: 'price' | 'shelfShare' | 'both' = 'both'
): Promise<AnalysisResult> {
  const MAX_RETRIES = 3;
  let lastError: any;

  // Attempt to load dynamic prompts from DB
  const dynamicSystem = await getActivePrompt('system');
  const dynamicUser = await getActivePrompt(category);

  const effectiveSystem = dynamicSystem?.text || defaultSystemInstruction;
  const effectiveUser = dynamicUser?.text || defaultPromptText;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const contents: Part[] = [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: effectiveUser }
      ];

      const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: { parts: contents },
        config: {
          systemInstruction: effectiveSystem,
          responseMimeType: 'application/json',
          responseSchema: productSchema,
          temperature: 0.1,
          maxOutputTokens: 8192,
          thinkingConfig: { thinkingBudget: 1024 },
        },
      });

      const rawText = response.text;
      if (!rawText) throw new Error("No response text received from AI.");

      const lowerText = rawText.toLowerCase();
      if (lowerText.includes("503") || lowerText.includes("overloaded") || lowerText.includes("unavailable")) {
          throw new Error("The model is overloaded. Please try again later.");
      }

      try {
        const jsonString = extractFirstJson(rawText.trim());
        const parsedJson = JSON.parse(jsonString);

        if (parsedJson.error) {
            throw new Error(`API Error: ${parsedJson.error.message || JSON.stringify(parsedJson.error)}`);
        }

        const result: AnalysisResult = parseMinifiedResponse(parsedJson);
        const usageMetadata = response.usageMetadata;
        if (usageMetadata) {
            result.usageMetadata = {
                promptTokenCount: usageMetadata.promptTokenCount || 0,
                candidatesTokenCount: usageMetadata.candidatesTokenCount || 0,
                totalTokenCount: usageMetadata.totalTokenCount || 0,
            };
        }

        return result;
      } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Invalid response format from API.");
      }
    } catch (e: any) {
        lastError = e;
        const msg = e.message?.toLowerCase() || '';
        const isRetryable = msg.includes("503") || msg.includes("overloaded") || msg.includes("unavailable") || msg.includes("fetch failed");
        if (isRetryable && attempt < MAX_RETRIES) {
            await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, attempt - 1)));
            continue;
        }
        throw e;
    }
  }
  throw lastError;
}

export async function createVisualFingerprint(productName: string, base64Images: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const imageParts = base64Images.map(img => ({ inlineData: { data: img, mimeType: 'image/jpeg' } }));
    const prompt = `Analyze images of "${productName}". Create a concise "Visual Fingerprint" to help identification (Color, Shape, Distinctive Layouts). Single string output.`;
    const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: { parts: [...imageParts, { text: prompt }] },
        config: { temperature: 0.1, maxOutputTokens: 100 }
    });
    return response.text?.trim() || "";
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from '../i18n';
import { db, getPromptHistory, saveNewPromptVersion, setActivePromptVersion } from '../db';
import type { PromptTemplate } from '../types';
import { 
    SpinnerIcon, 
    SaveIcon, 
    HistoryIcon, 
    CheckCircleIcon, 
    TagIcon, 
    ChartPieIcon, 
    ClipboardDocumentListIcon, 
    CpuChipIcon,
    ArrowPathIcon,
    EditIcon
} from './Icons';

export const PromptManagerPanel: React.FC = () => {
    const { t } = useTranslation();
    const [category, setCategory] = useState<PromptTemplate['category']>('system');
    const [history, setHistory] = useState<PromptTemplate[]>([]);
    const [editingText, setEditingText] = useState('');
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    const loadHistory = async () => {
        setIsLoading(true);
        const data = await getPromptHistory(category);
        setHistory(data);

        // Ak existuje aktívny, nastavíme ho do editoru, inak najnovší
        const active = data.find(p => p.isActive) || data[0];
        setEditingText(active?.text || '');
        setIsLoading(false);
    };

    useEffect(() => {
        loadHistory();
    }, [category]);

    const handleSave = async () => {
        if (!editingText.trim()) return;
        setIsSaving(true);
        try {
            await saveNewPromptVersion(category, editingText.trim());
            await loadHistory();
        } finally {
            setIsSaving(false);
        }
    };

    const handleActivate = async (id: number) => {
        await setActivePromptVersion(id);
        await loadHistory();
    };

    const categories: { id: PromptTemplate['category'], label: string, icon: React.ElementType }[] = [
        { id: 'system', label: 'System Instruction', icon: CpuChipIcon },
        { id: 'price', label: 'OSP (Pricing)', icon: TagIcon },
        { id: 'shelfShare', label: 'SoS (Shelf Share)', icon: ChartPieIcon },
        { id: 'both', label: 'Complete Analysis', icon: ClipboardDocumentListIcon }
    ];

    if (isLoading && history.length === 0) {
        return (
            <div className="flex justify-center items-center h-64">
                <SpinnerIcon className="w-12 h-12 text-lime-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-6xl mx-auto pb-20">
            {/* Header */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-3">
                    <div className="bg-lime-100 p-2 rounded-lg">
                        <EditIcon className="w-6 h-6 text-lime-600" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">{t('promptManager')}</h2>
                        <p className="text-xs text-gray-500 uppercase tracking-wider font-bold">{t('promptManagerSubtitle')}</p>
                    </div>
                </div>

                <div className="flex bg-gray-100 p-1 rounded-xl w-full md:w-auto">
                    {categories.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => setCategory(cat.id)}
                            className={`flex-1 md:flex-none flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                                category === cat.id 
                                ? 'bg-white text-lime-700 shadow-sm ring-1 ring-black/5' 
                                : 'text-gray-500 hover:text-gray-700'
                            }`}
                        >
                            <cat.icon className="w-4 h-4" />
                            <span className="hidden sm:inline">{cat.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Editor */}
                <div className="lg:col-span-2 space-y-4">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[500px]">
                        <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                            <span className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                <EditIcon className="w-4 h-4" /> Editor
                            </span>
                            <div className="flex gap-2">
                                <button 
                                    onClick={loadHistory}
                                    className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-white transition-colors"
                                    title={t('reset')}
                                >
                                    <ArrowPathIcon className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={handleSave}
                                    disabled={isSaving || !editingText.trim()}
                                    className="flex items-center gap-2 bg-lime-600 text-white px-6 py-1.5 rounded-lg text-sm font-bold hover:bg-lime-500 shadow-md shadow-lime-100 disabled:bg-gray-300 transition-all"
                                >
                                    {isSaving ? <SpinnerIcon className="w-4 h-4" /> : <SaveIcon className="w-4 h-4" />}
                                    {t('saveAsNewVersion')}
                                </button>
                            </div>
                        </div>
                        <textarea
                            className="flex-grow p-6 font-mono text-sm bg-white text-gray-800 focus:ring-0 border-none resize-none"
                            value={editingText}
                            onChange={(e) => setEditingText(e.target.value)}
                            spellCheck={false}
                            placeholder="Vložte sem prompt pre Gemini..."
                        />
                    </div>
                </div>

                {/* History Sidebar */}
                <div className="space-y-4">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col h-[500px]">
                        <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center gap-2">
                            <HistoryIcon className="w-4 h-4 text-gray-500" />
                            <span className="text-sm font-bold text-gray-700">{t('versionHistory')}</span>
                        </div>
                        <div className="flex-grow overflow-y-auto p-4 space-y-3">
                            {history.length > 0 ? history.map((p) => (
                                <div 
                                    key={p.id} 
                                    className={`p-4 rounded-xl border-2 transition-all ${
                                        p.isActive 
                                        ? 'border-lime-500 bg-lime-50/50' 
                                        : 'border-gray-100 hover:border-gray-300'
                                    }`}
                                >
                                    <div className="flex justify-between items-start mb-2">
                                        <div>
                                            <span className={`text-[10px] uppercase font-black px-2 py-0.5 rounded-full ${p.isActive ? 'bg-lime-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
                                                v{p.version}
                                            </span>
                                            <p className="text-[10px] text-gray-400 mt-1">{new Date(p.createdAt).toLocaleString()}</p>
                                        </div>
                                        {p.isActive ? (
                                            <span className="text-lime-600 bg-lime-100 p-1 rounded-full">
                                                <CheckCircleIcon className="w-4 h-4" />
                                            </span>
                                        ) : (
                                            <button
                                                onClick={() => p.id && handleActivate(p.id)}
                                                className="text-[10px] font-bold text-gray-500 hover:text-lime-600 uppercase tracking-widest border border-gray-200 px-2 py-1 rounded-lg hover:border-lime-200"
                                            >
                                                {t('activate')}
                                            </button>
                                        )}
                                    </div>
                                    <p className="text-xs text-gray-600 line-clamp-3 italic">"{p.text}"</p>
                                    <button 
                                        onClick={() => setEditingText(p.text)}
                                        className="mt-2 text-[10px] text-blue-600 hover:underline font-bold"
                                    >
                                        {t('loadToEditor')}
                                    </button>
                                </div>
                            )) : (
                                <div className="text-center py-10">
                                    <p className="text-sm text-gray-400 italic">{t('noHistoryYet')}</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

