// --- Prompt Management ---

export const getActivePrompt = async (category: PromptTemplate['category']): Promise<PromptTemplate | undefined> => {
    return await db.prompts.where({ category, isActive: 1 }).first();
};

export const getPromptHistory = async (category: PromptTemplate['category']): Promise<PromptTemplate[]> => {
    return await db.prompts.where('category').equals(category).reverse().sortBy('version');
};

export const saveNewPromptVersion = async (category: PromptTemplate['category'], text: string): Promise<void> => {
    return await (db as any).transaction('rw', db.prompts, async () => {
        const lastVersion = await db.prompts.where('category').equals(category).reverse().sortBy('version');
        const nextVersion = lastVersion.length > 0 ? lastVersion[0].version + 1 : 1;

        // Deactivate all in this category
        await db.prompts.where('category').equals(category).modify({ isActive: false });

        await db.prompts.add({
            category,
            text,
            version: nextVersion,
            isActive: true,
            createdAt: new Date().toISOString()
        });
    });
};

export const setActivePromptVersion = async (id: number): Promise<void> => {
    return await (db as any).transaction('rw', db.prompts, async () => {
        const target = await db.prompts.get(id);
        if (!target) return;

        await db.prompts.where('category').equals(target.category).modify({ isActive: false });
        await db.prompts.update(id, { isActive: true });
    });
};

// --- Analyses ---

export const getAnalyses = (): Promise<Analysis[]> => db.analyses.orderBy('createdAt').reverse().toArray();

export const saveAnalysis = (analysis: Analysis): Promise<string> => {
    return (db as any).transaction('rw', db.analyses, db.search_index, db.product_catalog, async () => {
        const catalog = await db.product_catalog.toArray();
        await db.search_index.where('analysisId').equals(analysis.id).delete();
        const entries = createIndexEntriesForAnalysis(analysis, catalog);
        if (entries.length > 0) await db.search_index.bulkAdd(entries);
        return db.analyses.put(analysis);
    });
};

export const loadAnalysis = (id: string): Promise<Analysis | undefined> => db.analyses.get(id);

export const deleteAnalysis = (id: string): Promise<void> => {
    return (db as any).transaction('rw', db.analyses, db.search_index, async () => {
        await db.analyses.delete(id);
        await db.search_index.where('analysisId').equals(id).delete();
    });
};

export const renameAnalysis = (id: string, newName: string): Promise<number> => {
    return (db as any).transaction('rw', db.analyses, db.search_index, async () => {
        const updateCount = await db.analyses.update(id, { name: newName });
        if (updateCount > 0) {
            const existingEntry = await db.search_index.where({ analysisId: id, type: 'analysis_name' }).first();
            if (existingEntry) {
                 await db.search_index.update(existingEntry.id!, { contentTokens: tokenize(newName), context: newName });
            } else {
                 const newEntry: SearchIndexEntry = { analysisId: id, type: 'analysis_name', contentTokens: tokenize(newName), context: newName };
                 await db.search_index.add(newEntry);
            }
        }
        return updateCount;
    });
};

export const recalculateAllCosts = async (inputRate: number, outputRate: number): Promise<void> => {
    return (db as any).transaction('rw', db.analyses, async () => {
        const allAnalyses = await db.analyses.toArray();
        for (const analysis of allAnalyses) {
            let totalInput = 0;
            let totalOutput = 0;
            let modelName = analysis.costInfo?.modelName || '';

            analysis.images.forEach(img => {
                if (img.analysisResult?.usageMetadata) {
                    totalInput += img.analysisResult.usageMetadata.promptTokenCount || 0;
                    totalOutput += img.analysisResult.usageMetadata.candidatesTokenCount || 0;
                }
                if (!modelName && img.analysisResult?.modelName) {
                    modelName = img.analysisResult.modelName;
                }
            });

            if (totalInput > 0 || totalOutput > 0) {
                const cost = ((totalInput / 1000000) * inputRate) + ((totalOutput / 1000000) * outputRate);
                analysis.costInfo = {
                    inputTokens: totalInput,
                    outputTokens: totalOutput,
                    cost: cost,
                    modelName: modelName || 'gemini-2.5-flash' // fallback
                };
                await db.analyses.put(analysis);
            }
        }
    });
};

