} from './Icons';

export const PromptManagerPanel: React.FC = () => {
    const { t } = useTranslation();
    const [category, setCategory] = useState<PromptTemplate['category']>('system');
    const [history, setHistory] = useState<PromptTemplate[]>([]);
    const [editingText, setEditingText] = useState('');
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    const loadHistory = async () => {
        setIsLoading(true);
        const data = await getPromptHistory(category);
        setHistory(data);

        // Ak existuje aktívny, nastavíme ho do editoru, inak najnovší
        const active = data.find(p => p.isActive) || data[0];
        setEditingText(active?.text || '');
        setIsLoading(false);
    };

    useEffect(() => {
        loadHistory();
    }, [category]);

    const handleSave = async () => {
        if (!editingText.trim()) return;
        setIsSaving(true);
        try {
            await saveNewPromptVersion(category, editingText.trim());
            await loadHistory();
        } finally {
            setIsSaving(false);
        }
    };

    const handleActivate = async (id: number) => {
        await setActivePromptVersion(id);
        await loadHistory();
    };

    const categories: { id: PromptTemplate['category'], label: string, icon: React.ElementType }[] = [
        { id: 'system', label: 'System Instruction', icon: CpuChipIcon },
        { id: 'price', label: 'OSP (Pricing)', icon: TagIcon },
        { id: 'shelfShare', label: 'SoS (Shelf Share)', icon: ChartPieIcon },
        { id: 'osa', label: 'OSA (Availability)', icon: TableCellsIcon },
        { id: 'both', label: 'Complete Analysis', icon: ClipboardDocumentListIcon }
    ];

    if (isLoading && history.length === 0) {
        return (
            <div className="flex justify-center items-center h-64">
                <SpinnerIcon className="w-12 h-12 text-lime-500" />
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-6xl mx-auto pb-20">
            {/* Header */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-3">
                    <div className="bg-lime-100 p-2 rounded-lg">
                        <EditIcon className="w-6 h-6 text-lime-600" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">{t('promptManager')}</h2>
                        <p className="text-xs text-gray-500 uppercase tracking-wider font-bold">{t('promptManagerSubtitle')}</p>
                    </div>
                </div>

                <div className="flex bg-gray-100 p-1 rounded-xl w-full md:w-auto overflow-x-auto">
                    {categories.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => setCategory(cat.id)}
                            className={`flex-shrink-0 flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                                category === cat.id 
                                ? 'bg-white text-lime-700 shadow-sm ring-1 ring-black/5' 
                                : 'text-gray-500 hover:text-gray-700'
                            }`}
                        >
                            <cat.icon className="w-4 h-4" />
                            <span className="hidden sm:inline">{cat.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Editor */}
                <div className="lg:col-span-2 space-y-4">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex flex-col h-[500px]">
                        <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                            <span className="text-sm font-bold text-gray-700 flex items-center gap-2">
                                <EditIcon className="w-4 h-4" /> Editor
                            </span>
                            <div className="flex gap-2">
                                <button 
                                    onClick={loadHistory}
                                    className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-white transition-colors"
                                    title={t('reset')}
                                >
                                    <ArrowPathIcon className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={handleSave}
                                    disabled={isSaving || !editingText.trim()}
                                    className="flex items-center gap-2 bg-lime-600 text-white px-6 py-1.5 rounded-lg text-sm font-bold hover:bg-lime-500 shadow-md shadow-lime-100 disabled:bg-gray-300 transition-all"
                                >
                                    {isSaving ? <SpinnerIcon className="w-4 h-4" /> : <SaveIcon className="w-4 h-4" />}
                                    {t('saveAsNewVersion')}
                                </button>
                            </div>
                        </div>
                        <textarea
                            className="flex-grow p-6 font-mono text-sm bg-white text-gray-800 focus:ring-0 border-none resize-none"
                            value={editingText}
                            onChange={(e) => setEditingText(e.target.value)}
                            spellCheck={false}
                            placeholder="Vložte sem prompt pre Gemini..."
                        />
                    </div>
                </div>

                {/* History Sidebar */}
                <div className="space-y-4">
                    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col h-[500px]">
                        <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center gap-2">
                            <HistoryIcon className="w-4 h-4 text-gray-500" />
                            <span className="text-sm font-bold text-gray-700">{t('versionHistory')}</span>
                        </div>
                        <div className="flex-grow overflow-y-auto p-4 space-y-3">
