                                            <span className="text-lime-600 bg-lime-100 p-1 rounded-full">
                                                <CheckCircleIcon className="w-4 h-4" />
                                            </span>
                                        ) : (
                                            <button
                                                onClick={() => p.id && handleActivate(p.id)}
                                                className="text-[10px] font-bold text-gray-500 hover:text-lime-600 uppercase tracking-widest border border-gray-200 px-2 py-1 rounded-lg hover:border-lime-200"
                                            >
                                                {t('activate')}
                                            </button>
                                        )}
                                    </div>
                                    <p className="text-xs text-gray-600 line-clamp-3 italic">"{p.text}"</p>
                                    <button 
                                        onClick={() => setEditingText(p.text)}
                                        className="mt-2 text-[10px] text-blue-600 hover:underline font-bold"
                                    >
                                        {t('loadToEditor')}
                                    </button>
                                </div>
                            )) : (
                                <div className="text-center py-10">
                                    <p className="text-sm text-gray-400 italic">{t('noHistoryYet')}</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from '../i18n/index.tsx';
