interface NewAnalysisModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (name: string, type: AnalysisType, files: FileList) => void;
  initialFiles: FileList | null;
}

export const NewAnalysisModal: React.FC<NewAnalysisModalProps> = ({ isOpen, onClose, onConfirm, initialFiles }) => {
  const { t } = useTranslation();
  const [name, setName] = useState('');
  const [selectedType, setSelectedType] = useState<AnalysisType>('both');
  const [files, setFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      const today = new Date();
      const formattedDate = `${today.getDate()}.${today.getMonth() + 1}.${today.getFullYear()}`;
      const formattedTime = `${today.getHours()}:${String(today.getMinutes()).padStart(2, '0')}`;
      setName(`${t('analysis')} ${formattedDate} ${formattedTime}`);

      if (initialFiles) {
        setFiles(Array.from(initialFiles));
      } else {
        setFiles([]);
      }
    }
  }, [isOpen, t, initialFiles]);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFiles(prev => [...prev, ...Array.from(e.target.files!)]);
    }
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleStart = () => {
    if (name.trim() && files.length > 0) {
      const dataTransfer = new DataTransfer();
      files.forEach(file => dataTransfer.items.add(file));
      onConfirm(name.trim(), selectedType, dataTransfer.files);
    }
  };

  const types = [
    { id: 'price', icon: TagIcon, label: t('analysisTypePriceButton'), desc: t('analysisTypePriceDescription') },
    { id: 'shelfShare', icon: ChartPieIcon, label: t('analysisTypeShelfShareButton'), desc: t('analysisTypeShelfShareDescription') },
    { id: 'osa', icon: TableCellsIcon, label: t('analysisTypeOsaButton'), desc: t('analysisTypeOsaDescription') },
    { id: 'both', icon: ClipboardDocumentListIcon, label: t('analysisTypeBothButton'), desc: t('analysisTypeBothDescription') },
  ];

  return (
    <div className="fixed inset-0 bg-gray-900 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-3xl transform transition-all flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-gray-900">{t('startNewAnalysis')}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-colors">
            <CloseIcon className="w-6 h-6" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-8">
          {/* Step 1: Name */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-2">{t('analysisName')}</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full rounded-lg border-gray-300 shadow-sm focus:border-lime-500 focus:ring-lime-500 text-lg py-3 px-4 bg-gray-50 border"
              placeholder={t('analysisNamePlaceholder')}
            />
          </section>

          {/* Step 2: Type Selection */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-3">{t('analysis_mode')}</label>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {types.map((type) => (
                <button
                  key={type.id}
                  onClick={() => setSelectedType(type.id as AnalysisType)}
                  className={`text-left p-4 rounded-xl border-2 transition-all ${
                    selectedType === type.id 
                      ? 'border-lime-500 bg-lime-50 ring-1 ring-lime-500' 
                      : 'border-gray-200 hover:border-lime-300 bg-white'
                  }`}
                >
                  <type.icon className={`w-8 h-8 mb-3 ${selectedType === type.id ? 'text-lime-600' : 'text-gray-400'}`} />
                  <h3 className={`font-bold text-sm ${selectedType === type.id ? 'text-lime-900' : 'text-gray-800'}`}>{type.label}</h3>
                  <p className="text-[10px] text-gray-500 mt-1 leading-relaxed line-clamp-2">{type.desc}</p>
                </button>
              ))}
            </div>
          </section>

          {/* Step 3: Files */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-3">{t('images')}</label>

            {files.length === 0 ? (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-10 border-2 border-dashed border-gray-300 rounded-xl flex flex-col items-center justify-center bg-gray-50 hover:bg-gray-100 hover:border-lime-400 transition-all text-gray-500"
              >
                <UploadIcon className="w-10 h-10 mb-2 opacity-50" />
                <span className="font-semibold">{t('uploadFiles')}</span>
                <span className="text-xs mt-1">{t('fileFormats')}</span>
              </button>
            ) : (
              <div className="space-y-2">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium text-gray-600">{t('selectedItems', { count: files.length })}</span>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="text-sm font-bold text-lime-600 hover:text-lime-700 flex items-center gap-1"
                  >
                    <UploadIcon className="w-4 h-4" /> {t('addMore')}
                  </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1">
                  {files.map((file, idx) => (
                    <div key={idx} className="flex items-center justify-between p-2 bg-gray-50 border border-gray-200 rounded-lg group">
