function extractFirstJson(text: string): string {
    const markdownMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    let cleanText = text;
    if (markdownMatch && markdownMatch[1]) {
        cleanText = markdownMatch[1].trim();
    }

    const firstBrace = cleanText.indexOf('{');
    const firstBracket = cleanText.indexOf('[');
    let startIndex = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
        startIndex = firstBrace;
    } else if (firstBracket !== -1) {
        startIndex = firstBracket;
    } else {
        throw new Error("No JSON object or array found in the response text.");
    }

    const stack: string[] = [];
    let inString = false;
    let isEscaped = false;
    let lastSafeIndex = -1;

    for (let i = startIndex; i < cleanText.length; i++) {
        const char = cleanText[i];

        if (inString) {
            if (isEscaped) {
                isEscaped = false;
            } else if (char === '\\') {
                isEscaped = true;
            } else if (char === '"') {
                inString = false;
            }
        } else {
            if (char === '"') {
                inString = true;
            } else if (char === '{' || char === '[') {
                stack.push(char);
            } else if (char === '}' || char === ']') {
                const expected = char === '}' ? '{' : '[';
                if (stack.length > 0 && stack[stack.length - 1] === expected) {
                    stack.pop();
                    if (char === '}' && stack.length > 0 && stack[stack.length - 1] === '[') {
                        lastSafeIndex = i;
                    }
                    if (char === ']' && stack.length > 0 && stack[stack.length - 1] === '{') {
                        lastSafeIndex = i;
                    }
                }
            }
        }

        if (!inString && stack.length === 0) {
             return cleanText.substring(startIndex, i + 1);
        }
    }

    if (lastSafeIndex !== -1) {
        let repaired = cleanText.substring(startIndex, lastSafeIndex + 1);
        const repairStack: string[] = [];
        let repairInString = false;
        let repairEscaped = false;
        for (let j = 0; j < repaired.length; j++) {
             const c = repaired[j];
             if (repairInString) {
                 if (repairEscaped) repairEscaped = false;
                 else if (c === '\\') repairEscaped = true;
                 else if (c === '"') repairInString = false;
             } else {
                 if (c === '"') repairInString = true;
                 else if (c === '{' || c === '[') repairStack.push(c);
                 else if (c === '}' || c === ']') repairStack.pop();
             }
        }
        while (repairStack.length > 0) {
            const type = repairStack.pop();
            if (type === '{') repaired += '}';
            if (type === '[') repaired += ']';
        }
        return repaired;
    }
    throw new Error("Unrepairable JSON truncation.");
}

function parseMinifiedPriceString(priceString: string | undefined): PriceInfo[] {
  if (!priceString) return [];
  const prices: PriceInfo[] = [];
  const parts = priceString.split(';');

  parts.forEach(part => {
    const trimmedPart = part.trim();
    if (trimmedPart) {
      const match = trimmedPart.match(/([\d.,]+)\s*([RP€])/i);
      if (match) {
        const value = match[1];
        const type = match[2].toUpperCase() === 'P' ? 'PROMO' : 'REGULAR';
        prices.push({ value, type });
      }
    }
  });
  return prices;
}

function parseMinifiedResponse(minifiedResponse: any): AnalysisResult {
  const products: DetectedProduct[] = [];
  const storeInfo: StoreInfo = {};

  if (minifiedResponse.products && Array.isArray(minifiedResponse.products)) {
    minifiedResponse.products.forEach((group: any) => {
      const name = group.n;
      const confidence = group.c || 0.9;
      const prices = parseMinifiedPriceString(group.p);

      if (typeof group.b === 'string' && group.b) {
        const boxStrings = group.b.split('|');
        boxStrings.forEach((boxString: string) => {
          const coords = boxString.split(',').map(Number);
          if (coords.length === 4 && !coords.some(isNaN)) {
            const ymin = coords[0] / 1000.0;
            const xmin = coords[1] / 1000.0;
            const ymax = coords[2] / 1000.0;
            const xmax = coords[3] / 1000.0;
            const y = ymin;
            const x = xmin;
            const height = ymax - ymin;
            const width = xmax - xmin;

            const brandMatch = name.match(/^(\S+)/);
            const brand = brandMatch ? brandMatch[1] : '';

            products.push({
              id: `${name}-${Math.random().toString(36).substring(7)}`,
              name,
              brand,
              prices,
              boundingBox: { x, y, width, height },
              confidence,
            });
          }
        });
      }
    });
  }

  if (minifiedResponse.info) {
    if (minifiedResponse.info.chn) storeInfo.chain = minifiedResponse.info.chn;
    if (minifiedResponse.info.adr) storeInfo.address = minifiedResponse.info.adr;
  }

  return { products, storeInfo, modelName: MODEL_NAME };
}


export async function analyzeImageWithGemini(
  base64Image: string, 
  defaultPromptText: string, 
  defaultSystemInstruction: string,
  category: 'price' | 'shelfShare' | 'both' | 'osa' = 'both'
): Promise<AnalysisResult> {
  const MAX_RETRIES = 3;
  let lastError: any;

  // Attempt to load dynamic prompts from DB
  const dynamicSystem = await getActivePrompt('system');
  const dynamicUser = await getActivePrompt(category);

  const effectiveSystem = dynamicSystem?.text || defaultSystemInstruction;
  const effectiveUser = dynamicUser?.text || defaultPromptText;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const contents: Part[] = [
        { inlineData: { data: base64Image, mimeType: 'image/jpeg' } },
        { text: effectiveUser }
      ];

      const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: { parts: contents },
        config: {
          systemInstruction: effectiveSystem,
          responseMimeType: 'application/json',
          responseSchema: productSchema,
          temperature: 0.1,
          maxOutputTokens: 8192,
          thinkingConfig: { thinkingBudget: 1024 },
        },
      });

      const rawText = response.text;
      if (!rawText) throw new Error("No response text received from AI.");

      const lowerText = rawText.toLowerCase();
      if (lowerText.includes("503") || lowerText.includes("overloaded") || lowerText.includes("unavailable")) {
          throw new Error("The model is overloaded. Please try again later.");
      }

      try {
        const jsonString = extractFirstJson(rawText.trim());
        const parsedJson = JSON.parse(jsonString);

        if (parsedJson.error) {
            throw new Error(`API Error: ${parsedJson.error.message || JSON.stringify(parsedJson.error)}`);
        }

        const result: AnalysisResult = parseMinifiedResponse(parsedJson);
        const usageMetadata = response.usageMetadata;
        if (usageMetadata) {
            result.usageMetadata = {
                promptTokenCount: usageMetadata.promptTokenCount || 0,
                candidatesTokenCount: usageMetadata.candidatesTokenCount || 0,
                totalTokenCount: usageMetadata.totalTokenCount || 0,
            };
        }

        return result;
      } catch (e) {
        console.error("JSON Parse Error:", e);
        throw new Error("Invalid response format from API.");
      }
    } catch (e: any) {
        lastError = e;
        const msg = e.message?.toLowerCase() || '';
        const isRetryable = msg.includes("503") || msg.includes("overloaded") || msg.includes("unavailable") || msg.includes("fetch failed");
        if (isRetryable && attempt < MAX_RETRIES) {
            await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, attempt - 1)));
            continue;
        }
        throw e;
    }
  }
  throw lastError;
}

export async function createVisualFingerprint(productName: string, base64Images: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const imageParts = base64Images.map(img => ({ inlineData: { data: img, mimeType: 'image/jpeg' } }));
    const prompt = `Analyze images of "${productName}". Create a concise "Visual Fingerprint" to help identification (Color, Shape, Distinctive Layouts). Single string output.`;
    const response = await ai.models.generateContent({
        model: MODEL_NAME,
        contents: { parts: [...imageParts, { text: prompt }] },
        config: { temperature: 0.1, maxOutputTokens: 100 }
    });
    return response.text?.trim() || "";
}

