interface ShelfShareData {
    category: string;
    share: number;
    count?: number;
}

/**
 * Escapes a value for CSV format.
 * - Wraps in double quotes if it contains a semicolon, double quote, or newline.
 * - Escapes double quotes inside the value by doubling them.
 * @param value The value to escape.
 * @returns A CSV-safe string.
 */
const escapeCsvValue = (value: any): string => {
    if (value === null || value === undefined) {
        return '';
    }
    const str = String(value);
    if (str.includes(';') || str.includes('"') || str.includes('\n')) {
        return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
};

/**
 * Converts an array of objects to a CSV string.
 * @param headers An array of header strings.
 * @param data An array of data rows, where each row is an array of values.
 * @returns A CSV formatted string with a semicolon delimiter.
 */
const convertToCSV = (headers: string[], data: (string | number | undefined)[][]): string => {
    const headerRow = headers.map(escapeCsvValue).join(';');
    const dataRows = data.map(row => row.map(escapeCsvValue).join(';'));
    return [headerRow, ...dataRows].join('\n');
};

const triggerDownload = (content: string, filename: string, mimeType: string) => {
    const link = document.createElement('a');
    // Add BOM for UTF-8 to ensure Excel opens it with correct encoding
    const blob = new Blob(['\uFEFF' + content], { type: mimeType });
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};


export const exportPriceMonitoringToXLS = (
    storeData: StoreCentricSummary[],
    t: (key: string, params?: Record<string, string | number>) => string
) => {
    const title = t('priceMonitoring');
    const headers = [
        t('storeInfo'),
        t('category'),
        t('products'),
        t('date'),
        t('priceValue'),
        t('priceType'),
        t('item_count_header'),
    ];

    const data: (string | number | undefined)[][] = [];

    storeData.forEach(store => {
        store.products.forEach(product => {
            if (product.priceHistory.length > 0) {
                // If there are prices, create a row for each price entry
                product.priceHistory.forEach(priceEntry => {
                    const priceValue = priceEntry.price.value.replace(/[^\d.,]/g, '').replace(',', '.');
                    const priceTypeKey = priceEntry.price.type === 'PROMO' ? 'promoPrice' : 'regularPrice';
                    const priceTypeText = t(priceTypeKey);

                    data.push([
                        store.storeName,
                        product.category,
                        product.name,
                        priceEntry.date.toLocaleDateString(),
                        priceValue,
                        priceTypeText,
                        product.count,
                    ]);
                });
            } else {
                // If there are no prices, create one row with empty price info
                data.push([
                    store.storeName,
                    product.category,
                    product.name,
                    '', // empty date
                    '', // empty price value
                    '', // empty price type
                    product.count,
                ]);
            }
        });
    });

    const csvContent = convertToCSV(headers, data);
    const date = new Date().toISOString().slice(0, 10);
    triggerDownload(csvContent, `${title}_${date}.csv`, 'text/csv;charset=utf-8;');
};


export const exportShelfShareToXLS = (
    shelfShareData: ShelfShareData[],
    selectedChain: string,
    shareMode: 'area' | 'count',
    t: (key: string, params?: Record<string, string | number>) => string
) => {
    const title = t('shelfShare');

    const headers = [t('category'), `${t('shelfShare')} (%)`];
    if (shareMode === 'count') {
        headers.push(t('item_count_header'));
    }

    const data: (string | number | undefined)[][] = shelfShareData.map(item => {
        const row: (string | number | undefined)[] = [item.category, item.share.toFixed(2).replace('.', ',')]; // Use comma for decimal separator for european locales
        if (shareMode === 'count') {
            row.push(item.count || 0);
        }
        return row;
    });

    const csvContent = convertToCSV(headers, data);
    const date = new Date().toISOString().slice(0, 10);
    triggerDownload(csvContent, `${title}_${shareMode}_${date}.csv`, 'text/csv;charset=utf-8;');
};

export const exportDistributionToXLS = (
    matrix: DistributionMatrix,
    t: (key: string, params?: Record<string, string | number>) => string
) => {
    const title = t('distributionModule');

    // Headers: Store Name | Product 1 | Product 2 | ... | Fulfillment
    // FIX: Using selectedEntities instead of selectedProducts as per types.ts
    const headers = [t('storeName'), ...matrix.selectedEntities, t('storeFulfillment')];

    const data: (string | number | undefined)[][] = matrix.rows.map(row => {
        // FIX: Using selectedEntities instead of selectedProducts
        const productValues = matrix.selectedEntities.map(p => {
            const cell = row.presence[p];
            // FIX: Using count > 0 instead of isPresent as per types.ts
            if (cell && cell.count > 0) {
                 return `${t('presenceYes')} (${Math.round(cell.maxConfidence * 100)}%)`;
            }
            return `${t('presenceNo')} (0%)`;
        });

        // FIX: Calculating fulfillment manually as it does not exist on current DistributionRow
        const presentCount = Object.values(row.presence).filter(c => c.count > 0).length;
        const fulfillment = matrix.selectedEntities.length > 0 ? (presentCount / matrix.selectedEntities.length) * 100 : 0;

        return [
            row.storeName,
            ...productValues,
            `${Math.round(fulfillment)}%`
        ];
    });

    // Add Summary Row
    const summaryRow = [
        t('distributionShare'),
        // FIX: Using selectedEntities instead of selectedProducts
        ...matrix.selectedEntities.map(p => `${Math.round(matrix.columnSummaries[p] || 0)}%`),
        '-'
    ];
    data.push(summaryRow);

    const csvContent = convertToCSV(headers, data);
    const date = new Date().toISOString().slice(0, 10);
    triggerDownload(csvContent, `${title}_${date}.csv`, 'text/csv;charset=utf-8;');
};

export const exportPromoAlertToXLS = (
    alerts: PromoAlertItem[],
    t: (key: string, params?: Record<string, string | number>) => string
) => {
    const title = t('promoAlert');
    // Headers: Alert Type | Product | Brand | Store | Regular Price | Promo Price
    const headers = [
        t('category'), // Using 'category' loosely for 'Alert Type' column header or create a new key if preferred
        t('product'),
        t('ourBrands'), // Using existing key for Brand column
        t('storeName'),
        t('avgRegularPrice'), // Using existing keys for price headers
        t('avgPromoPrice')
    ];

    const data: (string | number | undefined)[][] = alerts.map(alert => {
        let typeLabel = '';
        switch (alert.type) {
            case 'competitor_promo': typeLabel = t('promoAlertCompetitorTitle'); break;
            case 'our_promo': typeLabel = t('promoAlertOurActiveTitle'); break;
            case 'missing_promo': typeLabel = t('promoAlertMissingTitle'); break;
        }

        const regularPrice = alert.product.prices?.find(p => p.type === 'REGULAR')?.value || '';
        const promoPrice = alert.product.prices?.find(p => p.type === 'PROMO')?.value || '';

        return [
            typeLabel,
            alert.product.name,
            alert.product.brand || '',
            alert.store,
            regularPrice,
            promoPrice
        ];
    });

    const csvContent = convertToCSV(headers, data);
    const date = new Date().toISOString().slice(0, 10);
    triggerDownload(csvContent, `${title}_${date}.csv`, 'text/csv;charset=utf-8;');
}

export const exportToPDF = (elementToPrint: HTMLElement | null) => {
    if (!elementToPrint) {
      console.error("Element to print was not provided.");
      return;
    }

    if (typeof html2canvas === 'undefined') {
        console.error("html2canvas library is not loaded.");
        alert("PDF export functionality is currently unavailable. Please try again later.");
        return;
    }

    // To capture full scrollable content, temporarily make it visible
    const scrollableElements = Array.from(elementToPrint.querySelectorAll<HTMLElement>('.overflow-y-auto'));
    // Identify elements to hide (e.g. buttons, filters, tabs) that have 'no-print' class
    const noPrintElements = Array.from(elementToPrint.querySelectorAll<HTMLElement>('.no-print'));

    const elementsToModify = [elementToPrint, ...scrollableElements];
    const originalStyles = new Map<HTMLElement, { overflow: string; maxHeight: string; height: string }>();
    const originalDisplayStyles = new Map<HTMLElement, string>();

    elementsToModify.forEach(el => {
        originalStyles.set(el, {
            overflow: el.style.overflow,
            maxHeight: el.style.maxHeight,
            height: el.style.height,
        });
        el.style.overflow = 'visible';
        el.style.maxHeight = 'none';
        el.style.height = 'auto'; // Allow element to expand to its full content height
    });

    noPrintElements.forEach(el => {
        originalDisplayStyles.set(el, el.style.display);
        el.style.display = 'none';
    });

    html2canvas(elementToPrint, {
        scale: 2, // Improves resolution for better quality PDF
        useCORS: true,
        backgroundColor: '#ffffff', // Ensure a white background for consistency
        windowWidth: elementToPrint.scrollWidth,
        windowHeight: elementToPrint.scrollHeight,
    }).then((canvas: HTMLCanvasElement) => {
        const imgData = canvas.toDataURL('image/png');

        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.write(`
                <html>
                    <head>
                        <title>Export to PDF</title>
                        <style>
                            @page { size: a4 portrait; margin: 0; }
                            body { margin: 0; }
                            img { width: 100%; display: block; }
                        </style>
                    </head>
                    <body>
                        <img src="${imgData}" alt="Export Preview" />
                    </body>
                </html>
            `);
            printWindow.document.close();

            printWindow.onload = () => {
                setTimeout(() => {
                    printWindow.focus();
                    printWindow.print();
                    // Let the user close the print preview window
                }, 250);
            };
        } else {
            alert("Could not open print window. Please disable your pop-up blocker.");
        }
    }).catch(err => {
        console.error("Failed to generate PDF screenshot:", err);
        alert("An error occurred while generating the PDF.");
    }).finally(() => {
        // Crucially, restore the original styles after the operation
        originalStyles.forEach((styles, el) => {
            el.style.overflow = styles.overflow;
            el.style.maxHeight = styles.maxHeight;
            el.style.height = styles.height;
        });

        noPrintElements.forEach(el => {
            el.style.display = originalDisplayStyles.get(el) || '';
        });
    });
};

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n';
import { getAnalyses, getCatalogProductNames, getStores, getBrandMemory } from '../db';
import { DistributionMatrix, DistributionRow, DistributionCell, Store, DetectedProduct } from '../types';
import { removeDateFromStoreName, findBestMatch, getBrandFromName } from '../utils/helpers';
import { exportDistributionToXLS } from '../utils/export';
// FIX: Corrected icon imports to match exported members in Icons.tsx
import { 
    TableCellsIcon, 
    CalculatorIcon, 
    SpinnerIcon, 
    ArrowDownTrayIcon, 
    FolderOpenIcon, 
    CircleStackIcon, 
    ShieldExclamationIcon, 
    FunnelIcon,
    AppIcon
} from './Icons';

export const DistributionPanel: React.FC = () => {
    const { t } = useTranslation();
    const [isLoading, setIsLoading] = useState(false);
    const [isCalculating, setIsCalculating] = useState(false);
    const [matrix, setMatrix] = useState<DistributionMatrix | null>(null);

    // UI Filters
    const [viewMode, setViewMode] = useState<'brand' | 'sku'>('brand');
    const [minFacing, setMinFacing] = useState(1);
    const [battleMode, setBattleMode] = useState(false);

    useEffect(() => {
        generateMatrix();
    }, [viewMode]);

    const generateMatrix = async () => {
        setIsCalculating(true);
        try {
            const analyses = await getAnalyses();
            const allStores = await getStores();
            const brandMemory = await getBrandMemory();
            const ourBrands = new Set(brandMemory.filter(m => m.classification === 'our').map(m => m.brand));

            const storesMap = new Map<number, Store>(allStores.map(s => [s.id!, s]));

            // Map: UniqueStoreKey -> { name, code, entities: Map<EntityName, { count, maxConf }> }
            const storeInventory = new Map<string, { name: string, code?: string, entities: Map<string, { count: number, maxConf: number }> }>();

            // Initialize known stores
            allStores.forEach(store => {
                const key = `ID_${store.id}`;
                storeInventory.set(key, { 
                    name: store.name, 
                    code: store.code, 
                    entities: new Map() 
                });
            });

            // Aggregate data
            analyses.forEach(analysis => {
                analysis.images.forEach(img => {
                    if (!img.analysisResult?.products) return;

                    let storeKey = '';
                    if (img.assignedStoreId) storeKey = `ID_${img.assignedStoreId}`;
                    else if (img.analysisResult.storeInfo?.chain) storeKey = `RAW_${removeDateFromStoreName(img.analysisResult.storeInfo.chain)}`;

                    if (!storeKey) return;
                    if (!storeInventory.has(storeKey)) {
                        storeInventory.set(storeKey, { 
                            name: storeKey.replace('RAW_', ''), 
                            entities: new Map() 
                        });
                    }

                    const inventory = storeInventory.get(storeKey)!;

                    img.analysisResult.products.forEach(p => {
                        const entityName = viewMode === 'brand' 
                            ? (p.brand || getBrandFromName(p.name))
                            : p.name;

                        if (!entityName) return;

                        const current = inventory.entities.get(entityName) || { count: 0, maxConf: 0 };
                        inventory.entities.set(entityName, {
                            count: current.count + 1,
                            maxConf: Math.max(current.maxConf, p.confidence)
                        });
                    });
                });
            });

            // Collect all entities that appeared at least once
            const allSeenEntities = new Set<string>();
            storeInventory.forEach(inv => {
                inv.entities.forEach((data, name) => {
                    if (data.count > 0) allSeenEntities.add(name);
                });
            });

            const sortedEntities = Array.from(allSeenEntities).sort((a, b) => {
                const aOur = ourBrands.has(a);
                const bOur = ourBrands.has(b);
                if (aOur && !bOur) return -1;
                if (!aOur && bOur) return 1;
                return a.localeCompare(b);
            });

            const rows: DistributionRow[] = Array.from(storeInventory.entries()).map(([key, data]) => {
                const presence: Record<string, DistributionCell> = {};
                let total = 0;

                sortedEntities.forEach(ent => {
                    const stats = data.entities.get(ent) || { count: 0, maxConf: 0 };
                    presence[ent] = { 
                        count: stats.count, 
                        maxConfidence: stats.maxConf,
                        isOurBrand: ourBrands.has(viewMode === 'brand' ? ent : getBrandFromName(ent))
                    };
                    total += stats.count;
                });

                return {
                    storeName: data.name,
                    storeCode: data.code,
                    presence,
                    totalFacings: total
                };
            }).filter(r => r.totalFacings > 0);

            const columnSummaries: Record<string, number> = {};
            sortedEntities.forEach(ent => {
                const totalInCol = rows.reduce((sum, r) => sum + (r.presence[ent]?.count || 0), 0);
                columnSummaries[ent] = totalInCol;
            });

            setMatrix({ rows, columnSummaries, selectedEntities: sortedEntities, mode: viewMode });
        } finally {
            setIsCalculating(false);
        }
    };

    const filteredEntities = useMemo(() => {
        if (!matrix) return [];
        return matrix.selectedEntities.filter(ent => matrix.columnSummaries[ent] >= minFacing);
    }, [matrix, minFacing]);

    if (isCalculating && !matrix) {
        return (
            <div className="flex flex-col items-center justify-center h-96">
                <SpinnerIcon className="w-12 h-12 text-lime-500 animate-spin" />
                <p className="mt-4 text-gray-500 font-medium">{t('calculating')}</p>
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-20">
            {/* Header & Controls */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
                <div>
                    <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
                        <TableCellsIcon className="w-7 h-7 text-lime-600" />
                        {t('distribution')}
                    </h2>
                    <p className="text-sm text-gray-500 mt-1 uppercase tracking-widest font-bold">Presence Matrix (Vision Only)</p>
                </div>

                <div className="flex flex-wrap items-center gap-4 w-full lg:w-auto">
                    {/* View Switcher */}
                    <div className="flex bg-gray-100 p-1 rounded-xl shadow-inner">
                        <button 
                            onClick={() => setViewMode('brand')}
                            // FIX: Using TableCellsIcon as a proxy for LayoutGridIcon
                            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'brand' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <AppIcon className="w-4 h-4" /> {t('sosLevel')}
                        </button>
                        <button 
                            onClick={() => setViewMode('sku')}
                            // FIX: Using CircleStackIcon instead of LayersIcon
                            className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'sku' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                        >
                            <CircleStackIcon className="w-4 h-4" /> {t('skuDetail')}
                        </button>
                    </div>

                    {/* Battle Mode */}
                    <button 
                        onClick={() => setBattleMode(!battleMode)}
                        // FIX: Using ShieldExclamationIcon instead of ShieldAlertIcon
                        className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold border-2 transition-all ${battleMode ? 'bg-red-50 border-red-200 text-red-700 shadow-sm' : 'bg-white border-gray-100 text-gray-500 hover:border-gray-300'}`}
                    >
                        <ShieldExclamationIcon className="w-4 h-4" />
                        {t('competitorBattle')}
                    </button>

                    {/* Export */}
                    <button onClick={() => matrix && exportDistributionToXLS(matrix as any, t)} className="p-2 bg-blue-600 text-white rounded-xl hover:bg-blue-700 shadow-lg shadow-blue-100">
                        <ArrowDownTrayIcon className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Matrix Table */}
            {matrix ? (
                <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">
                    {/* Facing Filter Slider */}
                    <div className="px-6 py-4 bg-gray-50 border-b border-gray-100 flex items-center gap-6">
                        <div className="flex items-center gap-3">
                            {/* FIX: Using FunnelIcon instead of FilterIcon */}
                            <FunnelIcon className="w-4 h-4 text-gray-400" />
                            <span className="text-xs font-bold text-gray-700 uppercase tracking-wider">{t('minFacingFilter')}:</span>
                            <span className="bg-lime-600 text-white px-2 py-0.5 rounded text-xs font-bold">{minFacing}</span>
                        </div>
                        <input 
                            type="range" 
                            min="1" 
                            max="50" 
                            value={minFacing} 
                            onChange={(e) => setMinFacing(parseInt(e.target.value))}
                            className="flex-grow max-w-xs h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-lime-600"
                        />
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-gray-800 text-white">
                                    <th className="px-4 py-4 text-xs font-black uppercase tracking-widest sticky left-0 bg-gray-800 z-30 min-w-[200px]">
                                        {t('storeName')}
                                    </th>
                                    {filteredEntities.map(ent => (
                                        <th key={ent} className="px-3 py-4 text-[10px] font-black uppercase tracking-tighter text-center border-l border-gray-700 min-w-[80px]">
                                            <div className="line-clamp-2 leading-tight">{ent}</div>
                                        </th>
                                    ))}
                                    <th className="px-4 py-4 text-xs font-black uppercase tracking-widest text-center bg-lime-700 min-w-[100px]">
                                        Total
                                    </th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {matrix.rows.map((row, idx) => (
                                    <tr key={idx} className="hover:bg-lime-50/30 transition-colors group">
                                        <td className="px-4 py-3 text-sm font-bold text-gray-900 sticky left-0 bg-white group-hover:bg-lime-50 transition-colors z-20 border-r shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                                            {row.storeName}
                                            {row.storeCode && <span className="ml-2 text-[10px] bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded-md">#{row.storeCode}</span>}
                                        </td>
                                        {filteredEntities.map(ent => {
                                            const cell = row.presence[ent];
                                            const count = cell?.count || 0;

                                            // Battle mode styling
                                            let cellBg = 'bg-white';
                                            if (count > 0) {
                                                if (battleMode) {
                                                    cellBg = cell.isOurBrand ? 'bg-green-50' : 'bg-red-50';
                                                } else {
                                                    cellBg = count > 5 ? 'bg-lime-50' : 'bg-white';
                                                }
                                            }

                                            return (
                                                <td key={ent} className={`px-2 py-3 text-center border-l border-gray-50 transition-all ${cellBg}`}>
                                                    {count > 0 ? (
                                                        <div className="flex flex-col items-center">
                                                            <span className={`text-sm font-black ${cell.isOurBrand ? 'text-lime-700' : 'text-gray-900'}`}>
                                                                {count}
                                                            </span>
                                                            <div className="w-8 h-1 bg-gray-200 rounded-full mt-1 overflow-hidden">
                                                                <div className={`h-full ${cell.isOurBrand ? 'bg-lime-500' : 'bg-gray-400'}`} style={{ width: `${Math.min(count * 10, 100)}%` }}></div>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <span className="text-gray-200 text-xs font-bold">-</span>
                                                    )}
                                                </td>
                                            );
                                        })}
                                        <td className="px-4 py-3 text-center font-black text-lime-800 bg-lime-50/50">
                                            {row.totalFacings}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot>
                                <tr className="bg-gray-100 border-t-2 border-gray-200">
                                    <th className="px-4 py-4 text-xs font-black text-gray-700 uppercase tracking-widest sticky left-0 bg-gray-100 z-20 border-r">
                                        Total Market
                                    </th>
                                    {filteredEntities.map(ent => (
                                        <th key={`f-${ent}`} className="px-2 py-4 text-center">
                                            <div className="text-xs font-black text-gray-900">{matrix.columnSummaries[ent]}</div>
                                            <div className="text-[10px] text-gray-500 font-medium">facing</div>
                                        </th>
                                    ))}
                                    <th className="px-4 py-4 text-center font-black text-lime-900">
                                        {/* FIX: Explicitly typed reduce parameters to fix unknown types error */}
                                        {Object.values(matrix.columnSummaries).reduce((a: number, b: number) => a + b, 0)}
                                    </th>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>
            ) : (
                <div className="bg-white p-20 rounded-2xl shadow-sm border border-gray-100 text-center">
                    <TableCellsIcon className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400 font-medium italic">{t('noDataForDistribution')}</p>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { CloseIcon, TagIcon, ChartPieIcon, ClipboardDocumentListIcon, UploadIcon, TrashIcon, SpinnerIcon, RocketLaunchIcon, TableCellsIcon } from './Icons.tsx';
import type { AnalysisType } from '../App.tsx';

interface NewAnalysisModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (name: string, type: AnalysisType, files: FileList) => void;
  initialFiles: FileList | null;
}

export const NewAnalysisModal: React.FC<NewAnalysisModalProps> = ({ isOpen, onClose, onConfirm, initialFiles }) => {
  const { t } = useTranslation();
  const [name, setName] = useState('');
  const [selectedType, setSelectedType] = useState<AnalysisType>('both');
  const [files, setFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      const today = new Date();
      const formattedDate = `${today.getDate()}.${today.getMonth() + 1}.${today.getFullYear()}`;
      const formattedTime = `${today.getHours()}:${String(today.getMinutes()).padStart(2, '0')}`;
      setName(`${t('analysis')} ${formattedDate} ${formattedTime}`);

      if (initialFiles) {
        setFiles(Array.from(initialFiles));
      } else {
        setFiles([]);
      }
    }
  }, [isOpen, t, initialFiles]);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFiles(prev => [...prev, ...Array.from(e.target.files!)]);
    }
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleStart = () => {
    if (name.trim() && files.length > 0) {
      const dataTransfer = new DataTransfer();
      files.forEach(file => dataTransfer.items.add(file));
      onConfirm(name.trim(), selectedType, dataTransfer.files);
    }
  };

  const types = [
    { id: 'price', icon: TagIcon, label: t('analysisTypePriceButton'), desc: t('analysisTypePriceDescription') },
    { id: 'shelfShare', icon: ChartPieIcon, label: t('analysisTypeShelfShareButton'), desc: t('analysisTypeShelfShareDescription') },
    { id: 'osa', icon: TableCellsIcon, label: t('analysisTypeOsaButton'), desc: t('analysisTypeOsaDescription') },
    { id: 'both', icon: ClipboardDocumentListIcon, label: t('analysisTypeBothButton'), desc: t('analysisTypeBothDescription') },
  ];

  return (
    <div className="fixed inset-0 bg-gray-900 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-3xl transform transition-all flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-gray-900">{t('startNewAnalysis')}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400 transition-colors">
            <CloseIcon className="w-6 h-6" />
          </button>
        </div>

        <div className="p-6 overflow-y-auto space-y-8">
          {/* Step 1: Name */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-2">{t('analysisName')}</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full rounded-lg border-gray-300 shadow-sm focus:border-lime-500 focus:ring-lime-500 text-lg py-3 px-4 bg-gray-50 border"
              placeholder={t('analysisNamePlaceholder')}
            />
          </section>

          {/* Step 2: Type Selection */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-3">{t('analysis_mode')}</label>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {types.map((type) => (
                <button
                  key={type.id}
                  onClick={() => setSelectedType(type.id as AnalysisType)}
                  className={`text-left p-4 rounded-xl border-2 transition-all ${
                    selectedType === type.id 
                      ? 'border-lime-500 bg-lime-50 ring-1 ring-lime-500' 
                      : 'border-gray-200 hover:border-lime-300 bg-white'
                  }`}
                >
                  <type.icon className={`w-8 h-8 mb-3 ${selectedType === type.id ? 'text-lime-600' : 'text-gray-400'}`} />
                  <h3 className={`font-bold text-sm ${selectedType === type.id ? 'text-lime-900' : 'text-gray-800'}`}>{type.label}</h3>
                  <p className="text-[10px] text-gray-500 mt-1 leading-relaxed line-clamp-2">{type.desc}</p>
                </button>
              ))}
            </div>
          </section>

          {/* Step 3: Files */}
          <section>
            <label className="block text-sm font-bold text-gray-700 uppercase tracking-wider mb-3">{t('images')}</label>

            {files.length === 0 ? (
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-10 border-2 border-dashed border-gray-300 rounded-xl flex flex-col items-center justify-center bg-gray-50 hover:bg-gray-100 hover:border-lime-400 transition-all text-gray-500"
              >
                <UploadIcon className="w-10 h-10 mb-2 opacity-50" />
                <span className="font-semibold">{t('uploadFiles')}</span>
                <span className="text-xs mt-1">{t('fileFormats')}</span>
              </button>
            ) : (
              <div className="space-y-2">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-sm font-medium text-gray-600">{t('selectedItems', { count: files.length })}</span>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="text-sm font-bold text-lime-600 hover:text-lime-700 flex items-center gap-1"
                  >
                    <UploadIcon className="w-4 h-4" /> {t('addMore')}
                  </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1">
                  {files.map((file, idx) => (
                    <div key={idx} className="flex items-center justify-between p-2 bg-gray-50 border border-gray-200 rounded-lg group">
                      <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 bg-gray-200 rounded flex-shrink-0 flex items-center justify-center text-[10px] font-bold text-gray-500 uppercase">
                          {file.name.split('.').pop()}
                        </div>
                        <span className="text-xs text-gray-700 truncate font-medium">{file.name}</span>
                      </div>
                      <button onClick={() => removeFile(idx)} className="p-1 text-gray-400 hover:text-red-500 transition-colors">
                        <TrashIcon className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <input type="file" ref={fileInputRef} className="hidden" multiple accept="image/*" onChange={handleFileChange} />
          </section>
        </div>

        {/* Footer */}
        <div className="p-6 bg-gray-50 border-t border-gray-100 rounded-b-xl flex justify-end gap-3">
          <button
            onClick={onClose}
            className="px-6 py-2 text-sm font-bold text-gray-600 hover:bg-gray-200 rounded-lg transition-colors"
          >
            {t('cancelButton')}
          </button>
          <button
            onClick={handleStart}
            disabled={!name.trim() || files.length === 0}
            className="px-8 py-2 bg-lime-600 text-white font-bold rounded-lg hover:bg-lime-700 disabled:bg-gray-300 disabled:cursor-not-allowed shadow-lg shadow-lime-200 transition-all flex items-center gap-2"
          >
            <RocketLaunchIcon className="w-5 h-5" />
            {t('startAnalysis')}
          </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react'; 
