}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const { t } = useTranslation();
  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandProductsMap, setBrandProductsMap] = React.useState<Record<string, string[]>>({});
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);

  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false);
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  // Inicializácia promptov pri prvom štarte
  React.useEffect(() => {
    const initPrompts = async () => {
        const count = await db.prompts.count();
        if (count === 0 || count < 5) {
            const currentPrompts = await db.prompts.toArray();
            const hasSystem = currentPrompts.some(p => p.category === 'system');
            const hasPrice = currentPrompts.some(p => p.category === 'price');
            const hasShelf = currentPrompts.some(p => p.category === 'shelfShare');
            const hasBoth = currentPrompts.some(p => p.category === 'both');
            const hasOsa = currentPrompts.some(p => p.category === 'osa');

            if (!hasSystem) await saveNewPromptVersion('system', t('geminiSystemInstruction'));
            if (!hasPrice) await saveNewPromptVersion('price', t('geminiPromptPriceOnly'));
            if (!hasShelf) await saveNewPromptVersion('shelfShare', t('geminiPromptShelfShareOnly'));
            if (!hasBoth) await saveNewPromptVersion('both', t('geminiPromptBoth'));
            if (!hasOsa) await saveNewPromptVersion('osa', t('geminiPromptOsaOnly'));
        }
    };
    initPrompts();
