export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const { t } = useTranslation();
  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandProductsMap, setBrandProductsMap] = React.useState<Record<string, string[]>>({});
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);

  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false);
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  // Inicializácia promptov pri prvom štarte
  React.useEffect(() => {
    const initPrompts = async () => {
        const count = await db.prompts.count();
        if (count === 0 || count < 5) {
            const currentPrompts = await db.prompts.toArray();
            const hasSystem = currentPrompts.some(p => p.category === 'system');
            const hasPrice = currentPrompts.some(p => p.category === 'price');
            const hasShelf = currentPrompts.some(p => p.category === 'shelfShare');
            const hasBoth = currentPrompts.some(p => p.category === 'both');
            const hasOsa = currentPrompts.some(p => p.category === 'osa');

            if (!hasSystem) await saveNewPromptVersion('system', t('geminiSystemInstruction'));
            if (!hasPrice) await saveNewPromptVersion('price', t('geminiPromptPriceOnly'));
            if (!hasShelf) await saveNewPromptVersion('shelfShare', t('geminiPromptShelfShareOnly'));
            if (!hasBoth) await saveNewPromptVersion('both', t('geminiPromptBoth'));
            if (!hasOsa) await saveNewPromptVersion('osa', t('geminiPromptOsaOnly'));
        }
    };
    initPrompts();
  }, [t]);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = React.useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const missingPriceItems = React.useMemo<MissingPriceItem[]>(() => {
      const items: MissingPriceItem[] = [];
      images.forEach(img => {
          if (img.analysisResult?.products) {
              img.analysisResult.products.forEach(p => {
                  if (!p.prices || p.prices.length === 0) {
                      items.push({
                          imageId: img.id,
                          productId: p.id,
                          name: p.name,
                          imageUrl: img.imageUrl
                      });
                  }
              });
          }
      });
      return items;
  }, [images]);

  const handleUpdatePrices = (updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prevImages => 
          prevImages.map(img => {
              const updatesForImage = updates.filter(u => u.imageId === img.id);
              if (updatesForImage.length === 0) return img;

              const updatedProducts = img.analysisResult?.products.map(p => {
                  const update = updatesForImage.find(u => u.productId === p.id);
                  if (update) {
                      return { ...p, prices: update.prices };
                  }
                  return p;
              });

              return {
                  ...img,
                  analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null
              };
          })
      );
  };

  const handleNewAnalysisClick = () => {
    if (activeAnalysis && images.length > 0) {
        setIsClearConfirmOpen(true);
    } else {
        setIsNewAnalysisModalOpen(true); 
    }
  };

  const handleImageUpload = React.useCallback((files: FileList) => {
    setPendingFiles(files);
    setIsNewAnalysisModalOpen(true); 
    setIsImageUploadOverlayOpen(false);
  }, []);

 const handleStartAnalysis = React.useCallback(async (name: string, type: AnalysisType, filesToProcess: FileList) => {
    setIsNewAnalysisModalOpen(false);
    setPendingFiles(null);

    const newAnalysis: Analysis = {
        id: `analysis-${Date.now()}`,
        name,
        createdAt: new Date().toISOString(),
        images: [],
        brandClassifications: { ourBrands: [], competitorBrands: [] },
        store: null,
    };
    await db.analyses.add(newAnalysis);
    setActiveAnalysis(newAnalysis);

    if (type === 'osa') {
        setActiveView('distribution');
    } else if (type === 'shelfShare') {
        setActiveView('shelfShare');
    } else {
        setActiveView('priceMonitoring');
    }

    const tempImages: ImageState[] = await Promise.all(Array.from(filesToProcess).map(async (file) => {
        const initialId = `${file.name}-${Date.now()}`;
        const filenameStoreName = extractStoreFromFilename(file.name);
        let effectiveStore: Store | null = null;
        let effectiveStoreId: number | undefined = undefined;

        if (filenameStoreName) {
             const chain = filenameStoreName.split(',')[0].trim();
             try {
                effectiveStore = await findOrCreateStore({ name: filenameStoreName, chain: chain, city: '', address: '', code: '' });
                effectiveStoreId = effectiveStore.id;
             } catch (e) {
                console.warn("Could not auto-create store, proceed without link", e);
             }
        }

        return {
            id: initialId,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: effectiveStore,
            assignedStoreId: effectiveStoreId
        };
    }));

    setImages(tempImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    const compressImages = async () => {
        const compressedImages: ImageState[] = await Promise.all(tempImages.map(async (img) => {
            try {
                const compressedFile = await resizeAndCompressImage(img.file);
                return {
                    ...img,
                    file: compressedFile,
                    imageUrl: URL.createObjectURL(compressedFile)
                };
            } catch (e) {
                console.error("Compression failed for", img.file.name, e);
                return img; 
            }
        }));

        setImages(prev => {
            return prev.map(p => {
                const compressed = compressedImages.find(c => c.id === p.id);
                return compressed || p;
            }).sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime());
        });
    };
    compressImages();

  }, []);


const handleRetryImage = (id: string) => {
    setImages(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'pending', error: null, retryCount: 0 } : img
    ));
};

React.useEffect(() => {
    const processQueue = async () => {
        if (!isOnline) return;

        const pendingImages = images.filter(img => img.status === 'pending');
        if (pendingImages.length === 0 || images.some(img => img.status === 'analyzing')) return;

        const BATCH_SIZE = 3;
        const currentBatch = pendingImages.slice(0, BATCH_SIZE);

        setImages(prev => prev.map(img => 
            currentBatch.find(batchImg => batchImg.id === img.id) 
                ? { ...img, status: 'analyzing', error: null } 
                : img
        ));

        const type = currentBatch[0].analysisType;

        const catalogEntries = await getCatalogEntries();
        const knownProductsList = catalogEntries.map(entry => entry.visualFeatures ? `${entry.canonicalName} (Visuals: ${entry.visualFeatures})` : entry.canonicalName);
        const knownProductsString = knownProductsList.length > 0 ? t('knownProductsList', { products: knownProductsList.join(', ') }) : '';

        const systemInstructionDefault = t('geminiSystemInstruction');
        let geminiPromptDefaultKey = 'geminiPromptBoth';
        if (type === 'price') geminiPromptDefaultKey = 'geminiPromptPriceOnly';
        else if (type === 'shelfShare') geminiPromptDefaultKey = 'geminiPromptShelfShareOnly';
        else if (type === 'osa') geminiPromptDefaultKey = 'geminiPromptOsaOnly';

        const geminiPromptDefault = t(geminiPromptDefaultKey).replace('{{knownProducts}}', knownProductsString);

        const processedResults: ImageState[] = [];
        const newDiscoveredBrandsWithProducts: Record<string, Set<string>> = {};

        await Promise.all(currentBatch.map(async (image) => {
            try {
                const base64Image = await fileToBase64(image.file);
                const result = await analyzeImageWithGemini(base64Image, geminiPromptDefault, systemInstructionDefault, image.analysisType); 

                let currentAssignedStore = image.assignedStore;
                let currentAssignedStoreId = image.assignedStoreId;

                if (currentAssignedStore) {
                    if (!result.storeInfo) result.storeInfo = {};
                    result.storeInfo.chain = currentAssignedStore.chain || currentAssignedStore.name; 
                    result.storeInfo.address = currentAssignedStore.address || '';
                } else if (result.storeInfo && (result.storeInfo.chain || result.storeInfo.address)) {
                    const chain = result.storeInfo.chain || '';
                    const address = result.storeInfo.address || '';
                    const storeName = chain + (address ? `, ${address}` : '');

                    try {
                        currentAssignedStore = await findOrCreateStore({
                            name: storeName,
                            chain: chain,
                            address: address,
                            city: '',
                            code: ''
                        });
                        currentAssignedStoreId = currentAssignedStore.id;
                    } catch (e) {
                        console.warn("DB Store creation failed during AI results processing", e);
                    }
                }

                const correctedProducts = await Promise.all(
                    (result.products || []).map(async p => {
                        if (!p || !p.name) return p;

                        const catalogEntry = await findProductByAlias(p.name);
                        let finalName = p.name;
                        let isCorrected = false;
                        let catalogProductId: number | undefined = undefined;

                        if (catalogEntry) {
                            catalogProductId = catalogEntry.id;
                            if (normalizeProductName(catalogEntry.canonicalName) !== normalizeProductName(p.name)) {
                                finalName = catalogEntry.canonicalName;
                                isCorrected = true;
                            }
                        }

                        return { 
                            ...p, 
                            name: finalName, 
                            isCorrected, 
                            catalogProductId, 
                            id: `${image.id}-${finalName}-${Math.random()}`, 
                            imageId: image.id 
                        };
                    })
                );

                const processedImage: ImageState = { 
                    ...image, 
                    analysisResult: { ...result, products: correctedProducts }, 
                    status: 'success', 
                    error: null,
                    assignedStore: currentAssignedStore,
                    assignedStoreId: currentAssignedStoreId
                };
                processedResults.push(processedImage);

                if (correctedProducts) {
                    correctedProducts.forEach(p => {
                        if (!p) return;
                        const brand = p.brand || getBrandFromName(p.name);
                        if (brand) {
                            if (!newDiscoveredBrandsWithProducts[brand]) {
                                newDiscoveredBrandsWithProducts[brand] = new Set();
                            }
                            newDiscoveredBrandsWithProducts[brand].add(p.name);
                        }
                    });
                }

            } catch (e: any) {
                console.error("Processing error:", e);
                let errorMessage = t('failedToAnalyze');
                if (e?.message?.toLowerCase().includes('requested entity was not found')) {
                     errorMessage = t('apiKeyError');
                     setHasApiKey(false);
                }
                processedResults.push({ ...image, status: 'error', error: errorMessage, retryCount: 0 });
            }
        }));

        setImages(prev => prev.map(img => {
            const processed = processedResults.find(p => p.id === img.id);
            return processed || img;
        }).sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

        const successfulImages = processedResults.filter(img => img.status === 'success');

        if (successfulImages.length > 0) {
            await populateCatalogFromAnalysis({ images: successfulImages });

            const currentClassifiedBrands = new Set([...brandClassifications.ourBrands, ...brandClassifications.competitorBrands]);
            const newlyFoundBrands = Object.keys(newDiscoveredBrandsWithProducts).filter(b => !currentClassifiedBrands.has(b));

            if (newlyFoundBrands.length > 0) {
                const updatedMap = { ...brandProductsMap };
                Object.entries(newDiscoveredBrandsWithProducts).forEach(([brand, products]) => {
                    if (!updatedMap[brand]) updatedMap[brand] = [];
                    const combined = new Set([...updatedMap[brand], ...Array.from(products)]);
                    updatedMap[brand] = Array.from(combined).sort().slice(0, 5);
                });

                setBrandProductsMap(updatedMap);
                setIsBrandModalOpen(true);
            }
        }
    };

    if (images.some(img => img.status === 'pending') && isOnline && !images.some(img => img.status === 'analyzing')) {
        processQueue();
    }
}, [images, isOnline, t, brandClassifications, activeAnalysis]);


  const endCurrentAnalysisWithoutSaving = () => {
    images.forEach(img => URL.revokeObjectURL(img.imageUrl));
    setImages([]);
    setSelectedImageId(null);
    setSelectedProductName(null);
    setSidebarView('images');
    setHighlightedProductName(null);
    setProductSearchTerm('');
    setBrandClassifications({ ourBrands: [], competitorBrands: [] });
    setBrandProductsMap({});
    setActiveAnalysis(null);
    setIsNewAnalysisModalOpen(false);
  };

    const endCurrentAnalysisAndSave = async () => {
    if (activeAnalysis) {
        await handleSaveAnalysis();
    }
    endCurrentAnalysisWithoutSaving();
  };

  const handleConfirmBrands = (classifications: BrandClassifications) => {
    setBrandClassifications(classifications);
    setIsBrandModalOpen(false);
  };

  const handleAddMoreClick = () => {
    setIsImageUploadOverlayOpen(true);
  };

  type ProductInList = { name: string; count: number; category: string; };

  const productList = React.useMemo(() => {
    const unassignedCategory = t('unassignedCategory');
    const productMap = new Map<string, { name: string; count: number }>();
    images.forEach(image => {
      if (image.analysisResult?.products && Array.isArray(image.analysisResult.products)) {
        image.analysisResult.products.forEach(product => {
          if (!product || !product.name) return;
          const currentName = product.name.trim();
          const existingCanonicalNames = Array.from(productMap.keys());
          const matchedCanonicalName = findBestMatch(currentName, existingCanonicalNames);

          const canonicalName = matchedCanonicalName || currentName;

          const entry = productMap.get(canonicalName);
          if (entry) {
            entry.count++;
          } else {
            productMap.set(canonicalName, { name: canonicalName, count: 1 });
          }
        });
      }
    });
    return Array.from(productMap.values())
      .map(({ name, count }) => ({ name, count, category: getCategoryFromName(name, unassignedCategory) }))
      .sort((a, b) => {
        const catCompare = a.category.localeCompare(b.category);
        if (catCompare !== 0) return catCompare;
        return b.count - a.count;
      });
  }, [images, t]);

  const groupedProducts: Record<string, ProductInList[]> = React.useMemo(() => {
    return productList.reduce<Record<string, ProductInList[]>>((acc, product) => {
        const category = product.category;
        if (!acc[category]) {
            acc[category] = [];
        }
        acc[category].push(product);
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [productList]);

  const filteredGroupedProducts = React.useMemo(() => {
    if (!productSearchTerm) return groupedProducts;
    const lowercasedTerm = productSearchTerm.toLowerCase();
    return Object.entries(groupedProducts).reduce<typeof groupedProducts>((acc, [category, products]) => {
        const filtered = products.filter(p => p.name.toLowerCase().includes(lowercasedTerm));
        if (filtered.length > 0) {
            acc[category] = filtered;
        }
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [groupedProducts, productSearchTerm]);

  const handleProductNameUpdate = React.useCallback(async (imageId: string, productId: string, originalName: string, newName: string) => {
    setImages(prevImages =>
      prevImages.map(image => {
        if (image.id !== imageId) return image;
        if (!image.analysisResult || !Array.isArray(image.analysisResult.products)) return image;

        const updatedProducts = image.analysisResult.products.map(p =>
          p.id === productId ? { ...p, name: newName, isCorrected: false } : p
        );

        return { ...image, analysisResult: { ...image.analysisResult, products: updatedProducts } };
      })
    );
    await addOrUpdateProductCorrection(originalName, newName);
  }, []);

  const selectedImage = React.useMemo(() => images.find(img => img.id === selectedImageId), [images, selectedImageId]);

  const handleSummaryClick = () => {
    setSelectedImageId(null);
    setSelectedProductName(null);
    setHighlightedProductName(null);
  };

  const handleNavClick = (view: ActiveView) => {
    setActiveView(view);
    setSelectedCatalogProduct(null);
    if (view !== 'home' && images.length > 0) { 
        handleSummaryClick();
    } 
  };

  const handleSelectImage = (id: string, productNameToHighlight: string | null = null) => {
    setSelectedImageId(id);
    setSelectedProductName(null);
    setHighlightedProductName(productNameToHighlight);
  };

  const handleProductClick = (name: string) => {
    setSelectedProductName(name);
    setSelectedImageId(null);
    setHighlightedProductName(null);
  };

  const handleSaveAnalysis = async () => {
    if (!activeAnalysis) return;
    try {
        let totalInput = 0;
        let totalOutput = 0;
        let usedModelName = '';

        const serializableImages: SerializableImageState[] = await Promise.all(
          images.map(async (image) => {
            const base64Data = await fileToBase64(image.file);

            if (image.analysisResult?.usageMetadata) {
                totalInput += image.analysisResult.usageMetadata.promptTokenCount || 0;
                totalOutput += image.analysisResult.usageMetadata.candidatesTokenCount || 0;
            }
            if (!usedModelName && image.analysisResult?.modelName) {
                usedModelName = image.analysisResult.modelName;
            }

            return {
              id: image.id,
              file: {
                name: image.file.name,
                type: image.file.type,
                lastModified: image.file.lastModified,
                data: base64Data,
              },
              imageUrl: '',
              analysisResult: image.analysisResult,
              status: image.status,
              error: image.error,
              uploadDate: image.uploadDate.toISOString(),
              analysisType: image.analysisType,
              retryCount: image.retryCount,
              assignedStore: image.assignedStore,
              assignedStoreId: image.assignedStoreId
            };
          })
        );

        const inRate = await getSetting('inputTokenRate', 0.10);
        const outRate = await getSetting('outputTokenRate', 0.40);
        const cost = ((totalInput / 1000000) * inRate) + ((totalOutput / 1000000) * outRate);

        const updatedAnalysis: Analysis = {
          ...activeAnalysis,
          images: serializableImages,
          brandClassifications: brandClassifications,
          storeId: serializableImages[0]?.assignedStoreId,
          costInfo: {
              inputTokens: totalInput,
              outputTokens: totalOutput,
              cost: cost,
              modelName: usedModelName
          }
        };

        await saveAnalysis(updatedAnalysis);
        setActiveAnalysis(updatedAnalysis);
    } catch (e) {
        console.error("Failed to save analysis:", e);
        alert(t('archiveSaveError'));
    }
  };

  const handleLoadAnalysis = async (analysisId: string) => {
    try {
        const analysisToLoad = await loadAnalysis(analysisId);

        if (analysisToLoad) {
          endCurrentAnalysisWithoutSaving();

          const loadedImages: ImageState[] = analysisToLoad.images.map(serializableImage => {
            const file = base64ToFile(
              serializableImage.file.data,
              serializableImage.file.name,
              serializableImage.file.type,
              serializableImage.file.lastModified
            );
            return {
              ...serializableImage,
              file,
              imageUrl: URL.createObjectURL(file),
              uploadDate: new Date(serializableImage.uploadDate),
              status: serializableImage.status || 'success', 
              analysisType: (serializableImage.analysisType || 'both') as AnalysisType,
              retryCount: serializableImage.retryCount || 0,
              assignedStoreId: serializableImage.assignedStoreId
            };
          });

          setActiveAnalysis(analysisToLoad);
          setImages(loadedImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
          setBrandClassifications(analysisToLoad.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');
        }
    } catch (e) {
        console.error("Failed to load analysis:", e);
        alert(t('archiveLoadError'));
    }
  };

  const handleMergeConfirm = async (sourceName: string, targetName: string) => {
    await addOrUpdateProductCorrection(sourceName, targetName);

    setImages(prevImages =>
      prevImages.map(image => {
        if (!image.analysisResult?.products) return image;

        const updatedProducts = image.analysisResult.products.map(p => {
            const isMatch = normalizeProductName(p.name) === normalizeProductName(sourceName);
            return isMatch ? { ...p, name: targetName, isCorrected: true } : p;
        });

        return { ...image, analysisResult: { ...image.analysisResult, products: updatedProducts } };
      })
    );
    setMergeCandidates(prev => prev.slice(1));
  };

  const handleMergeReject = () => {
    setMergeCandidates(prev => prev.slice(1));
  };


  const isSummarySelected = !selectedImageId && !selectedProductName;

  if (!hasApiKey) {
    return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;
  }

  // --- RENDEROVANIE MODULOV S UVÍTACÍMI OBRAZOVKAMI ---
  // FIX: Changed viewType type to match BatchSummaryPanel's expected initialView type, replacing 'priceAnalysis' with 'priceMonitoring'
  const renderAnalysisModule = (title: string, icon: React.ElementType, description: string, viewType: 'priceMonitoring' | 'shelfShare' | 'promoAlert') => {
    if (!activeAnalysis && images.length === 0) {
        return (
            <div className="bg-white p-12 rounded-3xl shadow-sm border border-gray-100 text-center max-w-4xl mx-auto animate-fade-in">
                <div className="w-24 h-24 bg-lime-50 rounded-[2rem] flex items-center justify-center mx-auto mb-8 transition-transform hover:scale-110 duration-500">
                    {icon({ className: "w-12 h-12 text-lime-600" })}
                </div>
                <h2 className="text-3xl font-black text-gray-900 mb-4 tracking-tight">
                    {title}
                </h2>
                <p className="text-gray-500 mb-10 max-w-md mx-auto text-lg leading-relaxed">
                    {description}
                </p>
                <button
                    onClick={handleNewAnalysisClick}
                    className="inline-flex items-center gap-3 px-10 py-4 bg-lime-600 text-white font-black rounded-2xl hover:bg-lime-500 transition-all shadow-2xl shadow-lime-100 uppercase tracking-widest text-sm active:scale-95"
                >
                    <CalendarDaysIcon className="w-5 h-5" />
                    {t('startNewAnalysis')}
                </button>
            </div>
        );
    }

    if (images.length === 0) {
        return (
            <div className="w-full h-full flex items-center justify-center">
                <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
            </div>
        );
    }

    return (
        <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8 main-grid-container">
            <aside className="lg:col-span-1 bg-white p-4 rounded-lg shadow-sm flex flex-col gap-4 self-start border border-gray-200 no-print">
                <div className="flex justify-between items-center mb-2 no-print">
                  <h3 className="font-bold text-gray-900 text-lg">
                    {sidebarView === 'images' ? t('images') : t('products')}
                  </h3>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setSidebarView('images')} className={`p-1 rounded-md text-sm font-medium ${sidebarView === 'images' ? 'bg-lime-100 text-lime-700' : 'text-gray-500 hover:bg-gray-100'}`} title={t('viewImages')}><AppIcon className="w-5 h-5" /></button>
                    <button onClick={() => setSidebarView('products')} className={`p-1 rounded-md text-sm font-medium ${sidebarView === 'products' ? 'bg-lime-100 text-lime-700' : 'text-gray-500 hover:bg-gray-100'}`} title={t('viewProducts')}><CircleStackIcon className="w-5 h-5" /></button>
                  </div>
                </div>

                {sidebarView === 'images' ? (
                  <>
                    <input
                      type="text"
                      placeholder={t('searchImages')}
                      value={productSearchTerm}
                      onChange={(e) => setProductSearchTerm(e.target.value)}
                      className="w-full rounded-md border-0 bg-gray-50 py-1.5 pl-3 pr-3 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-lime-500 sm:text-sm mb-4 no-print"
                    />
                    <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
                      {images.filter(img => productSearchTerm === '' || img.file.name.toLowerCase().includes(productSearchTerm.toLowerCase())).map((image) => (
                        <div
                          key={image.id}
                          onClick={() => handleSelectImage(image.id)}
                          className={`flex items-center gap-3 p-3 rounded-md cursor-pointer transition-colors mb-2 border ${
                            selectedImageId === image.id ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                          }`}
                        >
                          <img src={image.imageUrl} alt={image.file.name} className="w-12 h-12 object-cover rounded-md flex-shrink-0" />
                          <div className="flex-grow min-w-0">
                            <p className="font-medium text-gray-800 truncate">{image.file.name}</p>
                            <p className="text-xs text-gray-500">{image.uploadDate.toLocaleDateString()}</p>
                          </div>
                          {image.status === 'analyzing' && <SpinnerIcon className="w-4 h-4 text-lime-500" />}
                          {image.status === 'error' && <WarningIcon className="w-4 h-4 text-red-500" title={image.error || t('errorOccurred')} />}
                          {image.status === 'success' && image.analysisResult?.products.length === 0 && <span className="text-xs text-gray-500 italic">{t('noProductsFound')}</span>}
                        </div>
                      ))}
                    </div>
                  </>
                ) : (
                  <>
                    <input
                        type="text"
                        placeholder={t('searchProduct')}
                        value={productSearchTerm}
                        onChange={(e) => setProductSearchTerm(e.target.value)}
                        className="w-full rounded-md border-0 bg-gray-50 py-1.5 pl-3 pr-3 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-lime-500 sm:text-sm mb-4 no-print"
                    />
                    <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
                        {Object.keys(filteredGroupedProducts).length > 0 ? (
                            Object.entries(filteredGroupedProducts).map(([category, products]: [string, ProductInList[]]) => (
                                <div key={category} className="mb-4">
                                    <h4 className="text-xs font-semibold text-gray-500 uppercase mb-2 px-1">{category}</h4>
                                    {products.map(product => (
                                        <button
                                            key={product.name}
                                            onClick={() => handleProductClick(product.name)}
                                            className={`flex justify-between items-center w-full p-3 rounded-md transition-colors mb-2 border ${
                                                selectedProductName === product.name ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                                            }`}
                                        >
                                            <span className="font-medium text-gray-800 truncate">{product.name}</span>
                                            <span className="text-sm font-semibold text-lime-600 flex-shrink-0">{product.count}</span>
                                        </button>
                                    ))}
                                </div>
                            ))
                        ) : (
                            <div className="text-center py-10 text-sm text-gray-500">
                                {t('noProductsFound')}
                            </div>
                        )}
                    </div>
                  </>
                )}
                {images.length > 0 && (
                    <div className="mt-4 border-t border-gray-200 pt-4 no-print">
                        <button
                            onClick={handleAddMoreClick}
                            className="w-full flex justify-center items-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-lime-600 hover:bg-lime-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500"
                        >
                            <UploadIcon className="w-5 h-5" />
                            {t('addMoreImages')}
                        </button>
                    </div>
                )}
            </aside>

            <main className="lg:col-span-3 flex flex-col gap-8">
                {isSummarySelected && (
                    <BatchSummaryPanel 
                        images={images} 
                        brandClassifications={brandClassifications} 
                        onReset={endCurrentAnalysisAndSave} 
                        // FIX: Removed 'as any' as the type viewType now correctly matches initialView expectations
                        initialView={viewType} 
                        onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} 
                    />
                )}

                {selectedImageId && selectedImage && (
                    <ImageAnalysisDisplay imageUrl={selectedImage.imageUrl} analysisResult={selectedImage.analysisResult} isLoading={selectedImage.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                )}

                {selectedImageId && selectedImage && (
                    <ResultsPanel
                        imageId={selectedImage.id}
                        analysisResult={selectedImage.analysisResult}
                        isLoading={selectedImage.status === 'analyzing'}
                        error={selectedImage.error}
                        onReset={endCurrentAnalysisAndSave}
                        onProductNameUpdate={handleProductNameUpdate}
                        onRetry={() => handleRetryImage(selectedImage.id)}
                    />
                )}

                {selectedProductName && (
                    <ProductSummaryPanel productName={selectedProductName} images={images} onReset={endCurrentAnalysisAndSave} onImageSelect={handleSelectImage} />
                )}
            </main>
        </div>
    );
  };

  const renderMainContent = (): React.ReactNode => {
    if (activeView === 'home') {
        return <HomeScreen onStartAnalysis={() => {
            handleNewAnalysisClick();
        }} />;
    }
    if (activeView === 'listing') return <ListingPanel />;
    if (activeView === 'productCatalog') {
        if (selectedCatalogProduct) {
            return <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} />;
        }
        return <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />;
    }
    if (activeView === 'analyses') return <AnalysesPanel onNewAnalysis={handleNewAnalysisClick} onLoadAnalysis={handleLoadAnalysis} />;
    if (activeView === 'stores') return <StoresPanel />;
    if (activeView === 'distribution') return <DistributionPanel activeImages={images} />;
    if (activeView === 'costs') return <CostPanel />;
    if (activeView === 'prompts') return <PromptManagerPanel />;

    // --- ANALYTICKÉ MODULY ---
    if (activeView === 'priceMonitoring') {
        // FIX: Fourth argument is correctly "priceMonitoring" to match updated renderAnalysisModule signature
        return renderAnalysisModule(t('priceMonitoring'), ChartBarIcon, "Sledujte a porovnávajte ceny produktov na regáloch v reálnom čase pomocou umelej inteligencie.", "priceMonitoring");
    }
    if (activeView === 'shelfShare') {
        return renderAnalysisModule(t('shelfShare'), ChartPieIcon, "Analyzujte vizuálny podiel vašich značiek na regáli a porovnávajte ho s konkurenciou.", "shelfShare");
    }
    if (activeView === 'promoAlert') {
        return (
            <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                <h2 className="text-xl font-bold text-gray-900 mb-6 flex items-center gap-2">
                    <ShieldExclamationIcon className="w-6 h-6 text-lime-600" />
                    {t('promoAlert')}
                </h2>
                <PromoAlertPanel images={images} brandClassifications={brandClassifications} />
            </div>
        );
    }

    return (
        <div className="w-full h-full flex items-center justify-center">
             <HomeScreen onStartAnalysis={handleNewAnalysisClick} />
        </div>
    );
  };

  return (
    <React.Fragment>
      <div className="min-h-screen bg-gray-100 flex flex-col">
        <Header onNewAnalysis={handleNewAnalysisClick} onOpenSearch={() => setIsSearchModalOpen(true)} />
        <div className="flex flex-1 overflow-hidden">
          <Sidebar activeView={activeView} onNavClick={handleNavClick} />
          <div className="flex-1 p-6 overflow-y-auto">
            {renderMainContent()}
          </div>
        </div>
      </div>
      <div className="modal-overlays-container">
        <NewAnalysisModal
            isOpen={isNewAnalysisModalOpen}
            onClose={() => setIsNewAnalysisModalOpen(false)}
            onConfirm={handleStartAnalysis}
            initialFiles={pendingFiles}
        />

        <ClearConfirmModal
          isOpen={isClearConfirmOpen}
          onClose={() => setIsClearConfirmOpen(false)}
          onConfirmDelete={endCurrentAnalysisWithoutSaving}
          onSaveToArchive={endCurrentAnalysisAndSave}
        />

        <BrandDefinitionModal
          isOpen={isBrandModalOpen}
          onClose={() => setIsBrandModalOpen(false)}
          onConfirm={handleConfirmBrands}
          allBrands={Object.keys(brandProductsMap)}
          brandProductsMap={brandProductsMap}
        />

        <SearchModal
          isOpen={isSearchModalOpen}
          onClose={() => setIsSearchModalOpen(false)}
          onLoadAnalysis={handleLoadAnalysis}
        />

        {mergeCandidates.length > 0 && (
            <MergeConfirmationModal
                isOpen={true}
                candidate={mergeCandidates[0]}
                onConfirm={handleMergeConfirm}
                onReject={handleMergeReject}
                onClose={handleMergeReject}
            />
        )}

         {missingPriceItems.length > 0 && (
              <MissingPriceModal
                  isOpen={isMissingPriceModalOpen}
                  onClose={() => setIsMissingPriceModalOpen(false)}
                  items={missingPriceItems}
                  onSave={handleUpdatePrices}
              />
         )}

        {isImageUploadOverlayOpen && (
            <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true" aria-labelledby="image-upload-modal-title">
                <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all">
                    <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-gray-50 rounded-t-lg">
                        <h2 id="image-upload-modal-title" className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            <UploadIcon className="w-6 h-6 text-lime-600" />
                            {t('uploadMoreImagesTitle')}
                        </h2>
                        <button onClick={() => setIsImageUploadOverlayOpen(false)} className="text-gray-400 hover:text-gray-600">
                            <CloseIcon className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6">
                        <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </React.Fragment>
  );
};

export default App;

