                          onClick={() => handleSelectImage(image.id)}
                          className={`flex items-center gap-3 p-3 rounded-md cursor-pointer transition-colors mb-2 border ${
                            selectedImageId === image.id ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                          }`}
                        >
                          <img src={image.imageUrl} alt={image.file.name} className="w-12 h-12 object-cover rounded-md flex-shrink-0" />
                          <div className="flex-grow min-w-0">
                            <p className="font-medium text-gray-800 truncate">{image.file.name}</p>
                            <p className="text-xs text-gray-500">{image.uploadDate.toLocaleDateString()}</p>
                          </div>
                          {image.status === 'analyzing' && <SpinnerIcon className="w-4 h-4 text-lime-500" />}
                          {image.status === 'error' && <WarningIcon className="w-4 h-4 text-red-500" title={image.error || t('errorOccurred')} />}
                          {image.status === 'success' && image.analysisResult?.products.length === 0 && <span className="text-xs text-gray-500 italic">{t('noProductsFound')}</span>}
                        </div>
                      ))}
                    </div>
                  </>
                ) : (
                  <>
                    <input
                        type="text"
                        placeholder={t('searchProduct')}
                        value={productSearchTerm}
                        onChange={(e) => setProductSearchTerm(e.target.value)}
                        className="w-full rounded-md border-0 bg-gray-50 py-1.5 pl-3 pr-3 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-lime-500 sm:text-sm mb-4 no-print"
                    />
                    <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
                        {Object.keys(filteredGroupedProducts).length > 0 ? (
                            Object.entries(filteredGroupedProducts).map(([category, products]: [string, ProductInList[]]) => (
                                <div key={category} className="mb-4">
                                    <h4 className="text-xs font-semibold text-gray-500 uppercase mb-2 px-1">{category}</h4>
                                    {products.map(product => (
                                        <button
                                            key={product.name}
                                            onClick={() => handleProductClick(product.name)}
                                            className={`flex justify-between items-center w-full p-3 rounded-md transition-colors mb-2 border ${
                                                selectedProductName === product.name ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                                            }`}
                                        >
                                            <span className="font-medium text-gray-800 truncate">{product.name}</span>
                                            <span className="text-sm font-semibold text-lime-600 flex-shrink-0">{product.count}</span>
                                        </button>
                                    ))}
                                </div>
                            ))
                        ) : (
                            <div className="text-center py-10 text-sm text-gray-500">
                                {t('noProductsFound')}
                            </div>
                        )}
                    </div>
                  </>
                )}
                {images.length > 0 && (
                    <div className="mt-4 border-t border-gray-200 pt-4 no-print">
                        <button
                            onClick={handleAddMoreClick}
                            className="w-full flex justify-center items-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-lime-600 hover:bg-lime-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500"
                        >
                            <UploadIcon className="w-5 h-5" />
                            {t('addMoreImages')}
                        </button>
                    </div>
                )}
            </aside>

            <main className="lg:col-span-3 flex flex-col gap-8">
                {isSummarySelected && (
                    <BatchSummaryPanel 
                        images={images} 
                        brandClassifications={brandClassifications} 
                        onReset={endCurrentAnalysisAndSave} 
                        initialView={viewType as any} 
                        onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} 
                    />
                )}

                {selectedImageId && selectedImage && (
                    <ImageAnalysisDisplay imageUrl={selectedImage.imageUrl} analysisResult={selectedImage.analysisResult} isLoading={selectedImage.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                )}

                {selectedImageId && selectedImage && (
                    <ResultsPanel
                        imageId={selectedImage.id}
                        analysisResult={selectedImage.analysisResult}
                        isLoading={selectedImage.status === 'analyzing'}
                        error={selectedImage.error}
                        onReset={endCurrentAnalysisAndSave}
                        onProductNameUpdate={handleProductNameUpdate}
                        onRetry={() => handleRetryImage(selectedImage.id)}
                    />
                )}

                {selectedProductName && (
                    <ProductSummaryPanel productName={selectedProductName} images={images} onReset={endCurrentAnalysisAndSave} onImageSelect={handleSelectImage} />
                )}
            </main>
        </div>
    );
  };

  const renderMainContent = (): React.ReactNode => {
    if (activeView === 'home') {
        return <HomeScreen onStartAnalysis={() => {
            handleNewAnalysisClick();
        }} />;
    }
    if (activeView === 'listing') return <ListingPanel />;
    if (activeView === 'productCatalog') {
        if (selectedCatalogProduct) {
            return <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} />;
        }
        return <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />;
    }
    if (activeView === 'analyses') return <AnalysesPanel onNewAnalysis={handleNewAnalysisClick} onLoadAnalysis={handleLoadAnalysis} />;
    if (activeView === 'stores') return <StoresPanel />;
    if (activeView === 'costs') return <CostPanel />;
    if (activeView === 'prompts') return <PromptManagerPanel />;

    // --- ANALYTICKÉ MODULY ---
    if (activeView === 'priceMonitoring') {
        return renderAnalysisModule(t('priceMonitoring'), ChartBarIcon, "Sledujte a porovnávajte ceny produktov na regáloch v reálnom čase pomocou umelej inteligencie.", "priceMonitoring");
    }
    if (activeView === 'shelfShare') {
        return renderAnalysisModule(t('shelfShare'), ChartPieIcon, "Analyzujte vizuálny podiel vašich značiek na regáli a porovnávajte ho s konkurenciou.", "shelfShare");
    }
    if (activeView === 'promoAlert') {
        return renderAnalysisModule(t('promoAlert'), ShieldExclamationIcon, "Monitorujte promo akcie konkurencie a kontrolujte správnosť nasadenia vašich vlastných akcií.", "promoAlert");
    }
    if (activeView === 'distribution') {
        return renderAnalysisModule(t('distributionModule'), TableCellsIcon, "Sledujte dostupnosť vašich produktov naprieč všetkými predajňami a identifikujte výpadky (Out-of-Stock) v reálnom čase.", "distribution");
    }

    return (
        <div className="w-full h-full flex items-center justify-center">
             <HomeScreen onStartAnalysis={handleNewAnalysisClick} />
        </div>
    );
  };

  return (
    <React.Fragment>
      <div className="min-h-screen bg-gray-100 flex flex-col">
        <Header onNewAnalysis={handleNewAnalysisClick} onOpenSearch={() => setIsSearchModalOpen(true)} />
        <div className="flex flex-1 overflow-hidden">
          <Sidebar activeView={activeView} onNavClick={handleNavClick} />
          <div className="flex-1 p-6 overflow-y-auto">
            {renderMainContent()}
          </div>
        </div>
      </div>
      <div className="modal-overlays-container">
        <NewAnalysisModal
            isOpen={isNewAnalysisModalOpen}
            onClose={() => setIsNewAnalysisModalOpen(false)}
            onConfirm={handleStartAnalysis}
            initialFiles={pendingFiles}
        />

        <ClearConfirmModal
          isOpen={isClearConfirmOpen}
          onClose={() => setIsClearConfirmOpen(false)}
          onConfirmDelete={endCurrentAnalysisWithoutSaving}
          onSaveToArchive={endCurrentAnalysisAndSave}
        />

        <BrandDefinitionModal
          isOpen={isBrandModalOpen}
          onClose={() => setIsBrandModalOpen(false)}
          onConfirm={handleConfirmBrands}
          allBrands={Object.keys(brandProductsMap)}
          brandProductsMap={brandProductsMap}
        />

        <SearchModal
          isOpen={isSearchModalOpen}
          onClose={() => setIsSearchModalOpen(false)}
          onLoadAnalysis={handleLoadAnalysis}
        />

        {mergeCandidates.length > 0 && (
            <MergeConfirmationModal
                isOpen={true}
                candidate={mergeCandidates[0]}
                onConfirm={handleMergeConfirm}
                onReject={handleMergeReject}
                onClose={handleMergeReject}
            />
        )}

         {missingPriceItems.length > 0 && (
              <MissingPriceModal
                  isOpen={isMissingPriceModalOpen}
                  onClose={() => setIsMissingPriceModalOpen(false)}
                  items={missingPriceItems}
                  onSave={handleUpdatePrices}
              />
         )}

        {isImageUploadOverlayOpen && (
            <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true" aria-labelledby="image-upload-modal-title">
                <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all">
                    <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-gray-50 rounded-t-lg">
                        <h2 id="image-upload-modal-title" className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            <UploadIcon className="w-6 h-6 text-lime-600" />
                            {t('uploadMoreImagesTitle')}
                        </h2>
                        <button onClick={() => setIsImageUploadOverlayOpen(false)} className="text-gray-400 hover:text-gray-600">
                            <CloseIcon className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6">
                        <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </React.Fragment>
  );
};

export default App;

export interface BoundingBox {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface PriceInfo {
  value: string;
  type: string;
}

export interface DetectedProduct {
  id: string;
  imageId?: string;
  name: string;
  brand?: string;
  prices?: PriceInfo[];
  boundingBox: BoundingBox;
  confidence: number;
  isCorrected?: boolean;
  catalogProductId?: number; // Link to master data
}

export interface StoreInfo {
  chain?: string;
  address?: string;
}

export interface AnalysisResult {
  products: DetectedProduct[];
  storeInfo?: StoreInfo;
  modelName?: string; 
  usageMetadata?: { 
    promptTokenCount: number;
    candidatesTokenCount: number;
    totalTokenCount: number;
  };
}

export interface CostInfo {
  inputTokens: number;
  outputTokens: number;
