export type ActiveView = 'home' | 'gallery' | 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'distribution' | 'listing' | 'productCatalog' | 'analyses' | 'stores' | 'costs' | 'prompts';

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses, getCatalogProductNames, getStores } from '../db.ts';
import type { Analysis, SerializableImageState, DetectedProduct, Store } from '../types.ts';
import { getCategoryFromName, findBestMatch, base64ToFile } from '../utils/helpers.ts';
import { 
    AppIcon, 
    SpinnerIcon, 
    SearchIcon, 
    BuildingStorefrontIcon, 
    TagIcon, 
    CloseIcon, 
    CalendarDaysIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    CircleStackIcon
} from './Icons.tsx';

interface GalleryItem {
    id: string;
    analysisId: string;
    analysisName: string;
    imageUrl: string;
    uploadDate: Date;
    storeName: string;
    products: DetectedProduct[];
    rawImage: SerializableImageState;
}

export const GalleryPanel: React.FC = () => {
    const { t } = useTranslation();
    const [items, setItems] = useState<GalleryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedItem, setSelectedItem] = useState<GalleryItem | null>(null);

    // Filtre
    const [searchProduct, setSearchProduct] = useState('');
    const [selectedStore, setSelectedStore] = useState('all');
    const [selectedCategory, setSelectedCategory] = useState('all');

    // Metadáta pre filtre
    const [allStores, setAllStores] = useState<string[]>([]);
    const [allCategories, setAllCategories] = useState<string[]>([]);

    useEffect(() => {
        const loadGallery = async () => {
            setIsLoading(true);
            try {
                const analyses = await getAnalyses();
                const flattened: GalleryItem[] = [];
                const storesSet = new Set<string>();
                const categoriesSet = new Set<string>();

                analyses.forEach(analysis => {
                    const storeName = analysis.store?.name || t('unknownStore');
                    storesSet.add(storeName);

                    analysis.images.forEach(img => {
                        const file = base64ToFile(img.file.data, img.file.name, img.file.type, img.file.lastModified);
                        const url = URL.createObjectURL(file);

                        const products = img.analysisResult?.products || [];
                        products.forEach(p => {
                            categoriesSet.add(getCategoryFromName(p.name, t('unassignedCategory')));
                        });

                        flattened.push({
                            id: img.id,
                            analysisId: analysis.id,
                            analysisName: analysis.name,
                            imageUrl: url,
                            uploadDate: new Date(img.uploadDate),
                            storeName,
                            products,
                            rawImage: img
                        });
                    });
                });

                setItems(flattened.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
                setAllStores(Array.from(storesSet).sort());
                setAllCategories(Array.from(categoriesSet).sort());
            } catch (e) {
                console.error("Gallery load error:", e);
            } finally {
                setIsLoading(false);
            }
        };
        loadGallery();

        return () => {
            items.forEach(item => URL.revokeObjectURL(item.imageUrl));
        };
    }, []);

    const filteredItems = useMemo(() => {
        return items.filter(item => {
            const matchesProduct = searchProduct === '' || 
                item.products.some(p => p.name.toLowerCase().includes(searchProduct.toLowerCase()));

            const matchesStore = selectedStore === 'all' || item.storeName === selectedStore;

            const matchesCategory = selectedCategory === 'all' || 
                item.products.some(p => getCategoryFromName(p.name, t('unassignedCategory')) === selectedCategory);

            return matchesProduct && matchesStore && matchesCategory;
        });
    }, [items, searchProduct, selectedStore, selectedCategory, t]);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-64">
                <SpinnerIcon className="w-12 h-12 text-lime-600 animate-spin" />
                <p className="mt-4 text-gray-500 font-medium">{t('pleaseWait')}</p>
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            {/* Filter Bar */}
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col md:flex-row gap-4 items-center sticky top-0 z-20">
                <div className="relative flex-grow w-full">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input 
                        type="text"
                        placeholder={t('filterByProduct')}
                        className="w-full pl-11 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-lime-500"
                        value={searchProduct}
                        onChange={(e) => setSearchProduct(e.target.value)}
                    />
                </div>

                <div className="flex gap-2 w-full md:w-auto">
                    <select 
                        className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500"
                        value={selectedStore}
                        onChange={(e) => setSelectedStore(e.target.value)}
                    >
                        <option value="all">{t('allStores')}</option>
                        {allStores.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>

                    <select 
                        className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500"
                        value={selectedCategory}
                        onChange={(e) => setSelectedCategory(e.target.value)}
                    >
                        <option value="all">{t('allCategories')}</option>
                        {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {/* Gallery Grid */}
            {filteredItems.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
                    {filteredItems.map(item => (
                        <div 
                            key={item.id}
                            onClick={() => setSelectedItem(item)}
                            className="group relative aspect-square bg-gray-200 rounded-2xl overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1"
                        >
                            <img 
                                src={item.imageUrl} 
                                alt={item.analysisName} 
                                className="w-full h-full object-cover"
                                loading="lazy"
                            />
                            {/* Overlay info */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-3 flex flex-col justify-end">
                                <p className="text-white text-[10px] font-black uppercase tracking-widest truncate">{item.storeName}</p>
                                <p className="text-white/80 text-[10px] font-medium">{item.uploadDate.toLocaleDateString()}</p>
                                <div className="mt-1 flex items-center gap-1">
                                    <span className="bg-lime-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded-full">
                                        {item.products.length} {t('totalLabel')}
                                    </span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="bg-white rounded-3xl p-20 text-center border border-dashed border-gray-200">
                    <AppIcon className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400 font-medium">{t('noImagesInGallery')}</p>
                </div>
            )}

            {/* Detail Lightbox */}
            {selectedItem && (
                <div className="fixed inset-0 bg-gray-950/95 z-[100] flex animate-fade-in">
                    <div className="flex-grow relative flex items-center justify-center p-4">
                        <img 
                            src={selectedItem.imageUrl} 
                            alt="Full preview"
                            className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
                        />
                        <button 
                            onClick={() => setSelectedItem(null)}
                            className="absolute top-6 left-6 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all backdrop-blur-md"
                        >
                            <ArrowLeftIcon className="w-6 h-6" />
                        </button>
                    </div>

                    {/* Side Info Panel */}
                    <div className="w-full md:w-[400px] bg-white h-full flex flex-col shadow-[-10px_0_30px_rgba(0,0,0,0.2)]">
                        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                            <h3 className="text-xl font-black text-gray-900">{t('photoDetail')}</h3>
                            <button onClick={() => setSelectedItem(null)} className="p-2 text-gray-400 hover:text-gray-600"><CloseIcon className="w-6 h-6" /></button>
                        </div>

                        <div className="flex-grow overflow-y-auto p-6 space-y-8">
                            {/* Metadata */}
                            <section className="space-y-4">
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-blue-50 rounded-xl">
                                        <BuildingStorefrontIcon className="w-6 h-6 text-blue-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{t('storeName')}</p>
                                        <p className="text-lg font-black text-gray-900">{selectedItem.storeName}</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-orange-50 rounded-xl">
                                        <CalendarDaysIcon className="w-6 h-6 text-orange-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{t('detectedAt')}</p>
                                        <p className="text-base font-bold text-gray-700">{selectedItem.uploadDate.toLocaleString()}</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-lime-50 rounded-xl">
                                        <CircleStackIcon className="w-6 h-6 text-lime-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Analýza</p>
                                        <p className="text-base font-bold text-gray-700">{selectedItem.analysisName}</p>
                                    </div>
                                </div>
                            </section>

                            {/* Products List */}
                            <section>
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="text-sm font-black text-gray-900 uppercase tracking-widest">{t('productsOnImage')}</h4>
                                    <span className="bg-lime-600 text-white text-[10px] font-black px-2 py-1 rounded-lg uppercase">{selectedItem.products.length} ks</span>
                                </div>
                                <div className="space-y-2">
                                    {selectedItem.products.map((p, idx) => (
                                        <div key={idx} className="bg-gray-50 p-3 rounded-xl border border-gray-100 flex justify-between items-center">
                                            <div className="min-w-0">
                                                <p className="text-xs text-lime-700 font-bold uppercase tracking-tighter">{getCategoryFromName(p.name, t('unassignedCategory'))}</p>
                                                <p className="text-sm font-bold text-gray-800 truncate pr-2">{p.name}</p>
                                            </div>
                                            {p.prices && p.prices.length > 0 && (
                                                <div className="flex-shrink-0">
                                                    <span className={`text-xs font-black px-2 py-1 rounded-md ${p.prices[0].type === 'PROMO' ? 'bg-red-100 text-red-600' : 'bg-gray-200 text-gray-700'}`}>
                                                        {p.prices[0].value}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            </section>
                        </div>

                        {/* Actions */}
                        <div className="p-6 bg-gray-50 border-t border-gray-100">
                             <button 
                                onClick={() => {
                                    // Tu by sme v budúcnosti mohli pridať navigáciu priamo do analýzy
                                    setSelectedItem(null);
                                }}
                                className="w-full py-4 bg-gray-900 text-white font-black rounded-2xl hover:bg-black transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                             >
                                <ChevronRightIcon className="w-5 h-5 text-lime-500" />
                                {t('viewInAnalysis')}
                             </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

