import React, { useMemo, useState } from 'react';
import type { AnalysisResult, PriceInfo, DetectedProduct } from '../types.ts';
import { SpinnerIcon, WarningIcon, EditIcon, ArchiveBoxIcon, TrashIcon, MagicWandIcon, ArrowPathIcon } from './Icons.tsx';
import { FilterControls, Filters } from './FilterControls.tsx';
import { getCategoryFromName, findBestMatch } from '../utils/helpers.ts';
import { useTranslation } from '../i18n/index.tsx';

interface ResultsPanelProps {
  analysisResult: AnalysisResult | null;
  isLoading: boolean;
  error: string | null;
  imageId: string;
  onProductNameUpdate: (imageId: string, productId: string, originalName: string, newName: string) => void;
  onRetry: () => void;
}

interface ProductSummaryWithCategory {
    id: string; // Keep one of the product IDs for this group
    name: string;
    isCorrected?: boolean;
    originalName?: string; // To keep track of what to save for the catalog
    category: string;
    count: number;
    prices: PriceInfo[];
    confidences: number[];
    avgConfidence: number;
}

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

export const ResultsPanel: React.FC<ResultsPanelProps> = ({ analysisResult, isLoading, error, imageId, onProductNameUpdate, onRetry }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingValue, setEditingValue] = useState('');
  const [originalEditingName, setOriginalEditingName] = useState('');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');

  const { filteredProductSummary, allCategories } = useMemo(() => {
    if (!analysisResult?.products || !Array.isArray(analysisResult.products)) return { filteredProductSummary: [], allCategories: [] };

    const summaryMap = new Map<string, { products: DetectedProduct[] }>();

    analysisResult.products.filter(p => p && p.name).forEach(product => {
      const currentName = product.name.trim();
      const existingCanonicalNames = Array.from(summaryMap.keys());
      const matchedCanonicalName = findBestMatch(currentName, existingCanonicalNames);

      const canonicalName = matchedCanonicalName || currentName;

      const entry = summaryMap.get(canonicalName);
      if (entry) {
        entry.products.push(product);
      } else {
        summaryMap.set(canonicalName, { products: [product] });
      }
    });

    const summarized: ProductSummaryWithCategory[] = Array.from(summaryMap.values()).map(({ products }) => {
      const firstProduct = products[0];
      const allPrices = products.flatMap(p => p.prices || []);
      const allConfidences = products.map(p => p.confidence);

      return {
        id: firstProduct.id,
        name: firstProduct.name,
        isCorrected: firstProduct.isCorrected,
        category: getCategoryFromName(firstProduct.name, unassignedCategory),
        count: products.length,
        prices: allPrices,
        confidences: allConfidences,
        avgConfidence: allConfidences.reduce((acc, val) => acc + val, 0) / allConfidences.length,
      };
    });

    const categories = [...new Set(summarized.map(p => p.category))].sort();

    const filtered = summarized.filter(item => {
        if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) {
            return false;
        }
        if (filters.category && item.category !== filters.category) {
            return false;
        }
        if (item.avgConfidence * 100 < filters.confidence) {
            return false;
        }
        if (filters.minPrice !== '' || filters.maxPrice !== '') {
            const numericPrices = item.prices.map(p => parsePrice(p.value)).filter((v): v is number => v !== null);
            if (numericPrices.length === 0) return false;

            const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
            const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);

            const hasMatchingPrice = numericPrices.some(p => p >= min && p <= max);
            if (!hasMatchingPrice) {
                return false;
            }
        }
        return true;
    });

    const sorted = filtered.sort((a, b) => {
        const catCompare = a.category.localeCompare(b.category);
        if (catCompare !== 0) return catCompare;

        const getRegularPrice = (item: ProductSummaryWithCategory): number | null => {
            const regularPriceInfo = item.prices.find(p => p.type === 'REGULAR');
            return regularPriceInfo ? parsePrice(regularPriceInfo.value) : null;
        };

        const priceA = getRegularPrice(a);
        const priceB = getRegularPrice(b);

        if (priceA !== null && priceB !== null) {
            return priceA - priceB;
        }
        if (priceA !== null) {
            return -1;
        }
        if (priceB !== null) {
            return 1;
        }
        return b.count - a.count;
    });

    return { filteredProductSummary: sorted, allCategories: categories };

  }, [analysisResult, filters, unassignedCategory]);

  const handleEditClick = (id: string, name: string) => {
    setEditingId(id);
    setEditingValue(name);
    setOriginalEditingName(name); 
  };

  const handleEditSubmit = () => {
    if (editingId && editingValue.trim() && originalEditingName !== editingValue.trim()) {
      onProductNameUpdate(imageId, editingId, originalEditingName, editingValue.trim());
    }
    setEditingId(null);
    setEditingValue('');
    setOriginalEditingName('');
  };

  const totalProducts = useMemo(() => {
    if (!analysisResult?.products || !Array.isArray(analysisResult.products)) return 0;
    return analysisResult.products.length;
  }, [analysisResult]);

  const uniqueProductCount = useMemo(() => {
      if (!analysisResult?.products || !Array.isArray(analysisResult.products)) return 0;
      return new Set(analysisResult.products.map(p => p.name)).size;
  }, [analysisResult]);

  const renderContent = () => {
    if (isLoading) {
      return (
        <div className="text-center py-10">
          <SpinnerIcon className="w-8 h-8 mx-auto text-lime-500" />
          <p className="mt-2 text-sm text-gray-500">{t('waitingForResults')}</p>
        </div>
      );
    }

    if (error) {
        return (
             <div className="text-center py-10 bg-red-50 border border-red-200 rounded-lg p-4">
                <WarningIcon className="w-10 h-10 mx-auto text-red-400" />
                <p className="mt-3 font-semibold text-red-700">{t('errorOccurred')}</p>
                <p className="mt-1 text-sm text-red-600">{error}</p>
                <button 
                    onClick={onRetry}
                    className="mt-4 inline-flex items-center px-4 py-2 bg-white border border-red-300 rounded-md font-semibold text-xs text-red-700 uppercase tracking-widest shadow-sm hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 transition ease-in-out duration-150"
                >
                    <ArrowPathIcon className="w-4 h-4 mr-2" />
                    {t('retry')}
                </button>
             </div>
        );
    }

    if (!analysisResult) {
       return <div className="text-center py-10 text-sm text-gray-500">{t('noDataForShelfShare')}</div>;
    }

    return (
      <>
        {analysisResult?.storeInfo && (analysisResult.storeInfo.chain || analysisResult.storeInfo.address) && (
          <div className="mb-4 bg-gray-100 p-3 rounded-md">
            <p className="text-sm font-semibold text-gray-800">{t('storeInfo')}</p>
            <p className="text-xs text-gray-600">
              {analysisResult.storeInfo.chain}{analysisResult.storeInfo.chain && analysisResult.storeInfo.address ? ', ' : ''}{analysisResult.storeInfo.address}
            </p>
          </div>
        )}
        <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="bg-gray-100 p-4 rounded-lg text-center">
                <p className="text-2xl font-bold text-lime-600">{totalProducts}</p>
                <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('totalProducts')}</p>
            </div>
            <div className="bg-gray-100 p-4 rounded-lg text-center">
                <p className="text-2xl font-bold text-lime-600">{uniqueProductCount}</p>
                <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('uniqueProducts')}</p>
            </div>
        </div>
        <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} />
        <div className="space-y-3 max-h-[calc(60vh-140px)] overflow-y-auto pr-2">
          {filteredProductSummary.length > 0 ? filteredProductSummary.map((item, index) => {
            const avgConfidence = item.confidences.reduce((acc, val) => acc + val, 0) / item.confidences.length;
            const confidenceColorClass = avgConfidence >= 0.9 ? 'text-green-600' : 'text-red-600';
            const borderClass = avgConfidence >= 0.9 ? 'border-l-transparent' : 'border-l-red-500';
            const uniquePrices: PriceInfo[] = Array.from(new Map<string, PriceInfo>(item.prices.filter(p => p && p.value && p.type).map(p => [`${p.value}|${p.type}`, p])).values());

            return (
                <div key={`${item.id}-${index}`} className={`bg-gray-50 p-3 rounded-md flex justify-between items-start border-l-4 transition-colors ${borderClass}`}>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-lime-700 font-semibold">{item.category}</p>
                    {editingId === item.id ? (
                      <input
                        type="text"
                        value={editingValue}
                        onChange={(e) => setEditingValue(e.target.value)}
                        onBlur={handleEditSubmit}
                        onKeyDown={(e) => { if (e.key === 'Enter') handleEditSubmit(); if (e.key === 'Escape') setEditingId(null); }}
                        className="bg-white text-gray-900 w-full rounded p-1 text-sm ring-1 ring-lime-500"
                        autoFocus
                      />
                    ) : (
                      <div className="flex items-center gap-2 -mt-1">
                        <p className="font-semibold text-gray-900 truncate">{item.name}</p>
                        {item.isCorrected && (
                            <span title={t('autoCorrectedTooltip')}>
                                <MagicWandIcon className="w-4 h-4 text-purple-500" />
                            </span>
                        )}
                      </div>
                    )}
                    <div className="text-xs flex flex-wrap items-center gap-x-3 gap-y-1.5 mt-1.5">
                        {uniquePrices.map((price, i) => (
                            <span key={i} className={`inline-flex items-center font-semibold px-2 py-0.5 rounded-full text-xs ${price.type === 'PROMO' ? 'bg-red-100 text-red-800' : 'bg-gray-200 text-gray-800'}`}>
                            {price.value}
                            <span className="ml-1.5 text-xs opacity-70">({price.type === 'PROMO' ? t('promoPrice') : t('regularPrice')})</span>
                            </span>
                        ))}
                        <span
                            className={`font-semibold ${confidenceColorClass}`}
                            title={t('confidenceTooltip')}
                        >
                            {t('confidence')}: {Math.round(avgConfidence * 100)}%
                        </span>
                    </div>
                  </div>
                  <div className="flex items-center flex-shrink-0 ml-2">
                    <div className="text-lg font-bold bg-gray-200 rounded-full w-8 h-8 flex items-center justify-center text-gray-800">
                      {item.count}
                    </div>
                    <button onClick={() => handleEditClick(item.id, item.name)} className="ml-2 p-1 text-gray-500 hover:text-gray-900 rounded-full hover:bg-gray-200 transition-colors">
                      <EditIcon className="w-4 h-4" />
                    </button>
                  </div>
                </div>
            );
          }) : (
             <div className="text-center py-10 text-sm text-gray-500">{t('noProductsForFilter')}</div>
          )}
        </div>
      </>
    );
  };


  return (
    <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col">
      <h2 className="text-xl font-bold text-gray-900 mb-4">{t('analysisResults')}</h2>
      <div className="flex-grow">
          {renderContent()}
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, ArchiveBoxIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number; // New grouping key
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, initialView, onOpenMissingPrices }): React.ReactNode => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') {
        setView('priceAnalysis');
    } else if (initialView === 'shelfShare') {
        setView('shelfShare');
    } else if (initialView === 'promoAlert') {
        setView('promoAlert');
    }
  }, [initialView]);

  const missingPriceCount = useMemo(() => {
      return images.reduce((count, img) => {
          if (!img.analysisResult?.products) return count;
          const missingInImage = img.analysisResult.products.filter(p => !p.prices || p.prices.length === 0).length;
          return count + missingInImage;
      }, 0);
  }, [images]);

  const getStoreIdentifier = useCallback((storeInfo?: StoreInfo) => {
    const unknownStore = t('unknownStore');
    if (storeInfo) {
        const { chain, address } = storeInfo;
        const cleanedChain = removeDateFromStoreName(chain);
        const cleanedAddress = removeDateFromStoreName(address);

        if (cleanedChain && cleanedAddress) return `${cleanedChain}, ${cleanedAddress}`;
        return cleanedChain || cleanedAddress || unknownStore;
    }
    return unknownStore;
  }, [t]);

  const { storeData, totalProducts, uniqueProductCount, analyzedImagesCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    images.forEach(img => {
        if (!img.analysisResult) return;

        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;

        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
                 if(img.assignedStore.code) storeDisplayName += ` [${img.assignedStore.code}]`;
            }
        } else {
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const { chain, address } = storeInfo;
                const cleanedChain = removeDateFromStoreName(chain);
                const cleanedAddress = removeDateFromStoreName(address);
                if (cleanedChain && cleanedAddress) storeDisplayName = `${cleanedChain}, ${cleanedAddress}`;
                else storeDisplayName = cleanedChain || cleanedAddress || unknownStore;
            } else if (img.assignedStore) {
                 storeDisplayName = img.assignedStore.name;
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) {
            productsByStore.set(storeKey, { name: storeDisplayName, items: [] });
        }

        const storeGroup = productsByStore.get(storeKey)!;

        if (storeGroup.name === unknownStore && img.assignedStore?.name) {
             storeGroup.name = img.assignedStore.name;
        }

        if (Array.isArray(img.analysisResult.products)) {
            img.analysisResult.products.forEach(p => {
                if (p && p.name) {
                    storeGroup.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
                }
            });
        }
    });

    const finalData: StoreCentricSummary[] = Array.from(productsByStore.entries())
        .map(([key, data]): StoreCentricSummary => {
            const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();

            data.items.forEach(p => {
                let groupKey = '';

                if (p.catalogProductId) {
                    groupKey = `ID_${p.catalogProductId}`;
                } else {
                    const currentName = p.name.trim();
                    const existingKeys = Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'));
                    const matchedCanonicalName = findBestMatch(currentName, existingKeys);
                    groupKey = matchedCanonicalName || currentName;
                }

                if (!productsMap.has(groupKey)) {
                    productsMap.set(groupKey, []);
                }
                productsMap.get(groupKey)!.push(p);
            });

            const summarizedProducts: ProductInStore[] = Array.from(productsMap.entries())
                .filter(([, occurrences]) => occurrences.length > 0) 
                .map(([groupKey, occurrences]): ProductInStore => {
                    const representative = occurrences[0];
                    const name = representative.name; 

                    const count = occurrences.length;
                    const confidences = occurrences.map(o => o.confidence);
                    const avgConfidence = confidences.reduce((a, b) => a + b, 0) / confidences.length;
                    const isCorrected = occurrences.some(o => o.isCorrected);

                    const occurrencesByImage = occurrences.reduce((acc, o) => {
                        (acc[o.imageId] = acc[o.imageId] || []).push(o);
                        return acc;
                    }, {} as Record<string, typeof occurrences>);

                    const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];
                    Object.values(occurrencesByImage).forEach(imageOccurrences => {
                        if (imageOccurrences.length === 0) return;
                        const uniquePricesOnImage = new Map<string, PriceInfo>();
                        const date = imageOccurrences[0].uploadDate;
                        const imageUrl = imageOccurrences[0].imageUrl;

                        imageOccurrences.forEach(o => {
                            (Array.isArray(o.prices) ? o.prices : []).forEach(price => {
                                const key = `${price.value}|${price.type}`;
                                if (!uniquePricesOnImage.has(key)) {
                                    uniquePricesOnImage.set(key, price);
                                }
                            });
                        });
                        uniquePricesOnImage.forEach(price => {
                            priceHistory.push({ price, date, imageUrl });
                        });
                    });
                    priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime());

                    let latestImageUrl: string | undefined;
                    if (priceHistory.length > 0) {
                        latestImageUrl = priceHistory[priceHistory.length - 1].imageUrl;
                    } else if (occurrences.length > 0) {
                        const sortedOccurrences = [...occurrences].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime());
                        latestImageUrl = sortedOccurrences[0].imageUrl;
                    }

                    return {
                        name,
                        isCorrected,
                        category: getCategoryFromName(name, unassignedCategory),
                        count,
                        priceHistory,
                        avgConfidence,
                        imageUrl: latestImageUrl,
                        catalogProductId: representative.catalogProductId
                    };
                });

            return {
                storeName: data.name,
                storeId: typeof key === 'number' ? key : undefined,
                products: summarizedProducts.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
            };
        }).sort((a,b) => a.storeName.localeCompare(b.storeName));

    const allChainsForFilter = Array.from(new Set(finalData.map(s => s.storeName))).sort();

    const filteredData = finalData
        .map(store => {
            if (filters.chain && store.storeName !== filters.chain) {
                return null;
            }

            const filteredProducts = store.products.filter(item => {
                if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
                if (filters.category && item.category !== filters.category) return false;
                if (item.avgConfidence * 100 < filters.confidence) return false;

                if (filters.minPrice !== '' || filters.maxPrice !== '') {
                    if (item.priceHistory.length === 0) return false;
                    const numericPrices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                    if (numericPrices.length === 0) return false;

                    const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                    const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);

                    if (!numericPrices.some(p => p >= min && p <= max)) return false;
                }
                return true;
            });

            if (filteredProducts.length === 0) return null;
            return { ...store, products: filteredProducts };
        })
        .filter((s): s is StoreCentricSummary => s !== null);

    const allProductsCount = Array.from(productsByStore.values()).reduce((sum, data) => sum + data.items.length, 0);
    const allUniqueProducts = new Set();
    finalData.forEach(store => {
        store.products.forEach(p => {
            if (p.catalogProductId) allUniqueProducts.add(`ID_${p.catalogProductId}`);
            else allUniqueProducts.add(p.name);
        });
    });

    return {
      storeData: filteredData,
      totalProducts: allProductsCount,
      uniqueProductCount: allUniqueProducts.size,
      analyzedImagesCount: images.filter(img => img.analysisResult || img.error).length,
      allCategories: allChainsForFilter,
      allChains: allChainsForFilter
    };
  }, [images, filters, t, unassignedCategory, getStoreIdentifier]);

  const totalImages = images.length;
  const isAnalyzing = images.some(img => img.status === 'analyzing');

  const handleExportPriceMonitoring = () => {
    exportPriceMonitoringToXLS(storeData, t);
  };

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content">
      {zoomedImage && (
        <div 
            className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" 
            onClick={() => setZoomedImage(null)}
        >
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg" alt={t('zoomedView')} />
