export const GalleryPanel: React.FC = () => {
    const { t } = useTranslation();
    const [items, setItems] = useState<GalleryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedItem, setSelectedItem] = useState<GalleryItem | null>(null);

    // Filtre
    const [searchProduct, setSearchProduct] = useState('');
    const [selectedStore, setSelectedStore] = useState('all');
    const [selectedCategory, setSelectedCategory] = useState('all');

    // Metadáta pre filtre
    const [allStores, setAllStores] = useState<string[]>([]);
    const [allCategories, setAllCategories] = useState<string[]>([]);

    useEffect(() => {
        const loadGallery = async () => {
            setIsLoading(true);
            try {
                const analyses = await getAnalyses();
                const flattened: GalleryItem[] = [];
                const storesSet = new Set<string>();
                const categoriesSet = new Set<string>();

                analyses.forEach(analysis => {
                    const storeName = analysis.store?.name || t('unknownStore');
                    storesSet.add(storeName);

                    analysis.images.forEach(img => {
                        const file = base64ToFile(img.file.data, img.file.name, img.file.type, img.file.lastModified);
                        const url = URL.createObjectURL(file);

                        const products = img.analysisResult?.products || [];
                        products.forEach(p => {
                            categoriesSet.add(getCategoryFromName(p.name, t('unassignedCategory')));
                        });

                        flattened.push({
                            id: img.id,
                            analysisId: analysis.id,
                            analysisName: analysis.name,
                            imageUrl: url,
                            uploadDate: new Date(img.uploadDate),
                            storeName,
                            products,
                            rawImage: img
                        });
                    });
                });

                setItems(flattened.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
                setAllStores(Array.from(storesSet).sort());
                setAllCategories(Array.from(categoriesSet).sort());
            } catch (e) {
                console.error("Gallery load error:", e);
            } finally {
                setIsLoading(false);
            }
        };
        loadGallery();

        return () => {
            items.forEach(item => URL.revokeObjectURL(item.imageUrl));
        };
    }, []);

    const filteredItems = useMemo(() => {
        return items.filter(item => {
            const matchesProduct = searchProduct === '' || 
                item.products.some(p => p.name.toLowerCase().includes(searchProduct.toLowerCase()));

            const matchesStore = selectedStore === 'all' || item.storeName === selectedStore;

            const matchesCategory = selectedCategory === 'all' || 
                item.products.some(p => getCategoryFromName(p.name, t('unassignedCategory')) === selectedCategory);

            return matchesProduct && matchesStore && matchesCategory;
        });
    }, [items, searchProduct, selectedStore, selectedCategory, t]);

    // Zoskupenie produktov pre detail fotografie
    const groupedProductsOnImage = useMemo(() => {
        if (!selectedItem) return [];

        const groupMap = new Map<string, { product: DetectedProduct, count: number }>();

        selectedItem.products.forEach(p => {
            const existing = groupMap.get(p.name);
            if (existing) {
                existing.count++;
            } else {
                groupMap.set(p.name, { product: p, count: 1 });
            }
        });

        return Array.from(groupMap.values()).sort((a, b) => b.count - a.count);
    }, [selectedItem]);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-64">
                <SpinnerIcon className="w-12 h-12 text-lime-600 animate-spin" />
                <p className="mt-4 text-gray-500 font-medium">{t('pleaseWait')}</p>
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            {/* Filter Bar */}
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col md:flex-row gap-4 items-center sticky top-0 z-20">
                <div className="relative flex-grow w-full">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input 
                        type="text"
                        placeholder={t('filterByProduct')}
                        className="w-full pl-11 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-lime-500"
                        value={searchProduct}
                        onChange={(e) => setSearchProduct(e.target.value)}
                    />
                </div>

                <div className="flex gap-2 w-full md:w-auto">
                    <select 
                        className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500"
                        value={selectedStore}
                        onChange={(e) => setSelectedStore(e.target.value)}
                    >
                        <option value="all">{t('allStores')}</option>
                        {allStores.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>

                    <select 
                        className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500"
                        value={selectedCategory}
                        onChange={(e) => setSelectedCategory(e.target.value)}
                    >
                        <option value="all">{t('allCategories')}</option>
                        {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {/* Gallery Grid */}
            {filteredItems.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
                    {filteredItems.map(item => (
                        <div 
                            key={item.id}
                            onClick={() => setSelectedItem(item)}
                            className="group relative aspect-square bg-gray-200 rounded-2xl overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1"
                        >
                            <img 
                                src={item.imageUrl} 
                                alt={item.analysisName} 
                                className="w-full h-full object-cover"
                                loading="lazy"
                            />
                            {/* Overlay info */}
                            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-3 flex flex-col justify-end">
                                <p className="text-white text-[10px] font-black uppercase tracking-widest truncate">{item.storeName}</p>
                                <p className="text-white/80 text-[10px] font-medium">{item.uploadDate.toLocaleDateString()}</p>
                                <div className="mt-1 flex items-center gap-1">
                                    <span className="bg-lime-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded-full">
                                        {item.products.length} {t('totalLabel')}
                                    </span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="bg-white rounded-3xl p-20 text-center border border-dashed border-gray-200">
                    <AppIcon className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400 font-medium">{t('noImagesInGallery')}</p>
                </div>
            )}

            {/* Detail Lightbox */}
            {selectedItem && (
                <div className="fixed inset-0 bg-gray-950/95 z-[100] flex animate-fade-in">
                    <div className="flex-grow relative flex items-center justify-center p-4">
                        <img 
                            src={selectedItem.imageUrl} 
                            alt="Full preview"
                            className="max-w-full max-h-full object-contain rounded-lg shadow-2xl"
                        />
                        <button 
                            onClick={() => setSelectedItem(null)}
                            className="absolute top-6 left-6 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all backdrop-blur-md"
                        >
                            <ArrowLeftIcon className="w-6 h-6" />
                        </button>
                    </div>

                    {/* Side Info Panel */}
                    <div className="w-full md:w-[400px] bg-white h-full flex flex-col shadow-[-10px_0_30px_rgba(0,0,0,0.2)]">
                        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                            <h3 className="text-xl font-black text-gray-900">{t('photoDetail')}</h3>
                            <button onClick={() => setSelectedItem(null)} className="p-2 text-gray-400 hover:text-gray-600"><CloseIcon className="w-6 h-6" /></button>
                        </div>

                        <div className="flex-grow overflow-y-auto p-6 space-y-8">
                            {/* Metadata */}
                            <section className="space-y-4">
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-blue-50 rounded-xl">
                                        <BuildingStorefrontIcon className="w-6 h-6 text-blue-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{t('storeName')}</p>
                                        <p className="text-lg font-black text-gray-900">{selectedItem.storeName}</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-orange-50 rounded-xl">
                                        <CalendarDaysIcon className="w-6 h-6 text-orange-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{t('detectedAt')}</p>
                                        <p className="text-base font-bold text-gray-700">{selectedItem.uploadDate.toLocaleString()}</p>
                                    </div>
                                </div>
                                <div className="flex items-start gap-4">
                                    <div className="p-2.5 bg-lime-50 rounded-xl">
                                        <CircleStackIcon className="w-6 h-6 text-lime-600" />
                                    </div>
                                    <div>
                                        <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">Analýza</p>
                                        <p className="text-base font-bold text-gray-700">{selectedItem.analysisName}</p>
                                    </div>
                                </div>
                            </section>

                            {/* Grouped Products List */}
                            <section>
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="text-sm font-black text-gray-900 uppercase tracking-widest">{t('productsOnImage')}</h4>
                                    <span className="bg-lime-600 text-white text-[10px] font-black px-2 py-1 rounded-lg uppercase">{selectedItem.products.length} ks celkovo</span>
                                </div>
                                <div className="space-y-2">
                                    {groupedProductsOnImage.map((group, idx) => (
                                        <div key={idx} className="bg-gray-50 p-3 rounded-xl border border-gray-100 flex justify-between items-center transition-all hover:border-lime-200">
                                            <div className="min-w-0">
                                                <p className="text-[10px] text-lime-700 font-black uppercase tracking-tight opacity-70">
                                                    {getCategoryFromName(group.product.name, t('unassignedCategory'))}
                                                </p>
                                                <p className="text-sm font-bold text-gray-800 truncate pr-2">
                                                    {group.product.name}
                                                </p>
                                            </div>
                                            <div className="flex items-center gap-3 flex-shrink-0">
                                                {group.product.prices && group.product.prices.length > 0 && (
                                                    <span className={`text-[10px] font-black px-2 py-1 rounded-md ${group.product.prices[0].type === 'PROMO' ? 'bg-red-100 text-red-600' : 'bg-gray-200 text-gray-700'}`}>
                                                        {group.product.prices[0].value}
                                                    </span>
                                                )}
                                                <div className="bg-white border-2 border-lime-500 text-lime-700 text-xs font-black w-8 h-8 flex items-center justify-center rounded-full shadow-sm">
                                                    {group.count}
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </section>
                        </div>

                        {/* Actions */}
                        <div className="p-6 bg-gray-50 border-t border-gray-100">
                             <button 
                                onClick={() => {
                                    setSelectedItem(null);
                                }}
                                className="w-full py-4 bg-gray-900 text-white font-black rounded-2xl hover:bg-black transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
                             >
                                <ChevronRightIcon className="w-5 h-5 text-lime-500" />
                                {t('viewInAnalysis')}
                             </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, ArchiveBoxIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number; // New grouping key
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, initialView, onOpenMissingPrices }): React.ReactNode => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') {
        setView('priceAnalysis');
    } else if (initialView === 'shelfShare') {
        setView('shelfShare');
    } else if (initialView === 'promoAlert') {
        setView('promoAlert');
    }
  }, [initialView]);

  const missingPriceCount = useMemo(() => {
      return images.reduce((count, img) => {
          if (!img.analysisResult?.products) return count;
          const missingInImage = img.analysisResult.products.filter(p => !p.prices || p.prices.length === 0).length;
          return count + missingInImage;
      }, 0);
  }, [images]);

  const getStoreIdentifier = useCallback((storeInfo?: StoreInfo) => {
    const unknownStore = t('unknownStore');
    if (storeInfo) {
        const { chain, address } = storeInfo;
        const cleanedChain = removeDateFromStoreName(chain);
        const cleanedAddress = removeDateFromStoreName(address);

        if (cleanedChain && cleanedAddress) return `${cleanedChain}, ${cleanedAddress}`;
        return cleanedChain || cleanedAddress || unknownStore;
    }
    return unknownStore;
  }, [t]);

  const { storeData, totalProducts, uniqueProductCount, analyzedImagesCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    images.forEach(img => {
        if (!img.analysisResult) return;

        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;

        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
                 if(img.assignedStore.code) storeDisplayName += ` [${img.assignedStore.code}]`;
            }
        } else {
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const { chain, address } = storeInfo;
                const cleanedChain = removeDateFromStoreName(chain);
                const cleanedAddress = removeDateFromStoreName(address);
                if (cleanedChain && cleanedAddress) storeDisplayName = `${cleanedChain}, ${cleanedAddress}`;
                else storeDisplayName = cleanedChain || cleanedAddress || unknownStore;
            } else if (img.assignedStore) {
                 storeDisplayName = img.assignedStore.name;
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) {
            productsByStore.set(storeKey, { name: storeDisplayName, items: [] });
        }

        const storeGroup = productsByStore.get(storeKey)!;

        if (storeGroup.name === unknownStore && img.assignedStore?.name) {
             storeGroup.name = img.assignedStore.name;
        }

        if (Array.isArray(img.analysisResult.products)) {
            img.analysisResult.products.forEach(p => {
                if (p && p.name) {
                    storeGroup.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
                }
            });
        }
    });

    const finalData: StoreCentricSummary[] = Array.from(productsByStore.entries())
        .map(([key, data]): StoreCentricSummary => {
            const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();

            data.items.forEach(p => {
                let groupKey = '';

                if (p.catalogProductId) {
                    groupKey = `ID_${p.catalogProductId}`;
                } else {
                    const currentName = p.name.trim();
                    const existingKeys = Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'));
                    const matchedCanonicalName = findBestMatch(currentName, existingKeys);
                    groupKey = matchedCanonicalName || currentName;
                }

                if (!productsMap.has(groupKey)) {
                    productsMap.set(groupKey, []);
                }
                productsMap.get(groupKey)!.push(p);
            });

            const summarizedProducts: ProductInStore[] = Array.from(productsMap.entries())
                .filter(([, occurrences]) => occurrences.length > 0) 
                .map(([groupKey, occurrences]): ProductInStore => {
                    const representative = occurrences[0];
                    const name = representative.name; 

                    const count = occurrences.length;
                    const confidences = occurrences.map(o => o.confidence);
                    const avgConfidence = confidences.reduce((a, b) => a + b, 0) / confidences.length;
                    const isCorrected = occurrences.some(o => o.isCorrected);

                    const occurrencesByImage = occurrences.reduce((acc, o) => {
                        (acc[o.imageId] = acc[o.imageId] || []).push(o);
                        return acc;
                    }, {} as Record<string, typeof occurrences>);

                    const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];
                    Object.values(occurrencesByImage).forEach(imageOccurrences => {
                        if (imageOccurrences.length === 0) return;
                        const uniquePricesOnImage = new Map<string, PriceInfo>();
                        const date = imageOccurrences[0].uploadDate;
                        const imageUrl = imageOccurrences[0].imageUrl;

                        imageOccurrences.forEach(o => {
                            (Array.isArray(o.prices) ? o.prices : []).forEach(price => {
                                const key = `${price.value}|${price.type}`;
                                if (!uniquePricesOnImage.has(key)) {
                                    uniquePricesOnImage.set(key, price);
                                }
                            });
                        });
                        uniquePricesOnImage.forEach(price => {
                            priceHistory.push({ price, date, imageUrl });
                        });
                    });
                    priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime());

                    let latestImageUrl: string | undefined;
                    if (priceHistory.length > 0) {
                        latestImageUrl = priceHistory[priceHistory.length - 1].imageUrl;
                    } else if (occurrences.length > 0) {
                        const sortedOccurrences = [...occurrences].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime());
                        latestImageUrl = sortedOccurrences[0].imageUrl;
                    }

                    return {
                        name,
                        isCorrected,
                        category: getCategoryFromName(name, unassignedCategory),
                        count,
                        priceHistory,
                        avgConfidence,
                        imageUrl: latestImageUrl,
                        catalogProductId: representative.catalogProductId
                    };
                });

            return {
                storeName: data.name,
                storeId: typeof key === 'number' ? key : undefined,
                products: summarizedProducts.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
            };
        }).sort((a,b) => a.storeName.localeCompare(b.storeName));

    const allChainsForFilter = Array.from(new Set(finalData.map(s => s.storeName))).sort();

    const filteredData = finalData
        .map(store => {
            if (filters.chain && store.storeName !== filters.chain) {
                return null;
            }

            const filteredProducts = store.products.filter(item => {
                if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
                if (filters.category && item.category !== filters.category) return false;
                if (item.avgConfidence * 100 < filters.confidence) return false;

                if (filters.minPrice !== '' || filters.maxPrice !== '') {
                    if (item.priceHistory.length === 0) return false;
                    const numericPrices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                    if (numericPrices.length === 0) return false;

                    const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                    const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);

                    if (!numericPrices.some(p => p >= min && p <= max)) return false;
                }
                return true;
            });

            if (filteredProducts.length === 0) return null;
            return { ...store, products: filteredProducts };
        })
        .filter((s): s is StoreCentricSummary => s !== null);

    const allProductsCount = Array.from(productsByStore.values()).reduce((sum, data) => sum + data.items.length, 0);
    const allUniqueProducts = new Set();
    finalData.forEach(store => {
        store.products.forEach(p => {
            if (p.catalogProductId) allUniqueProducts.add(`ID_${p.catalogProductId}`);
            else allUniqueProducts.add(p.name);
        });
    });

    return {
      storeData: filteredData,
      totalProducts: allProductsCount,
      uniqueProductCount: allUniqueProducts.size,
      analyzedImagesCount: images.filter(img => img.analysisResult || img.error).length,
      allCategories: allChainsForFilter,
      allChains: allChainsForFilter
    };
  }, [images, filters, t, unassignedCategory, getStoreIdentifier]);

  const totalImages = images.length;
  const isAnalyzing = images.some(img => img.status === 'analyzing');

  const handleExportPriceMonitoring = () => {
    exportPriceMonitoringToXLS(storeData, t);
  };

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content">
      {zoomedImage && (
        <div 
            className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" 
            onClick={() => setZoomedImage(null)}
        >
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg" alt={t('zoomedView')} />
            <button className="absolute top-4 right-4 text-white bg-black/50 p-2 rounded-full hover:bg-black/80 transition-colors">
                <CloseIcon className="w-6 h-6" />
            </button>
        </div>
      )}
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-gray-900">{t('batchSummary')}</h2>
        {missingPriceCount > 0 && (
            <button
                onClick={onOpenMissingPrices}
                className="flex items-center gap-2 px-4 py-2 bg-orange-100 text-orange-800 rounded-md hover:bg-orange-200 border border-orange-200 transition-colors animate-pulse"
            >
                <TagIcon className="w-5 h-5" />
                <span className="font-semibold text-sm">{t('fixMissingPrices', { count: missingPriceCount })}</span>
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 my-4">
        <div className="bg-gray-100 p-4 rounded-lg text-center">
          <p className="text-2xl font-bold text-lime-600">{totalImages}</p>
          <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('imagesCount')}</p>
        </div>
        <div className="bg-gray-100 p-4 rounded-lg text-center">
          <p className="text-2xl font-bold text-lime-600">{analyzedImagesCount}</p>
          <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('analyzed')}</p>
        </div>
        <div className="bg-gray-100 p-4 rounded-lg text-center">
          <p className="text-2xl font-bold text-lime-600">{totalProducts}</p>
          <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('totalProducts')}</p>
        </div>
        <div className="bg-gray-100 p-4 rounded-lg text-center">
          <p className="text-2xl font-bold text-lime-600">{uniqueProductCount}</p>
          <p className="text-xs text-gray-500 uppercase font-semibold tracking-wider">{t('uniqueProducts')}</p>
        </div>
      </div>

      {isAnalyzing && (
        <div className="text-center text-sm text-lime-600 mb-4 no-print">
          {t('analyzingInProgress')}
        </div>
      )}

      <div className="flex border-b border-gray-200 mb-4 no-print overflow-x-auto">
          {initialView === 'priceMonitoring' && (
            <button
                onClick={() => setView('priceAnalysis')}
                className={`-mb-px px-4 py-2 text-sm font-semibold transition-colors flex items-center gap-2 border-b-2 whitespace-nowrap ${view === 'priceAnalysis' ? 'border-lime-500 text-gray-900' : 'border-transparent text-gray-500 hover:text-gray-800'}`}
            >
                <ChartBarIcon className="w-5 h-5" />
                {t('priceAnalysis')}
            </button>
          )}

          {initialView === 'shelfShare' && (
            <button
