import { 
    CalculatorIcon, 
    ArrowPathIcon, 
    SpinnerIcon, 
    CircleStackIcon, 
    TagIcon, 
    CalendarDaysIcon, 
    CpuChipIcon,
    AppIcon,
    BoxIcon,
    ShieldCheckIcon,
    SaveIcon
