interface GlobalAnalysisStatusProps {
  total: number;
  completed: number;
  analyzing: number;
  errors: number;
}

export const GlobalAnalysisStatus: React.FC<GlobalAnalysisStatusProps> = ({ total, completed, analyzing, errors }) => {
  const { t } = useTranslation();

  if (total === 0 || (completed + errors === total && analyzing === 0)) return null;

  const progress = Math.round(((completed + errors) / total) * 100);
  const isFinished = completed + errors === total;

  return (
    <div className="sticky top-0 z-30 w-full bg-white/80 backdrop-blur-md border-b border-lime-100 shadow-sm animate-fade-in-down no-print">
      <div className="max-w-7xl mx-auto px-6 py-3">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

          {/* Status Text & Info */}
          <div className="flex items-center gap-4">
            <div className={`p-2 rounded-xl flex-shrink-0 ${isFinished ? 'bg-green-100' : 'bg-lime-100'}`}>
                {analyzing > 0 ? (
                    <SpinnerIcon className="w-5 h-5 text-lime-600 animate-spin" />
                ) : (
                    <CpuChipIcon className="w-5 h-5 text-lime-600" />
                )}
            </div>
            <div>
                <h4 className="text-sm font-black text-gray-900 flex items-center gap-2 uppercase tracking-tight">
                    {isFinished ? 'Analýza dokončená' : 'Prebieha AI analýza...'}
                    {!isFinished && <span className="flex h-2 w-2 rounded-full bg-lime-500 animate-pulse"></span>}
                </h4>
                <div className="flex items-center gap-3 mt-0.5">
                    <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
                        {completed + errors} z {total} fotiek spracovaných
                    </span>
                    {analyzing > 0 && (
                         <span className="text-[10px] font-black text-lime-600 bg-lime-50 px-2 py-0.5 rounded-full border border-lime-100 animate-pulse">
                            AKTÍVNE: {analyzing}
                         </span>
                    )}
                    {errors > 0 && (
                        <span className="flex items-center gap-1 text-[10px] font-bold text-red-600">
                            <WarningIcon className="w-3 h-3" /> {errors} chyby
                        </span>
                    )}
                </div>
            </div>
          </div>

          {/* Progress Bar Container */}
          <div className="flex-grow max-w-md">
            <div className="flex justify-between items-center mb-1.5">
                <span className="text-[11px] font-black text-lime-700">{progress}%</span>
                {progress === 100 && <CheckCircleIcon className="w-4 h-4 text-green-600" />}
            </div>
            <div className="w-full bg-gray-100 rounded-full h-2.5 overflow-hidden border border-gray-50">
              <div 
                className="h-full bg-lime-500 transition-all duration-700 ease-out relative"
                style={{ width: `${progress}%` }}
              >
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/30 to-transparent animate-shimmer" style={{ backgroundSize: '200% 100%' }}></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* CSS for Shimmer effect */}
      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .animate-shimmer {
          animation: shimmer 2s infinite linear;
        }
        @keyframes fade-in-down {
          0% { opacity: 0; transform: translateY(-10px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-down {
          animation: fade-in-down 0.4s ease-out forwards;
        }
      `}</style>
    </div>
  );
