export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName: string; // Model selected for this specific analysis
}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  const { t } = useTranslation();

  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandProductsMap, setBrandProductsMap] = React.useState<Record<string, string[]>>({});
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);

  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false);
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);

  // --- STATS PRE PROGRESS BAR ---
  const analysisStats = React.useMemo(() => {
    return {
        total: images.length,
        completed: images.filter(img => img.status === 'success').length,
        analyzing: images.filter(img => img.status === 'analyzing').length,
        errors: images.filter(img => img.status === 'error').length
    };
  }, [images]);

  // Inicializácia promptov pri prvom štarte
  React.useEffect(() => {
    const initPrompts = async () => {
        const count = await db.prompts.count();
        if (count === 0 || count < 5) {
            const currentPrompts = await db.prompts.toArray();
            const hasSystem = currentPrompts.some(p => p.category === 'system');
            const hasPrice = currentPrompts.some(p => p.category === 'price');
            const hasShelf = currentPrompts.some(p => p.category === 'shelfShare');
            const hasBoth = currentPrompts.some(p => p.category === 'both');
            const hasOsa = currentPrompts.some(p => p.category === 'osa');

            if (!hasSystem) await saveNewPromptVersion('system', t('geminiSystemInstruction'));
            if (!hasPrice) await saveNewPromptVersion('price', t('geminiPromptPriceOnly'));
            if (!hasShelf) await saveNewPromptVersion('shelfShare', t('geminiPromptShelfShareOnly'));
            if (!hasBoth) await saveNewPromptVersion('both', t('geminiPromptBoth'));
            if (!hasOsa) await saveNewPromptVersion('osa', t('geminiPromptOsaOnly'));
        }
    };
    initPrompts();
  }, [t]);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = React.useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const missingPriceItems = React.useMemo<MissingPriceItem[]>(() => {
      const items: MissingPriceItem[] = [];
      images.forEach(img => {
          if (img.analysisResult?.products) {
              img.analysisResult.products.forEach(p => {
                  if (!p.prices || p.prices.length === 0) {
                      items.push({
                          imageId: img.id,
                          productId: p.id,
                          name: p.name,
                          imageUrl: img.imageUrl
                      });
                  }
              });
          }
      });
      return items;
  }, [images]);

  const handleUpdatePrices = (updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prevImages => 
          prevImages.map(img => {
              const updatesForImage = updates.filter(u => u.imageId === img.id);
              if (updatesForImage.length === 0) return img;

              const updatedProducts = img.analysisResult?.products.map(p => {
                  const update = updatesForImage.find(u => u.productId === p.id);
                  if (update) {
                      return { ...p, prices: update.prices };
                  }
                  return p;
              });

              return {
                  ...img,
                  analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null
              };
          })
      );
  };

  const endCurrentAnalysisWithoutSaving = React.useCallback(() => {
    images.forEach(img => URL.revokeObjectURL(img.imageUrl));
    setImages([]);
    setSelectedImageId(null);
    setSelectedProductName(null);
    setSidebarView('images');
    setHighlightedProductName(null);
    setProductSearchTerm('');
    setBrandClassifications({ ourBrands: [], competitorBrands: [] });
    setBrandProductsMap({});
    setActiveAnalysis(null);
    setIsNewAnalysisModalOpen(false);
  }, [images]);

  // --- ROBUSTNÉ UKLADANIE DÁT S DYNAMICKÝM VÝPOČTOM NÁKLADOV ---
  const handleSaveAnalysis = React.useCallback(async () => {
    if (!activeAnalysis || images.length === 0) return;
    try {
        let totalInput = 0;
        let totalOutput = 0;
        let usedModelName = images[0]?.modelName || 'gemini-2.5-flash';

        const serializableImages: SerializableImageState[] = await Promise.all(
          images.map(async (image) => {
            const base64Data = await fileToBase64(image.file);

            if (image.analysisResult?.usageMetadata) {
                totalInput += image.analysisResult.usageMetadata.promptTokenCount || 0;
                totalOutput += image.analysisResult.usageMetadata.candidatesTokenCount || 0;
            }

            return {
              id: image.id,
              file: {
                name: image.file.name,
                type: image.file.type,
                lastModified: image.file.lastModified,
                data: base64Data,
              },
              imageUrl: '',
              analysisResult: image.analysisResult,
              status: image.status,
              error: image.error,
              uploadDate: image.uploadDate.toISOString(),
              analysisType: image.analysisType,
              retryCount: image.retryCount,
              assignedStore: image.assignedStore,
              assignedStoreId: image.assignedStoreId,
              modelName: image.modelName
            };
          })
        );

        const modelRates = getRatesForModel(usedModelName);
        const inRate = await getSetting('inputTokenRate', modelRates.input);
        const outRate = await getSetting('outputTokenRate', modelRates.output);
        const cost = ((totalInput / 1000000) * inRate) + ((totalOutput / 1000000) * outRate);

        const updatedAnalysis: Analysis = {
          ...activeAnalysis,
          images: serializableImages,
          brandClassifications: brandClassifications,
          storeId: serializableImages[0]?.assignedStoreId,
          costInfo: {
              inputTokens: totalInput,
              outputTokens: totalOutput,
              cost: cost,
              modelName: usedModelName
          }
        };

        await saveAnalysis(updatedAnalysis);
        setActiveAnalysis(updatedAnalysis);
        console.log("Analysis automatically saved.");
    } catch (e) {
        console.error("Failed to auto-save analysis:", e);
    }
  }, [activeAnalysis, images, brandClassifications]);

  // ZJEDNODUŠENÝ FLOW: Automatické uloženie a otvorenie novej analýzy
  const handleNewAnalysisClick = async () => {
    if (activeAnalysis && images.length > 0) {
        // Tiché uloženie predchádzajúcej práce
        await handleSaveAnalysis();
        // Vyčistenie stavu pre novú dávku
        endCurrentAnalysisWithoutSaving();
    }
    setIsNewAnalysisModalOpen(true); 
  };

  const handleImageUpload = React.useCallback((files: FileList) => {
    setPendingFiles(files);
    setIsNewAnalysisModalOpen(true); 
    setIsImageUploadOverlayOpen(false);
  }, []);

  // --- AUTOMATICKÉ UKLADANIE PRI ZMENE STAVU ---
  const wasAnalyzing = React.useRef(false);
  React.useEffect(() => {
      if (wasAnalyzing.current && !isAnalyzing && images.length > 0) {
          handleSaveAnalysis();
      }
      wasAnalyzing.current = isAnalyzing;
  }, [isAnalyzing, images.length, handleSaveAnalysis]);

 const handleStartAnalysis = React.useCallback(async (name: string, type: AnalysisType, model: string, filesToProcess: FileList) => {
    setIsNewAnalysisModalOpen(false);
    setPendingFiles(null);

    const newAnalysis: Analysis = {
        id: `analysis-${Date.now()}`,
        name,
        createdAt: new Date().toISOString(),
        images: [],
        brandClassifications: { ourBrands: [], competitorBrands: [] },
        store: null,
    };
    await db.analyses.add(newAnalysis);
    setActiveAnalysis(newAnalysis);

    if (type === 'osa') {
        setActiveView('distribution');
    } else if (type === 'shelfShare') {
        setActiveView('shelfShare');
    } else {
        setActiveView('priceMonitoring');
    }

    const tempImages: ImageState[] = await Promise.all(Array.from(filesToProcess).map(async (file) => {
        const initialId = `${file.name}-${Date.now()}`;
        const filenameStoreName = extractStoreFromFilename(file.name);
        let effectiveStore: Store | null = null;
        let effectiveStoreId: number | undefined = undefined;

        if (filenameStoreName) {
             const chain = filenameStoreName.split(',')[0].trim();
             try {
                effectiveStore = await findOrCreateStore({ name: filenameStoreName, chain: chain, city: '', address: '', code: '' });
                effectiveStoreId = effectiveStore.id;
             } catch (e) {
                console.warn("Could not auto-create store, proceed without link", e);
             }
        }

        return {
            id: initialId,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: effectiveStore,
            assignedStoreId: effectiveStoreId,
            modelName: model
        };
    }));

    setImages(tempImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    const compressImages = async () => {
        const compressedImages: ImageState[] = await Promise.all(tempImages.map(async (img) => {
            try {
                const compressedFile = await resizeAndCompressImage(img.file);
                return {
                    ...img,
                    file: compressedFile,
                    imageUrl: URL.createObjectURL(compressedFile)
                };
            } catch (e) {
                console.error("Compression failed for", img.file.name, e);
                return img; 
            }
        }));

        setImages(prev => {
            return prev.map(p => {
                const compressed = compressedImages.find(c => c.id === p.id);
                return compressed || p;
            }).sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime());
        });
    };
    compressImages();

  }, []);


const handleRetryImage = (id: string) => {
    setImages(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'pending', error: null, retryCount: 0 } : img
    ));
};

React.useEffect(() => {
    const processQueue = async () => {
        if (!isOnline) return;

        const pendingImages = images.filter(img => img.status === 'pending');
        if (pendingImages.length === 0 || images.some(img => img.status === 'analyzing')) return;

        const BATCH_SIZE = 3;
        const currentBatch = pendingImages.slice(0, BATCH_SIZE);

        setImages(prev => prev.map(img => 
            currentBatch.find(batchImg => batchImg.id === img.id) 
                ? { ...img, status: 'analyzing', error: null } 
                : img
        ));

        const type = currentBatch[0].analysisType;
        const model = currentBatch[0].modelName;

        const catalogEntries = await getCatalogEntries();
        const knownProductsList = catalogEntries.map(entry => entry.visualFeatures ? `${entry.canonicalName} (Visuals: ${entry.visualFeatures})` : entry.canonicalName);
        const knownProductsString = knownProductsList.length > 0 ? t('knownProductsList', { products: knownProductsList.join(', ') }) : '';

        const systemInstructionDefault = t('geminiSystemInstruction');
        let geminiPromptDefaultKey = 'geminiPromptBoth';
        if (type === 'price') geminiPromptDefaultKey = 'geminiPromptPriceOnly';
        else if (type === 'shelfShare') geminiPromptDefaultKey = 'geminiPromptShelfShareOnly';
        else if (type === 'osa') geminiPromptDefaultKey = 'geminiPromptOsaOnly';

        const geminiPromptDefault = t(geminiPromptDefaultKey).replace('{{knownProducts}}', knownProductsString);

        const processedResults: ImageState[] = [];
        const newDiscoveredBrandsWithProducts: Record<string, Set<string>> = {};

        await Promise.all(currentBatch.map(async (image) => {
            try {
                const base64Image = await fileToBase64(image.file);
                const result = await analyzeImageWithGemini(base64Image, geminiPromptDefault, systemInstructionDefault, image.analysisType, image.modelName); 

                let currentAssignedStore = image.assignedStore;
                let currentAssignedStoreId = image.assignedStoreId;

                if (currentAssignedStore) {
                    if (!result.storeInfo) result.storeInfo = {};
                    result.storeInfo.chain = currentAssignedStore.chain || currentAssignedStore.name; 
                    result.storeInfo.address = currentAssignedStore.address || '';
                } else if (result.storeInfo && (result.storeInfo.chain || result.storeInfo.address)) {
                    const chain = result.storeInfo.chain || '';
                    const address = result.storeInfo.address || '';
                    const storeName = chain + (address ? `, ${address}` : '');

                    try {
                        currentAssignedStore = await findOrCreateStore({
                            name: storeName,
                            chain: chain,
                            address: address,
                            city: '',
                            code: ''
                        });
                        currentAssignedStoreId = currentAssignedStore.id;
                    } catch (e) {
                        console.warn("DB Store creation failed during AI results processing", e);
                    }
                }

                const correctedProducts = await Promise.all(
                    (result.products || []).map(async p => {
                        if (!p || !p.name) return p;

                        const catalogEntry = await findProductByAlias(p.name);
                        let finalName = p.name;
                        let isCorrected = false;
                        let catalogProductId: number | undefined = undefined;

                        if (catalogEntry) {
                            catalogProductId = catalogEntry.id;
                            if (normalizeProductName(catalogEntry.canonicalName) !== normalizeProductName(p.name)) {
                                finalName = catalogEntry.canonicalName;
                                isCorrected = true;
                            }
                        }

                        return { 
                            ...p, 
                            name: finalName, 
                            isCorrected, 
                            catalogProductId, 
                            id: `${image.id}-${finalName}-${Math.random()}`, 
                            imageId: image.id 
                        };
                    })
                );

                const processedImage: ImageState = { 
                    ...image, 
                    analysisResult: { ...result, products: correctedProducts }, 
                    status: 'success', 
                    error: null,
                    assignedStore: currentAssignedStore,
                    assignedStoreId: currentAssignedStoreId
                };
                processedResults.push(processedImage);

                if (correctedProducts) {
                    correctedProducts.forEach(p => {
                        if (!p) return;
                        const brand = p.brand || getBrandFromName(p.name);
                        if (brand) {
                            if (!newDiscoveredBrandsWithProducts[brand]) {
                                newDiscoveredBrandsWithProducts[brand] = new Set();
                            }
                            newDiscoveredBrandsWithProducts[brand].add(p.name);
                        }
                    });
                }

            } catch (e: any) {
                console.error("Processing error:", e);
                let errorMessage = t('failedToAnalyze');
                if (e?.message?.toLowerCase().includes('requested entity was not found')) {
                     errorMessage = t('apiKeyError');
                     setHasApiKey(false);
                }
                processedResults.push({ ...image, status: 'error', error: errorMessage, retryCount: 0 });
            }
        }));

        setImages(prev => prev.map(img => {
            const processed = processedResults.find(p => p.id === img.id);
            return processed || img;
        }).sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

        const successfulImages = processedResults.filter(img => img.status === 'success');

        if (successfulImages.length > 0) {
            await populateCatalogFromAnalysis({ images: successfulImages });

            const currentClassifiedBrands = new Set([...brandClassifications.ourBrands, ...brandClassifications.competitorBrands]);
            const newlyFoundBrands = Object.keys(newDiscoveredBrandsWithProducts).filter(b => !currentClassifiedBrands.has(b));

            if (newlyFoundBrands.length > 0) {
                const updatedMap = { ...brandProductsMap };
                Object.entries(newDiscoveredBrandsWithProducts).forEach(([brand, products]) => {
                    if (!updatedMap[brand]) updatedMap[brand] = [];
                    const combined = new Set([...updatedMap[brand], ...Array.from(products)]);
                    updatedMap[brand] = Array.from(combined).sort().slice(0, 5);
                });

                setBrandProductsMap(updatedMap);
                setIsBrandModalOpen(true);
            }
        }
    };

    if (images.some(img => img.status === 'pending') && isOnline && !images.some(img => img.status === 'analyzing')) {
        processQueue();
    }
}, [images, isOnline, t, brandClassifications, activeAnalysis]);


  const endCurrentAnalysisAndSave = async () => {
    if (activeAnalysis) {
        await handleSaveAnalysis();
    }
    endCurrentAnalysisWithoutSaving();
  };

  const handleConfirmBrands = (classifications: BrandClassifications) => {
    setBrandClassifications(classifications);
    setIsBrandModalOpen(false);
    handleSaveAnalysis(); // Save after brand classification as well
  };

  const handleAddMoreClick = () => {
    setIsImageUploadOverlayOpen(true);
  };

  type ProductInList = { name: string; count: number; category: string; };

  const productList = React.useMemo(() => {
    const unassignedCategory = t('unassignedCategory');
    const productMap = new Map<string, { name: string; count: number }>();
    images.forEach(image => {
      if (image.analysisResult?.products && Array.isArray(image.analysisResult.products)) {
        image.analysisResult.products.forEach(product => {
          if (!product || !product.name) return;
          const currentName = product.name.trim();
          const existingCanonicalNames = Array.from(productMap.keys());
          const matchedCanonicalName = findBestMatch(currentName, existingCanonicalNames);

          const canonicalName = matchedCanonicalName || currentName;

          const entry = productMap.get(canonicalName);
          if (entry) {
            entry.count++;
          } else {
            productMap.set(canonicalName, { name: canonicalName, count: 1 });
          }
        });
      }
    });
    return Array.from(productMap.values())
      .map(({ name, count }) => ({ name, count, category: getCategoryFromName(name, unassignedCategory) }))
      .sort((a, b) => {
        const catCompare = a.category.localeCompare(b.category);
        if (catCompare !== 0) return catCompare;
        return b.count - a.count;
      });
  }, [images, t]);

  const groupedProducts: Record<string, ProductInList[]> = React.useMemo(() => {
    return productList.reduce<Record<string, ProductInList[]>>((acc, product) => {
        const category = product.category;
        if (!acc[category]) {
            acc[category] = [];
        }
        acc[category].push(product);
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [productList]);

  const filteredGroupedProducts = React.useMemo(() => {
    if (!productSearchTerm) return groupedProducts;
    const lowercasedTerm = productSearchTerm.toLowerCase();
    return Object.entries(groupedProducts).reduce<typeof groupedProducts>((acc, [category, products]) => {
        const filtered = products.filter(p => p.name.toLowerCase().includes(lowercasedTerm));
        if (filtered.length > 0) {
            acc[category] = filtered;
        }
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [groupedProducts, productSearchTerm]);

  const handleProductNameUpdate = React.useCallback(async (imageId: string, productId: string, originalName: string, newName: string) => {
    setImages(prevImages =>
      prevImages.map(image => {
        if (image.id !== imageId) return image;
        if (!image.analysisResult || !Array.isArray(image.analysisResult.products)) return image;

        const updatedProducts = image.analysisResult.products.map(p =>
          p.id === productId ? { ...p, name: newName, isCorrected: false } : p
        );

        return { ...image, analysisResult: { ...image.analysisResult, products: updatedProducts } };
      })
    );
    await addOrUpdateProductCorrection(originalName, newName);
    handleSaveAnalysis(); // Auto-save after product rename
  }, [handleSaveAnalysis]);

  const selectedImage = React.useMemo(() => images.find(img => img.id === selectedImageId), [images, selectedImageId]);

  const handleSummaryClick = () => {
    setSelectedImageId(null);
    setSelectedProductName(null);
    setHighlightedProductName(null);
  };

  const handleNavClick = (view: ActiveView) => {
    setActiveView(view);
    setSelectedCatalogProduct(null);
    if (view !== 'home' && images.length > 0) { 
        handleSummaryClick();
    } 
  };

  const handleSelectImage = (id: string, productNameToHighlight: string | null = null) => {
    setSelectedImageId(id);
    setSelectedProductName(null);
    setHighlightedProductName(productNameToHighlight);
  };

  const handleProductClick = (name: string) => {
    setSelectedProductName(name);
    setSelectedImageId(null);
    setHighlightedProductName(null);
  };

  const handleLoadAnalysis = async (analysisId: string) => {
    try {
        const analysisToLoad = await loadAnalysis(analysisId);

        if (analysisToLoad) {
          endCurrentAnalysisWithoutSaving();

          const loadedImages: ImageState[] = analysisToLoad.images.map(serializableImage => {
            const file = base64ToFile(
              serializableImage.file.data,
              serializableImage.file.name,
              serializableImage.file.type,
              serializableImage.file.lastModified
            );
            return {
              ...serializableImage,
              file,
              imageUrl: URL.createObjectURL(file),
              uploadDate: new Date(serializableImage.uploadDate),
              status: serializableImage.status || 'success', 
              analysisType: (serializableImage.analysisType || 'both') as AnalysisType,
              retryCount: serializableImage.retryCount || 0,
              assignedStoreId: serializableImage.assignedStoreId,
              modelName: serializableImage.modelName || 'gemini-2.5-flash'
            };
          });

          setActiveAnalysis(analysisToLoad);
          setImages(loadedImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
          setBrandClassifications(analysisToLoad.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');
        }
    } catch (e) {
        console.error("Failed to load analysis:", e);
        alert(t('archiveLoadError'));
    }
  };

  const handleMergeConfirm = async (sourceName: string, targetName: string) => {
    await addOrUpdateProductCorrection(sourceName, targetName);

    setImages(prevImages =>
      prevImages.map(image => {
        if (!image.analysisResult?.products) return image;

        const updatedProducts = image.analysisResult.products.map(p => {
            const isMatch = normalizeProductName(p.name) === normalizeProductName(sourceName);
            return isMatch ? { ...p, name: targetName, isCorrected: true } : p;
        });

        return { ...image, analysisResult: { ...image.analysisResult, products: updatedProducts } };
      })
    );
    setMergeCandidates(prev => prev.slice(1));
    handleSaveAnalysis();
  };

  const handleMergeReject = () => {
    setMergeCandidates(prev => prev.slice(1));
  };


  const isSummarySelected = !selectedImageId && !selectedProductName;

  if (!hasApiKey) {
    return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;
  }

  // --- RENDEROVANIE MODULOV S UVÍTACÍMI OBRAZOVKAMI ---
  const renderAnalysisModule = (title: string, icon: React.ElementType, description: string, viewType: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'distribution') => {
    if (!activeAnalysis && images.length === 0) {
        return (
            <div className="bg-white p-12 rounded-3xl shadow-sm border border-gray-100 text-center max-w-4xl mx-auto animate-fade-in">
                <div className="w-24 h-24 bg-lime-50 rounded-[2rem] flex items-center justify-center mx-auto mb-8 transition-transform hover:scale-110 duration-500">
                    {icon({ className: "w-12 h-12 text-lime-600" })}
                </div>
                <h2 className="text-3xl font-black text-gray-900 mb-4 tracking-tight">
                    {title}
                </h2>
                <p className="text-gray-500 mb-10 max-w-md mx-auto text-lg leading-relaxed">
                    {description}
                </p>
                <button
                    onClick={handleNewAnalysisClick}
                    className="inline-flex items-center gap-3 px-10 py-4 bg-lime-600 text-white font-black rounded-2xl hover:bg-lime-500 transition-all shadow-2xl shadow-lime-100 uppercase tracking-widest text-sm active:scale-95"
                >
                    <CalendarDaysIcon className="w-5 h-5" />
                    {t('startNewAnalysis')}
                </button>
            </div>
        );
    }

    if (images.length === 0 && viewType !== 'distribution') {
        return (
            <div className="w-full h-full flex items-center justify-center">
                <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
            </div>
        );
    }

    // OSA (Distribution) je špecifický panel, ktorý nepotrebuje bočný panel s fotkami
    if (viewType === 'distribution') {
        return <DistributionPanel activeImages={images} />;
    }

    return (
        <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8 main-grid-container">
            <aside className="lg:col-span-1 bg-white p-4 rounded-lg shadow-sm flex flex-col gap-4 self-start border border-gray-200 no-print">
                <div className="flex justify-between items-center mb-2 no-print">
                  <h3 className="font-bold text-gray-900 text-lg">
                    {sidebarView === 'images' ? t('images') : t('products')}
                  </h3>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setSidebarView('images')} className={`p-1 rounded-md text-sm font-medium ${sidebarView === 'images' ? 'bg-lime-100 text-lime-700' : 'text-gray-500 hover:bg-gray-100'}`} title={t('viewImages')}><AppIcon className="w-5 h-5" /></button>
                    <button onClick={() => setSidebarView('products')} className={`p-1 rounded-md text-sm font-medium ${sidebarView === 'products' ? 'bg-lime-100 text-lime-700' : 'text-gray-500 hover:bg-gray-100'}`} title={t('viewProducts')}><CircleStackIcon className="w-5 h-5" /></button>
                  </div>
                </div>

                {sidebarView === 'images' ? (
                  <>
                    <input
                      type="text"
                      placeholder={t('searchImages')}
                      value={productSearchTerm}
                      onChange={(e) => setProductSearchTerm(e.target.value)}
                      className="w-full rounded-md border-0 bg-gray-50 py-1.5 pl-3 pr-3 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-lime-500 sm:text-sm mb-4 no-print"
                    />
                    <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
                      {images.filter(img => productSearchTerm === '' || img.file.name.toLowerCase().includes(productSearchTerm.toLowerCase())).map((image) => (
                        <div
                          key={image.id}
                          onClick={() => handleSelectImage(image.id)}
                          className={`flex items-center gap-3 p-3 rounded-md cursor-pointer transition-colors mb-2 border ${
                            selectedImageId === image.id ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                          }`}
                        >
                          <img src={image.imageUrl} alt={image.file.name} className="w-12 h-12 object-cover rounded-md flex-shrink-0" />
                          <div className="flex-grow min-w-0">
                            <p className="font-medium text-gray-800 truncate">{image.file.name}</p>
                            <p className="text-xs text-gray-500">{image.uploadDate.toLocaleDateString()}</p>
                          </div>
                          {image.status === 'analyzing' && <SpinnerIcon className="w-4 h-4 text-lime-500" />}
                          {image.status === 'error' && <WarningIcon className="w-4 h-4 text-red-500" title={image.error || t('errorOccurred')} />}
                          {image.status === 'success' && image.analysisResult?.products.length === 0 && <span className="text-xs text-gray-500 italic">{t('noProductsFound')}</span>}
                        </div>
                      ))}
                    </div>
                  </>
                ) : (
                  <>
                    <input
                        type="text"
                        placeholder={t('searchProduct')}
                        value={productSearchTerm}
                        onChange={(e) => setProductSearchTerm(e.target.value)}
                        className="w-full rounded-md border-0 bg-gray-50 py-1.5 pl-3 pr-3 text-gray-900 ring-1 ring-inset ring-gray-300 placeholder:text-gray-400 focus:ring-2 focus:ring-inset focus:ring-lime-500 sm:text-sm mb-4 no-print"
                    />
                    <div className="max-h-[calc(100vh-280px)] overflow-y-auto pr-2">
                        {Object.keys(filteredGroupedProducts).length > 0 ? (
                            Object.entries(filteredGroupedProducts).map(([category, products]: [string, ProductInList[]]) => (
                                <div key={category} className="mb-4">
                                    <h4 className="text-xs font-semibold text-gray-500 uppercase mb-2 px-1">{category}</h4>
                                    {products.map(product => (
                                        <button
                                            key={product.name}
                                            onClick={() => handleProductClick(product.name)}
                                            className={`flex justify-between items-center w-full p-3 rounded-md transition-colors mb-2 border ${
                                                selectedProductName === product.name ? 'bg-lime-50 border-lime-400 ring-1 ring-lime-400' : 'bg-white border-gray-200 hover:bg-gray-50'
                                            }`}
                                        >
                                            <span className="font-medium text-gray-800 truncate">{product.name}</span>
                                            <span className="text-sm font-semibold text-lime-600 flex-shrink-0">{product.count}</span>
                                        </button>
                                    ))}
                                </div>
                            ))
                        ) : (
                            <div className="text-center py-10 text-sm text-gray-500">
                                {t('noProductsFound')}
                            </div>
                        )}
                    </div>
                  </>
                )}
                {images.length > 0 && (
                    <div className="mt-4 border-t border-gray-200 pt-4 no-print">
                        <button
                            onClick={handleAddMoreClick}
                            className="w-full flex justify-center items-center gap-2 py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-lime-600 hover:bg-lime-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-lime-500"
                        >
                            <UploadIcon className="w-5 h-5" />
                            {t('addMoreImages')}
                        </button>
                    </div>
                )}
            </aside>

            <main className="lg:col-span-3 flex flex-col gap-8">
                {isSummarySelected && (
                    <BatchSummaryPanel 
                        images={images} 
                        brandClassifications={brandClassifications} 
                        initialView={viewType as any} 
                        onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} 
                    />
                )}

                {selectedImageId && selectedImage && (
                    <ImageAnalysisDisplay imageUrl={selectedImage.imageUrl} analysisResult={selectedImage.analysisResult} isLoading={selectedImage.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                )}

                {selectedImageId && selectedImage && (
                    <ResultsPanel
                        imageId={selectedImage.id}
                        analysisResult={selectedImage.analysisResult}
                        isLoading={selectedImage.status === 'analyzing'}
                        error={selectedImage.error}
                        onProductNameUpdate={handleProductNameUpdate}
                        onRetry={() => handleRetryImage(selectedImage.id)}
                    />
                )}

                {selectedProductName && (
                    <ProductSummaryPanel productName={selectedProductName} images={images} onImageSelect={handleSelectImage} />
                )}
            </main>
        </div>
    );
  };

  const renderMainContent = (): React.ReactNode => {
    if (activeView === 'home') {
        return <HomeScreen onStartAnalysis={() => {
            handleNewAnalysisClick();
        }} />;
    }
    if (activeView === 'listing') return <ListingPanel />;
    if (activeView === 'productCatalog') {
        if (selectedCatalogProduct) {
            return <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} />;
        }
        return <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />;
    }
    if (activeView === 'analyses') return <AnalysesPanel onNewAnalysis={handleNewAnalysisClick} onLoadAnalysis={handleLoadAnalysis} />;
    if (activeView === 'stores') return <StoresPanel />;
    if (activeView === 'costs') return <CostPanel />;
    if (activeView === 'prompts') return <PromptManagerPanel />;

    // --- ANALYTICKÉ MODULY ---
    if (activeView === 'priceMonitoring') {
        return renderAnalysisModule(t('priceMonitoring'), ChartBarIcon, "Sledujte a porovnávajte ceny produktov na regáloch v reálnom čase pomocou umelej inteligencie.", "priceMonitoring");
    }
    if (activeView === 'shelfShare') {
        return renderAnalysisModule(t('shelfShare'), ChartPieIcon, "Analyzujte vizuálny podiel vašich značiek na regáli a porovnávajte ho s konzervanciou.", "shelfShare");
    }
    if (activeView === 'promoAlert') {
        return renderAnalysisModule(t('promoAlert'), ShieldExclamationIcon, "Monitorujte promo akcie konkurencie a kontrolujte správnosť nasadenia vašich vlastných akcií.", "promoAlert");
    }
    if (activeView === 'distribution') {
        return renderAnalysisModule(t('distributionModule'), TableCellsIcon, "Sledujte dostupnosť vašich produktov naprieč všetkými predajňami a identifikujte výpadky (Out-of-Stock) v reálnom čase.", "distribution");
    }
    if (activeView === 'gallery') {
        return <GalleryPanel />;
    }

    return (
        <div className="w-full h-full flex items-center justify-center">
             <HomeScreen onStartAnalysis={handleNewAnalysisClick} />
        </div>
    );
  };

  return (
    <React.Fragment>
      <div className="min-h-screen bg-gray-100 flex flex-col">
        <Header onNewAnalysis={handleNewAnalysisClick} onOpenSearch={() => setIsSearchModalOpen(true)} />
        <GlobalAnalysisStatus 
            total={analysisStats.total} 
            completed={analysisStats.completed} 
            analyzing={analysisStats.analyzing} 
            errors={analysisStats.errors} 
        />
        <div className="flex flex-1 overflow-hidden">
          <Sidebar activeView={activeView} onNavClick={handleNavClick} />
          <div className="flex-1 p-6 overflow-y-auto">
            {renderMainContent()}
          </div>
        </div>
      </div>
      <div className="modal-overlays-container">
        <NewAnalysisModal
            isOpen={isNewAnalysisModalOpen}
            onClose={() => setIsNewAnalysisModalOpen(false)}
            onConfirm={handleStartAnalysis}
            initialFiles={pendingFiles}
        />

        <ClearConfirmModal
          isOpen={isClearConfirmOpen}
          onClose={() => setIsClearConfirmOpen(false)}
          onConfirmDelete={endCurrentAnalysisWithoutSaving}
          onSaveToArchive={endCurrentAnalysisAndSave}
        />

        <BrandDefinitionModal
          isOpen={isBrandModalOpen}
          onClose={() => setIsBrandModalOpen(false)}
          onConfirm={handleConfirmBrands}
          allBrands={Object.keys(brandProductsMap)}
          brandProductsMap={brandProductsMap}
        />

        <SearchModal
          isOpen={isSearchModalOpen}
          onClose={() => setIsSearchModalOpen(false)}
          onLoadAnalysis={handleLoadAnalysis}
        />

        {mergeCandidates.length > 0 && (
            <MergeConfirmationModal
                isOpen={true}
                candidate={mergeCandidates[0]}
                onConfirm={handleMergeConfirm}
                onReject={handleMergeReject}
                onClose={handleMergeReject}
            />
        )}

         {missingPriceItems.length > 0 && (
              <MissingPriceModal
                  isOpen={isMissingPriceModalOpen}
                  onClose={() => setIsMissingPriceModalOpen(false)}
                  items={missingPriceItems}
                  onSave={handleUpdatePrices}
              />
         )}

        {isImageUploadOverlayOpen && (
            <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true" aria-labelledby="image-upload-modal-title">
                <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all">
                    <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-gray-50 rounded-t-lg">
                        <h2 id="image-upload-modal-title" className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            <UploadIcon className="w-6 h-6 text-lime-600" />
                            {t('uploadMoreImagesTitle')}
                        </h2>
                        <button onClick={() => setIsImageUploadOverlayOpen(false)} className="text-gray-400 hover:text-gray-600">
                            <CloseIcon className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6">
                        <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </React.Fragment>
  );
};

export default App;

import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, ArchiveBoxIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon, BoxIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number;
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    storeCode?: string;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices }): React.ReactNode => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') {
        setView('priceAnalysis');
    } else if (initialView === 'shelfShare') {
        setView('shelfShare');
    } else if (initialView === 'promoAlert') {
        setView('promoAlert');
    } else if (initialView === 'costs') {
        setView('rawData'); 
    }
  }, [initialView]);

  const missingPriceCount = useMemo(() => {
      return images.reduce((count, img) => {
          if (!img.analysisResult?.products) return count;
          const missingInImage = img.analysisResult.products.filter(p => !p.prices || p.prices.length === 0).length;
          return count + missingInImage;
      }, 0);
  }, [images]);

  const getStoreIdentifier = useCallback((storeInfo?: StoreInfo) => {
    const unknownStore = t('unknownStore');
    if (storeInfo) {
        const { chain, address } = storeInfo;
        const cleanedChain = removeDateFromStoreName(chain);
        const cleanedAddress = removeDateFromStoreName(address);

        if (cleanedChain && cleanedAddress) return `${cleanedChain}, ${cleanedAddress}`;
        return cleanedChain || cleanedAddress || unknownStore;
    }
    return unknownStore;
  }, [t]);

  const { storeData, analyzedImagesCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, code?: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    images.forEach(img => {
        if (!img.analysisResult) return;

        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;
        let storeCode = img.assignedStore?.code;

        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
            }
        } else {
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const { chain, address } = storeInfo;
                const cleanedChain = removeDateFromStoreName(chain);
                const cleanedAddress = removeDateFromStoreName(address);
                if (cleanedChain && cleanedAddress) storeDisplayName = `${cleanedChain}, ${cleanedAddress}`;
                else storeDisplayName = cleanedChain || cleanedAddress || unknownStore;
            } else if (img.assignedStore) {
                 storeDisplayName = img.assignedStore.name;
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) {
            productsByStore.set(storeKey, { name: storeDisplayName, code: storeCode, items: [] });
        }

        const storeGroup = productsByStore.get(storeKey)!;
        if (storeGroup.name === unknownStore && img.assignedStore?.name) {
             storeGroup.name = img.assignedStore.name;
        }

        if (Array.isArray(img.analysisResult.products)) {
            img.analysisResult.products.forEach(p => {
                if (p && p.name) {
                    storeGroup.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
                }
            });
        }
    });

    const finalData: StoreCentricSummary[] = Array.from(productsByStore.entries())
        .map(([key, data]): StoreCentricSummary => {
            const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();

            data.items.forEach(p => {
                let groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : findBestMatch(p.name.trim(), Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'))) || p.name.trim();
                if (!productsMap.has(groupKey)) productsMap.set(groupKey, []);
                productsMap.get(groupKey)!.push(p);
            });

            const summarizedProducts: ProductInStore[] = Array.from(productsMap.entries())
                .filter(([, occurrences]) => occurrences.length > 0)
                .map(([groupKey, occurrences]): ProductInStore => {
                    const representative = occurrences[0];
                    const name = representative.name; 
                    const confidences = occurrences.map(o => o.confidence);

                    const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];
                    const occurrencesByImage = occurrences.reduce((acc, o) => { (acc[o.imageId] = acc[o.imageId] || []).push(o); return acc; }, {} as Record<string, typeof occurrences>);

                    Object.values(occurrencesByImage).forEach(imageOccurrences => {
                        const uniquePricesOnImage = new Map<string, PriceInfo>();
                        imageOccurrences.forEach(o => (o.prices || []).forEach(price => uniquePricesOnImage.set(`${price.value}|${price.type}`, price)));
                        uniquePricesOnImage.forEach(price => priceHistory.push({ price, date: imageOccurrences[0].uploadDate, imageUrl: imageOccurrences[0].imageUrl }));
                    });

                    return {
                        name,
                        isCorrected: occurrences.some(o => o.isCorrected),
                        category: getCategoryFromName(name, unassignedCategory),
                        count: occurrences.length,
                        priceHistory: priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime()),
                        avgConfidence: confidences.reduce((a, b) => a + b, 0) / confidences.length,
                        imageUrl: priceHistory.length > 0 ? priceHistory[priceHistory.length - 1].imageUrl : occurrences[0].imageUrl,
                        catalogProductId: representative.catalogProductId
                    };
                });

            return {
                storeName: data.name,
                storeId: typeof key === 'number' ? key : undefined,
                storeCode: data.code,
                products: summarizedProducts.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
            };
        }).sort((a,b) => a.storeName.localeCompare(b.storeName));

    const filteredData = finalData
        .map(store => {
            if (filters.chain && store.storeName !== filters.chain) return null;
            const filteredProducts = store.products.filter(item => {
                if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
                if (filters.category && item.category !== filters.category) return false;
                if (item.avgConfidence * 100 < filters.confidence) return false;
                if (filters.minPrice !== '' || filters.maxPrice !== '') {
                    const numericPrices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                    const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                    const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);
                    if (!numericPrices.some(p => p >= min && p <= max)) return false;
                }
                return true;
            });
            if (filteredProducts.length === 0) return null;
            return { ...store, products: filteredProducts };
        })
        .filter((s): s is StoreCentricSummary => s !== null);

    return {
      storeData: filteredData,
      analyzedImagesCount: images.filter(img => img.analysisResult || img.error).length,
      allCategories: Array.from(new Set(finalData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(finalData.map(s => s.storeName))).sort()
    };
  }, [images, filters, t, unassignedCategory, getStoreIdentifier]);

  const totalImages = images.length;
  const isAnalyzing = images.some(img => img.status === 'analyzing');

  const stats = useMemo(() => {
    let total = 0;
    let unique = new Set();
    storeData.forEach(s => s.products.forEach(p => { 
        total += p.count; 
        unique.add(p.catalogProductId ? `ID_${p.catalogProductId}` : p.name); 
    }));
    return { total, unique: unique.size };
  }, [storeData]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[95vw] max-h-[95vh] object-contain rounded-lg" alt="Zoom" />
            <button className="absolute top-6 right-6 text-white bg-black/40 p-3 rounded-full hover:bg-black/60"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-black text-gray-900 tracking-tight">{t('batchSummary')}</h2>
        {missingPriceCount > 0 && (
            <button onClick={onOpenMissingPrices} className="flex items-center gap-2 px-4 py-2 bg-orange-50 text-orange-700 rounded-xl hover:bg-orange-100 border border-orange-200 transition-all font-bold text-sm animate-pulse">
                <TagIcon className="w-5 h-5" />
                {t('fixMissingPrices', { count: missingPriceCount })}
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
        {[
            { label: t('imagesCount'), val: totalImages, color: 'text-gray-900' },
            { label: t('analyzed'), val: analyzedImagesCount, color: 'text-lime-600' },
            { label: t('totalProducts'), val: stats.total, color: 'text-lime-600' },
            { label: t('uniqueProducts'), val: stats.unique, color: 'text-lime-600' }
        ].map((s, i) => (
            <div key={i} className="bg-gray-50 p-5 rounded-2xl border border-gray-100 text-center">
                <p className={`text-2xl font-black ${s.color}`}>{s.val}</p>
                <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{s.label}</p>
            </div>
        ))}
      </div>

      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon, cond: true },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon, cond: initialView === 'shelfShare' },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon, cond: initialView === 'promoAlert' },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon, cond: true }
          ].filter(tab => tab.cond).map(tab => (
            <button
                key={tab.id}
                onClick={() => setView(tab.id as any)}
                className={`-mb-px px-6 py-3 text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600 bg-lime-50/30' : 'border-transparent text-gray-400 hover:text-gray-700'}`}
            >
                <tab.icon className="w-4 h-4" />
                {tab.label}
            </button>
          ))}
      </div>

      <div className="flex-grow">
        {view === 'priceAnalysis' && (
          <div className="animate-fade-in">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-3 mb-6 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-xl transition-all bg-lime-600 text-white hover:bg-lime-700 shadow-lg shadow-lime-100">
                    <ArrowDownTrayIcon className="w-4 h-4" /> {t('exportToXLS')}
                </button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-xl transition-all bg-gray-900 text-white hover:bg-black shadow-lg shadow-gray-200">
                    <DocumentTextIcon className="w-4 h-4" /> {t('exportToPDF')}
                </button>
            </div>

            <div className="space-y-8 max-h-[calc(100vh-480px)] overflow-y-auto pr-3 custom-scrollbar">
                {storeData.length > 0 ? storeData.map(store => {
                    // Group products by category within store
                    const groupedByCategory = store.products.reduce((acc, p) => {
                        if (!acc[p.category]) acc[p.category] = [];
                        acc[p.category].push(p);
                        return acc;
                    }, {} as Record<string, ProductInStore[]>);

                    return (
                        <div key={store.storeName} className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="bg-gray-50/50 px-6 py-4 border-b border-gray-100 flex items-center justify-between">
                                <h3 className="font-black text-gray-900 text-base flex items-center gap-3">
                                    {store.storeName}
                                    {store.storeCode && <span className="bg-blue-100 text-blue-700 text-[10px] px-2 py-0.5 rounded-lg font-black uppercase">#{store.storeCode}</span>}
                                </h3>
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                    {store.products.length} {t('products').toLowerCase()}
                                </span>
                            </div>

                            <div className="p-2 space-y-4">
                                {Object.entries(groupedByCategory).map(([catName, products]) => (
                                    <div key={catName} className="space-y-1">
                                        <div className="px-4 py-1.5 flex items-center gap-2">
                                            <div className="h-px bg-gray-100 flex-grow"></div>
                                            <span className="text-[10px] font-black text-lime-600 uppercase tracking-[0.2em]">{catName}</span>
                                            <div className="h-px bg-gray-100 flex-grow"></div>
                                        </div>

                                        <div className="divide-y divide-gray-50">
                                            {products.map(product => {
                                                const regularPrice = product.priceHistory.find(ph => ph.price.type === 'REGULAR')?.price.value;
                                                const promoPrice = product.priceHistory.find(ph => ph.price.type === 'PROMO')?.price.value;
                                                const confColor = product.avgConfidence >= 0.9 ? 'bg-green-500' : 'bg-orange-500';

                                                return (
                                                    <div key={product.name} className="group flex items-center gap-4 px-4 py-2 hover:bg-lime-50/40 transition-colors rounded-xl">
                                                        <div className="flex-grow min-w-0">
                                                            <div className="flex items-center gap-2">
                                                                <p className="font-bold text-gray-800 text-sm truncate">{product.name}</p>
                                                                {product.isCorrected && <MagicWandIcon className="w-3.5 h-3.5 text-purple-500 flex-shrink-0" />}
                                                            </div>
                                                            <div className="flex items-center gap-3 mt-0.5">
                                                                <div className="flex items-center gap-1.5">
                                                                    <div className={`w-1.5 h-1.5 rounded-full ${confColor}`}></div>
                                                                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">
                                                                        {Math.round(product.avgConfidence * 100)}% {t('confidence').toLowerCase()}
                                                                    </span>
                                                                </div>
                                                                <div className="flex items-center gap-1 text-[10px] font-bold text-gray-400">
                                                                    <BoxIcon className="w-3 h-3" />
                                                                    {product.count} {t('facesLabel').toLowerCase()}
                                                                </div>
                                                            </div>
                                                        </div>

                                                        <div className="flex items-center gap-2 flex-shrink-0">
                                                            {regularPrice && (
                                                                <div className={`px-2 py-1 rounded-lg text-xs font-black border ${promoPrice ? 'bg-gray-100 text-gray-400 line-through border-gray-100' : 'bg-gray-50 text-gray-700 border-gray-100'}`}>
                                                                    {regularPrice}
                                                                </div>
                                                            )}
                                                            {promoPrice && (
                                                                <div className="px-2 py-1 rounded-lg text-xs font-black bg-red-50 text-red-600 border border-red-100 shadow-sm">
                                                                    {promoPrice}
                                                                </div>
                                                            )}
                                                            {!regularPrice && !promoPrice && (
                                                                <span className="text-[10px] font-bold text-gray-300 italic uppercase">{t('noPriceData')}</span>
                                                            )}
                                                        </div>

                                                        <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-100 flex-shrink-0 bg-gray-50 group-hover:border-lime-200 transition-all cursor-zoom-in" onClick={() => setZoomedImage(product.imageUrl || null)}>
                                                            {product.imageUrl && <img src={product.imageUrl} alt="P" className="w-full h-full object-cover grayscale-[0.5] group-hover:grayscale-0 transition-all" />}
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                }) : (
                    <div className="text-center py-20 bg-gray-50 rounded-3xl border border-dashed border-gray-200">
                        <ChartBarIcon className="w-12 h-12 text-gray-200 mx-auto mb-3" />
                        <p className="text-sm text-gray-400 font-medium">{t('noProductsForFilter')}</p>
                    </div>
                )}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && (
            <div className="bg-gray-900 text-lime-400 p-6 rounded-2xl overflow-x-auto font-mono text-xs max-h-[calc(100vh-320px)] custom-scrollbar border border-gray-800 shadow-2xl">
                <pre>{JSON.stringify(images, null, 2)}</pre>
            </div>
        )}
      </div>

       <div className="mt-8 pt-6 border-t border-gray-100 flex items-center gap-4 no-print">
        <button
          onClick={onReset}
          className="w-full bg-red-50 hover:bg-red-100 text-red-600 font-black py-4 px-6 rounded-2xl transition-all duration-200 flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
        >
          <TrashIcon className="w-5 h-5" />
          {t('endVisit')}
        </button>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e5e7eb; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #d1d5db; }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .animate-fade-in { animation: fadeIn 0.3s ease-out forwards; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  );
};

import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
// FIX: Re-importing icons to ensure all exports are recognized. The issue appears to be with module resolution, not the import path or component names themselves.
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, ArchiveBoxIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';
// Removed: import { PlanogramCompliancePanel } from './PlanogramCompliancePanel'; // NEW

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number; // New grouping key
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    // FIX: Updated initialView type to exclude 'planogramCompliance' and include 'costs'.
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
    // Removed: referenceImageBase64: string | null; // NEW
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices /*, referenceImageBase64 */ }): React.ReactNode => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  // FIX: Updated view state to exclude 'planogramCompliance' and include 'rawData'.
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Set initial view, ensuring it's one of the valid tabs within BatchSummaryPanel
    // FIX: Removed 'planogramCompliance' from validViews and corrected mapping for 'costs'.
    const validViews = ['priceMonitoring', 'shelfShare', 'promoAlert', 'costs']; 
    if (validViews.includes(initialView)) {
        // Map external `initialView` to internal `view` state
        if (initialView === 'priceMonitoring') {
            setView('priceAnalysis');
        } else if (initialView === 'shelfShare') {
            setView('shelfShare');
        } else if (initialView === 'promoAlert') {
            setView('promoAlert');
        } else if (initialView === 'costs') {
            // FIX: Map 'costs' initialView to 'rawData' since CostPanel is removed.
            setView('rawData'); 
        }
    } else {
        setView('priceAnalysis'); // Default to priceAnalysis if initialView is not recognized
    }
  }, [initialView]);

  // Calculate missing prices count
  const missingPriceCount = useMemo(() => {
      return images.reduce((count, img) => {
          if (!img.analysisResult?.products) return count;
          const missingInImage = img.analysisResult.products.filter(p => !p.prices || p.prices.length === 0).length;
          return count + missingInImage;
      }, 0);
  }, [images]);

  // Define getStoreIdentifier here
  const getStoreIdentifier = useCallback((storeInfo?: StoreInfo) => {
    const unknownStore = t('unknownStore');
    if (storeInfo) {
        const { chain, address } = storeInfo;
        const cleanedChain = removeDateFromStoreName(chain);
        const cleanedAddress = removeDateFromStoreName(address);

        if (cleanedChain && cleanedAddress) return `${cleanedChain}, ${cleanedAddress}`;
        return cleanedChain || cleanedAddress || unknownStore;
    }
    return unknownStore;
  }, [t]);

  const { storeData, totalProducts, uniqueProductCount, analyzedImagesCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');

    // 1. Group by Store (preferring storeId)
    // Key: StoreID (number) or StoreName (string)
    const productsByStore = new Map<string | number, { name: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    images.forEach(img => {
        if (!img.analysisResult) return;

        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;

        // Use Store ID if linked
        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
                 if(img.assignedStore.code) storeDisplayName += ` [${img.assignedStore.code}]`;
            }
        } else {
            // Fallback to name/address string
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const { chain, address } = storeInfo;
                const cleanedChain = removeDateFromStoreName(chain);
                const cleanedAddress = removeDateFromStoreName(address);
                if (cleanedChain && cleanedAddress) storeDisplayName = `${cleanedChain}, ${cleanedAddress}`;
                else storeDisplayName = cleanedChain || cleanedAddress || unknownStore;
            } else if (img.assignedStore) {
                 storeDisplayName = img.assignedStore.name;
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) {
            productsByStore.set(storeKey, { name: storeDisplayName, items: [] });
        }

        const storeGroup = productsByStore.get(storeKey)!;

        // FIX: Update storeGroup.name only if it's less specific (i.e., 'unknownStore')
        if (storeGroup.name === unknownStore && img.assignedStore?.name) {
             storeGroup.name = img.assignedStore.name;
        }

        if (Array.isArray(img.analysisResult.products)) {
            img.analysisResult.products.forEach(p => {
                if (p && p.name) {
                    storeGroup.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
                }
            });
        }
    });

    // 2. For each store, group products by CatalogID or Name
    // FIX: Added explicit return type to the map callback to help TypeScript inference.
    const finalData: StoreCentricSummary[] = Array.from(productsByStore.entries())
        .map(([key, data]): StoreCentricSummary => {
            // Group items: ID-based preferred, fallback to fuzzy name
            const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();

            data.items.forEach(p => {
                let groupKey = '';

                if (p.catalogProductId) {
                    groupKey = `ID_${p.catalogProductId}`;
                } else {
                    const currentName = p.name.trim();
                    const existingKeys = Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'));
                    const matchedCanonicalName = findBestMatch(currentName, existingKeys);
                    groupKey = matchedCanonicalName || currentName;
                }

                if (!productsMap.has(groupKey)) {
                    productsMap.set(groupKey, []);
                }
                productsMap.get(groupKey)!.push(p);
            });

            // FIX: Filter out empty occurrences before mapping to ProductInStore
            // FIX: Add explicit return type to the map callback to help TypeScript inference.
            const summarizedProducts: ProductInStore[] = Array.from(productsMap.entries())
                .filter(([, occurrences]) => occurrences.length > 0) // Ensure occurrences is not empty
                .map(([groupKey, occurrences]): ProductInStore => {
                    const representative = occurrences[0]; // Now guaranteed to be defined
                    const name = representative.name; 

                    const count = occurrences.length;
                    const confidences = occurrences.map(o => o.confidence);
                    const avgConfidence = confidences.reduce((a, b) => a + b, 0) / confidences.length;
                    const isCorrected = occurrences.some(o => o.isCorrected);

                    const occurrencesByImage = occurrences.reduce((acc, o) => {
                        (acc[o.imageId] = acc[o.imageId] || []).push(o);
                        return acc;
                    }, {} as Record<string, typeof occurrences>);

                    const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];
                    Object.values(occurrencesByImage).forEach(imageOccurrences => {
                        if (imageOccurrences.length === 0) return;
                        const uniquePricesOnImage = new Map<string, PriceInfo>();
                        const date = imageOccurrences[0].uploadDate;
                        const imageUrl = imageOccurrences[0].imageUrl;

                        imageOccurrences.forEach(o => {
                            (Array.isArray(o.prices) ? o.prices : []).forEach(price => {
                                const key = `${price.value}|${price.type}`;
                                if (!uniquePricesOnImage.has(key)) {
                                    uniquePricesOnImage.set(key, price);
                                }
                            });
                        });
                        uniquePricesOnImage.forEach(price => {
                            priceHistory.push({ price, date, imageUrl });
                        });
                    });
                    priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime());

                    let latestImageUrl: string | undefined;
                    if (priceHistory.length > 0) {
                        latestImageUrl = priceHistory[priceHistory.length - 1].imageUrl;
                    } else if (occurrences.length > 0) {
                        const sortedOccurrences = [...occurrences].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime());
                        latestImageUrl = sortedOccurrences[0].imageUrl;
                    }

                    return {
                        name,
                        isCorrected,
                        category: getCategoryFromName(name, unassignedCategory),
                        count,
                        priceHistory,
                        avgConfidence,
                        imageUrl: latestImageUrl,
                        catalogProductId: representative.catalogProductId
                    };
                });

            return {
                storeName: data.name,
                storeId: typeof key === 'number' ? key : undefined,
                products: summarizedProducts.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
            };
        }).sort((a,b) => a.storeName.localeCompare(b.storeName));

    const allChainsForFilter = Array.from(new Set(finalData.map(s => s.storeName))).sort();

    // 3. Apply filters
    const filteredData = finalData
        .map(store => {
            if (filters.chain && store.storeName !== filters.chain) {
                return null;
            }

            const filteredProducts = store.products.filter(item => {
                if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
                if (filters.category && item.category !== filters.category) return false;
                if (item.avgConfidence * 100 < filters.confidence) return false;

                if (filters.minPrice !== '' || filters.maxPrice !== '') {
                    if (item.priceHistory.length === 0) return false;
                    const numericPrices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                    if (numericPrices.length === 0) return false;

                    const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                    const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);

                    if (!numericPrices.some(p => p >= min && p <= max)) return false;
                }
                return true;
            });

            if (filteredProducts.length === 0) return null;
            return { ...store, products: filteredProducts };
        })
        .filter((s): s is StoreCentricSummary => s !== null);

    const allProductsCount = Array.from(productsByStore.values()).reduce((sum, data) => sum + data.items.length, 0);
    // Unique based on ID if available, else name
    const allUniqueProducts = new Set();
    finalData.forEach(store => {
        store.products.forEach(p => {
            if (p.catalogProductId) allUniqueProducts.add(`ID_${p.catalogProductId}`);
