import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo, ObjectType, PosType } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, ArchiveBoxIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon, BoxIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number;
    type: ObjectType;
    posType?: PosType;
    isGhost?: boolean;
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    storeCode?: string;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices }): React.ReactNode => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '',
    minPrice: '',
    maxPrice: '',
    confidence: 0,
    category: '',
    chain: '',
    posFilter: 'all',
    hideGhosts: true
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') setView('priceAnalysis');
    else if (initialView === 'shelfShare') setView('shelfShare');
    else if (initialView === 'promoAlert') setView('promoAlert');
    else if (initialView === 'costs') setView('rawData'); 
  }, [initialView]);

  // FIX: Added missing getStoreIdentifier callback to resolve reference error in storeData useMemo dependencies.
  const getStoreIdentifier = useCallback((storeInfo?: StoreInfo) => {
    const unknownStore = t('unknownStore');
    if (storeInfo) {
        const { chain, address } = storeInfo;
        const cleanedChain = removeDateFromStoreName(chain);
        const cleanedAddress = removeDateFromStoreName(address);

        if (cleanedChain && cleanedAddress) return `${cleanedChain}, ${cleanedAddress}`;
        return cleanedChain || cleanedAddress || unknownStore;
    }
    return unknownStore;
  }, [t]);

  const missingPriceCount = useMemo(() => {
      return images.reduce((count, img) => {
          if (!img.analysisResult?.products) return count;
          // Pre výpočet chýbajúcich cien berieme len reálne produkty
          const missingInImage = img.analysisResult.products.filter(p => p.type === 'product' && !p.isGhost && (!p.prices || p.prices.length === 0)).length;
          return count + missingInImage;
      }, 0);
  }, [images]);

  const { storeData, analyzedImagesCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, code?: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    images.forEach(img => {
        if (!img.analysisResult) return;

        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;
        let storeCode = img.assignedStore?.code;

        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
            }
        } else {
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const { chain, address } = storeInfo;
                const cleanedChain = removeDateFromStoreName(chain);
                const cleanedAddress = removeDateFromStoreName(address);
                if (cleanedChain && cleanedAddress) storeDisplayName = `${cleanedChain}, ${cleanedAddress}`;
                else storeDisplayName = cleanedChain || cleanedAddress || unknownStore;
            } else if (img.assignedStore) {
                 storeDisplayName = img.assignedStore.name;
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) {
            productsByStore.set(storeKey, { name: storeDisplayName, code: storeCode, items: [] });
        }

        const storeGroup = productsByStore.get(storeKey)!;
        if (storeGroup.name === unknownStore && img.assignedStore?.name) {
             storeGroup.name = img.assignedStore.name;
        }

        if (Array.isArray(img.analysisResult.products)) {
            img.analysisResult.products.forEach(p => {
                if (p && p.name) {
                    storeGroup.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
                }
            });
        }
    });

    const finalData: StoreCentricSummary[] = Array.from(productsByStore.entries())
        .map(([key, data]): StoreCentricSummary => {
            const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();

            data.items.forEach(p => {
                let groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : findBestMatch(p.name.trim(), Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'))) || p.name.trim();
                // Rozlišujeme POS od Produktov v kľúči
                groupKey = `${p.type}_${groupKey}`;
                if (p.isGhost) groupKey += '_ghost';

                if (!productsMap.has(groupKey)) productsMap.set(groupKey, []);
                productsMap.get(groupKey)!.push(p);
            });

            const summarizedProducts: ProductInStore[] = Array.from(productsMap.entries())
                .filter(([, occurrences]) => occurrences.length > 0)
                .map(([groupKey, occurrences]): ProductInStore => {
                    const representative = occurrences[0];
                    const name = representative.name; 
                    const confidences = occurrences.map(o => o.confidence);

                    const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];
                    const occurrencesByImage = occurrences.reduce((acc, o) => { (acc[o.imageId] = acc[o.imageId] || []).push(o); return acc; }, {} as Record<string, typeof occurrences>);

                    Object.values(occurrencesByImage).forEach(imageOccurrences => {
                        const uniquePricesOnImage = new Map<string, PriceInfo>();
                        imageOccurrences.forEach(o => (o.prices || []).forEach(price => uniquePricesOnImage.set(`${price.value}|${price.type}`, price)));
                        uniquePricesOnImage.forEach(price => priceHistory.push({ price, date: imageOccurrences[0].uploadDate, imageUrl: imageOccurrences[0].imageUrl }));
                    });

                    return {
                        name,
                        isCorrected: occurrences.some(o => o.isCorrected),
                        category: getCategoryFromName(name, unassignedCategory),
                        count: occurrences.length,
                        priceHistory: priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime()),
                        avgConfidence: confidences.reduce((a, b) => a + b, 0) / confidences.length,
                        imageUrl: priceHistory.length > 0 ? priceHistory[priceHistory.length - 1].imageUrl : occurrences[0].imageUrl,
                        catalogProductId: representative.catalogProductId,
                        type: representative.type,
                        posType: representative.posType,
                        isGhost: representative.isGhost
                    };
                });

            return {
                storeName: data.name,
                storeId: typeof key === 'number' ? key : undefined,
                storeCode: data.code,
                products: summarizedProducts.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
            };
        }).sort((a,b) => a.storeName.localeCompare(b.storeName));

    const filteredData = finalData
        .map(store => {
            if (filters.chain && store.storeName !== filters.chain) return null;
            const filteredProducts = store.products.filter(item => {
                if (filters.hideGhosts && item.isGhost) return false;

                if (filters.posFilter === 'products_only' && item.type !== 'product') return false;
                if (filters.posFilter === 'pos_only' && item.type !== 'pos_material') return false;
                if (filters.posFilter && ['wobbler', 'stopper', 'stand', 'pallet', 'secondary_display'].includes(filters.posFilter) && item.posType !== filters.posFilter) return false;

                if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
                if (filters.category && item.category !== filters.category) return false;
                if (item.avgConfidence * 100 < filters.confidence) return false;

                if (filters.minPrice !== '' || filters.maxPrice !== '') {
                    const numericPrices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                    const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                    const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);
                    if (!numericPrices.some(p => p >= min && p <= max)) return false;
                }
                return true;
            });
            if (filteredProducts.length === 0) return null;
            return { ...store, products: filteredProducts };
        })
        .filter((s): s is StoreCentricSummary => s !== null);

    return {
      storeData: filteredData,
      analyzedImagesCount: images.filter(img => img.analysisResult || img.error).length,
      allCategories: Array.from(new Set(finalData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(finalData.map(s => s.storeName))).sort()
    };
  }, [images, filters, t, unassignedCategory, getStoreIdentifier]);

  const stats = useMemo(() => {
    let totalFacings = 0;
    let posCount = 0;
    let unique = new Set();
    storeData.forEach(s => s.products.forEach(p => { 
        if (p.type === 'product' && !p.isGhost) totalFacings += p.count; 
        if (p.type === 'pos_material') posCount += p.count;
        unique.add(p.catalogProductId ? `ID_${p.catalogProductId}` : p.name); 
    }));
    return { totalFacings, posCount, unique: unique.size };
  }, [storeData]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-[100] flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[95vw] max-h-[95vh] object-contain rounded-lg" alt="Zoom" />
            <button className="absolute top-6 right-6 text-white bg-black/40 p-3 rounded-full hover:bg-black/60"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-black text-gray-900 tracking-tight">{t('batchSummary')}</h2>
        {missingPriceCount > 0 && (
            <button onClick={onOpenMissingPrices} className="flex items-center gap-2 px-4 py-2 bg-orange-50 text-orange-700 rounded-xl hover:bg-orange-100 border border-orange-200 transition-all font-bold text-sm animate-pulse">
                <TagIcon className="w-5 h-5" />
                {t('fixMissingPrices', { count: missingPriceCount })}
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
        <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 text-center">
            <p className="text-2xl font-black text-gray-900">{analyzedImagesCount}</p>
            <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">Spracované</p>
        </div>
        <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 text-center">
            <p className="text-2xl font-black text-lime-600">{stats.totalFacings}</p>
            <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">Kusov (SKU)</p>
        </div>
        <div className="bg-purple-50 p-5 rounded-2xl border border-purple-100 text-center">
            <p className="text-2xl font-black text-purple-600">{stats.posCount}</p>
            <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">POS Materiálov</p>
        </div>
        <div className="bg-gray-50 p-5 rounded-2xl border border-gray-100 text-center">
            <p className="text-2xl font-black text-gray-900">{stats.unique}</p>
            <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">Unikátnych SKU</p>
        </div>
      </div>

      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon, cond: true },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon, cond: initialView === 'shelfShare' },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon, cond: initialView === 'promoAlert' },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon, cond: true }
          ].filter(tab => tab.cond).map(tab => (
            <button
                key={tab.id}
                onClick={() => setView(tab.id as any)}
                className={`-mb-px px-6 py-3 text-xs font-black uppercase tracking-widest transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600 bg-lime-50/30' : 'border-transparent text-gray-400 hover:text-gray-700'}`}
            >
                <tab.icon className="w-4 h-4" />
                {tab.label}
            </button>
          ))}
      </div>

      <div className="flex-grow">
        {view === 'priceAnalysis' && (
          <div className="animate-fade-in">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-3 mb-6 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-xl transition-all bg-lime-600 text-white hover:bg-lime-700 shadow-lg shadow-lime-100">
                    <ArrowDownTrayIcon className="w-4 h-4" /> {t('exportToXLS')}
                </button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-xl transition-all bg-gray-900 text-white hover:bg-black shadow-lg shadow-gray-200">
                    <DocumentTextIcon className="w-4 h-4" /> {t('exportToPDF')}
                </button>
            </div>

            <div className="space-y-8 max-h-[calc(100vh-480px)] overflow-y-auto pr-3 custom-scrollbar">
                {storeData.length > 0 ? storeData.map(store => {
                    const groupedByCategory = store.products.reduce((acc, p) => {
                        if (!acc[p.category]) acc[p.category] = [];
                        acc[p.category].push(p);
                        return acc;
                    }, {} as Record<string, ProductInStore[]>);

                    return (
                        <div key={store.storeName} className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="bg-gray-50/50 px-6 py-4 border-b border-gray-100 flex items-center justify-between">
                                <h3 className="font-black text-gray-900 text-base flex items-center gap-3">
                                    {store.storeName}
                                    {store.storeCode && <span className="bg-blue-100 text-blue-700 text-[10px] px-2 py-0.5 rounded-lg font-black uppercase">#{store.storeCode}</span>}
                                </h3>
                                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                                    {store.products.length} položiek
                                </span>
                            </div>

                            <div className="p-2 space-y-4">
                                {Object.entries(groupedByCategory).map(([catName, products]: [string, ProductInStore[]]) => (
                                    <div key={catName} className="space-y-1">
                                        <div className="px-4 py-1.5 flex items-center gap-2">
                                            <div className="h-px bg-gray-100 flex-grow"></div>
                                            <span className="text-[10px] font-black text-lime-600 uppercase tracking-[0.2em]">{catName}</span>
                                            <div className="h-px bg-gray-100 flex-grow"></div>
                                        </div>

                                        <div className="divide-y divide-gray-50">
                                            {products.map(product => {
                                                const regularPrice = product.priceHistory.find(ph => ph.price.type === 'REGULAR')?.price.value;
                                                const promoPrice = product.priceHistory.find(ph => ph.price.type === 'PROMO')?.price.value;
                                                const isPOS = product.type === 'pos_material';

                                                return (
                                                    <div key={`${product.name}-${product.isGhost}`} className="group flex items-center gap-4 px-4 py-2 hover:bg-lime-50/40 transition-colors rounded-xl">
                                                        <div className="flex-grow min-w-0">
                                                            <div className="flex items-center gap-2">
                                                                <p className={`font-bold text-sm truncate ${product.isGhost ? 'text-gray-400 italic' : 'text-gray-800'}`}>
                                                                    {product.name}
                                                                </p>
                                                                {product.isGhost && <ShieldExclamationIcon className="w-3.5 h-3.5 text-gray-300" title="Ghost produkt (reklama)" />}
                                                                {isPOS && <span className="bg-purple-100 text-purple-600 text-[8px] px-1.5 py-0.5 rounded font-black uppercase">POS: {product.posType}</span>}
                                                                {product.isCorrected && <MagicWandIcon className="w-3.5 h-3.5 text-purple-500 flex-shrink-0" />}
                                                            </div>
                                                            <div className="flex items-center gap-3 mt-0.5">
                                                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">
                                                                    {Math.round(product.avgConfidence * 100)}% {t('confidence').toLowerCase()}
                                                                </span>
                                                                {!isPOS && (
                                                                    <div className="flex items-center gap-1 text-[10px] font-bold text-gray-400">
                                                                        <BoxIcon className="w-3 h-3" />
                                                                        {product.count} {t('facesLabel').toLowerCase()}
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>

                                                        {!isPOS && (
                                                            <div className="flex items-center gap-2 flex-shrink-0">
                                                                {regularPrice && (
                                                                    <div className={`px-2 py-1 rounded-lg text-xs font-black border ${promoPrice ? 'bg-gray-100 text-gray-400 line-through border-gray-100' : 'bg-gray-50 text-gray-700 border-gray-100'}`}>
                                                                        {regularPrice}
                                                                    </div>
                                                                )}
                                                                {promoPrice && (
                                                                    <div className="px-2 py-1 rounded-lg text-xs font-black bg-red-50 text-red-600 border border-red-100 shadow-sm">
                                                                        {promoPrice}
                                                                    </div>
                                                                )}
                                                            </div>
                                                        )}

                                                        <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-100 flex-shrink-0 bg-gray-50 group-hover:border-lime-200 transition-all cursor-zoom-in" onClick={() => setZoomedImage(product.imageUrl || null)}>
                                                            {product.imageUrl && <img src={product.imageUrl} alt="P" className={`w-full h-full object-cover transition-all ${product.isGhost ? 'grayscale opacity-50' : 'grayscale-[0.5] group-hover:grayscale-0'}`} />}
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                }) : (
                    <div className="text-center py-20 bg-gray-50 rounded-3xl border border-dashed border-gray-200">
                        <ChartBarIcon className="w-12 h-12 text-gray-200 mx-auto mb-3" />
                        <p className="text-sm text-gray-400 font-medium">{t('noProductsForFilter')}</p>
                    </div>
                )}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && (
            <div className="bg-gray-900 text-lime-400 p-6 rounded-2xl overflow-x-auto font-mono text-xs max-h-[calc(100vh-320px)] custom-scrollbar border border-gray-800 shadow-2xl">
                <pre>{JSON.stringify(images, null, 2)}</pre>
            </div>
        )}
      </div>

       <div className="mt-8 pt-6 border-t border-gray-100 flex items-center gap-4 no-print">
        <button
          onClick={onReset}
          className="w-full bg-red-50 hover:bg-red-100 text-red-600 font-black py-4 px-6 rounded-2xl transition-all duration-200 flex items-center justify-center gap-3 uppercase tracking-widest text-sm"
        >
          <TrashIcon className="w-5 h-5" />
          {t('endVisit')}
        </button>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e5e7eb; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #d1d5db; }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .animate-fade-in { animation: fadeIn 0.3s ease-out forwards; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
    </div>
  );
};

