  type ProductInList = { name: string; count: number; category: string; };

  const productList = React.useMemo(() => {
    const unassignedCategory = t('unassignedCategory');
    const productMap = new Map<string, { name: string; count: number }>();
    images.forEach(image => {
      if (image.analysisResult?.products && Array.isArray(image.analysisResult.products)) {
        image.analysisResult.products.forEach(product => {
          if (!product || !product.name) return;
          const currentName = product.name.trim();
          const existingCanonicalNames = Array.from(productMap.keys());
          const matchedCanonicalName = findBestMatch(currentName, existingCanonicalNames);

          const canonicalName = matchedCanonicalName || currentName;

          const entry = productMap.get(canonicalName);
          if (entry) {
            entry.count++;
          } else {
            productMap.set(canonicalName, { name: canonicalName, count: 1 });
          }
        });
      }
    });
    return Array.from(productMap.values())
      .map(({ name, count }) => ({ name, count, category: getCategoryFromName(name, unassignedCategory) }))
      .sort((a, b) => {
        const catCompare = a.category.localeCompare(b.category);
        if (catCompare !== 0) return catCompare;
        return b.count - a.count;
      });
  }, [images, t]);

  const groupedProducts: Record<string, ProductInList[]> = React.useMemo(() => {
    return productList.reduce<Record<string, ProductInList[]>>((acc, product) => {
        const category = product.category;
        if (!acc[category]) {
            acc[category] = [];
        }
        acc[category].push(product);
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [productList]);

  const filteredGroupedProducts = React.useMemo(() => {
    if (!productSearchTerm) return groupedProducts;
    const lowercasedTerm = productSearchTerm.toLowerCase();
    return Object.entries(groupedProducts).reduce<typeof groupedProducts>((acc, [category, products]) => {
        const filtered = products.filter(p => p.name.toLowerCase().includes(lowercasedTerm));
        if (filtered.length > 0) {
            acc[category] = filtered;
        }
        return acc;
    }, {} as Record<string, ProductInList[]>);
  }, [groupedProducts, productSearchTerm]);

