                    <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={endCurrentAnalysisAndSave} initialView={activeView} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />
                )}
                {isSummarySelected && activeView === 'shelfShare' && (
                    <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={endCurrentAnalysisAndSave} initialView={activeView} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />
                )}
                {isSummarySelected && activeView === 'promoAlert' && (
                    <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={endCurrentAnalysisAndSave} initialView={activeView} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />
                )}

                {selectedImageId && selectedImage && (
                    <ImageAnalysisDisplay imageUrl={selectedImage.imageUrl} analysisResult={selectedImage.analysisResult} isLoading={selectedImage.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                )}

                {selectedImageId && selectedImage && (
                    <ResultsPanel
                        imageId={selectedImage.id}
                        analysisResult={selectedImage.analysisResult}
                        isLoading={selectedImage.status === 'analyzing'}
                        error={selectedImage.error}
                        onReset={endCurrentAnalysisAndSave}
                        onProductNameUpdate={handleProductNameUpdate}
                        onRetry={() => handleRetryImage(selectedImage.id)}
                    />
                )}

                {selectedProductName && (
                    <ProductSummaryPanel productName={selectedProductName} images={images} onReset={endCurrentAnalysisAndSave} onImageSelect={handleSelectImage} />
                )}
            </main>
        </div>
    );
  };

  const currentAnalysisStats = React.useMemo(() => {
    return {
        total: images.length,
        completed: images.filter(img => img.status === 'success').length,
        analyzing: images.filter(img => img.status === 'analyzing').length,
        errors: images.filter(img => img.status === 'error').length
    };
  }, [images]);

  return (
    <React.Fragment>
      <div className="min-h-screen bg-gray-100 flex flex-col">
        <Header onNewAnalysis={handleNewAnalysisClick} onOpenSearch={() => setIsSearchModalOpen(true)} />
        <GlobalAnalysisStatus {...currentAnalysisStats} />
        <div className="flex flex-1 overflow-hidden">
          <Sidebar activeView={activeView} onNavClick={handleNavClick} />
          <div className="flex-1 p-6 overflow-y-auto">
            {renderMainContent()}
          </div>
        </div>
      </div>
      <div className="modal-overlays-container">
        <NewAnalysisModal
            isOpen={isNewAnalysisModalOpen}
            onClose={() => setIsNewAnalysisModalOpen(false)}
            onConfirm={handleCreateAnalysis}
        />

        <AnalysisTypeModal
          isOpen={isAnalysisModalOpen}
          onClose={() => {
              setIsAnalysisModalOpen(false);
          }}
          onSelect={handleConfirmAnalysisType} 
        />

        <StoreAssignmentModal
            isOpen={isStoreAssignmentOpen}
            onClose={() => setIsStoreAssignmentOpen(false)}
            onAssign={(store) => {
                setImages(prev => prev.map(img => ({ ...img, assignedStore: store, assignedStoreId: store.id })));
                setIsStoreAssignmentOpen(false);
            }}
            imagesCount={images.length}
        />

        <ClearConfirmModal
          isOpen={isClearConfirmOpen}
          onClose={() => setIsClearConfirmOpen(false)}
          onConfirmDelete={endCurrentAnalysisWithoutSaving}
          onSaveToArchive={endCurrentAnalysisAndSave}
        />

        <BrandDefinitionModal
          isOpen={isBrandModalOpen}
          onClose={() => setIsBrandModalOpen(false)}
          onConfirm={handleConfirmBrands}
          allBrands={brandsForClassification}
        />

        <SearchModal
          isOpen={isSearchModalOpen}
          onClose={() => setIsSearchModalOpen(false)}
          onLoadAnalysis={handleLoadAnalysis}
        />

        {mergeCandidates.length > 0 && (
            <MergeConfirmationModal
                isOpen={true}
                candidate={mergeCandidates[0]}
                onConfirm={handleMergeConfirm}
                onReject={handleMergeReject}
                onClose={handleMergeReject}
            />
        )}

         {missingPriceItems.length > 0 && (
              <MissingPriceModal
                  isOpen={isMissingPriceModalOpen}
                  onClose={() => setIsMissingPriceModalOpen(false)}
                  items={missingPriceItems}
                  onSave={handleUpdatePrices}
              />
         )}

        {isImageUploadOverlayOpen && (
            <div className="fixed inset-0 bg-gray-800 bg-opacity-75 flex items-center justify-center z-50 p-4" role="dialog" aria-modal="true" aria-labelledby="image-upload-modal-title">
                <div className="bg-white rounded-lg shadow-xl w-full max-w-2xl transform transition-all">
                    <div className="p-6 border-b border-gray-200 flex justify-between items-center bg-gray-50 rounded-t-lg">
                        <h2 id="image-upload-modal-title" className="text-lg font-bold text-gray-900 flex items-center gap-2">
                            <UploadIcon className="w-6 h-6 text-lime-600" />
                            {t('uploadMoreImagesTitle')}
                        </h2>
                        <button onClick={() => setIsImageUploadOverlayOpen(false)} className="text-gray-400 hover:text-gray-600">
                            <CloseIcon className="w-5 h-5" />
                        </button>
                    </div>
                    <div className="p-6">
                        <ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} />
                    </div>
                </div>
            </div>
        )}
      </div>
    </React.Fragment>
  );
};

