            return {
              id: image.id,
              file: {
                name: image.file.name,
                type: image.file.type,
                lastModified: image.file.lastModified,
                data: base64Data,
              },
              imageUrl: '',
              analysisResult: image.analysisResult,
              status: image.status,
              error: image.error,
              uploadDate: image.uploadDate.toISOString(),
              analysisType: image.analysisType,
              retryCount: image.retryCount,
              assignedStore: image.assignedStore,
              assignedStoreId: image.assignedStoreId,
              modelName: image.modelName
