import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses } from '../db.ts';
import type { DetectedProduct, Analysis } from '../types.ts';
import { base64ToFile } from '../utils/helpers.ts';
import { 
    TagIcon, 
    SpinnerIcon, 
    BuildingStorefrontIcon, 
    CalendarDaysIcon,
    AppIcon,
    ChevronRightIcon
} from './Icons.tsx';

interface PosMaterialItem {
    id: string;
    type: string;
    storeName: string;
    analysisName: string;
    uploadDate: Date;
    imageUrl: string;
    product: DetectedProduct;
}

export const PosMaterialPanel: React.FC = () => {
    const { t } = useTranslation();
    const [items, setItems] = useState<PosMaterialItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        const loadPOS = async () => {
            setIsLoading(true);
            try {
                const analyses = await getAnalyses();
                const flattened: PosMaterialItem[] = [];

                analyses.forEach(analysis => {
                    const storeName = analysis.store?.name || t('unknownStore');

                    analysis.images.forEach(img => {
                        if (!img.analysisResult?.products) return;

                        const posProducts = img.analysisResult.products.filter(p => p.type === 'pos_material');

                        if (posProducts.length > 0) {
                            const file = base64ToFile(img.file.data, img.file.name, img.file.type, img.file.lastModified);
                            const url = URL.createObjectURL(file);

                            posProducts.forEach(pos => {
                                flattened.push({
                                    id: pos.id,
                                    type: pos.posType || 'unspecified',
                                    storeName,
                                    analysisName: analysis.name,
                                    uploadDate: new Date(img.uploadDate),
                                    imageUrl: url,
                                    product: pos
                                });
                            });
                        }
                    });
                });

                setItems(flattened.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
            } catch (e) {
                console.error("POS load error:", e);
            } finally {
                setIsLoading(false);
            }
        };
        loadPOS();

        return () => {
            // Clean up URLs to prevent memory leaks
            items.forEach(item => {
                if (item.imageUrl.startsWith('blob:')) {
                    URL.revokeObjectURL(item.imageUrl);
                }
            });
        };
    }, []);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center h-64">
                <SpinnerIcon className="w-12 h-12 text-lime-600 animate-spin" />
                <p className="mt-4 text-gray-500 font-medium">{t('pleaseWait')}</p>
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-6xl mx-auto pb-10">
            <div className="flex justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                <div className="flex items-center gap-4">
                    <div className="bg-purple-100 p-3 rounded-2xl">
                        <TagIcon className="w-6 h-6 text-purple-700" />
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-900">{t('posMaterial')}</h2>
                        <p className="text-sm text-gray-500 font-medium">{t('posMaterialTitle')}</p>
                    </div>
                </div>
                <div className="bg-purple-50 px-4 py-2 rounded-xl border border-purple-100">
                    <span className="text-purple-700 font-black text-lg">{items.length}</span>
                    <span className="ml-2 text-[10px] text-purple-400 uppercase font-black tracking-widest">detekcií</span>
                </div>
            </div>

            {items.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {items.map((item) => (
                        <div key={item.id} className="bg-white rounded-2xl overflow-hidden border border-gray-100 shadow-sm hover:shadow-md transition-all flex h-40">
                            {/* Thumbnail */}
                            <div className="w-40 h-full relative flex-shrink-0 bg-gray-100">
                                <img 
                                    src={item.imageUrl} 
                                    className="w-full h-full object-cover" 
                                    alt="POS Preview"
                                />
                                <div className="absolute top-2 left-2">
                                    <span className="bg-purple-600 text-white text-[10px] font-black px-2 py-1 rounded-lg uppercase shadow-lg">
                                        {item.type}
                                    </span>
                                </div>
                            </div>

                            {/* Details */}
                            <div className="flex-grow p-4 flex flex-col justify-between">
                                <div>
                                    <div className="flex items-center gap-2 mb-1">
                                        <BuildingStorefrontIcon className="w-4 h-4 text-gray-400" />
                                        <p className="text-sm font-black text-gray-800 truncate">{item.storeName}</p>
                                    </div>
                                    <h3 className="font-bold text-gray-900 leading-tight mb-2">
                                        {item.product.name}
                                    </h3>
                                    <div className="flex items-center gap-4">
                                        <div className="flex items-center gap-1.5">
                                            <CalendarDaysIcon className="w-3.5 h-3.5 text-gray-300" />
                                            <span className="text-[10px] font-bold text-gray-400">{item.uploadDate.toLocaleDateString()}</span>
                                        </div>
                                        <div className="flex items-center gap-1.5">
                                            <AppIcon className="w-3.5 h-3.5 text-gray-300" />
                                            <span className="text-[10px] font-bold text-gray-400 truncate max-w-[100px]">{item.analysisName}</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="flex justify-between items-end mt-2">
                                    <div className="flex items-center gap-1">
                                        <div className="h-1.5 w-1.5 rounded-full bg-green-500"></div>
                                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">AI CONFIDENCE: {Math.round(item.product.confidence * 100)}%</span>
                                    </div>
                                    <button className="p-2 bg-gray-50 hover:bg-lime-50 rounded-xl text-gray-400 hover:text-lime-600 transition-colors">
                                        <ChevronRightIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="bg-white rounded-3xl p-20 text-center border border-dashed border-gray-200">
                    <TagIcon className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400 font-medium">{t('noPosFound')}</p>
                </div>
            )}
        </div>
    );
};

