import type { DetectedProduct, MergeCandidate } from '../types';

const MULTI_WORD_CATEGORIES = ['Bon pari'];

// Interná cache pre normalizované názvy kvoli šetreniu CPU v cykloch
const normalizationCache = new Map<string, string>();

const capitalize = (s: string) => {
    if (!s) return '';
    return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
}

export const getCategoryFromName = (name: string, unassignedCategory: string): string => {
  if (!name) return unassignedCategory;
  const lowerName = name.toLowerCase();
  for (const cat of MULTI_WORD_CATEGORIES) {
    if (lowerName.startsWith(cat.toLowerCase())) return cat;
  }
  const firstWord = name.split(' ')[0];
  return capitalize(firstWord) || unassignedCategory;
};

export const getBrandFromName = (name: string): string => {
  if (!name) return '';
  return name.split(' ')[0];
};

export const parseDateFromFileName = (fileName: string): Date | null => {
    let match = fileName.match(/(\d{1,2})[._-]\d{1,2}[._-]\d{4}/);
    if (match) {
        const [_, day, month, year] = match;
        const date = new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T12:00:00Z`);
        if (!isNaN(date.getTime())) return date;
    }
    match = fileName.match(/(\d{4})-(\d{2})-(\d{2})/);
    if (match) {
        const [_, year, month, day] = match;
        const date = new Date(`${year}-${month}-${day}T12:00:00Z`);
        if (!isNaN(date.getTime())) return date;
    }
    return null;
}

export const extractStoreFromFilename = (filename: string): string | null => {
    const knownChains = [
        'Tesco', 'Billa', 'Lidl', 'Kaufland', 'Coop', 'Metro', 'Terno', 'Kraj', 
        'Fresh', 'CBA', 'Jednota', 'Albert', 'Globus', 'Penny', 'DM'
    ];
    let cleanedName = filename.replace(/\.[^/.]+$/, "");
    cleanedName = cleanedName.replace(/\d{1,2}[._-]\d{1,2}[._-]\d{4}/g, ' ');
    const normalized = cleanedName.replace(/[_\-.]/g, ' ').replace(/\s+/g, ' ').trim();

    for (const chain of knownChains) {
        const regex = new RegExp(`\\b${chain}\\b`, 'i');
        const match = normalized.match(regex);
        if (match) {
            const remainder = normalized.substring((match.index || 0) + match[0].length).trim();
            const locationParts = remainder.split(/[, ]+/).filter(t => t.length > 2).slice(0, 2);
            return locationParts.length > 0 ? `${chain}, ${locationParts.map(capitalize).join(' ')}` : chain;
        }
    }
    return null;
};

export const calculateStringSimilarity = (a: string, b: string): number => {
    if (!a || !b) return 0;
    if (a === b) return 100;
    const alen = a.length;
    const blen = b.length;
    const matrix = Array(blen + 1).fill(null).map(() => Array(alen + 1).fill(0));
    for (let i = 0; i <= alen; i++) matrix[0][i] = i;
    for (let j = 0; j <= blen; j++) matrix[j][0] = j;
    for (let j = 1; j <= blen; j++) {
        for (let i = 1; i <= alen; i++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            matrix[j][i] = Math.min(matrix[j][i - 1] + 1, matrix[j - 1][i] + 1, matrix[j - 1][i - 1] + cost);
        }
    }
    return (1 - matrix[blen][alen] / Math.max(alen, blen)) * 100;
};

export const normalizeProductName = (name: string): string => {
  if (!name) return '';
  const cached = normalizationCache.get(name);
  if (cached) return cached;
  const result = name.toLowerCase().trim().replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, "").replace(/\s+/g, ' ');
  normalizationCache.set(name, result);
  return result;
};

interface Candidate { name: string; visualFeatures?: string; }

// Výkonná verzia matching logiky s redukovaným počtom operácií
export const findBestMatch = (query: string, candidates: (string | Candidate)[]): string | null => {
    if (!query || candidates.length === 0) return null;
    const normQuery = normalizeProductName(query);
    let bestMatch: string | null = null;
    let highestScore = 0;

    for (const cand of candidates) {
        const candName = typeof cand === 'string' ? cand : cand.name;
        if (candName === query) return candName;

        const normCand = normalizeProductName(candName);
        if (normCand === normQuery) return candName;

        const score = calculateStringSimilarity(normQuery, normCand);
        if (score > highestScore && score > 85) {
            highestScore = score;
            bestMatch = candName;
        }
    }
    return bestMatch;
};

export const removeDateFromStoreName = (name?: string): string => {
    if (!name) return '';
    return name.replace(/\s*\(\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*-\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*\)/gi, '').trim();
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = error => reject(error);
  });
};

export const base64ToFile = (base64: string, name: string, type: string, lastModified: number): File => {
  const byteCharacters = atob(base64);
  const byteArray = new Uint8Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) byteArray[i] = byteCharacters.charCodeAt(i);
  return new File([new Blob([byteArray], { type })], name, { type, lastModified });
};

export const resizeAndCompressImage = (file: File, maxWidth: number = 1600, quality: number = 0.75): Promise<File> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.src = url;
        img.onload = () => {
            URL.revokeObjectURL(url);
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
                const ratio = maxWidth / width;
                width = maxWidth;
                height = height * ratio;
            }
            const canvas = document.createElement('canvas');
            canvas.width = width;
            canvas.height = height;
            canvas.getContext('2d')?.drawImage(img, 0, 0, width, height);
            canvas.toBlob(blob => {
                if (blob) resolve(new File([blob], file.name, { type: 'image/jpeg', lastModified: file.lastModified }));
                else reject(new Error("Compression failed"));
            }, 'image/jpeg', quality);
        };
        img.onerror = () => {
            URL.revokeObjectURL(url);
            reject(new Error("Image load failed"));
        };
    });
};

export const findMergeCandidates = (newProducts: DetectedProduct[], allProducts: DetectedProduct[]): MergeCandidate[] => {
    const candidates: MergeCandidate[] = [];
    const processedIds = new Set<string>();
    for (const np of newProducts) {
        if (processedIds.has(np.id)) continue;
        for (const ep of allProducts) {
            if (np.id === ep.id || processedIds.has(ep.id)) continue;
            const score = calculateStringSimilarity(normalizeProductName(np.name), normalizeProductName(ep.name));
            if (score >= 92) {
                candidates.push({ target: ep, source: np });
                processedIds.add(np.id);
                processedIds.add(ep.id);
                break;
            }
        }
    }
    return candidates;
};

