import { useTranslation } from './i18n';
import { AnalysisTypeModal } from './components/AnalysisTypeModal';
import { ClearConfirmModal } from './components/ClearConfirmModal';
import { HomeScreen } from './components/HomeScreen';
import { db, saveAnalysis, loadAnalysis, addOrUpdateProductCorrection, findProductByAlias, populateCatalogFromAnalysis, getCatalogEntries, getAnalyses, findOrCreateStore } from './db';
import { BrandDefinitionModal } from './components/BrandDefinitionModal';
import { Header } from './components/Header';
import { SearchModal } from './components/SearchModal';
import { ProductCatalogPanel, ProductCardPanel } from './components/ProductCatalogPanel';
import { NewAnalysisModal } from './components/NewAnalysisModal';
import { DistributionPanel } from './components/DistributionPanel';
import { ListingPanel } from './components/ListingPanel';
import { StoresPanel } from './components/StoresPanel';
import { StoreAssignmentModal } from './components/StoreAssignmentModal';
import { MergeConfirmationModal } from './components/MergeConfirmationModal';
import { AnalysesPanel } from './components/AnalysesPanel';
import { ApiKeySelectionScreen } from './components/ApiKeySelectionScreen';
import { MissingPriceModal, MissingPriceItem } from './components/MissingPriceModal';
import Sidebar from './components/Sidebar';
import { GlobalAnalysisStatus } from './components/GlobalAnalysisStatus';
import { GalleryPanel } from './components/GalleryPanel';
import { CostPanel } from './components/CostPanel';
import { PromptManagerPanel } from './components/PromptManagerPanel';
import { PosMaterialPanel } from './components/PosMaterialPanel';

export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName?: string;
}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = React.useState(false); 
  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandsForClassification, setBrandsForClassification] = React.useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);
  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = React.useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const missingPriceItems = React.useMemo<MissingPriceItem[]>(() => {
      const items: MissingPriceItem[] = [];
      images.forEach(img => {
          if (img.analysisResult?.products) {
              img.analysisResult.products.forEach(p => {
                  if (p.type === 'product' && !p.isGhost && (!p.prices || p.prices.length === 0)) {
                      items.push({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl });
                  }
              });
          }
      });
      return items;
  }, [images]);

  const handleUpdatePrices = (updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prev => prev.map(img => {
          const updatesForImage = updates.filter(u => u.imageId === img.id);
          if (updatesForImage.length === 0) return img;
          const updatedProducts = img.analysisResult?.products.map(p => {
              const update = updatesForImage.find(u => u.productId === p.id);
              return update ? { ...p, prices: update.prices } : p;
          });
          return { ...img, analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null };
      }));
  };

  const handleNewAnalysisClick = () => {
    if (activeAnalysis && images.length > 0) setIsClearConfirmOpen(true);
    else setIsNewAnalysisModalOpen(true);
  };

  const handleImageUpload = React.useCallback((files: FileList) => {
    if (!activeAnalysis) {
        setPendingFiles(files); 
        handleNewAnalysisClick(); 
        return;
    }
    setPendingFiles(files);
    setIsAnalysisModalOpen(true); 
    setIsImageUploadOverlayOpen(false); 
  }, [activeAnalysis]);

  const handleStartAnalysis = React.useCallback(async (type: AnalysisType, model: string, fileList: FileList, analysisOverride?: Analysis) => {
    const targetAnalysis = analysisOverride || activeAnalysis;
    if (!targetAnalysis) return;

    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const initialId = `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`;
        const filenameStoreName = extractStoreFromFilename(file.name);
        let effectiveStore: Store | null = null;
        let effectiveStoreId: number | undefined = undefined;

        if (filenameStoreName) {
             try {
                effectiveStore = await findOrCreateStore({ name: filenameStoreName, chain: filenameStoreName.split(',')[0].trim(), city: '', address: '', code: '' });
                effectiveStoreId = effectiveStore.id;
             } catch (e) { console.warn("Auto-store link failed", e); }
        }

        return {
            id: initialId,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: effectiveStore,
            assignedStoreId: effectiveStoreId,
            modelName: model
        };
    }));

    setImages(prev => [...prev, ...tempImages].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    (async () => {
        for (const img of tempImages) {
            try {
                const compressedFile = await resizeAndCompressImage(img.file);
                const newUrl = URL.createObjectURL(compressedFile);
                setImages(prev => prev.map(p => {
                    if (p.id === img.id) {
                        URL.revokeObjectURL(p.imageUrl);
                        return { ...p, file: compressedFile, imageUrl: newUrl };
                    }
                    return p;
                }));
            } catch (e) { console.error("Compression error", e); }
        }
    })();
  }, [activeAnalysis]);

  const handleRetryImage = (id: string) => {
      setImages(prev => prev.map(img => img.id === id ? { ...img, status: 'pending', error: null } : img));
  };

  React.useEffect(() => {
    const processQueue = async () => {
        if (!isOnline) return;
        const pendingImages = images.filter(img => img.status === 'pending');
        if (pendingImages.length === 0 || images.some(img => img.status === 'analyzing')) return;

        const currentBatch = pendingImages.slice(0, 2); // Menší batch kvoli plynulosti mobilov
        setImages(prev => prev.map(img => currentBatch.find(b => b.id === img.id) ? { ...img, status: 'analyzing' } : img));

        const type = currentBatch[0].analysisType;
        const usedModelName = currentBatch[0].modelName || 'gemini-2.5-flash';
        const catalogEntries = await getCatalogEntries();
        const knownProductsList = catalogEntries.map(e => e.canonicalName).join(', ');
        const knownProductsString = knownProductsList ? t('knownProductsList', { products: knownProductsList }) : '';

        const geminiPrompt = t(type === 'price' ? 'geminiPromptPriceOnly' : type === 'shelfShare' ? 'geminiPromptShelfShareOnly' : type === 'osa' ? 'geminiPromptOsaOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', knownProductsString);

        await Promise.all(currentBatch.map(async (image) => {
            try {
                const base64Image = await fileToBase64(image.file);
                const result = await analyzeImageWithGemini(base64Image, geminiPrompt, t('geminiSystemInstruction'), type, usedModelName); 

                let store = image.assignedStore;
                let storeId = image.assignedStoreId;

                if (!store && result.storeInfo && (result.storeInfo.chain || result.storeInfo.address)) {
                    const chain = result.storeInfo.chain || '';
                    const address = result.storeInfo.address || '';
                    store = await findOrCreateStore({ name: chain + (address ? `, ${address}` : ''), chain, address, city: '', code: '' });
                    storeId = store.id;
                }

                const correctedProducts = await Promise.all((result.products || []).map(async p => {
                    const entry = await findProductByAlias(p.name);
                    const finalName = entry ? entry.canonicalName : p.name;
                    return { ...p, name: finalName, isCorrected: !!entry, catalogProductId: entry?.id, id: `${image.id}-${finalName}-${Math.random()}`, imageId: image.id };
                }));

                setImages(prev => prev.map(img => img.id === image.id ? { ...img, analysisResult: { ...result, products: correctedProducts }, status: 'success', assignedStore: store, assignedStoreId: storeId } : img));
            } catch (e: any) {
                console.error("AI Error:", e);
                const isAuth = e?.message?.includes('entity was not found');
                if (isAuth) setHasApiKey(false);
                setImages(prev => prev.map(img => img.id === image.id ? { ...img, status: 'error', error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } : img));
            }
        }));
    };
    processQueue();
  }, [images, isOnline, t]);

  const endCurrentAnalysisWithoutSaving = () => {
    images.forEach(img => URL.revokeObjectURL(img.imageUrl));
    setImages([]);
    setSelectedImageId(null);
    setSelectedProductName(null);
    setActiveView('home');
    setActiveAnalysis(null);
  };

  const endCurrentAnalysisAndSave = async () => {
    if (activeAnalysis) await handleSaveAnalysis();
    endCurrentAnalysisWithoutSaving();
  };

  const handleCreateAnalysis = async (name: string, type: AnalysisType, model: string, files: FileList) => {
    endCurrentAnalysisWithoutSaving(); 
    const newA: Analysis = { id: `analysis-${Date.now()}`, name, createdAt: new Date().toISOString(), images: [], store: null };
    const id = await db.analyses.add(newA); 
    const saved = await db.analyses.get(id); 
    if (saved) {
        setActiveAnalysis(saved);
        setIsNewAnalysisModalOpen(false); 
        setActiveView('priceMonitoring'); 
        await handleStartAnalysis(type, model, files, saved);
    }
  };

  const productList = React.useMemo(() => {
    const map = new Map<string, { name: string; count: number; category: string }>();
    images.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p || !p.name) return;
        const canonical = findBestMatch(p.name, Array.from(map.keys())) || p.name;
        const existing = map.get(canonical);
        if (existing) existing.count++;
        else map.set(canonical, { name: canonical, count: 1, category: getCategoryFromName(canonical, t('unassignedCategory')) });
      });
    });
    return Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
  }, [images, t]);

  const handleProductNameUpdate = React.useCallback(async (imageId: string, productId: string, originalName: string, newName: string) => {
    setImages(prev => prev.map(img => {
        if (img.id !== imageId || !img.analysisResult) return img;
        const updated = img.analysisResult.products.map(p => p.id === productId ? { ...p, name: newName, isCorrected: false } : p);
        return { ...img, analysisResult: { ...img.analysisResult, products: updated } };
    }));
    await addOrUpdateProductCorrection(originalName, newName);
  }, []);

  const handleSaveAnalysis = async () => {
    if (!activeAnalysis) return;
    try {
        const serialImages: SerializableImageState[] = await Promise.all(images.map(async img => {
            const data = await fileToBase64(img.file);
            return {
              id: img.id,
              file: { name: img.file.name, type: img.file.type, lastModified: img.file.lastModified, data },
              imageUrl: '',
              analysisResult: img.analysisResult,
              status: img.status,
              error: img.error,
              uploadDate: img.uploadDate.toISOString(),
              analysisType: img.analysisType,
              retryCount: img.retryCount,
              assignedStore: img.assignedStore,
              assignedStoreId: img.assignedStoreId,
              modelName: img.modelName
            };
        }));
        const updated = { ...activeAnalysis, images: serialImages, brandClassifications, storeId: serialImages[0]?.assignedStoreId };
        await db.analyses.put(updated);
        setActiveAnalysis(updated);
    } catch (e) { console.error("Save failed", e); }
  };

  const handleLoadAnalysis = async (id: string) => {
    const a = await loadAnalysis(id);
    if (a) {
        endCurrentAnalysisWithoutSaving();
        const loaded = a.images.map(si => {
            const f = base64ToFile(si.file.data, si.file.name, si.file.type, si.file.lastModified);
            return { ...si, file: f, imageUrl: URL.createObjectURL(f), uploadDate: new Date(si.uploadDate), status: 'success', retryCount: 0 };
        });
        setActiveAnalysis(a);
        setImages(loaded.sort((x, y) => y.uploadDate.getTime() - x.uploadDate.getTime()));
        setBrandClassifications(a.brandClassifications || { ourBrands: [], competitorBrands: [] });
        setIsSearchModalOpen(false);
        setActiveView('priceMonitoring');
    }
  };

  const currentAnalysisStats = React.useMemo(() => ({
      total: images.length,
      completed: images.filter(img => img.status === 'success').length,
      analyzing: images.filter(img => img.status === 'analyzing').length,
      errors: images.filter(img => img.status === 'error').length
  }), [images]);

  if (!hasApiKey) return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      <Header onNewAnalysis={handleNewAnalysisClick} onOpenSearch={() => setIsSearchModalOpen(true)} />
      <GlobalAnalysisStatus {...currentAnalysisStats} />
      <div className="flex flex-1 overflow-hidden">
        <Sidebar activeView={activeView} onNavClick={v => { setActiveView(v); setSelectedCatalogProduct(null); if (v !== 'home' && images.length) handleSummaryClick(); }} />
        <div className="flex-1 p-6 overflow-y-auto">
          {activeView === 'home' ? <HomeScreen onStartAnalysis={handleNewAnalysisClick} /> :
           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={handleNewAnalysisClick} onLoadAnalysis={handleLoadAnalysis} /> :
           activeView === 'stores' ? <StoresPanel /> :
           activeView === 'productCatalog' ? (selectedCatalogProduct ? <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} /> : <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />) :
           activeView === 'listing' ? <ListingPanel /> :
           activeView === 'distribution' ? <DistributionPanel activeImages={images} /> :
           activeView === 'gallery' ? <GalleryPanel /> :
           activeView === 'costs' ? <CostPanel /> :
           activeView === 'prompts' ? <PromptManagerPanel /> :
           activeView === 'posMaterial' ? <PosMaterialPanel /> :
           images.length === 0 ? <div className="h-full flex items-center justify-center"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div> :
           <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8">
             <aside className="lg:col-span-1 bg-white p-4 rounded-xl shadow-sm border flex flex-col gap-4 self-start no-print">
               <div className="flex justify-between items-center">
                 <h3 className="font-bold text-gray-900">{sidebarView === 'images' ? t('images') : t('products')}</h3>
                 <div className="flex gap-2">
                   <button onClick={() => setSidebarView('images')} className={`p-1 rounded ${sidebarView === 'images' ? 'bg-lime-100 text-lime-700' : 'text-gray-400'}`}><AppIcon className="w-5 h-5"/></button>
                   <button onClick={() => setSidebarView('products')} className={`p-1 rounded ${sidebarView === 'products' ? 'bg-lime-100 text-lime-700' : 'text-gray-400'}`}><CircleStackIcon className="w-5 h-5"/></button>
                 </div>
               </div>
               <input type="text" placeholder={t('searchImages')} value={productSearchTerm} onChange={e => setProductSearchTerm(e.target.value)} className="w-full rounded-lg border-gray-200 text-sm mb-2" />
               <div className="max-h-[calc(100vh-320px)] overflow-y-auto space-y-2 custom-scrollbar">
                 {sidebarView === 'images' ? 
                   images.filter(img => !productSearchTerm || img.file.name.toLowerCase().includes(productSearchTerm.toLowerCase())).map(img => (
                     <div key={img.id} onClick={() => { setSelectedImageId(img.id); setSelectedProductName(null); }} className={`flex gap-3 p-2 rounded-lg cursor-pointer border transition-all ${selectedImageId === img.id ? 'bg-lime-50 border-lime-400' : 'hover:bg-gray-50'}`}>
                       <img src={img.imageUrl} className="w-10 h-10 object-cover rounded shadow-sm" />
                       <div className="min-w-0 flex-1">
                         <p className="text-xs font-bold truncate">{img.file.name}</p>
                         <p className="text-[10px] text-gray-400">{img.uploadDate.toLocaleDateString()}</p>
                       </div>
                       {img.status === 'analyzing' && <SpinnerIcon className="w-4 h-4 text-lime-500"/>}
                       {img.status === 'error' && <WarningIcon className="w-4 h-4 text-red-500"/>}
                     </div>
                   )) : 
                   productList.filter(p => !productSearchTerm || p.name.toLowerCase().includes(productSearchTerm.toLowerCase())).map(p => (
                     <button key={p.name} onClick={() => { setSelectedProductName(p.name); setSelectedImageId(null); }} className={`flex justify-between w-full p-3 rounded-lg border text-left transition-all ${selectedProductName === p.name ? 'bg-lime-50 border-lime-400' : 'hover:bg-gray-50'}`}>
                       <span className="text-xs font-bold truncate">{p.name}</span>
                       <span className="text-xs font-black text-lime-600">{p.count}</span>
                     </button>
                   ))
                 }
               </div>
               <button onClick={() => setIsImageUploadOverlayOpen(true)} className="w-full py-2 bg-lime-600 text-white rounded-lg text-sm font-bold flex justify-center items-center gap-2"><UploadIcon className="w-4 h-4"/>{t('addMoreImages')}</button>
             </aside>
             <main className="lg:col-span-3 flex flex-col gap-6">
                {!selectedImageId && !selectedProductName && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') && 
                  <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={endCurrentAnalysisAndSave} initialView={activeView} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />}
                {selectedImageId && images.find(i => i.id === selectedImageId) && <>
                  <ImageAnalysisDisplay imageUrl={images.find(i => i.id === selectedImageId)!.imageUrl} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                  <ResultsPanel imageId={selectedImageId} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} error={images.find(i => i.id === selectedImageId)!.error} onReset={endCurrentAnalysisAndSave} onProductNameUpdate={handleProductNameUpdate} onRetry={() => handleRetryImage(selectedImageId)} />
                </>}
                {selectedProductName && <ProductSummaryPanel productName={selectedProductName} images={images} onReset={endCurrentAnalysisAndSave} onImageSelect={(id, name) => { setSelectedImageId(id); setSelectedProductName(null); setHighlightedProductName(name); }} />}
             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={handleCreateAnalysis} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { await handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles!); setIsAnalysisModalOpen(false); setPendingFiles(null); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={endCurrentAnalysisWithoutSaving} onSaveToArchive={endCurrentAnalysisAndSave} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={c => { setBrandClassifications(c); setIsBrandModalOpen(false); }} allBrands={brandsForClassification} brandProductsMap={images.reduce((acc, img) => { img.analysisResult?.products.forEach(p => { const b = p.brand || getBrandFromName(p.name); if (!acc[b]) acc[b] = []; if (!acc[b].includes(p.name)) acc[b].push(p.name); }); return acc; }, {} as any)} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={handleLoadAnalysis} />
        <StoreAssignmentModal isOpen={isStoreAssignmentOpen} onClose={() => setIsStoreAssignmentOpen(false)} onAssign={s => { setImages(prev => prev.map(img => ({ ...img, assignedStore: s, assignedStoreId: s.id }))); setIsStoreAssignmentOpen(false); }} imagesCount={images.length} />
        {mergeCandidates.length > 0 && <MergeConfirmationModal isOpen={true} candidate={mergeCandidates[0]} onConfirm={async (s, t) => { await addOrUpdateProductCorrection(s, t); setImages(prev => prev.map(img => ({ ...img, analysisResult: img.analysisResult ? { ...img.analysisResult, products: img.analysisResult.products.map(p => normalizeProductName(p.name) === normalizeProductName(s) ? { ...p, name: t, isCorrected: true } : p) } : null }))); setMergeCandidates(prev => prev.slice(1)); }} onReject={() => setMergeCandidates(prev => prev.slice(1))} onClose={() => setMergeCandidates(prev => prev.slice(1))} />}
        {isMissingPriceModalOpen && <MissingPriceModal isOpen={true} onClose={() => setIsMissingPriceModalOpen(false)} items={missingPriceItems} onSave={handleUpdatePrices} />}
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl"><div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-2xl"><h2 className="text-lg font-bold flex items-center gap-2"><UploadIcon className="w-6 h-6 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)}><CloseIcon className="w-5 h-5"/></button></div><div className="p-6"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div></div></div>}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses } from '../db.ts';
import type { DetectedProduct, SerializableImageState } from '../types.ts';
import { getCategoryFromName, base64ToFile } from '../utils/helpers.ts';
import { 
    AppIcon, 
    SpinnerIcon, 
    SearchIcon, 
    BuildingStorefrontIcon, 
    CloseIcon, 
    CalendarDaysIcon,
    ChevronRightIcon,
    ArrowLeftIcon,
    CircleStackIcon
} from './Icons.tsx';

interface GalleryItem {
    id: string;
    analysisId: string;
    analysisName: string;
    imageUrl: string;
    uploadDate: Date;
    storeName: string;
    products: DetectedProduct[];
    rawImage: SerializableImageState;
}

export const GalleryPanel: React.FC = () => {
    const { t } = useTranslation();
    const [items, setItems] = useState<GalleryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedItem, setSelectedItem] = useState<GalleryItem | null>(null);
    const [searchProduct, setSearchProduct] = useState('');
    const [selectedStore, setSelectedStore] = useState('all');
    const [selectedCategory, setSelectedCategory] = useState('all');
    const [allStores, setAllStores] = useState<string[]>([]);
    const [allCategories, setAllCategories] = useState<string[]>([]);

    useEffect(() => {
        let isMounted = true;
        const currentUrls: string[] = [];

        const loadGallery = async () => {
            setIsLoading(true);
            try {
                const analyses = await getAnalyses();
                if (!isMounted) return;

                const flattened: GalleryItem[] = [];
                const storesSet = new Set<string>();
                const categoriesSet = new Set<string>();

                analyses.forEach(analysis => {
                    const storeName = analysis.store?.name || t('unknownStore');
                    storesSet.add(storeName);

                    analysis.images.forEach(img => {
                        const file = base64ToFile(img.file.data, img.file.name, img.file.type, img.file.lastModified);
                        const url = URL.createObjectURL(file);
                        currentUrls.push(url);

                        const products = img.analysisResult?.products || [];
                        products.forEach(p => {
                            categoriesSet.add(getCategoryFromName(p.name, t('unassignedCategory')));
                        });

                        flattened.push({
                            id: img.id,
                            analysisId: analysis.id,
                            analysisName: analysis.name,
                            imageUrl: url,
                            uploadDate: new Date(img.uploadDate),
                            storeName,
                            products,
                            rawImage: img
                        });
                    });
                });

                if (isMounted) {
                    setItems(flattened.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
                    setAllStores(Array.from(storesSet).sort());
                    setAllCategories(Array.from(categoriesSet).sort());
                }
            } catch (e) {
                console.error("Gallery load error:", e);
            } finally {
                if (isMounted) setIsLoading(false);
            }
        };
        loadGallery();

        return () => {
            isMounted = false;
            currentUrls.forEach(url => URL.revokeObjectURL(url));
        };
    }, [t]);

    const filteredItems = useMemo(() => {
        const query = searchProduct.toLowerCase();
        return items.filter(item => {
            const matchesProduct = !query || item.products.some(p => p.name.toLowerCase().includes(query));
            const matchesStore = selectedStore === 'all' || item.storeName === selectedStore;
            const matchesCategory = selectedCategory === 'all' || item.products.some(p => getCategoryFromName(p.name, t('unassignedCategory')) === selectedCategory);
            return matchesProduct && matchesStore && matchesCategory;
        });
    }, [items, searchProduct, selectedStore, selectedCategory, t]);

    const groupedProductsOnImage = useMemo(() => {
        if (!selectedItem) return [];
        const groupMap = new Map<string, { product: DetectedProduct, count: number }>();
        selectedItem.products.forEach(p => {
            const existing = groupMap.get(p.name);
            if (existing) existing.count++;
            else groupMap.set(p.name, { product: p, count: 1 });
        });
        return Array.from(groupMap.values()).sort((a, b) => b.count - a.count);
    }, [selectedItem]);

    if (isLoading) return <div className="flex flex-col items-center justify-center h-64"><SpinnerIcon className="w-12 h-12 text-lime-600 animate-spin" /><p className="mt-4 text-gray-500 font-medium">{t('pleaseWait')}</p></div>;

    return (
        <div className="space-y-6 max-w-[1600px] mx-auto pb-10">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col md:flex-row gap-4 items-center sticky top-0 z-20">
                <div className="relative flex-grow w-full">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                    <input type="text" placeholder={t('filterByProduct')} className="w-full pl-11 pr-4 py-2.5 bg-gray-50 border-none rounded-xl text-sm focus:ring-2 focus:ring-lime-500" value={searchProduct} onChange={e => setSearchProduct(e.target.value)} />
                </div>
                <div className="flex gap-2 w-full md:w-auto">
                    <select className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500" value={selectedStore} onChange={e => setSelectedStore(e.target.value)}>
                        <option value="all">{t('allStores')}</option>
                        {allStores.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                    <select className="flex-1 md:w-48 bg-gray-50 border-none rounded-xl text-sm py-2.5 px-4 focus:ring-2 focus:ring-lime-500" value={selectedCategory} onChange={e => setSelectedCategory(e.target.value)}>
                        <option value="all">{t('allCategories')}</option>
                        {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {filteredItems.length > 0 ? (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
                    {filteredItems.map(item => (
                        <div key={item.id} onClick={() => setSelectedItem(item)} className="group relative aspect-square bg-gray-200 rounded-2xl overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1">
                            <img src={item.imageUrl} alt={item.analysisName} className="w-full h-full object-cover" loading="lazy" />
                            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-3 flex flex-col justify-end">
                                <p className="text-white text-[10px] font-black uppercase tracking-widest truncate">{item.storeName}</p>
                                <p className="text-white/80 text-[10px] font-medium">{item.uploadDate.toLocaleDateString()}</p>
                                <div className="mt-1"><span className="bg-lime-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded-full">{item.products.length} {t('totalLabel')}</span></div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="bg-white rounded-3xl p-20 text-center border border-dashed border-gray-200">
                    <AppIcon className="w-16 h-16 text-gray-200 mx-auto mb-4" />
                    <p className="text-gray-400 font-medium">{t('noImagesInGallery')}</p>
