            )}

            {selectedItem && (
                <div className="fixed inset-0 bg-gray-950/95 z-[100] flex animate-fade-in">
                    <div className="flex-grow relative flex items-center justify-center p-4">
                        <img src={selectedItem.imageUrl} alt="Full preview" className="max-w-full max-h-full object-contain rounded-lg shadow-2xl" />
                        <button onClick={() => setSelectedItem(null)} className="absolute top-6 left-6 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white transition-all backdrop-blur-md">
                            <ArrowLeftIcon className="w-6 h-6" />
