                    </div>
                    <div className="w-full md:w-[400px] bg-white h-full flex flex-col shadow-[-10px_0_30px_rgba(0,0,0,0.2)]">
                        <div className="p-6 border-b border-gray-100 flex justify-between items-center"><h3 className="text-xl font-black text-gray-900">{t('photoDetail')}</h3><button onClick={() => setSelectedItem(null)} className="p-2 text-gray-400 hover:text-gray-600"><CloseIcon className="w-6 h-6" /></button></div>
