  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
