             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={async (n, t, m, f) => { const a = { id: `analysis-${Date.now()}`, name: n, createdAt: new Date().toISOString(), images: [], store: null }; await db.analyses.add(a); setActiveAnalysis(a); setActiveView('priceMonitoring'); handleStartAnalysis(t, m, f); setIsNewAnalysisModalOpen(false); }} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles!); setIsAnalysisModalOpen(false); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={() => { images.forEach(i => URL.revokeObjectURL(i.imageUrl)); setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} onSaveToArchive={async () => { images.forEach(i => URL.revokeObjectURL(i.imageUrl)); setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={c => { setBrandClassifications(c); setIsBrandModalOpen(false); }} allBrands={brandsForClassification} brandProductsMap={images.reduce((acc, img) => { img.analysisResult?.products.forEach(p => { const b = p.brand || getBrandFromName(p.name); if (!acc[b]) acc[b] = []; if (!acc[b].includes(p.name)) acc[b].push(p.name); }); return acc; }, {} as any)} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={id => loadAnalysis(id).then(a => a && handleLoadAnalysis(id))} />
        <MissingPriceModal isOpen={isMissingPriceModalOpen} onClose={() => setIsMissingPriceModalOpen(false)} items={images.flatMap(img => (img.analysisResult?.products || []).filter(p => !p.prices?.length).map(p => ({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl })))} onSave={handleUpdatePrices} />
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl"><div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-2xl"><h2 className="text-lg font-bold flex items-center gap-2"><UploadIcon className="w-6 h-6 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)}><CloseIcon className="w-5 h-5"/></button></div><div className="p-6"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div></div></div>}
      </div>
    </div>
  );
};

