  useEffect(() => {
    if (initialView === 'priceMonitoring') setView('priceAnalysis');
    else if (initialView === 'shelfShare') setView('shelfShare');
    else if (initialView === 'promoAlert') setView('promoAlert');
    else if (initialView === 'costs') setView('rawData'); 
  }, [initialView]);

  // OPTIMALIZÁCIA: Sledujeme len hotové analýzy
  const successfulImages = useMemo(() => images.filter(img => img.status === 'success'), [images]);

  const { storeData, totalProducts, uniqueProductCount, allCategories, allChains } = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    successfulImages.forEach(img => {
        if (!img.analysisResult) return;
        let storeKey: string | number = unknownStore;
        let storeDisplayName = unknownStore;

        if (img.assignedStoreId) {
            storeKey = img.assignedStoreId;
            if (img.assignedStore) {
                 const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
                 storeDisplayName = [...new Set(components)].join(', ');
            }
        } else {
            const storeInfo = img.analysisResult.storeInfo;
            if (storeInfo) {
                const chain = removeDateFromStoreName(storeInfo.chain);
                const address = removeDateFromStoreName(storeInfo.address);
                storeDisplayName = (chain && address) ? `${chain}, ${address}` : (chain || address || unknownStore);
            }
            storeKey = storeDisplayName;
        }

        if (!productsByStore.has(storeKey)) productsByStore.set(storeKey, { name: storeDisplayName, items: [] });
        img.analysisResult.products.forEach(p => {
            if (p && p.name) productsByStore.get(storeKey)!.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
        });
    });

    const finalData = Array.from(productsByStore.entries()).map(([key, data]): StoreCentricSummary => {
        const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();
        data.items.forEach(p => {
            const groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : findBestMatch(p.name.trim(), Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'))) || p.name.trim();
            if (!productsMap.has(groupKey)) productsMap.set(groupKey, []);
            productsMap.get(groupKey)!.push(p);
        });

        const summarizedProducts = Array.from(productsMap.entries()).map(([, occurrences]): ProductInStore => {
            const representative = occurrences[0];
            const confidences = occurrences.map(o => o.confidence);
            const priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[] = [];

            occurrences.forEach(o => {
                (o.prices || []).forEach(price => {
                    if (!priceHistory.some(ph => ph.price.value === price.value && ph.price.type === price.type)) {
                        priceHistory.push({ price, date: o.uploadDate, imageUrl: o.imageUrl });
                    }
                });
            });

            return {
                name: representative.name,
                isCorrected: occurrences.some(o => o.isCorrected),
                category: getCategoryFromName(representative.name, unassignedCategory),
                count: occurrences.length,
                priceHistory: priceHistory.sort((a, b) => a.date.getTime() - b.date.getTime()),
                avgConfidence: confidences.reduce((a, b) => a + b, 0) / confidences.length,
                imageUrl: occurrences[occurrences.length - 1].imageUrl,
                catalogProductId: representative.catalogProductId
            };
        });

        return { storeName: data.name, storeId: typeof key === 'number' ? key : undefined, products: summarizedProducts.sort((a,b) => a.category.localeCompare(b.category)) };
    });

    const filteredData = finalData.map(store => {
        if (filters.chain && store.storeName !== filters.chain) return null;
        const filteredProducts = store.products.filter(item => {
            if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
            if (filters.category && item.category !== filters.category) return false;
            if (item.avgConfidence * 100 < filters.confidence) return false;
            if (filters.minPrice !== '' || filters.maxPrice !== '') {
                const prices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);
                if (!prices.some(p => p >= min && p <= max)) return false;
            }
            return true;
        });
        return filteredProducts.length > 0 ? { ...store, products: filteredProducts } : null;
    }).filter((s): s is StoreCentricSummary => s !== null);

    return {
      storeData: filteredData,
      totalProducts: successfulImages.reduce((sum, img) => sum + (img.analysisResult?.products.length || 0), 0),
      uniqueProductCount: new Set(finalData.flatMap(s => s.products.map(p => p.catalogProductId ? `ID_${p.catalogProductId}` : p.name))).size,
      allCategories: Array.from(new Set(finalData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(finalData.map(s => s.storeName))).sort()
    };
  }, [successfulImages, filters, t]);

  const missingPriceCount = useMemo(() => successfulImages.reduce((c, img) => c + (img.analysisResult?.products.filter(p => !p.prices?.length).length || 0), 0), [successfulImages]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg" alt="Zoom" />
            <button className="absolute top-4 right-4 text-white bg-black/50 p-2 rounded-full"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-900">{t('batchSummary')}</h2>
        {missingPriceCount > 0 && (
            <button onClick={onOpenMissingPrices} className="flex items-center gap-2 px-4 py-2 bg-orange-100 text-orange-800 rounded-md hover:bg-orange-200 animate-pulse">
                <TagIcon className="w-5 h-5" />
                <span className="font-semibold text-sm">{t('fixMissingPrices', { count: missingPriceCount })}</span>
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 text-center">
          <p className="text-2xl font-bold text-lime-600">{images.length}</p>
          <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{t('imagesCount')}</p>
        </div>
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 text-center">
          <p className="text-2xl font-bold text-lime-600">{successfulImages.length}</p>
          <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{t('analyzed')}</p>
        </div>
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 text-center">
          <p className="text-2xl font-bold text-lime-600">{totalProducts}</p>
          <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{t('totalProducts')}</p>
        </div>
        <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 text-center">
          <p className="text-2xl font-bold text-lime-600">{uniqueProductCount}</p>
          <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{t('uniqueProducts')}</p>
        </div>
      </div>

      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon, cond: true },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon, cond: true },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon, cond: true },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon, cond: true }
          ].map(tab => (
            <button key={tab.id} onClick={() => setView(tab.id as any)} className={`-mb-px px-6 py-3 text-sm font-bold transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                <tab.icon className="w-4 h-4" /> {tab.label}
            </button>
          ))}
      </div>

      <div className="flex-grow">
        {view === 'priceAnalysis' && (
          <div className="animate-fade-in">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-2 mb-4 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-sm font-bold rounded-lg bg-lime-600 text-white hover:bg-lime-700 shadow-md">
                    <ArrowDownTrayIcon className="w-4 h-4" /> XLS
                </button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-sm font-bold rounded-lg bg-gray-800 text-white hover:bg-black shadow-md">
                    <DocumentTextIcon className="w-4 h-4" /> PDF
                </button>
            </div>
            <div className="space-y-6 max-h-[calc(100vh-480px)] overflow-y-auto pr-2 custom-scrollbar">
                {storeData.map(store => (
                    <div key={store.storeName} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="bg-gray-50 px-4 py-3 border-b border-gray-100 flex items-center justify-between">
                            <h3 className="font-bold text-gray-900">{store.storeName}</h3>
                            <span className="text-[10px] font-black text-gray-400 uppercase">{store.products.length} SKU</span>
                        </div>
                        <div className="p-2 divide-y divide-gray-50">
                            {store.products.map(product => {
                                const regular = product.priceHistory.find(ph => ph.price.type === 'REGULAR')?.price.value;
                                const promo = product.priceHistory.find(ph => ph.price.type === 'PROMO')?.price.value;
                                return (
                                    <div key={product.name} className="flex items-center gap-4 p-3 hover:bg-lime-50/50 transition-colors rounded-lg">
                                        <div className="flex-grow min-w-0">
                                            <p className="text-xs text-lime-700 font-black uppercase tracking-tighter">{product.category}</p>
                                            <p className="font-bold text-sm text-gray-800 truncate">{product.name}</p>
                                        </div>
                                        <div className="flex gap-2 flex-shrink-0">
                                            {regular && <span className={`px-2 py-1 rounded text-xs font-bold ${promo ? 'line-through text-gray-300' : 'bg-gray-100 text-gray-700'}`}>{regular}</span>}
                                            {promo && <span className="px-2 py-1 rounded bg-red-100 text-red-600 text-xs font-bold">{promo}</span>}
                                        </div>
                                        <div className="w-10 h-10 rounded border border-gray-100 overflow-hidden flex-shrink-0 cursor-zoom-in" onClick={() => setZoomedImage(product.imageUrl || null)}>
                                            {product.imageUrl && <img src={product.imageUrl} className="w-full h-full object-cover" />}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && <div className="bg-gray-900 text-lime-400 p-4 rounded-xl overflow-x-auto font-mono text-xs max-h-[calc(100vh-320px)]"><pre>{JSON.stringify(images, null, 2)}</pre></div>}
      </div>

       <div className="mt-8 pt-6 border-t border-gray-100 flex items-center gap-4 no-print">
        <button onClick={onReset} className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 px-6 rounded-xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm shadow-lg shadow-red-100">
          <TrashIcon className="w-5 h-5" /> {t('endVisit')}
        </button>
      </div>
    </div>
  );
};

import React from 'react'; 
