export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName?: string;
}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = React.useState(false); 
  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandsForClassification, setBrandsForClassification] = React.useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);
  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = React.useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const handleUpdatePrices = (updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prev => prev.map(img => {
          const updatesForImage = updates.filter(u => u.imageId === img.id);
          if (updatesForImage.length === 0) return img;
          const updatedProducts = img.analysisResult?.products.map(p => {
              const update = updatesForImage.find(u => u.productId === p.id);
              return update ? { ...p, prices: update.prices } : p;
          });
          return { ...img, analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null };
      }));
  };

  const handleNewAnalysisClick = () => {
    if (activeAnalysis && images.length > 0) setIsClearConfirmOpen(true);
    else setIsNewAnalysisModalOpen(true);
  };

  const handleImageUpload = React.useCallback((files: FileList) => {
    if (!activeAnalysis) {
        setPendingFiles(files); 
        setIsNewAnalysisModalOpen(true);
        return;
    }
    setPendingFiles(files);
    setIsAnalysisModalOpen(true); 
    setIsImageUploadOverlayOpen(false); 
  }, [activeAnalysis]);

  const handleStartAnalysis = React.useCallback(async (type: AnalysisType, model: string, fileList: FileList, analysisOverride?: Analysis) => {
    const targetAnalysis = analysisOverride || activeAnalysis;
    if (!targetAnalysis) return;

    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const filenameStoreName = extractStoreFromFilename(file.name);
        let effectiveStore: Store | null = null;
        let effectiveStoreId: number | undefined = undefined;

        if (filenameStoreName) {
             try {
                effectiveStore = await findOrCreateStore({ name: filenameStoreName, chain: filenameStoreName.split(',')[0].trim(), city: '', address: '', code: '' });
                effectiveStoreId = effectiveStore.id;
             } catch (e) { console.warn(e); }
        }

        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: effectiveStore,
            assignedStoreId: effectiveStoreId,
            modelName: model
        };
    }));

    setImages(prev => [...prev, ...tempImages].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    (async () => {
        for (const img of tempImages) {
            try {
                const compressedFile = await resizeAndCompressImage(img.file);
                const newUrl = URL.createObjectURL(compressedFile);
                setImages(prev => prev.map(p => {
                    if (p.id === img.id) {
                        URL.revokeObjectURL(p.imageUrl);
                        return { ...p, file: compressedFile, imageUrl: newUrl };
                    }
                    return p;
                }));
            } catch (e) { console.error(e); }
        }
    })();
  }, [activeAnalysis]);

  React.useEffect(() => {
    if (!isOnline || isAnalyzing) return;
    const pending = images.filter(img => img.status === 'pending');
    if (pending.length === 0) return;

    const process = async () => {
        const current = pending[0];
        setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'analyzing' } : img));

        try {
            const base64 = await fileToBase64(current.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(current.analysisType === 'price' ? 'geminiPromptPriceOnly' : current.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), current.analysisType, current.modelName);

            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${current.id}-${Math.random()}` };
            }));

            setImages(prev => prev.map(img => img.id === current.id ? { ...img, analysisResult: { ...result, products: corrected }, status: 'success' } : img));
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'error', error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } : img));
        }
    };
    // Mierny delay kvoli plynulosti animácií
    const timer = setTimeout(process, 100);
    return () => clearTimeout(timer);
  }, [images, isOnline, isAnalyzing, t]);

  const productList = React.useMemo(() => {
    // Táto časť sa spúšťa len ak sa zmenili ANALÝZY, nie len stav pending/analyzing
    const completedImages = images.filter(img => img.status === 'success');
    const map = new Map<string, { name: string; count: number; category: string }>();
    const knownNames: string[] = [];

    completedImages.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p || !p.name) return;
        const matched = findBestMatch(p.name, knownNames);
        const name = matched || p.name;
        if (!matched) knownNames.push(name);

        const existing = map.get(name);
        if (existing) existing.count++;
        else map.set(name, { name, count: 1, category: getCategoryFromName(name, t('unassignedCategory')) });
      });
    });
    return Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
  }, [images.filter(i => i.status === 'success').length, t]);

  const handleSummaryClick = React.useCallback(() => {
    setSelectedImageId(null);
    setSelectedProductName(null);
    setHighlightedProductName(null);
  }, []);

  // FIX: Implemented handleLoadAnalysis to restore state from a saved analysis in IndexedDB
  const handleLoadAnalysis = React.useCallback(async (analysisId: string) => {
    try {
        const analysisToLoad = await loadAnalysis(analysisId);

        if (analysisToLoad) {
          // Clean up currently active object URLs to prevent memory leaks
          images.forEach(i => URL.revokeObjectURL(i.imageUrl));

          const loadedImages: ImageState[] = analysisToLoad.images.map(serializableImage => {
            const file = base64ToFile(
              serializableImage.file.data,
              serializableImage.file.name,
              serializableImage.file.type,
              serializableImage.file.lastModified
            );
            return {
              id: serializableImage.id,
              file,
              imageUrl: URL.createObjectURL(file),
              analysisResult: serializableImage.analysisResult,
              status: serializableImage.status,
              error: serializableImage.error,
              uploadDate: new Date(serializableImage.uploadDate),
              analysisType: (serializableImage.analysisType || 'both') as AnalysisType,
              retryCount: serializableImage.retryCount || 0,
              assignedStore: serializableImage.assignedStore,
              assignedStoreId: serializableImage.assignedStoreId,
              modelName: serializableImage.modelName
            };
          });

          setActiveAnalysis(analysisToLoad);
          setImages(loadedImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
          setBrandClassifications(analysisToLoad.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');

          // Reset interaction states
          setSelectedImageId(null);
          setSelectedProductName(null);
