import type { DetectedProduct, MergeCandidate } from '../types';

const MULTI_WORD_CATEGORIES = ['Bon pari'];
const normalizationCache = new Map<string, string>();
const similarityCache = new Map<string, number>();

/**
 * Normalizuje názov produktu. Cache obmedzená na 2000 položiek pre stabilitu RAM.
 */
export const normalizeProductName = (name: string): string => {
  if (!name) return '';
  const cached = normalizationCache.get(name);
  if (cached) return cached;

  const result = name
    .toLowerCase()
    .trim()
    .replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, "") 
    .replace(/\s+/g, ' ');

  if (normalizationCache.size > 2000) normalizationCache.clear();
  normalizationCache.set(name, result);
  return result;
};

/**
 * Výpočet podobnosti s lineárnou pamäťovou náročnosťou O(min(n, m)).
 * Šetrí RAM pri porovnávaní tisícov dvojíc SKU.
 */
export const calculateStringSimilarity = (a: string, b: string): number => {
    if (!a || !b) return 0;
    if (a === b) return 100;

    const lenA = a.length;
    const lenB = b.length;

    // Early exit guard
    if (Math.abs(lenA - lenB) > Math.max(lenA, lenB) * 0.35) return 0;

    const cacheKey = a < b ? `${a}|${b}` : `${b}|${a}`;
    const cached = similarityCache.get(cacheKey);
    if (cached !== undefined) return cached;

    // Linear memory implementation
    let v0 = new Int32Array(lenB + 1);
    let v1 = new Int32Array(lenB + 1);

    for (let i = 0; i <= lenB; i++) v0[i] = i;

    for (let i = 0; i < lenA; i++) {
        v1[0] = i + 1;
        for (let j = 0; j < lenB; j++) {
            const cost = a[i] === b[j] ? 0 : 1;
            v1[j + 1] = Math.min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost);
        }
        v0.set(v1);
    }

    const score = (1 - v0[lenB] / Math.max(lenA, lenB)) * 100;

    if (similarityCache.size > 3000) similarityCache.clear();
    similarityCache.set(cacheKey, score);
    return score;
};

export const findBestMatch = (query: string, candidates: string[]): string | null => {
    if (!query || candidates.length === 0) return null;
    const normQuery = normalizeProductName(query);

    // Fast path: Exact normalized match
    for (const cand of candidates) {
        if (normalizeProductName(cand) === normQuery) return cand;
    }

    let bestMatch: string | null = null;
    let highestScore = 0;

    for (const cand of candidates) {
        const score = calculateStringSimilarity(normQuery, normalizeProductName(cand));
        if (score > highestScore && score > 88) {
            highestScore = score;
            bestMatch = cand;
        }
    }
    return bestMatch;
};

export const getCategoryFromName = (name: string, unassignedCategory: string): string => {
  if (!name) return unassignedCategory;
  const lowerName = name.toLowerCase();
  for (const cat of MULTI_WORD_CATEGORIES) {
    if (lowerName.startsWith(cat.toLowerCase())) return cat;
  }
  const firstWord = name.split(' ')[0];
  if (!firstWord) return unassignedCategory;
  return firstWord.charAt(0).toUpperCase() + firstWord.slice(1).toLowerCase();
};

export const getBrandFromName = (name: string): string => {
  if (!name) return '';
  return name.split(' ')[0];
};

export const parseDateFromFileName = (fileName: string): Date | null => {
    const match = fileName.match(/(\d{1,2})[._-](\d{1,2})[._-](\d{4})/);
    if (match) {
        const [_, day, month, year] = match;
        const date = new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T12:00:00Z`);
        return isNaN(date.getTime()) ? null : date;
    }
    return null;
}

export const extractStoreFromFilename = (filename: string): string | null => {
    const knownChains = ['Tesco', 'Billa', 'Lidl', 'Kaufland', 'Coop', 'Metro', 'Terno', 'Kraj', 'Fresh', 'CBA', 'Jednota', 'Albert', 'DM'];
    let cleaned = filename.replace(/\.[^/.]+$/, "").replace(/[_\-.]/g, ' ').replace(/\s+/g, ' ').trim();
    for (const chain of knownChains) {
        const regex = new RegExp(`\\b${chain}\\b`, 'i');
        if (regex.test(cleaned)) {
            const remainder = cleaned.replace(regex, '').trim().split(' ').slice(0, 2).join(' ');
            return remainder ? `${chain}, ${remainder}` : chain;
        }
    }
    return null;
};

export const removeDateFromStoreName = (name?: string): string => {
    if (!name) return '';
    return name.replace(/\s*\(\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*-\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*\)/gi, '').trim();
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = reject;
  });
};

export const base64ToFile = (base64: string, name: string, type: string, lastModified: number): File => {
  const byteCharacters = atob(base64);
  const byteArray = new Uint8Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) byteArray[i] = byteCharacters.charCodeAt(i);
  return new File([byteArray], name, { type, lastModified });
};

export const resizeAndCompressImage = (file: File, maxWidth: number = 1600, quality: number = 0.75): Promise<File> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.src = url;
        img.onload = () => {
            URL.revokeObjectURL(url);
            let { width, height } = img;
            if (width > maxWidth) {
                height = (maxWidth / width) * height;
                width = maxWidth;
            }
            const canvas = document.createElement('canvas');
            canvas.width = width; canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(img, 0, 0, width, height);
                canvas.toBlob(b => {
                    if (b) resolve(new File([b], file.name, { type: 'image/jpeg' }));
                    else reject();
                    canvas.width = 0; canvas.height = 0;
                }, 'image/jpeg', quality);
            } else {
                reject();
            }
        };
        img.onerror = () => { URL.revokeObjectURL(url); reject(); };
    });
};

export const findMergeCandidates = (newProducts: DetectedProduct[], allProducts: DetectedProduct[]): MergeCandidate[] => {
    const SIMILARITY_THRESHOLD = 90;
    const candidates: MergeCandidate[] = [];
    const processedIds = new Set<string>();

    for (const newProduct of newProducts) {
        if (processedIds.has(newProduct.id)) continue;
        for (const existingProduct of allProducts) {
            if (newProduct.id === existingProduct.id || processedIds.has(existingProduct.id)) continue;
            const normNew = normalizeProductName(newProduct.name);
            const normExisting = normalizeProductName(existingProduct.name);
            if (normNew === normExisting) continue;
            const similarity = calculateStringSimilarity(normNew, normExisting);
            if (similarity >= SIMILARITY_THRESHOLD) {
                candidates.push({ target: existingProduct, source: newProduct });
                processedIds.add(newProduct.id);
                processedIds.add(existingProduct.id);
                break;
            }
        }
    }
    return candidates;
};

import React, { useState, useEffect, useMemo } from 'react';
import { useTranslation } from '../i18n/index.tsx';
import { getAnalyses, getCatalogProductNames, saveDistributionReport, getDistributionReports, deleteDistributionReport, getStores } from '../db.ts';
import { DetectedProduct, DistributionMatrix, DistributionRow, DistributionReport, DistributionCell, Store, Analysis } from '../types.ts';
import { normalizeProductName, removeDateFromStoreName, findBestMatch } from '../utils/helpers.ts';
import { exportDistributionToXLS } from '../utils/export.ts';
import { TableCellsIcon, CheckCircleIcon, XCircleIcon, FunnelIcon, SpinnerIcon, ArrowDownTrayIcon, SaveIcon, FolderOpenIcon, TrashIcon, CloseIcon } from './Icons.tsx';
import type { ImageState } from '../App.tsx';

interface DistributionPanelProps {
    activeImages?: ImageState[];
}

export const DistributionPanel: React.FC<DistributionPanelProps> = ({ activeImages = [] }) => {
    const { t } = useTranslation();
    const [allCatalogProducts, setAllCatalogProducts] = useState<string[]>([]);
    const [selectedProducts, setSelectedProducts] = useState<string[]>([]);
    const [matrix, setMatrix] = useState<DistributionMatrix | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isCalculating, setIsCalculating] = useState(false);

    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);
    const [isLoadModalOpen, setIsLoadModalOpen] = useState(false);
    const [newReportName, setNewReportName] = useState('');
    const [savedReports, setSavedReports] = useState<DistributionReport[]>([]);

    useEffect(() => {
        const load = async () => {
            setIsLoading(true);
            const products = await getCatalogProductNames();
            setAllCatalogProducts(products.sort());

            if (selectedProducts.length === 0 && activeImages.length > 0) {
                const found = new Set<string>();
                activeImages.forEach(img => img.analysisResult?.products.forEach(p => p.name && found.add(p.name)));
                if (found.size > 0) setSelectedProducts(products.filter(p => found.has(p)));
            }
            setIsLoading(false);
        };
        load();
    }, [activeImages.length]);

    const successfulActiveCount = useMemo(() => activeImages.filter(img => img.status === 'success').length, [activeImages]);

    useEffect(() => {
        if (selectedProducts.length > 0) generateMatrix();
        else setMatrix(null);
    }, [selectedProducts, successfulActiveCount]);

    const generateMatrix = async () => {
        if (selectedProducts.length === 0) return;
        setIsCalculating(true);

        try {
            const [archived, allStores] = await Promise.all([getAnalyses(), getStores()]);

            // Map: StoreKey -> Set of Detected Product Names (pre-normalized for speed)
            const storeInventory = new Map<string, { name: string, code?: string, foundProducts: Set<string> }>();

            allStores.forEach(s => {
                storeInventory.set(`ID_${s.id}`, { name: s.name, code: s.code, foundProducts: new Set() });
            });

            const processAnalysisSet = (items: (Analysis | ImageState)[], isActive: boolean) => {
                items.forEach(item => {
                    const images = isActive ? [item as ImageState] : (item as Analysis).images;
                    images.forEach(img => {
                        const result = isActive ? (img as ImageState).analysisResult : (img as any).analysisResult;
                        if (!result) return;

                        let key = '';
                        if (img.assignedStoreId) key = `ID_${img.assignedStoreId}`;
                        else if (result.storeInfo) {
                            const chain = removeDateFromStoreName(result.storeInfo.chain);
                            if (chain) key = `RAW_${chain}`;
                        }

                        if (!key) return;
                        if (!storeInventory.has(key)) {
                            storeInventory.set(key, { name: key.replace('RAW_', ''), foundProducts: new Set() });
                        }

                        const inv = storeInventory.get(key)!;
                        result.products.forEach((p: any) => {
                            if (p.confidence > 0.7) inv.foundProducts.add(p.name);
                        });
                    });
                });
            };

            processAnalysisSet(activeImages, true);
            processAnalysisSet(archived, false);

            // Phase 2: Compute Matrix with optimized fuzzy matching
            const rows: DistributionRow[] = [];
            const columnCounts: Record<string, number> = {};
            selectedProducts.forEach(p => columnCounts[p] = 0);

            // Cache matches per product name across different stores
            const matchCache = new Map<string, string | null>();

            for (const [key, data] of storeInventory.entries()) {
                const presence: Record<string, DistributionCell> = {};
                let presentCount = 0;

                selectedProducts.forEach(target => {
                    let isPresent = false;
                    for (const detected of data.foundProducts) {
                        const cacheKey = `${detected}|${target}`;
                        let match = matchCache.get(cacheKey);
                        if (match === undefined) {
                            match = findBestMatch(detected, [target]);
                            matchCache.set(cacheKey, match);
                        }
                        if (match === target) { isPresent = true; break; }
                    }

                    presence[target] = { isPresent, maxConfidence: isPresent ? 1 : 0 };
                    if (isPresent) { presentCount++; columnCounts[target]++; }
                });

                rows.push({
                    storeName: data.name,
                    storeId: key.startsWith('ID_') ? parseInt(key.split('_')[1]) : undefined,
                    storeCode: data.code,
                    presence,
                    fulfillment: selectedProducts.length > 0 ? (presentCount / selectedProducts.length) * 100 : 0
                });
            }

            const columnSummaries: Record<string, number> = {};
            selectedProducts.forEach(p => columnSummaries[p] = rows.length > 0 ? (columnCounts[p] / rows.length) * 100 : 0);

            setMatrix({ rows: rows.sort((a,b) => b.fulfillment - a.fulfillment), columnSummaries, selectedProducts });
        } catch (e) { console.error(e); } finally { setIsCalculating(false); }
    };

    if (isLoading) return <div className="flex justify-center py-20"><SpinnerIcon className="w-10 h-10 text-lime-500 animate-spin" /></div>;

    return (
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col max-w-[98vw] mx-auto animate-fade-in">
            {isSaveModalOpen && (
                <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4">
                     <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6">
                        <h3 className="text-lg font-bold mb-4">{t('saveReportTitle')}</h3>
                        <input type="text" value={newReportName} onChange={e => setNewReportName(e.target.value)} className="w-full border-gray-200 rounded-xl p-3 mb-4 bg-gray-50 focus:ring-2 focus:ring-lime-500" placeholder={t('reportNamePlaceholder')} />
                        <div className="flex justify-end gap-3">
                            <button onClick={() => setIsSaveModalOpen(false)} className="px-4 py-2 text-gray-500 font-bold uppercase text-xs">{t('cancelButton')}</button>
                            <button onClick={handleSaveReport} className="px-6 py-2 bg-lime-600 text-white rounded-xl font-bold">{t('save')}</button>
                        </div>
                     </div>
                </div>
            )}

            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 mb-6">
                <div>
                    <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2"><TableCellsIcon className="w-6 h-6 text-lime-600" />{t('distributionModule')}</h2>
                </div>
                <div className="flex gap-2">
                    <button onClick={openLoadModal} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200"><FolderOpenIcon className="w-4 h-4" /> {t('savedReports')}</button>
                    {selectedProducts.length > 0 && <button onClick={openSaveModal} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200"><SaveIcon className="w-4 h-4" /> {t('saveReport')}</button>}
                    {matrix && <button onClick={() => exportDistributionToXLS(matrix, t)} className="flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-lg bg-blue-600 text-white"><ArrowDownTrayIcon className="w-4 h-4" /> XLS</button>}
                </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-2xl mb-6">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><FunnelIcon className="w-4 h-4" /> {t('selectProducts')}</h3>
                    <div className="flex gap-4">
                        <button onClick={() => setSelectedProducts(allCatalogProducts)} className="text-[10px] font-black text-lime-700 uppercase">{t('selectAll')}</button>
                        <button onClick={() => setSelectedProducts([])} className="text-[10px] font-black text-gray-400 uppercase">{t('deselectAll')}</button>
                    </div>
                </div>
                <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto pr-2 custom-scrollbar">
                    {allCatalogProducts.map(p => (
                        <button key={p} onClick={() => setSelectedProducts(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all border-2 ${selectedProducts.includes(p) ? 'bg-lime-600 border-lime-600 text-white shadow-md' : 'bg-white border-gray-200 text-gray-500'}`}>{p}</button>
                    ))}
                </div>
            </div>

            {isCalculating ? (
                <div className="flex-grow flex flex-col items-center justify-center py-20"><SpinnerIcon className="w-10 h-10 text-lime-500 animate-spin" /><p className="mt-4 text-sm font-bold text-gray-400 uppercase tracking-widest">{t('calculating')}</p></div>
            ) : matrix ? (
                <div className="flex-grow overflow-x-auto border border-gray-100 rounded-xl custom-scrollbar">
                    <table className="min-w-full divide-y divide-gray-200 border-collapse">
                        <thead className="bg-gray-800 text-white sticky top-0 z-10">
                            <tr>
                                <th className="px-4 py-3 text-left text-[10px] font-black uppercase tracking-wider min-w-[200px] sticky left-0 bg-gray-800 border-r border-gray-700">{t('storeName')}</th>
                                {matrix.selectedProducts.map(p => (
                                    <th key={p} className="px-2 py-3 text-center text-[10px] font-black uppercase tracking-tighter min-w-[80px] border-l border-gray-700"><div className="truncate max-w-[120px] mx-auto" title={p}>{p}</div></th>
                                ))}
                                <th className="px-4 py-3 text-center text-[10px] font-black uppercase tracking-wider bg-lime-700 min-w-[80px]">{t('storeFulfillment')}</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-100">
                            {matrix.rows.map((row, idx) => (
                                <tr key={idx} className="hover:bg-lime-50/50 transition-colors">
                                    <td className="px-4 py-3 text-xs font-bold text-gray-900 sticky left-0 bg-white border-r border-gray-100 shadow-[2px_0_5px_rgba(0,0,0,0.03)]">{row.storeName}{row.storeCode && <span className="ml-2 text-[10px] bg-blue-100 text-blue-700 px-1 rounded">#{row.storeCode}</span>}</td>
                                    {matrix.selectedProducts.map(p => <td key={p} className="px-2 py-3 text-center border-l border-gray-50">{renderCell(row.presence[p])}</td>)}
                                    <td className="px-4 py-3 text-center text-xs font-black text-lime-800 bg-lime-50/50">{Math.round(row.fulfillment)}%</td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-gray-100 font-bold border-t-2 border-gray-200">
                            <tr>
                                <td className="px-4 py-3 text-[10px] uppercase font-black text-gray-500 sticky left-0 bg-gray-100 border-r border-gray-200">{t('distributionShare')}</td>
                                {matrix.selectedProducts.map(p => <td key={p} className="px-2 py-3 text-center text-xs text-lime-700 border-l border-gray-200">{Math.round(matrix.columnSummaries[p])}%</td>)}
                                <td className="bg-lime-100"></td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            ) : (
                <div className="flex-grow flex flex-col items-center justify-center py-20 text-center text-gray-300"><TableCellsIcon className="w-16 h-16 mb-4 opacity-20" /><p className="font-medium italic">{t('selectProductsAndCalculate')}</p></div>
            )}
        </div>
    );
};

import React from 'react'; 
import { ImageUploader } from './components/ImageUploader';
import { ImageAnalysisDisplay } from './components/ImageAnalysisDisplay';
import { ResultsPanel } from './components/ResultsPanel';
import { BatchSummaryPanel } from './components/BatchSummaryPanel';
import { ProductSummaryPanel } from './components/ProductSummaryPanel';
import { analyzeImageWithGemini } from './services/geminiService';
import type { AnalysisResult, Analysis, SerializableImageState, DetectedProduct, BrandClassifications, Store, MergeCandidate, ProductCatalogEntry, PriceInfo, ActiveView } from './types';
import { getCategoryFromName, parseDateFromFileName, findBestMatch, fileToBase64, base64ToFile, getBrandFromName, normalizeProductName, findMergeCandidates, extractStoreFromFilename, resizeAndCompressImage } from './utils/helpers';
import { AppIcon, SpinnerIcon, WarningIcon, UploadIcon, CircleStackIcon, HomeIcon, CalendarDaysIcon, TableCellsIcon, BookOpenIcon, StoreIcon, CalculatorIcon, MessageSquareCodeIcon, ShieldExclamationIcon, TagIcon, CloseIcon } from './components/Icons';
import { useTranslation } from './i18n';
import { AnalysisTypeModal } from './components/AnalysisTypeModal';
import { ClearConfirmModal } from './components/ClearConfirmModal';
import { HomeScreen } from './components/HomeScreen';
import { db, saveAnalysis, loadAnalysis, addOrUpdateProductCorrection, findProductByAlias, populateCatalogFromAnalysis, getCatalogEntries, getAnalyses, findOrCreateStore } from './db';
import { BrandDefinitionModal } from './components/BrandDefinitionModal';
import { Header } from './components/Header';
import { SearchModal } from './components/SearchModal';
import { ProductCatalogPanel, ProductCardPanel } from './components/ProductCatalogPanel';
import { NewAnalysisModal } from './components/NewAnalysisModal';
import { DistributionPanel } from './components/DistributionPanel';
import { ListingPanel } from './components/ListingPanel';
import { StoresPanel } from './components/StoresPanel';
import { StoreAssignmentModal } from './components/StoreAssignmentModal';
import { MergeConfirmationModal } from './components/MergeConfirmationModal';
import { AnalysesPanel } from './components/AnalysesPanel';
import { ApiKeySelectionScreen } from './components/ApiKeySelectionScreen';
import { MissingPriceModal, MissingPriceItem } from './components/MissingPriceModal';
import Sidebar from './components/Sidebar';
import { GlobalAnalysisStatus } from './components/GlobalAnalysisStatus';
import { GalleryPanel } from './components/GalleryPanel';
import { CostPanel } from './components/CostPanel';
import { PromptManagerPanel } from './components/PromptManagerPanel';
import { PosMaterialPanel } from './components/PosMaterialPanel';

export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName?: string;
}

export const App: React.FC = () => {
  const [images, setImages] = React.useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = React.useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = React.useState<string | null>(null);
  const [sidebarView, setSidebarView] = React.useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = React.useState('');
  const [highlightedProductName, setHighlightedProductName] = React.useState<string | null>(null);
  const [activeView, setActiveView] = React.useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = React.useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = React.useState(false); 
  const [pendingFiles, setPendingFiles] = React.useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = React.useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = React.useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = React.useState(false);
  const [brandsForClassification, setBrandsForClassification] = React.useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = React.useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [mergeCandidates, setMergeCandidates] = React.useState<MergeCandidate[]>([]);
  const [isStoreAssignmentOpen, setIsStoreAssignmentOpen] = React.useState(false);
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = React.useState(false);
  const [activeAnalysis, setActiveAnalysis] = React.useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = React.useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = React.useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = React.useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  React.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // AGRESÍVNA SPRÁVA PAMÄTE: Uvoľnenie URL pri zmene návštevy
  React.useEffect(() => {
    return () => images.forEach(img => URL.revokeObjectURL(img.imageUrl));
  }, [activeAnalysis?.id]);

  React.useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = React.useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const handleUpdatePrices = (updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prev => prev.map(img => {
          const updatesForImage = updates.filter(u => u.imageId === img.id);
          if (updatesForImage.length === 0) return img;
          const updatedProducts = img.analysisResult?.products.map(p => {
              const update = updatesForImage.find(u => u.productId === p.id);
              return update ? { ...p, prices: update.prices } : p;
          });
          return { ...img, analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null };
      }));
  };

  const handleImageUpload = React.useCallback((files: FileList) => {
    if (!activeAnalysis) {
        setPendingFiles(files); 
        setIsNewAnalysisModalOpen(true);
        return;
    }
    setPendingFiles(files);
    setIsAnalysisModalOpen(true); 
    setIsImageUploadOverlayOpen(false); 
  }, [activeAnalysis]);

  const handleStartAnalysis = React.useCallback(async (type: AnalysisType, model: string, fileList: FileList, analysisOverride?: Analysis) => {
    const targetAnalysis = analysisOverride || activeAnalysis;
    if (!targetAnalysis) return;

    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const filenameStoreName = extractStoreFromFilename(file.name);
        let effectiveStore: Store | null = null;
        let effectiveStoreId: number | undefined = undefined;

        if (filenameStoreName) {
             try {
                effectiveStore = await findOrCreateStore({ name: filenameStoreName, chain: filenameStoreName.split(',')[0].trim(), city: '', address: '', code: '' });
                effectiveStoreId = effectiveStore.id;
             } catch (e) { console.warn(e); }
        }

        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: effectiveStore,
            assignedStoreId: effectiveStoreId,
            modelName: model
        };
    }));

    setImages(prev => [...prev, ...tempImages].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    (async () => {
        for (const img of tempImages) {
            try {
                const compressedFile = await resizeAndCompressImage(img.file);
                const newUrl = URL.createObjectURL(compressedFile);
                setImages(prev => prev.map(p => {
                    if (p.id === img.id) {
                        URL.revokeObjectURL(p.imageUrl);
                        return { ...p, file: compressedFile, imageUrl: newUrl };
                    }
                    return p;
                }));
            } catch (e) { console.error(e); }
        }
    })();
  }, [activeAnalysis]);

  React.useEffect(() => {
    if (!isOnline || isAnalyzing) return;
    const pending = images.filter(img => img.status === 'pending');
    if (pending.length === 0) return;

    const process = async () => {
        const current = pending[0];
        setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'analyzing' } : img));

        try {
            const base64 = await fileToBase64(current.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(current.analysisType === 'price' ? 'geminiPromptPriceOnly' : current.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), current.analysisType, current.modelName);

            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${current.id}-${Math.random()}` };
            }));

            setImages(prev => prev.map(img => img.id === current.id ? { ...img, analysisResult: { ...result, products: corrected }, status: 'success' } : img));
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'error', error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } : img));
        }
    };
    const timer = setTimeout(process, 100);
    return () => clearTimeout(timer);
  }, [images, isOnline, isAnalyzing, t]);

  const productList = React.useMemo(() => {
    const completedImages = images.filter(img => img.status === 'success');
    const map = new Map<string, { name: string; count: number; category: string }>();
    const knownNames: string[] = [];

    completedImages.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p || !p.name) return;
        const matched = findBestMatch(p.name, knownNames);
        const name = matched || p.name;
        if (!matched) knownNames.push(name);

        const existing = map.get(name);
        if (existing) existing.count++;
        else map.set(name, { name, count: 1, category: getCategoryFromName(name, t('unassignedCategory')) });
      });
    });
    return Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
  }, [images.filter(i => i.status === 'success').length, t]);

  const handleSummaryClick = React.useCallback(() => {
    setSelectedImageId(null);
    setSelectedProductName(null);
    setHighlightedProductName(null);
  }, []);

  const handleLoadAnalysis = React.useCallback(async (analysisId: string) => {
    try {
        const analysisToLoad = await loadAnalysis(analysisId);
        if (analysisToLoad) {
          images.forEach(i => URL.revokeObjectURL(i.imageUrl));
          const loadedImages: ImageState[] = analysisToLoad.images.map(serializableImage => {
            const file = base64ToFile(serializableImage.file.data, serializableImage.file.name, serializableImage.file.type, serializableImage.file.lastModified);
            return {
              id: serializableImage.id,
              file,
              imageUrl: URL.createObjectURL(file),
              analysisResult: serializableImage.analysisResult,
              status: serializableImage.status,
              error: serializableImage.error,
              uploadDate: new Date(serializableImage.uploadDate),
              analysisType: (serializableImage.analysisType || 'both') as AnalysisType,
              retryCount: serializableImage.retryCount || 0,
              assignedStore: serializableImage.assignedStore,
              assignedStoreId: serializableImage.assignedStoreId,
              modelName: serializableImage.modelName
            };
          });
          setActiveAnalysis(analysisToLoad);
          setImages(loadedImages.sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));
          setBrandClassifications(analysisToLoad.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');
          setSelectedImageId(null);
          setSelectedProductName(null);
          setSidebarView('images');
          setProductSearchTerm('');
        }
    } catch (e) {
        console.error(e);
        alert(t('archiveLoadError'));
    }
  }, [images, t]);

  if (!hasApiKey) return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      <Header onNewAnalysis={() => activeAnalysis ? setIsClearConfirmOpen(true) : setIsNewAnalysisModalOpen(true)} onOpenSearch={() => setIsSearchModalOpen(true)} />
      <GlobalAnalysisStatus total={images.length} completed={images.filter(i => i.status === 'success').length} analyzing={images.filter(i => i.status === 'analyzing').length} errors={images.filter(i => i.status === 'error').length} />
      <div className="flex flex-1 overflow-hidden">
        <Sidebar activeView={activeView} onNavClick={v => { setActiveView(v); if (v !== 'home' && images.length) handleSummaryClick(); }} />
        <div className="flex-1 p-6 overflow-y-auto">
          {activeView === 'home' ? <HomeScreen onStartAnalysis={() => setIsNewAnalysisModalOpen(true)} /> :
           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={() => setIsNewAnalysisModalOpen(true)} onLoadAnalysis={handleLoadAnalysis} /> :
           activeView === 'stores' ? <StoresPanel /> :
           activeView === 'gallery' ? <GalleryPanel /> :
           activeView === 'posMaterial' ? <PosMaterialPanel /> :
           activeView === 'productCatalog' ? (selectedCatalogProduct ? <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} /> : <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />) :
           activeView === 'distribution' ? <DistributionPanel activeImages={images} /> :
           activeView === 'listing' ? <ListingPanel /> :
           activeView === 'costs' ? <CostPanel /> :
           activeView === 'prompts' ? <PromptManagerPanel /> :
           images.length === 0 ? <div className="h-full flex items-center justify-center"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div> :
           <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8">
             <aside className="lg:col-span-1 bg-white p-4 rounded-xl shadow-sm border flex flex-col gap-4 self-start no-print">
               <div className="flex justify-between items-center">
                 <h3 className="font-bold text-gray-900">{sidebarView === 'images' ? t('images') : t('products')}</h3>
                 <div className="flex gap-2">
                   <button onClick={() => setSidebarView('images')} className={`p-1 rounded ${sidebarView === 'images' ? 'bg-lime-100 text-lime-700' : 'text-gray-400'}`}><AppIcon className="w-5 h-5"/></button>
                   <button onClick={() => setSidebarView('products')} className={`p-1 rounded ${sidebarView === 'products' ? 'bg-lime-100 text-lime-700' : 'text-gray-400'}`}><CircleStackIcon className="w-5 h-5"/></button>
                 </div>
               </div>
               <div className="max-h-[calc(100vh-320px)] overflow-y-auto space-y-2 custom-scrollbar pr-1">
                 {sidebarView === 'images' ? 
                   images.map(img => (
                     <div key={img.id} onClick={() => { setSelectedImageId(img.id); setSelectedProductName(null); }} className={`flex gap-3 p-2 rounded-lg cursor-pointer border transition-all ${selectedImageId === img.id ? 'bg-lime-50 border-lime-400' : 'hover:bg-gray-50'}`}>
                       <img src={img.imageUrl} className="w-10 h-10 object-cover rounded" loading="lazy" />
                       <div className="min-w-0 flex-1">
                         <p className="text-xs font-bold truncate">{img.file.name}</p>
                         <p className="text-[10px] text-gray-400">{img.status === 'analyzing' ? t('analyzing') : img.uploadDate.toLocaleDateString()}</p>
                       </div>
                     </div>
                   )) : 
                   productList.map(p => (
                     <button key={p.name} onClick={() => { setSelectedProductName(p.name); setSelectedImageId(null); }} className={`flex justify-between w-full p-2.5 rounded-lg border text-left transition-all ${selectedProductName === p.name ? 'bg-lime-50 border-lime-400' : 'hover:bg-gray-50'}`}>
                       <span className="text-xs font-bold truncate pr-2">{p.name}</span>
                       <span className="text-xs font-black text-lime-600">{p.count}</span>
                     </button>
                   ))
                 }
               </div>
               <button onClick={() => setIsImageUploadOverlayOpen(true)} className="w-full py-2.5 bg-lime-600 text-white rounded-lg text-sm font-bold flex justify-center items-center gap-2 hover:bg-lime-700 transition-colors shadow-lg shadow-lime-100"><UploadIcon className="w-4 h-4"/>{t('addMoreImages')}</button>
             </aside>
             <main className="lg:col-span-3 flex flex-col gap-6">
                {!selectedImageId && !selectedProductName && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') && 
                  <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} initialView={activeView as any} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />}
                {selectedImageId && images.find(i => i.id === selectedImageId) && <>
                  <ImageAnalysisDisplay imageUrl={images.find(i => i.id === selectedImageId)!.imageUrl} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                  <ResultsPanel imageId={selectedImageId} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} error={images.find(i => i.id === selectedImageId)!.error} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} onProductNameUpdate={async (i, pid, o, n) => { await addOrUpdateProductCorrection(o, n); setImages(prev => prev.map(img => img.id === i ? { ...img, analysisResult: { ...img.analysisResult!, products: img.analysisResult!.products.map(p => p.id === pid ? { ...p, name: n } : p) } } : img)); }} onRetry={() => setImages(prev => prev.map(i => i.id === selectedImageId ? { ...i, status: 'pending' } : i))} />
                </>}
                {selectedProductName && <ProductSummaryPanel productName={selectedProductName} images={images} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} onImageSelect={(id, name) => { setSelectedImageId(id); setSelectedProductName(null); setHighlightedProductName(name); }} />}
             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={async (n, t, m, f) => { const a = { id: `analysis-${Date.now()}`, name: n, createdAt: new Date().toISOString(), images: [], store: null }; await db.analyses.add(a); setActiveAnalysis(a); setActiveView('priceMonitoring'); handleStartAnalysis(t, m, f); setIsNewAnalysisModalOpen(false); }} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles!); setIsAnalysisModalOpen(false); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={() => { images.forEach(i => URL.revokeObjectURL(i.imageUrl)); setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} onSaveToArchive={async () => { images.forEach(i => URL.revokeObjectURL(i.imageUrl)); setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={c => { setBrandClassifications(c); setIsBrandModalOpen(false); }} allBrands={brandsForClassification} brandProductsMap={images.reduce((acc, img) => { img.analysisResult?.products.forEach(p => { const b = p.brand || getBrandFromName(p.name); if (!acc[b]) acc[b] = []; if (!acc[b].includes(p.name)) acc[b].push(p.name); }); return acc; }, {} as any)} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={handleLoadAnalysis} />
        <MissingPriceModal isOpen={isMissingPriceModalOpen} onClose={() => setIsMissingPriceModalOpen(false)} items={images.flatMap(img => (img.analysisResult?.products || []).filter(p => !p.prices?.length).map(p => ({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl })))} onSave={handleUpdatePrices} />
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl"><div className="p-6 border-b flex justify-between items-center bg-gray-50 rounded-t-2xl"><h2 className="text-lg font-bold flex items-center gap-2"><UploadIcon className="w-6 h-6 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)}><CloseIcon className="w-5 h-5"/></button></div><div className="p-6"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div></div></div>}
      </div>
    </div>
  );
};

export default App;

