import type { DetectedProduct, MergeCandidate } from '../types';

const MULTI_WORD_CATEGORIES = ['Bon pari'];
// Globálna cache prežíva re-rendery komponentov
const normalizationCache = new Map<string, string>();
const similarityCache = new Map<string, number>();

export const normalizeProductName = (name: string): string => {
  if (!name) return '';
  const cached = normalizationCache.get(name);
  if (cached) return cached;

  const result = name
    .toLowerCase()
    .trim()
    .replace(/[.,/#!$%^&*;:{}=\-_`~()]/g, "") 
    .replace(/\s+/g, ' ');

  if (normalizationCache.size > 5000) normalizationCache.clear();
  normalizationCache.set(name, result);
  return result;
};

export const calculateStringSimilarity = (a: string, b: string): number => {
    if (a === b) return 100;
    if (!a || !b) return 0;

    const lenA = a.length;
    const lenB = b.length;

    // Early exit - rozdiel dĺžok je príliš veľký na to aby prešli thresholdom 85%
    if (Math.abs(lenA - lenB) > Math.max(lenA, lenB) * 0.25) return 0;

    const cacheKey = a < b ? `${a}|${b}` : `${b}|${a}`;
    const cached = similarityCache.get(cacheKey);
    if (cached !== undefined) return cached;

    // Linear space optimization O(min(n, m))
    let v0 = new Int32Array(lenB + 1);
    let v1 = new Int32Array(lenB + 1);

    for (let i = 0; i <= lenB; i++) v0[i] = i;

    for (let i = 0; i < lenA; i++) {
        v1[0] = i + 1;
        for (let j = 0; j < lenB; j++) {
            const cost = a[i] === b[j] ? 0 : 1;
            v1[j + 1] = Math.min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost);
        }
        v0.set(v1);
    }

    const score = (1 - v0[lenB] / Math.max(lenA, lenB)) * 100;

    if (similarityCache.size > 10000) similarityCache.clear();
    similarityCache.set(cacheKey, score);
    return score;
};

export const findBestMatch = (query: string, candidates: string[]): string | null => {
    if (!query || candidates.length === 0) return null;
    const normQuery = normalizeProductName(query);

    // Fast path: Exact match
    if (candidates.includes(query)) return query;

    let bestMatch: string | null = null;
    let highestScore = 0;

    for (const cand of candidates) {
        const normCand = normalizeProductName(cand);
        if (normQuery === normCand) return cand;

        const score = calculateStringSimilarity(normQuery, normCand);
        if (score > highestScore && score > 88) {
            highestScore = score;
            bestMatch = cand;
        }
    }
    return bestMatch;
};

export const getCategoryFromName = (name: string, unassignedCategory: string): string => {
  if (!name) return unassignedCategory;
  const lowerName = name.toLowerCase();
  for (const cat of MULTI_WORD_CATEGORIES) {
    if (lowerName.startsWith(cat.toLowerCase())) return cat;
  }
  const firstWord = name.split(' ')[0];
  if (!firstWord) return unassignedCategory;
  return firstWord.charAt(0).toUpperCase() + firstWord.slice(1).toLowerCase();
};

export const getBrandFromName = (name: string): string => {
  if (!name) return '';
  return name.split(' ')[0];
};

export const parseDateFromFileName = (fileName: string): Date | null => {
    const match = fileName.match(/(\d{1,2})[._-](\d{1,2})[._-](\d{4})/);
    if (match) {
        const [_, day, month, year] = match;
        const date = new Date(`${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T12:00:00Z`);
        return isNaN(date.getTime()) ? null : date;
    }
    return null;
}

export const extractStoreFromFilename = (filename: string): string | null => {
    const knownChains = ['Tesco', 'Billa', 'Lidl', 'Kaufland', 'Coop', 'Metro', 'Terno', 'Kraj', 'Fresh', 'CBA', 'Jednota', 'Albert', 'DM'];
    let cleaned = filename.replace(/\.[^/.]+$/, "").replace(/[_\-.]/g, ' ').replace(/\s+/g, ' ').trim();
    for (const chain of knownChains) {
        const regex = new RegExp(`\\b${chain}\\b`, 'i');
        if (regex.test(cleaned)) {
            const remainder = cleaned.replace(regex, '').trim().split(' ').slice(0, 2).join(' ');
            return remainder ? `${chain}, ${remainder}` : chain;
        }
    }
    return null;
};

export const removeDateFromStoreName = (name?: string): string => {
    if (!name) return '';
    return name.replace(/\s*\(\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*-\s*\d{1,2}[./-]\d{1,2}[./-]\d{4}\s*\)/gi, '').trim();
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve((reader.result as string).split(',')[1]);
    reader.onerror = reject;
  });
};

export const base64ToFile = (base64: string, name: string, type: string, lastModified: number): File => {
  const byteCharacters = atob(base64);
  const byteArray = new Uint8Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) byteArray[i] = byteCharacters.charCodeAt(i);
  return new File([byteArray], name, { type, lastModified });
};

export const resizeAndCompressImage = (file: File, maxWidth: number = 1600, quality: number = 0.75): Promise<File> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.src = url;
        img.onload = () => {
            URL.revokeObjectURL(url);
            let { width, height } = img;
            if (width > maxWidth) {
                height = (maxWidth / width) * height;
                width = maxWidth;
            }
            const canvas = document.createElement('canvas');
            canvas.width = width; canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.drawImage(img, 0, 0, width, height);
                canvas.toBlob(b => {
                    if (b) resolve(new File([b], file.name, { type: 'image/jpeg' }));
                    else reject();
                    canvas.width = 0; canvas.height = 0;
                }, 'image/jpeg', quality);
            } else {
                reject();
            }
        };
        img.onerror = () => { URL.revokeObjectURL(url); reject(); };
    });
};

export const findMergeCandidates = (newProducts: DetectedProduct[], allProducts: DetectedProduct[]): MergeCandidate[] => {
    const SIMILARITY_THRESHOLD = 90;
    const candidates: MergeCandidate[] = [];
    const processedIds = new Set<string>();

    for (const newProduct of newProducts) {
        if (processedIds.has(newProduct.id)) continue;
        for (const existingProduct of allProducts) {
            if (newProduct.id === existingProduct.id || processedIds.has(existingProduct.id)) continue;
            const normNew = normalizeProductName(newProduct.name);
            const normExisting = normalizeProductName(existingProduct.name);
            if (normNew === normExisting) continue;
            const similarity = calculateStringSimilarity(normNew, normExisting);
            if (similarity >= SIMILARITY_THRESHOLD) {
                candidates.push({ target: existingProduct, source: newProduct });
                processedIds.add(newProduct.id);
                processedIds.add(existingProduct.id);
                break;
            }
        }
    }
    return candidates;
};

