const LazyGalleryImage: React.FC<{ item: GalleryItem; onClick: (url: string) => void }> = ({ item, onClick }) => {
    const [url, setUrl] = useState<string | null>(null);
    const imgRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting && !url) {
                const f = base64ToFile(item.rawImage.file.data, item.rawImage.file.name, item.rawImage.file.type, item.rawImage.file.lastModified);
                const newUrl = URL.createObjectURL(f);
                setUrl(newUrl);
            }
        }, { threshold: 0.1 });

        if (imgRef.current) observer.observe(imgRef.current);
        return () => {
            observer.disconnect();
            if (url) URL.revokeObjectURL(url);
        };
    }, [item, url]);

    return (
        <div 
            ref={imgRef}
            onClick={() => url && onClick(url)}
            className="group relative aspect-square bg-gray-100 rounded-2xl overflow-hidden cursor-pointer shadow-sm hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 border border-gray-100"
        >
            {url ? (
                <img src={url} alt="Shelf" className="w-full h-full object-cover animate-fade-in" loading="lazy" />
            ) : (
                <div className="w-full h-full flex items-center justify-center text-gray-200">
                    <AppIcon className="w-8 h-8 opacity-20" />
                </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-3 flex flex-col justify-end">
                <p className="text-white text-[10px] font-black uppercase tracking-widest truncate">{item.storeName}</p>
                <p className="text-white/60 text-[9px] font-medium">{item.uploadDate.toLocaleDateString()}</p>
                <div className="mt-1"><span className="bg-lime-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded-full">{item.products.length} položiek</span></div>
            </div>
        </div>
    );
};

