const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number;
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices }) => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({
    searchTerm: '', minPrice: '', maxPrice: '', confidence: 0, category: '', chain: '',
  });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') setView('priceAnalysis');
    else if (initialView === 'shelfShare') setView('shelfShare');
    else if (initialView === 'promoAlert') setView('promoAlert');
    else if (initialView === 'costs') setView('rawData'); 
  }, [initialView]);

  const successfulImages = useMemo(() => images.filter(img => img.status === 'success'), [images]);

  // Úroveň 1: Surové zoskupenie (výkonovo náročné)
  const rawGroupedData = useMemo(() => {
    const unknownStore = t('unknownStore');
    const productsByStore = new Map<string | number, { name: string, items: (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[] }>();

    successfulImages.forEach(img => {
        if (!img.analysisResult) return;
        let storeKey: string | number = img.assignedStoreId || (img.analysisResult.storeInfo ? removeDateFromStoreName(img.analysisResult.storeInfo.chain) + (img.analysisResult.storeInfo.address || '') : unknownStore);
        let storeDisplayName = unknownStore;

        if (img.assignedStoreId && img.assignedStore) {
             const components = [img.assignedStore.name, img.assignedStore.address, img.assignedStore.city].filter(p => p && p.trim());
             storeDisplayName = [...new Set(components)].join(', ');
        } else if (img.analysisResult.storeInfo) {
             const chain = removeDateFromStoreName(img.analysisResult.storeInfo.chain);
             const address = removeDateFromStoreName(img.analysisResult.storeInfo.address);
             storeDisplayName = (chain && address) ? `${chain}, ${address}` : (chain || address || unknownStore);
        }

        if (!productsByStore.has(storeKey)) productsByStore.set(storeKey, { name: storeDisplayName, items: [] });
        img.analysisResult.products.forEach(p => {
            if (p?.name) productsByStore.get(storeKey)!.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl, imageId: img.id });
        });
    });

    return Array.from(productsByStore.entries()).map(([key, data]): StoreCentricSummary => {
        const productsMap = new Map<string, (DetectedProduct & { uploadDate: Date; imageUrl: string; imageId: string })[]>();
        data.items.forEach(p => {
            const groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : findBestMatch(p.name.trim(), Array.from(productsMap.keys()).filter(k => !k.startsWith('ID_'))) || p.name.trim();
            if (!productsMap.has(groupKey)) productsMap.set(groupKey, []);
            productsMap.get(groupKey)!.push(p);
        });

        const summarizedProducts = Array.from(productsMap.values()).map((occurrences): ProductInStore => {
            const rep = occurrences[0];
            return {
                name: rep.name,
                isCorrected: occurrences.some(o => o.isCorrected),
                category: getCategoryFromName(rep.name, unassignedCategory),
                count: occurrences.length,
                priceHistory: occurrences.flatMap(o => (o.prices || []).map(p => ({ price: p, date: o.uploadDate, imageUrl: o.imageUrl }))).sort((a, b) => a.date.getTime() - b.date.getTime()),
                avgConfidence: occurrences.reduce((a, b) => a + b.confidence, 0) / occurrences.length,
                imageUrl: occurrences[occurrences.length - 1].imageUrl,
                catalogProductId: rep.catalogProductId
            };
        });

        return { storeName: data.name, storeId: typeof key === 'number' ? key : undefined, products: summarizedProducts };
    });
  }, [successfulImages, t, unassignedCategory]);

  // Úroveň 2: Filtrovanie a transformácia pre UI
  const { storeData, totalProducts, uniqueProductCount, allCategories, allChains } = useMemo(() => {
    const filtered = rawGroupedData.map(store => {
        if (filters.chain && store.storeName !== filters.chain) return null;
        const filteredProducts = store.products.filter(item => {
            if (filters.searchTerm && !item.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
            if (filters.category && item.category !== filters.category) return false;
            if (item.avgConfidence * 100 < filters.confidence) return false;
            if (filters.minPrice || filters.maxPrice) {
                const prices = item.priceHistory.map(h => parsePrice(h.price.value)).filter((v): v is number => v !== null);
                const min = filters.minPrice === '' ? -Infinity : Number(filters.minPrice);
                const max = filters.maxPrice === '' ? Infinity : Number(filters.maxPrice);
                if (!prices.some(p => p >= min && p <= max)) return false;
            }
            return true;
        });
        return filteredProducts.length > 0 ? { ...store, products: filteredProducts } : null;
    }).filter((s): s is StoreCentricSummary => s !== null);

    return {
      storeData: filtered,
      totalProducts: successfulImages.reduce((sum, img) => sum + (img.analysisResult?.products.length || 0), 0),
      uniqueProductCount: new Set(rawGroupedData.flatMap(s => s.products.map(p => p.catalogProductId ? `ID_${p.catalogProductId}` : p.name))).size,
      allCategories: Array.from(new Set(rawGroupedData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(rawGroupedData.map(s => s.storeName))).sort()
    };
  }, [rawGroupedData, filters, successfulImages]);

  const missingPriceCount = useMemo(() => successfulImages.reduce((c, img) => c + (img.analysisResult?.products.filter(p => !p.prices?.length).length || 0), 0), [successfulImages]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content animate-fade-in">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg shadow-2xl" alt="Zoom" />
            <button className="absolute top-6 right-6 text-white bg-black/50 p-3 rounded-full hover:bg-black transition-colors"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-900">{t('batchSummary')}</h2>
        {missingPriceCount > 0 && (
            <button onClick={onOpenMissingPrices} className="flex items-center gap-2 px-4 py-2 bg-orange-100 text-orange-800 rounded-xl hover:bg-orange-200 transition-all animate-pulse border border-orange-200">
                <TagIcon className="w-5 h-5" />
                <span className="font-bold text-xs uppercase tracking-wider">{t('fixMissingPrices', { count: missingPriceCount })}</span>
            </button>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {[
          { label: t('imagesCount'), val: images.length, color: 'text-blue-600' },
          { label: t('analyzed'), val: successfulImages.length, color: 'text-green-600' },
          { label: t('totalProducts'), val: totalProducts, color: 'text-lime-600' },
          { label: t('uniqueProducts'), val: uniqueProductCount, color: 'text-purple-600' }
        ].map(stat => (
          <div key={stat.label} className="bg-gray-50/50 p-4 rounded-2xl border border-gray-100 text-center">
            <p className={`text-2xl font-black ${stat.color}`}>{stat.val}</p>
            <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest mt-1">{stat.label}</p>
          </div>
        ))}
      </div>

      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon }
          ].map(tab => (
            <button key={tab.id} onClick={() => setView(tab.id as any)} className={`-mb-px px-6 py-3 text-sm font-bold transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600 bg-lime-50/30' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                <tab.icon className="w-4 h-4" /> {tab.label}
            </button>
          ))}
      </div>

      <div className="flex-grow min-h-0">
        {view === 'priceAnalysis' && (
          <div className="h-full flex flex-col">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-2 mb-4 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 shadow-sm transition-all">
                    <ArrowDownTrayIcon className="w-4 h-4 text-green-600" /> XLS
                </button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-gray-900 text-white hover:bg-black shadow-lg transition-all">
                    <DocumentTextIcon className="w-4 h-4" /> PDF
                </button>
            </div>
            <div className="space-y-6 overflow-y-auto pr-2 custom-scrollbar">
                {storeData.map(store => (
                    <div key={store.storeName} className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="bg-gray-50/80 px-5 py-4 border-b border-gray-100 flex items-center justify-between">
                            <h3 className="font-black text-gray-900 uppercase tracking-tight">{store.storeName}</h3>
                            <span className="bg-white px-2 py-1 rounded-lg border border-gray-100 text-[10px] font-black text-gray-400 uppercase">{store.products.length} SKU</span>
                        </div>
                        <div className="divide-y divide-gray-50">
                            {store.products.map(product => {
                                const regular = product.priceHistory.find(ph => ph.price.type === 'REGULAR')?.price.value;
                                const promo = product.priceHistory.find(ph => ph.price.type === 'PROMO')?.price.value;
                                return (
                                    <div key={product.name} className="flex items-center gap-4 p-4 hover:bg-lime-50/30 transition-colors">
                                        <div className="flex-grow min-w-0">
                                            <p className="text-[10px] text-lime-700 font-black uppercase tracking-tighter mb-0.5">{product.category}</p>
                                            <p className="font-bold text-sm text-gray-800 truncate">{product.name}</p>
                                        </div>
                                        <div className="flex gap-2 flex-shrink-0 items-center">
                                            {regular && <span className={`px-2 py-1 rounded-lg text-xs font-black ${promo ? 'line-through text-gray-300' : 'bg-gray-100 text-gray-700'}`}>{regular}</span>}
                                            {promo && <span className="px-2 py-1 rounded-lg bg-red-100 text-red-600 text-xs font-black shadow-sm ring-1 ring-red-200">{promo}</span>}
                                        </div>
                                        <div className="w-12 h-12 rounded-xl border border-gray-100 overflow-hidden flex-shrink-0 cursor-zoom-in group relative" onClick={() => setZoomedImage(product.imageUrl || null)}>
                                            {product.imageUrl && <img src={product.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" loading="lazy" />}
                                            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center"><BoxIcon className="w-4 h-4 text-white opacity-0 group-hover:opacity-100" /></div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && <div className="bg-gray-900 text-lime-400 p-6 rounded-2xl overflow-x-auto font-mono text-xs max-h-full"><pre>{JSON.stringify(images, null, 2)}</pre></div>}
      </div>

       <div className="mt-8 pt-6 border-t border-gray-100 no-print">
        <button onClick={onReset} className="w-full bg-red-600 hover:bg-red-700 text-white font-black py-4 px-8 rounded-2xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm shadow-xl shadow-red-100 hover:scale-[1.01] active:scale-95">
          <TrashIcon className="w-5 h-5" /> {t('endVisit')}
        </button>
      </div>
    </div>
  );
};

