    else setIsAnalysisModalOpen(true);
    setIsImageUploadOverlayOpen(false); 
  }, [activeAnalysis]);

  const handleStartAnalysis = useCallback(async (type: AnalysisType, model: string, fileList: FileList) => {
    if (!activeAnalysis) return;

    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const storeName = extractStoreFromFilename(file.name);
        let store: Store | null = null;
        if (storeName) {
             try {
                store = await findOrCreateStore({ name: storeName, chain: storeName.split(',')[0].trim(), city: '', address: '', code: '' });
             } catch (e) { console.warn(e); }
        }

        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: store,
            assignedStoreId: store?.id,
            modelName: model
        };
    }));

    setImages(prev => [...prev, ...tempImages].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    // Kompresia na pozadí pre plynulosť UI
    setTimeout(async () => {
        for (const img of tempImages) {
            try {
                const compressed = await resizeAndCompressImage(img.file);
                const newUrl = URL.createObjectURL(compressed);
                setImages(prev => prev.map(p => {
                    if (p.id === img.id) {
                        URL.revokeObjectURL(p.imageUrl);
                        return { ...p, file: compressed, imageUrl: newUrl };
                    }
                    return p;
                }));
            } catch (e) { console.error(e); }
        }
    }, 10);
  }, [activeAnalysis]);

  useEffect(() => {
    if (!isOnline || isAnalyzing) return;
    const pending = images.filter(img => img.status === 'pending');
    if (pending.length === 0) return;

    const process = async () => {
        const current = pending[0];
        setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'analyzing' } : img));

        try {
            const base64 = await fileToBase64(current.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(current.analysisType === 'price' ? 'geminiPromptPriceOnly' : current.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), current.analysisType, current.modelName);

            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${current.id}-${Math.random()}` };
            }));

            setImages(prev => prev.map(img => img.id === current.id ? { ...img, analysisResult: { ...result, products: corrected }, status: 'success' } : img));
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'error', error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } : img));
        }
    };
    const timer = setTimeout(process, 100);
    return () => clearTimeout(timer);
  }, [images, isOnline, isAnalyzing, t]);

  const productList = useMemo(() => {
    const completed = images.filter(img => img.status === 'success');
    if (!completed.length) return [];

    const map = new Map<string, { name: string; count: number; category: string }>();
    const knownNames: string[] = [];

    completed.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p?.name) return;
        const matched = findBestMatch(p.name, knownNames) || p.name;
        if (!knownNames.includes(matched)) knownNames.push(matched);

        const entry = map.get(matched);
        if (entry) entry.count++;
        else map.set(matched, { name: matched, count: 1, category: getCategoryFromName(matched, t('unassignedCategory')) });
      });
    });
    return Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
  }, [images.filter(i => i.status === 'success').length, t]);

  const handleNavClick = useCallback((v: ActiveView) => {
    setActiveView(v);
    if (v !== 'home' && images.length) {
        setSelectedImageId(null);
        setSelectedProductName(null);
        setHighlightedProductName(null);
    }
  }, [images.length]);

  const handleLoadAnalysis = useCallback(async (analysisId: string) => {
    try {
        const a = await loadAnalysis(analysisId);
        if (a) {
          images.forEach(i => URL.revokeObjectURL(i.imageUrl));
          const loaded: ImageState[] = a.images.map(s => {
            const f = base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified);
            return {
              ...s, file: f, imageUrl: URL.createObjectURL(f), uploadDate: new Date(s.uploadDate),
              analysisType: (s.analysisType || 'both') as AnalysisType
            };
          });
          setActiveAnalysis(a);
          setImages(loaded.sort((x, y) => new Date(y.uploadDate).getTime() - new Date(x.uploadDate).getTime()));
          setBrandClassifications(a.brandClassifications || { ourBrands: [], competitorBrands: [] });
          setIsSearchModalOpen(false);
          setActiveView('priceMonitoring');
        }
    } catch (e) { alert(t('archiveLoadError')); }
  }, [images, t]);

  if (!hasApiKey) return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col antialiased">
      <Header onNewAnalysis={() => activeAnalysis ? setIsClearConfirmOpen(true) : setIsNewAnalysisModalOpen(true)} onOpenSearch={() => setIsSearchModalOpen(true)} />
      <GlobalAnalysisStatus total={images.length} completed={images.filter(i => i.status === 'success').length} analyzing={images.filter(i => i.status === 'analyzing').length} errors={images.filter(i => i.status === 'error').length} />
      <div className="flex flex-1 overflow-hidden">
        <MemoizedSidebar activeView={activeView} onNavClick={handleNavClick} />
        <div className="flex-1 p-6 overflow-y-auto scroll-smooth">
          {activeView === 'home' ? <HomeScreen onStartAnalysis={() => setIsNewAnalysisModalOpen(true)} /> :
           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={() => setIsNewAnalysisModalOpen(true)} onLoadAnalysis={handleLoadAnalysis} /> :
           activeView === 'stores' ? <StoresPanel /> :
           activeView === 'gallery' ? <GalleryPanel /> :
           activeView === 'posMaterial' ? <PosMaterialPanel /> :
           activeView === 'productCatalog' ? (selectedCatalogProduct ? <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} /> : <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />) :
           activeView === 'distribution' ? <DistributionPanel activeImages={images} /> :
           activeView === 'costs' ? <CostPanel /> :
           activeView === 'prompts' ? <PromptManagerPanel /> :
           images.length === 0 && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') ? 
           <ModuleLandingPage type={activeView} onStart={() => setIsNewAnalysisModalOpen(true)} onLoad={() => setActiveView('analyses')} /> :
           images.length === 0 ? <div className="h-full flex items-center justify-center"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div> :
           <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8">
             <aside className="lg:col-span-1 bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col gap-4 self-start no-print">
               <div className="flex justify-between items-center px-1">
                 <h3 className="font-black text-gray-900 uppercase text-xs tracking-widest">{sidebarView === 'images' ? t('images') : t('products')}</h3>
                 <div className="flex gap-2 bg-gray-100 p-1 rounded-lg">
                   <button onClick={() => setSidebarView('images')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'images' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><AppIcon className="w-4 h-4"/></button>
                   <button onClick={() => setSidebarView('products')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'products' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><CircleStackIcon className="w-4 h-4"/></button>
                 </div>
               </div>
               <div className="max-h-[calc(100vh-320px)] overflow-y-auto space-y-2 custom-scrollbar pr-1">
                 {sidebarView === 'images' ? 
                   images.map(img => (
                     <div key={img.id} onClick={() => { setSelectedImageId(img.id); setSelectedProductName(null); }} className={`flex gap-3 p-2 rounded-xl cursor-pointer border transition-all duration-200 ${selectedImageId === img.id ? 'bg-lime-50 border-lime-400 scale-[1.02] shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <img src={img.imageUrl} className="w-10 h-10 object-cover rounded-lg bg-gray-100" loading="lazy" />
                       <div className="min-w-0 flex-1">
                         <p className="text-[11px] font-bold truncate text-gray-800">{img.file.name}</p>
                         <p className="text-[9px] font-black uppercase text-gray-400">{img.status === 'analyzing' ? t('analyzing') : img.uploadDate.toLocaleDateString()}</p>
                       </div>
                       {img.status === 'success' && <div className="h-1.5 w-1.5 rounded-full bg-green-500 mt-2"></div>}
                     </div>
                   )) : 
                   productList.map(p => (
                     <button key={p.name} onClick={() => { setSelectedProductName(p.name); setSelectedImageId(null); }} className={`flex justify-between w-full p-3 rounded-xl border text-left transition-all duration-200 ${selectedProductName === p.name ? 'bg-lime-50 border-lime-400 shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <span className="text-[11px] font-bold truncate pr-2 text-gray-700">{p.name}</span>
                       <span className="text-[11px] font-black text-lime-600 bg-lime-100/50 px-2 py-0.5 rounded-lg">{p.count}</span>
                     </button>
                   ))
                 }
               </div>
               <button onClick={() => setIsImageUploadOverlayOpen(true)} className="w-full py-3 bg-lime-600 text-white rounded-xl text-xs font-black uppercase tracking-widest flex justify-center items-center gap-2 hover:bg-lime-700 transition-all shadow-lg shadow-lime-100 active:scale-95"><UploadIcon className="w-4 h-4"/>{t('addMoreImages')}</button>
             </aside>
             <main className="lg:col-span-3 flex flex-col gap-6">
                {!selectedImageId && !selectedProductName && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') && 
                  <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} initialView={activeView as any} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />}
                {selectedImageId && images.find(i => i.id === selectedImageId) && <>
                  <ImageAnalysisDisplay imageUrl={images.find(i => i.id === selectedImageId)!.imageUrl} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                  <ResultsPanel imageId={selectedImageId} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} error={images.find(i => i.id === selectedImageId)!.error} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} onProductNameUpdate={async (i, pid, o, n) => { await addOrUpdateProductCorrection(o, n); setImages(prev => prev.map(img => img.id === i ? { ...img, analysisResult: { ...img.analysisResult!, products: img.analysisResult!.products.map(p => p.id === pid ? { ...p, name: n } : p) } } : img)); }} onRetry={() => setImages(prev => prev.map(i => i.id === selectedImageId ? { ...i, status: 'pending' } : i))} />
                </>}
                {selectedProductName && <ProductSummaryPanel productName={selectedProductName} images={images} onReset={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); }} onImageSelect={(id, name) => { setSelectedImageId(id); setSelectedProductName(null); setHighlightedProductName(name); }} />}
             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={async (n, t, m, f) => { const a = { id: `analysis-${Date.now()}`, name: n, createdAt: new Date().toISOString(), images: [], store: null }; await db.analyses.add(a); setActiveAnalysis(a); setActiveView('priceMonitoring'); handleStartAnalysis(t, m, f); setIsNewAnalysisModalOpen(false); }} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles!); setIsAnalysisModalOpen(false); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={() => { setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} onSaveToArchive={async () => { setImages([]); setActiveAnalysis(null); setActiveView('home'); setIsClearConfirmOpen(false); }} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={c => { setBrandClassifications(c); setIsBrandModalOpen(false); }} allBrands={brandsForClassification} brandProductsMap={images.reduce((acc, img) => { img.analysisResult?.products.forEach(p => { const b = p.brand || getBrandFromName(p.name); if (!acc[b]) acc[b] = []; if (!acc[b].includes(p.name)) acc[b].push(p.name); }); return acc; }, {} as any)} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={handleLoadAnalysis} />
        <MissingPriceModal isOpen={isMissingPriceModalOpen} onClose={() => setIsMissingPriceModalOpen(false)} items={images.flatMap(img => (img.analysisResult?.products || []).filter(p => !p.prices?.length).map(p => ({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl })))} onSave={handleUpdatePrices} />
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl overflow-hidden"><div className="p-6 border-b flex justify-between items-center bg-gray-50"><h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2 text-gray-700"><UploadIcon className="w-5 h-5 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-400"><CloseIcon className="w-5 h-5"/></button></div><div className="p-10"><ImageUploader onImageUpload={handleImageUpload} isLoading={isAnalyzing} /></div></div></div>}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react'; 
import { ImageUploader } from './components/ImageUploader';
import { ImageAnalysisDisplay } from './components/ImageAnalysisDisplay';
import { ResultsPanel } from './components/ResultsPanel';
import { BatchSummaryPanel } from './components/BatchSummaryPanel';
import { ProductSummaryPanel } from './components/ProductSummaryPanel';
import { analyzeImageWithGemini } from './services/geminiService';
import type { AnalysisResult, Analysis, SerializableImageState, DetectedProduct, BrandClassifications, Store, MergeCandidate, ProductCatalogEntry, PriceInfo, ActiveView } from './types';
import { getCategoryFromName, parseDateFromFileName, findBestMatch, fileToBase64, base64ToFile, getBrandFromName, normalizeProductName, findMergeCandidates, extractStoreFromFilename, resizeAndCompressImage } from './utils/helpers';
import { AppIcon, SpinnerIcon, WarningIcon, UploadIcon, CircleStackIcon, HomeIcon, CalendarDaysIcon, TableCellsIcon, BookOpenIcon, StoreIcon, CalculatorIcon, MessageSquareCodeIcon, ShieldExclamationIcon, TagIcon, CloseIcon } from './components/Icons';
import { useTranslation } from './i18n';
import { AnalysisTypeModal } from './components/AnalysisTypeModal';
import { ClearConfirmModal } from './components/ClearConfirmModal';
import { HomeScreen } from './components/HomeScreen';
import { db, saveAnalysis, loadAnalysis, addOrUpdateProductCorrection, findProductByAlias, populateCatalogFromAnalysis, getCatalogEntries, getAnalyses, findOrCreateStore } from './db';
import { BrandDefinitionModal } from './components/BrandDefinitionModal';
import { Header } from './components/Header';
import { SearchModal } from './components/SearchModal';
import { ProductCatalogPanel, ProductCardPanel } from './components/ProductCatalogPanel';
import { NewAnalysisModal } from './components/NewAnalysisModal';
import { DistributionPanel } from './components/DistributionPanel';
import { ListingPanel } from './components/ListingPanel';
import { StoresPanel } from './components/StoresPanel';
import { StoreAssignmentModal } from './components/StoreAssignmentModal';
import { MergeConfirmationModal } from './components/MergeConfirmationModal';
import { AnalysesPanel } from './components/AnalysesPanel';
import { ApiKeySelectionScreen } from './components/ApiKeySelectionScreen';
import { MissingPriceModal, MissingPriceItem } from './components/MissingPriceModal';
import Sidebar from './components/Sidebar';
import { GlobalAnalysisStatus } from './components/GlobalAnalysisStatus';
import { GalleryPanel } from './components/GalleryPanel';
import { CostPanel } from './components/CostPanel';
import { PromptManagerPanel } from './components/PromptManagerPanel';
import { PosMaterialPanel } from './components/PosMaterialPanel';
import { ModuleLandingPage } from './components/ModuleLandingPage';

export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName?: string;
}

// MEMOIZOVANÝ SIDEBAR PRE ZNÍŽENIE RE-RENDEROV
const MemoizedSidebar = React.memo(Sidebar);

export const App: React.FC = () => {
  const [images, setImages] = useState<ImageState[]>([]);
  const [selectedImageId, setSelectedImageId] = useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = useState<string | null>(null);
  const [sidebarView, setSidebarView] = useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = useState('');
  const [highlightedProductName, setHighlightedProductName] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false); 
  const [pendingFiles, setPendingFiles] = useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = useState(false);
  const [brandsForClassification, setBrandsForClassification] = useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = useState(false);
  const [activeAnalysis, setActiveAnalysis] = useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // AGRESÍVNA SPRÁVA PAMÄTE PRI PREPÍNANÍ ANALÝZ
  useEffect(() => {
    return () => {
        images.forEach(img => {
            if (img.imageUrl.startsWith('blob:')) URL.revokeObjectURL(img.imageUrl);
        });
    };
  }, [activeAnalysis?.id]);

  useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const isAnalyzing = useMemo(() => images.some(img => img.status === 'analyzing'), [images]);

  const handleUpdatePrices = useCallback((updates: { imageId: string; productId: string; prices: PriceInfo[] }[]) => {
      setImages(prev => prev.map(img => {
          const updatesForImage = updates.filter(u => u.imageId === img.id);
          if (updatesForImage.length === 0) return img;
          const updatedProducts = img.analysisResult?.products.map(p => {
              const update = updatesForImage.find(u => u.productId === p.id);
              return update ? { ...p, prices: update.prices } : p;
          });
          return { ...img, analysisResult: img.analysisResult ? { ...img.analysisResult, products: updatedProducts || [] } : null };
      }));
  }, []);

  const handleImageUpload = useCallback((files: FileList) => {
    setPendingFiles(files);
    if (!activeAnalysis) setIsNewAnalysisModalOpen(true);
    else setIsAnalysisModalOpen(true);
    setIsImageUploadOverlayOpen(false); 
  }, [activeAnalysis]);

  const handleStartAnalysis = useCallback(async (type: AnalysisType, model: string, fileList: FileList) => {
    if (!activeAnalysis) return;

    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const storeName = extractStoreFromFilename(file.name);
        let store: Store | null = null;
        if (storeName) {
             try {
                store = await findOrCreateStore({ name: storeName, chain: storeName.split(',')[0].trim(), city: '', address: '', code: '' });
             } catch (e) { console.warn(e); }
        }

        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file,
            imageUrl: URL.createObjectURL(file),
            analysisResult: null,
            status: 'pending',
            error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type,
            retryCount: 0,
            assignedStore: store,
            assignedStoreId: store?.id,
            modelName: model
        };
    }));

    setImages(prev => [...prev, ...tempImages].sort((a, b) => b.uploadDate.getTime() - a.uploadDate.getTime()));

    // Kompresia na pozadí pre plynulosť UI
    setTimeout(async () => {
        for (const img of tempImages) {
            try {
                const compressed = await resizeAndCompressImage(img.file);
                const newUrl = URL.createObjectURL(compressed);
                setImages(prev => prev.map(p => {
                    if (p.id === img.id) {
                        URL.revokeObjectURL(p.imageUrl);
                        return { ...p, file: compressed, imageUrl: newUrl };
                    }
                    return p;
                }));
            } catch (e) { console.error(e); }
        }
    }, 10);
  }, [activeAnalysis]);

  useEffect(() => {
    if (!isOnline || isAnalyzing) return;
    const pending = images.filter(img => img.status === 'pending');
    if (pending.length === 0) return;

    const process = async () => {
        const current = pending[0];
        setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'analyzing' } : img));

        try {
            const base64 = await fileToBase64(current.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(current.analysisType === 'price' ? 'geminiPromptPriceOnly' : current.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), current.analysisType, current.modelName);

            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${current.id}-${Math.random()}` };
            }));

            setImages(prev => prev.map(img => img.id === current.id ? { ...img, analysisResult: { ...result, products: corrected }, status: 'success' } : img));
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            setImages(prev => prev.map(img => img.id === current.id ? { ...img, status: 'error', error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } : img));
        }
    };
    const timer = setTimeout(process, 100);
    return () => clearTimeout(timer);
  }, [images, isOnline, isAnalyzing, t]);

  const productList = useMemo(() => {
