export const ImageAnalysisDisplay: React.FC<ImageAnalysisDisplayProps> = ({ imageUrl, analysisResult, isLoading, highlightedProductName }) => {
  const [showBoxes, setShowBoxes] = useState(true);
  const [showHeatmap, setShowHeatmap] = useState(false);
  const [showPos, setShowPos] = useState(true);
  const { t } = useTranslation();

  const products = useMemo(() => Array.isArray(analysisResult?.products) ? analysisResult.products : [], [analysisResult]);

  return (
    <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200">
      <div className="relative w-full overflow-hidden rounded-md bg-gray-200" style={{ isolation: 'isolate' }}>
        <img src={imageUrl} alt="Analyzovaný regál" className="w-full h-auto object-contain block" />

        {isLoading && (
            <div className="absolute inset-0 bg-white bg-opacity-80 flex flex-col items-center justify-center text-gray-800 z-30">
                <SpinnerIcon className="w-16 h-16 text-lime-500" />
                <p className="mt-4 text-lg font-semibold">{t('analyzingInProgress')}</p>
            </div>
        )}

        {showBoxes && products.map((product, index) => {
          if (!product || !product.boundingBox) return null;
          const isPOS = product.type === 'pos_material';
          if (isPOS && !showPos) return null;

          const isHighlighted = product.name === highlightedProductName;

          // CSS OPTIMALIZÁCIA: Bounding boxy využívajú will-change a premenné
          return (
            <div
              key={`box-${index}`}
              className={`absolute group z-20 transition-all duration-300 ${isHighlighted ? 'highlight-box' : ''}`}
              style={{
                left: `${(product.boundingBox.x || 0) * 100}%`,
                top: `${(product.boundingBox.y || 0) * 100}%`,
                width: `${(product.boundingBox.width || 0) * 100}%`,
                height: `${(product.boundingBox.height || 0) * 100}%`,
                borderWidth: '2px',
                borderStyle: product.isGhost ? 'dashed' : 'solid',
                borderColor: isPOS ? '#9333ea' : product.confidence >= 0.9 ? '#22c55e' : '#ef4444',
                willChange: 'transform',
                pointerEvents: 'auto'
              }}
            >
              <div className="absolute -top-7 left-0 bg-black/80 text-white text-[9px] font-black px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-50 flex items-center gap-1.5 backdrop-blur-sm pointer-events-none">
                {product.isGhost && <ShieldExclamationIcon className="w-2.5 h-2.5 text-orange-400" />}
                {isPOS && <TagIcon className="w-2.5 h-2.5 text-purple-400" />}
                {product.name}
                <span className="opacity-50">({Math.round(product.confidence * 100)}%)</span>
              </div>
            </div>
          );
        })}

        {showHeatmap && (
            <div className="absolute inset-0 z-10 pointer-events-none mix-blend-overlay">
                {products.filter(p => p.type === 'product').map((product, index) => {
                    if (!product || !product.boundingBox) return null;
                    return (
                        <div
                            key={`heat-${index}`}
                            className="absolute rounded-full"
                            style={{
                                left: `${((product.boundingBox.x || 0) + (product.boundingBox.width || 0) / 2) * 100}%`,
                                top: `${((product.boundingBox.y || 0) + (product.boundingBox.height || 0) / 2) * 100}%`,
                                width: `${Math.max((product.boundingBox.width || 0), (product.boundingBox.height || 0)) * 200}%`,
                                height: `${Math.max((product.boundingBox.width || 0), (product.boundingBox.height || 0)) * 200}%`,
                                transform: 'translate(-50%, -50%)',
                                background: 'radial-gradient(circle, rgba(163,230,53,0.4) 0%, rgba(163,230,53,0) 70%)',
                            }}
                        />
                    );
                })}
            </div>
        )}
      </div>
       <div className="mt-4 flex items-center justify-end gap-3 no-print">
            <ToggleButton isActive={showBoxes} onClick={() => setShowBoxes(p => !p)}>
                <BoxIcon className="w-4 h-4" /> {t('boxes')}
            </ToggleButton>
            <ToggleButton isActive={showPos} onClick={() => setShowPos(p => !p)}>
                <TagIcon className="w-4 h-4" /> POS
            </ToggleButton>
            <ToggleButton isActive={showHeatmap} onClick={() => setShowHeatmap(p => !p)}>
                <FireIcon className="w-4 h-4" /> {t('heatmap')}
            </ToggleButton>
        </div>
    </div>
  );
};

