const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number;
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

// POMOCNÝ KOMPONENT PRE VIRTUÁLNE RENDEROVANIE PREDANEJ
const StoreRow: React.FC<{ store: StoreCentricSummary, onZoom: (url: string) => void, t: any }> = ({ store, onZoom, t }) => {
    const [isVisible, setIsVisible] = useState(false);
    const rowRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting) setIsVisible(true);
        }, { threshold: 0.01, rootMargin: '400px' });
        if (rowRef.current) observer.observe(rowRef.current);
        return () => observer.disconnect();
    }, []);

    return (
        <div ref={rowRef} className={`bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden min-h-[100px] transition-opacity duration-500 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
            {isVisible ? (
                <>
                    <div className="bg-gray-50/80 px-5 py-4 border-b border-gray-100 flex items-center justify-between">
                        <h3 className="font-black text-gray-900 uppercase tracking-tight">{store.storeName}</h3>
                        <span className="bg-white px-2 py-1 rounded-lg border border-gray-100 text-[10px] font-black text-gray-400 uppercase">{store.products.length} SKU</span>
                    </div>
                    <div className="divide-y divide-gray-50">
                        {store.products.map(product => {
                            const promo = product.priceHistory.find(ph => ph.price.type === 'PROMO')?.price.value;
                            const regular = product.priceHistory.find(ph => ph.price.type === 'REGULAR')?.price.value;
                            return (
                                <div key={product.name} className="flex items-center gap-4 p-4 hover:bg-lime-50/30 transition-colors">
                                    <div className="flex-grow min-w-0">
                                        <p className="text-[10px] text-lime-700 font-black uppercase tracking-tighter mb-0.5">{product.category}</p>
                                        <p className="font-bold text-sm text-gray-800 truncate">{product.name}</p>
                                    </div>
                                    <div className="flex gap-2 flex-shrink-0 items-center">
                                        {regular && <span className={`px-2 py-1 rounded-lg text-xs font-black ${promo ? 'line-through text-gray-300' : 'bg-gray-100 text-gray-700'}`}>{regular}</span>}
                                        {promo && <span className="px-2 py-1 rounded-lg bg-red-100 text-red-600 text-xs font-black shadow-sm ring-1 ring-red-200">{promo}</span>}
                                    </div>
                                    <div className="w-12 h-12 rounded-xl border border-gray-100 overflow-hidden flex-shrink-0 cursor-zoom-in group relative" onClick={() => product.imageUrl && onZoom(product.imageUrl)}>
                                        {product.imageUrl && <img src={product.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" loading="lazy" />}
                                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center"><BoxIcon className="w-4 h-4 text-white opacity-0 group-hover:opacity-100" /></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </>
            ) : (
                <div className="p-10 flex justify-center"><SpinnerIcon className="w-6 h-6 text-gray-100 animate-spin" /></div>
            )}
        </div>
    );
};

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices }) => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({ searchTerm: '', minPrice: '', maxPrice: '', confidence: 0, category: '', chain: '' });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') setView('priceAnalysis');
    else if (initialView === 'shelfShare') setView('shelfShare');
    else if (initialView === 'promoAlert') setView('promoAlert');
    else if (initialView === 'costs') setView('rawData'); 
  }, [initialView]);

  const rawGroupedData = useMemo(() => {
    const unknownStore = t('unknownStore');
    const storeMap = new Map<string | number, { name: string, items: any[] }>();
    const successful = images.filter(img => img.status === 'success');

    successful.forEach(img => {
        if (!img.analysisResult) return;
        const storeKey = img.assignedStoreId || (img.analysisResult.storeInfo ? removeDateFromStoreName(img.analysisResult.storeInfo.chain) + (img.analysisResult.storeInfo.address || '') : unknownStore);
        if (!storeMap.has(storeKey)) {
            let displayName = unknownStore;
            if (img.assignedStore) displayName = [img.assignedStore.name, img.assignedStore.city].filter(Boolean).join(', ');
            else if (img.analysisResult.storeInfo) displayName = [img.analysisResult.storeInfo.chain, img.analysisResult.storeInfo.address].filter(Boolean).join(', ');
            storeMap.set(storeKey, { name: displayName, items: [] });
        }
        img.analysisResult.products.forEach(p => {
            if (p?.name) storeMap.get(storeKey)!.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl });
        });
    });

    return Array.from(storeMap.entries()).map(([key, data]): StoreCentricSummary => {
        const productGrouping = new Map<string, any[]>();
        const nameToKey = new Map<string, string>();
        data.items.forEach(p => {
            let groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : null;
            if (!groupKey) {
                const normName = p.name.trim();
                if (nameToKey.has(normName)) groupKey = nameToKey.get(normName)!;
                else {
                    const match = findBestMatch(normName, Array.from(productGrouping.keys()).filter(k => !k.startsWith('ID_')));
                    groupKey = match || normName;
                    nameToKey.set(normName, groupKey);
                }
            }
            if (!productGrouping.has(groupKey)) productGrouping.set(groupKey, []);
            productGrouping.get(groupKey)!.push(p);
        });
        return {
            storeName: data.name,
            storeId: typeof key === 'number' ? key : undefined,
            products: Array.from(productGrouping.values()).map(occ => ({
                name: occ[0].name,
                isCorrected: occ.some(o => o.isCorrected),
                category: getCategoryFromName(occ[0].name, unassignedCategory),
                count: occ.length,
                avgConfidence: occ.reduce((a, b) => a + b.confidence, 0) / occ.length,
                imageUrl: occ[occ.length - 1].imageUrl,
                priceHistory: occ.flatMap(o => (o.prices || []).map(pr => ({ price: pr, date: o.uploadDate, imageUrl: o.imageUrl }))).sort((a, b) => a.date.getTime() - b.date.getTime())
            }))
        };
    });
  }, [images, t, unassignedCategory]);

  const { storeData, allCategories, allChains } = useMemo(() => {
    const filtered = rawGroupedData.map(store => {
        if (filters.chain && store.storeName !== filters.chain) return null;
        const filteredProducts = store.products.filter(p => {
            if (filters.searchTerm && !p.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
            if (filters.category && p.category !== filters.category) return false;
            if (p.avgConfidence * 100 < filters.confidence) return false;
            return true;
        });
        return filteredProducts.length > 0 ? { ...store, products: filteredProducts } : null;
    }).filter(Boolean) as StoreCentricSummary[];
    return {
      storeData: filtered,
      allCategories: Array.from(new Set(rawGroupedData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(rawGroupedData.map(s => s.storeName))).sort()
    };
  }, [rawGroupedData, filters]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content animate-fade-in">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg shadow-2xl" alt="Zoom" />
            <button className="absolute top-6 right-6 text-white bg-black/50 p-3 rounded-full hover:bg-black transition-colors"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-900">{t('batchSummary')}</h2>
        <div className="flex gap-4">
            <div className="text-center"><p className="text-xl font-black text-lime-600">{images.length}</p><p className="text-[10px] text-gray-400 uppercase font-black">{t('imagesCount')}</p></div>
            <div className="text-center"><p className="text-xl font-black text-purple-600">{rawGroupedData.reduce((acc, s) => acc + s.products.length, 0)}</p><p className="text-[10px] text-gray-400 uppercase font-black">{t('uniqueProducts')}</p></div>
        </div>
      </div>
      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon }
          ].map(tab => (
            <button key={tab.id} onClick={() => setView(tab.id as any)} className={`-mb-px px-6 py-3 text-sm font-bold transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600 bg-lime-50/30' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                <tab.icon className="w-4 h-4" /> {tab.label}
            </button>
          ))}
      </div>
      <div className="flex-grow min-h-0">
        {view === 'priceAnalysis' && (
          <div className="h-full flex flex-col">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-2 mb-4 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 shadow-sm transition-all"><ArrowDownTrayIcon className="w-4 h-4 text-green-600" /> XLS</button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-gray-900 text-white hover:bg-black shadow-lg transition-all"><DocumentTextIcon className="w-4 h-4" /> PDF</button>
            </div>
            <div className="space-y-6 overflow-y-auto pr-2 custom-scrollbar">
                {storeData.map(store => (
                    <StoreRow key={store.storeName} store={store} t={t} onZoom={setZoomedImage} />
                ))}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && <div className="bg-gray-900 text-lime-400 p-6 rounded-2xl overflow-x-auto font-mono text-xs max-h-full"><pre>{JSON.stringify(images, null, 2)}</pre></div>}
      </div>
       <div className="mt-8 pt-6 border-t border-gray-100 no-print">
        <button onClick={onReset} className="w-full bg-red-600 hover:bg-red-700 text-white font-black py-4 px-8 rounded-2xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm shadow-xl shadow-red-100 hover:scale-[1.01] active:scale-95">
          <TrashIcon className="w-5 h-5" /> {t('endVisit')}
        </button>
      </div>
    </div>
  );
};

