interface GlobalAnalysisStatusProps {
  total: number;
  completed: number;
  analyzing: number;
  errors: number;
}

export const GlobalAnalysisStatus: React.FC<GlobalAnalysisStatusProps> = ({ total, completed, analyzing, errors }) => {
  const { t } = useTranslation();

  // Bar zobrazujeme, kým nie sú všetky fotky úspešne spracované alebo skončené chybou
  if (total === 0 || (completed + errors === total && analyzing === 0)) return null;

  const progress = Math.round(((completed + errors) / total) * 100);
  const isFinished = completed + errors === total;
  const isWaiting = completed === 0 && errors === 0 && analyzing === 0;

  return (
    <div className="sticky top-0 z-[100] w-full bg-white/90 backdrop-blur-md border-b border-lime-100 shadow-lg animate-fade-in-down no-print">
      <div className="max-w-7xl mx-auto px-6 py-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">

          <div className="flex items-center gap-5">
            <div className={`p-3 rounded-2xl flex-shrink-0 ${isFinished ? 'bg-green-100' : 'bg-lime-100 shadow-inner'}`}>
                {analyzing > 0 || isWaiting ? (
                    <SpinnerIcon className="w-6 h-6 text-lime-600 animate-spin" />
                ) : (
                    <CpuChipIcon className="w-6 h-6 text-lime-600" />
                )}
            </div>
            <div>
                <h4 className="text-sm font-black text-gray-900 flex items-center gap-3 uppercase tracking-tighter">
                    {isWaiting ? 'Príprava dát...' : isFinished ? 'Analýza dokončená' : 'Prebieha AI analýza...'}
                    {!isFinished && <span className="flex h-2 w-2 rounded-full bg-lime-500 animate-pulse"></span>}
                </h4>
                <div className="flex items-center gap-4 mt-1">
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                        {completed + errors} / {total} {t('images').toLowerCase()}
                    </span>
                    {analyzing > 0 && (
                         <span className="text-[10px] font-black text-lime-600 bg-lime-100 px-2 py-0.5 rounded-lg border border-lime-200 animate-pulse">
                            AKTÍVNE: {analyzing}
                         </span>
                    )}
                    {errors > 0 && (
                        <span className="flex items-center gap-1 text-[10px] font-black text-red-600 bg-red-50 px-2 py-0.5 rounded-lg border border-red-100">
                            <WarningIcon className="w-3 h-3" /> {errors} CHYBY
                        </span>
                    )}
                </div>
            </div>
          </div>

          <div className="flex-grow max-w-xl">
            <div className="flex justify-between items-center mb-2">
                <span className="text-xs font-black text-lime-700 tracking-tighter">{progress}%</span>
                {progress === 100 && <CheckCircleIcon className="w-5 h-5 text-green-600" />}
            </div>
            <div className="w-full bg-gray-100 rounded-full h-3 overflow-hidden border border-gray-200 shadow-inner">
              <div 
                className="h-full bg-lime-500 transition-all duration-1000 ease-in-out relative"
                style={{ width: `${Math.max(progress, 2)}%` }}
              >
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent animate-shimmer" style={{ backgroundSize: '200% 100%' }}></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

