import { GoogleGenAI, Type, Part } from "@google/genai";
import type { AnalysisResult, DetectedProduct, PriceInfo, StoreInfo, ObjectType, PosType } from '../types';
import { fileToBase64 } from '../utils/helpers';
import { getActivePrompt } from '../db';

const productSchema = {
  type: Type.OBJECT,
  properties: {
    products: {
      type: Type.ARRAY,
      description: 'List of identified objects (products or POS materials).',
      items: {
        type: Type.OBJECT,
        properties: {
          n: { type: Type.STRING, description: 'Product name or POS material label.' },
          t: { type: Type.STRING, enum: ['product', 'pos_material'], description: 'Type of object.' },
          pt: { type: Type.STRING, enum: ['wobbler', 'stopper', 'stand', 'pallet', 'secondary_display'], description: 'Sub-type for POS materials.' },
          g: { type: Type.BOOLEAN, description: 'Is this a "Ghost" product (image on backboard)?' },
          p: { type: Type.STRING, description: 'Price string. Format: "VALUE R; VALUE P". MANDATORY IF VISIBLE.' },
          b: { type: Type.STRING, description: "Coordinates 'y1,x1,y2,x2|y1,x1...'. Scale 0-999." },
        },
        required: ['n', 't', 'b'],
      },
    },
    info: {
      type: Type.OBJECT,
      properties: {
        chn: { type: Type.STRING, description: 'Chain name found on shelf labels or bottom watermark.' },
        adr: { type: Type.STRING, description: 'Store location/address.' },
      },
    },
  },
  required: ['products'],
};

function extractFirstJson(text: string): string {
    const markdownMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
    let cleanText = markdownMatch ? markdownMatch[1].trim() : text;
    const firstBrace = cleanText.indexOf('{');
    if (firstBrace === -1) throw new Error("No JSON object found.");
    const stack: string[] = [];
    let inString = false;
    for (let i = firstBrace; i < cleanText.length; i++) {
        const char = cleanText[i];
        if (char === '"' && cleanText[i-1] !== '\\') inString = !inString;
        if (!inString) {
            if (char === '{' || char === '[') stack.push(char);
            else if (char === '}' || char === ']') stack.pop();
        }
        if (stack.length === 0) return cleanText.substring(firstBrace, i + 1);
    }
    throw new Error("Truncated JSON.");
}

function parseMinifiedPriceString(priceString: string | undefined): PriceInfo[] {
  if (!priceString) return [];
  return priceString.split(';').map(part => {
    const trimmed = part.trim();
    const match = trimmed.match(/([\d.,]+)\s*([RP])/i);
    return match ? { value: match[1], type: match[2].toUpperCase() === 'P' ? 'PROMO' : 'REGULAR' } : null;
  }).filter((p): p is PriceInfo => p !== null);
}

function parseMinifiedResponse(minifiedResponse: any, usedModel: string): AnalysisResult {
  const products: DetectedProduct[] = [];
  if (minifiedResponse.products) {
    minifiedResponse.products.forEach((group: any) => {
      const prices = parseMinifiedPriceString(group.p);
      if (group.b) {
        group.b.split('|').forEach((boxString: string) => {
          const c = boxString.split(',').map(Number);
          if (c.length === 4) {
            products.push({
              id: `${group.n}-${Math.random().toString(36).substring(7)}`,
              name: group.n,
              brand: group.n.split(' ')[0],
              prices,
              boundingBox: { x: c[1]/1000, y: c[0]/1000, width: (c[3]-c[1])/1000, height: (c[2]-c[0])/1000 },
              confidence: group.c || 0.95,
              type: (group.t || 'product') as ObjectType,
              posType: group.pt as PosType,
              isGhost: group.g === true
            });
          }
        });
      }
    });
  }
  return { products, storeInfo: { chain: minifiedResponse.info?.chn, address: minifiedResponse.info?.adr }, modelName: usedModel };
}

export async function analyzeImageWithGemini(
  base64Image: string, 
  defaultPromptText: string, 
  defaultSystemInstruction: string,
  category: 'price' | 'shelfShare' | 'both' | 'osa' = 'both',
  modelName: string = 'gemini-2.5-flash'
): Promise<AnalysisResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const dynamicSystem = await getActivePrompt('system');
  const dynamicUser = await getActivePrompt(category);

  const systemWithContext = (dynamicSystem?.text || defaultSystemInstruction) + 
    " CRITICAL: For EVERY identified product, you MUST look for the nearest price tag. If a price tag is even partially visible, extract the numeric value and set the type (R=Regular, P=Promo). Do not skip prices for secondary images.";

  const response = await ai.models.generateContent({
    model: modelName,
    contents: { parts: [{ inlineData: { data: base64Image, mimeType: 'image/jpeg' } }, { text: dynamicUser?.text || defaultPromptText }] },
    config: {
      systemInstruction: systemWithContext,
      responseMimeType: "application/json",
      responseSchema: productSchema,
      temperature: 0.0, // Pre maximálnu presnosť OCR
    },
  });

  const result = parseMinifiedResponse(JSON.parse(extractFirstJson(response.text)), modelName);
  if (response.usageMetadata) {
      result.usageMetadata = {
          promptTokenCount: response.usageMetadata.promptTokenCount || 0,
          candidatesTokenCount: response.usageMetadata.candidatesTokenCount || 0,
          totalTokenCount: response.usageMetadata.totalTokenCount || 0,
      };
  }
  return result;
}

export async function createVisualFingerprint(productName: string, base64Images: string[]): Promise<string> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const imageParts = base64Images.map(img => ({ inlineData: { data: img, mimeType: 'image/jpeg' } }));
    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { parts: [...imageParts, { text: `Analyze "${productName}". Create a concise visual fingerprint (colors, shape, unique features) for identification.` }] },
        config: { temperature: 0.1 }
    });
    return response.text?.trim() || "";
}

