export type AnalysisType = 'price' | 'shelfShare' | 'both' | 'osa';

export interface ImageState {
  id: string;
  file: File;
  imageUrl: string;
  analysisResult: AnalysisResult | null;
  status: 'pending' | 'analyzing' | 'success' | 'error';
  error: string | null;
  uploadDate: Date;
  analysisType: AnalysisType;
  retryCount: number;
  assignedStore?: Store | null;
  assignedStoreId?: number;
  modelName?: string;
}

type ImageAction = 
  | { type: 'ADD_IMAGES'; payload: ImageState[] }
  | { type: 'SET_ANALYZING'; payload: string }
  | { type: 'SET_PENDING'; payload: string }
  | { type: 'SET_SUCCESS'; payload: { id: string; result: AnalysisResult; store?: Store; storeId?: number } }
  | { type: 'SET_ERROR'; payload: { id: string; error: string; needsAuthReset?: boolean } }
  | { type: 'UPDATE_PRICES'; payload: { imageId: string; productId: string; prices: PriceInfo[] }[] }
  | { type: 'RENAME_PRODUCT'; payload: { imageId: string; productId: string; newName: string } }
  | { type: 'CLEAR_ALL' };

function imageReducer(state: ImageState[], action: ImageAction): ImageState[] {
  switch (action.type) {
    case 'ADD_IMAGES': return [...action.payload, ...state];
    case 'SET_ANALYZING': return state.map(img => img.id === action.payload ? { ...img, status: 'analyzing' } : img);
    case 'SET_PENDING': return state.map(img => img.id === action.payload ? { ...img, status: 'pending', error: null } : img);
    case 'SET_SUCCESS': return state.map(img => img.id === action.payload.id ? { 
        ...img, status: 'success', analysisResult: Object.freeze(action.payload.result),
        assignedStore: action.payload.store || img.assignedStore, assignedStoreId: action.payload.storeId || img.assignedStoreId
    } : img);
    case 'SET_ERROR': return state.map(img => img.id === action.payload.id ? { ...img, status: 'error', error: action.payload.error } : img);
    case 'UPDATE_PRICES': {
        return state.map(img => {
            const updates = action.payload.filter(u => u.imageId === img.id);
            if (!updates.length || !img.analysisResult) return img;
            const updatedProducts = img.analysisResult.products.map(p => {
                const update = updates.find(u => u.productId === p.id);
                return update ? { ...p, prices: update.prices } : p;
            });
            return { ...img, analysisResult: { ...img.analysisResult, products: updatedProducts } };
        });
    }
    case 'RENAME_PRODUCT': return state.map(img => img.id === action.payload.imageId ? {
        ...img, 
        analysisResult: img.analysisResult ? { 
            ...img.analysisResult, 
            products: img.analysisResult.products.map(p => p.id === action.payload.productId ? { ...p, name: action.payload.newName } : p)
        } : null
    } : img);
    case 'CLEAR_ALL': return [];
    default: return state;
  }
}

export const App: React.FC = () => {
  const [images, dispatch] = useReducer(imageReducer, []);
  const [selectedImageId, setSelectedImageId] = useState<string | null>(null);
  const [selectedProductName, setSelectedProductName] = useState<string | null>(null);
  const [sidebarView, setSidebarView] = useState<'images' | 'products'>('images');
  const [productSearchTerm, setProductSearchTerm] = useState('');
  const deferredSearchTerm = useDeferredValue(productSearchTerm);
  const [highlightedProductName, setHighlightedProductName] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<ActiveView>('home');
  const [hasApiKey, setHasApiKey] = useState(false);
  const { t } = useTranslation();
  const [isAnalysisModalOpen, setIsAnalysisModalOpen] = useState(false); 
  const [pendingFiles, setPendingFiles] = useState<FileList | null>(null);
  const [isClearConfirmOpen, setIsClearConfirmOpen] = useState(false);
  const [isBrandModalOpen, setIsBrandModalOpen] = useState(false);
  const [isSearchModalOpen, setIsSearchModalOpen] = useState(false);
  const [brandsForClassification, setBrandsForClassification] = useState<string[]>([]);
  const [brandClassifications, setBrandClassifications] = useState<BrandClassifications>({ ourBrands: [], competitorBrands: [] });
  const [isMissingPriceModalOpen, setIsMissingPriceModalOpen] = useState(false);
  const [activeAnalysis, setActiveAnalysis] = useState<Analysis | null>(null);
  const [isNewAnalysisModalOpen, setIsNewAnalysisModalOpen] = useState(false); 
  const [isImageUploadOverlayOpen, setIsImageUploadOverlayOpen] = useState(false); 
  const [selectedCatalogProduct, setSelectedCatalogProduct] = useState<ProductCatalogEntry | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Kontrola súbežnosti
  const processingCountRef = useRef(0);
  const MAX_CONCURRENT = 3;

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
        window.removeEventListener('online', handleOnline);
        window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    const checkApiKey = async () => {
      if ((window as any).aistudio) { 
        const hasKey = await (window as any).aistudio.hasSelectedApiKey(); 
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectApiKey = async () => {
    if ((window as any).aistudio) { 
      await (window as any).aistudio.openSelectKey(); 
      setHasApiKey(true);
    }
  };

  const handleStartAnalysis = useCallback(async (type: AnalysisType, model: string, fileList: FileList) => {
    const filesToProcess = Array.from(fileList);
    const tempImages: ImageState[] = await Promise.all(filesToProcess.map(async (file) => {
        const storeName = extractStoreFromFilename(file.name);
        let store: Store | null = null;
        if (storeName) {
             try { store = await findOrCreateStore({ name: storeName, chain: storeName.split(',')[0].trim(), city: '', address: '', code: '' }); } catch (e) {}
        }
        return {
            id: `${file.name}-${Date.now()}-${Math.random().toString(36).substring(7)}`,
            file, imageUrl: URL.createObjectURL(file), analysisResult: null, status: 'pending', error: null,
            uploadDate: parseDateFromFileName(file.name) || new Date(file.lastModified),
            analysisType: type, retryCount: 0, assignedStore: store, assignedStoreId: store?.id, modelName: model
        };
    }));
    dispatch({ type: 'ADD_IMAGES', payload: tempImages });
  }, []);

  // FRONT OPERÁCIA: Paralelné spracovanie s limitom
  useEffect(() => {
    if (!isOnline) return;

    const processNext = async () => {
        if (processingCountRef.current >= MAX_CONCURRENT) return;
        const next = images.find(img => img.status === 'pending');
        if (!next) return;

        processingCountRef.current++;
        dispatch({ type: 'SET_ANALYZING', payload: next.id });

        try {
            const base64 = await fileToBase64(next.file);
            const catalog = await getCatalogEntries();
            const known = catalog.map(e => e.canonicalName).join(', ');
            const prompt = t(next.analysisType === 'price' ? 'geminiPromptPriceOnly' : next.analysisType === 'shelfShare' ? 'geminiPromptShelfShareOnly' : 'geminiPromptBoth').replace('{{knownProducts}}', known);

            const result = await analyzeImageWithGemini(base64, prompt, t('geminiSystemInstruction'), next.analysisType, next.modelName);

            // Inteligentná korekcia názvov
            const corrected = await Promise.all((result.products || []).map(async p => {
                const entry = await findProductByAlias(p.name);
                return { ...p, name: entry ? entry.canonicalName : p.name, isCorrected: !!entry, catalogProductId: entry?.id, id: `${next.id}-${Math.random()}` };
            }));

            // Detekcia značiek a automatická klasifikácia
            const memory = await getBrandMemory();
            const classifiedOur = new Set(memory.filter(m => m.classification === 'our').map(m => m.brand));
            const classifiedComp = new Set(memory.filter(m => m.classification === 'competitor').map(m => m.brand));

            const newlyDiscovered = new Set<string>();
            corrected.forEach(p => {
                const b = getBrandFromName(p.name);
                if (b && !classifiedOur.has(b) && !classifiedComp.has(b) && !brandClassifications.ourBrands.includes(b) && !brandClassifications.competitorBrands.includes(b)) {
                    newlyDiscovered.add(b);
                }
            });

            if (newlyDiscovered.size > 0) {
                setBrandsForClassification(prev => Array.from(new Set([...prev, ...newlyDiscovered])).sort());
                setIsBrandModalOpen(true);
            }

            dispatch({ type: 'SET_SUCCESS', payload: { id: next.id, result: { ...result, products: corrected } } });
        } catch (e: any) {
            const isAuth = e?.message?.includes('entity was not found');
            if (isAuth) setHasApiKey(false);
            dispatch({ type: 'SET_ERROR', payload: { id: next.id, error: isAuth ? t('apiKeyError') : t('failedToAnalyze') } });
        } finally {
            processingCountRef.current--;
        }
    };

    const timer = setInterval(processNext, 200);
    return () => clearInterval(timer);
  }, [images, isOnline, t, brandClassifications]);

  const productList = useMemo(() => {
    const completed = images.filter(img => img.status === 'success');
    if (!completed.length) return [];
    const map = new Map<string, { name: string; count: number; category: string }>();
    const knownNames: string[] = [];
    completed.forEach(img => {
      img.analysisResult?.products.forEach(p => {
        if (!p?.name) return;
        const matched = findBestMatch(p.name, knownNames) || p.name;
        if (!knownNames.includes(matched)) knownNames.push(matched);
        const entry = map.get(matched);
        if (entry) entry.count++;
        else map.set(matched, { name: matched, count: 1, category: getCategoryFromName(matched, t('unassignedCategory')) });
      });
    });
    const result = Array.from(map.values()).sort((a, b) => a.category.localeCompare(b.category) || b.count - a.count);
    return deferredSearchTerm ? result.filter(p => p.name.toLowerCase().includes(deferredSearchTerm.toLowerCase())) : result;
  }, [images, t, deferredSearchTerm]);

  const handleNavClick = useCallback((v: ActiveView) => {
    setActiveView(v);
    if (v !== 'home' && images.length) { setSelectedImageId(null); setSelectedProductName(null); setHighlightedProductName(null); }
  }, [images.length]);

  if (!hasApiKey) return <ApiKeySelectionScreen onSelectApiKey={handleSelectApiKey} />;

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col antialiased">
      <Header onNewAnalysis={() => activeAnalysis ? setIsClearConfirmOpen(true) : setIsNewAnalysisModalOpen(true)} onOpenSearch={() => setIsSearchModalOpen(true)} />
      <GlobalAnalysisStatus total={images.length} completed={images.filter(i => i.status === 'success').length} analyzing={images.filter(i => i.status === 'analyzing').length} errors={images.filter(i => i.status === 'error').length} />
      <div className="flex flex-1 overflow-hidden">
        <Sidebar activeView={activeView} onNavClick={handleNavClick} />
        <div className="flex-1 p-6 overflow-y-auto scroll-smooth custom-scrollbar">
          {activeView === 'home' ? <HomeScreen onStartAnalysis={() => setIsNewAnalysisModalOpen(true)} /> :
           activeView === 'analyses' ? <AnalysesPanel onNewAnalysis={() => setIsNewAnalysisModalOpen(true)} onLoadAnalysis={async (id) => {
                const a = await loadAnalysis(id);
                if (a) {
                    dispatch({ type: 'CLEAR_ALL' });
                    setActiveAnalysis(a);
                    const loaded = a.images.map(s => ({
                        ...s, file: base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified),
                        imageUrl: URL.createObjectURL(base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified)),
                        uploadDate: new Date(s.uploadDate), analysisType: (s.analysisType || 'both') as AnalysisType, retryCount: s.retryCount || 0
                    }));
                    dispatch({ type: 'ADD_IMAGES', payload: loaded });
                    setBrandClassifications(a.brandClassifications || { ourBrands: [], competitorBrands: [] });
                    setActiveView('priceMonitoring');
                }
           }} /> :
           activeView === 'stores' ? <StoresPanel /> :
           activeView === 'gallery' ? <GalleryPanel /> :
           activeView === 'posMaterial' ? <PosMaterialPanel /> :
           activeView === 'productCatalog' ? (selectedCatalogProduct ? <ProductCardPanel product={selectedCatalogProduct} onBack={() => setSelectedCatalogProduct(null)} /> : <ProductCatalogPanel onProductSelect={setSelectedCatalogProduct} />) :
           activeView === 'distribution' ? <DistributionPanel activeImages={images} /> :
           activeView === 'costs' ? <CostPanel /> :
           activeView === 'prompts' ? <PromptManagerPanel /> :
           images.length === 0 && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') ? 
           <ModuleLandingPage type={activeView} onStart={() => setIsNewAnalysisModalOpen(true)} onLoad={() => setActiveView('analyses')} /> :
           images.length === 0 ? <div className="h-full flex items-center justify-center"><ImageUploader onImageUpload={(f) => { setPendingFiles(f); setIsAnalysisModalOpen(true); }} isLoading={images.some(i => i.status === 'analyzing')} /></div> :
           <div className="w-full grid grid-cols-1 lg:grid-cols-4 gap-8 main-grid-container">
             <aside className="lg:col-span-1 bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col gap-4 self-start no-print">
               <div className="flex justify-between items-center px-1">
                 <h3 className="font-black text-gray-900 uppercase text-xs tracking-widest">{sidebarView === 'images' ? t('images') : t('products')}</h3>
                 <div className="flex gap-2 bg-gray-100 p-1 rounded-lg">
                   <button onClick={() => setSidebarView('images')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'images' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><AppIcon className="w-4 h-4"/></button>
                   <button onClick={() => setSidebarView('products')} className={`p-1.5 rounded-md transition-all ${sidebarView === 'products' ? 'bg-white text-lime-700 shadow-sm' : 'text-gray-400'}`}><CircleStackIcon className="w-4 h-4"/></button>
                 </div>
               </div>
               <div className="relative px-1">
                   <input type="text" className="w-full bg-gray-50 border-none rounded-xl text-[11px] p-2 pr-8 focus:ring-1 focus:ring-lime-500" placeholder={sidebarView === 'images' ? t('searchImages') : t('searchProduct')} value={productSearchTerm} onChange={e => setProductSearchTerm(e.target.value)} />
               </div>
               <div className="max-h-[calc(100vh-360px)] overflow-y-auto space-y-2 custom-scrollbar pr-1">
                 {sidebarView === 'images' ? 
                   images.map(img => (
                     <div key={img.id} onClick={() => { setSelectedImageId(img.id); setSelectedProductName(null); }} className={`flex gap-3 p-2 rounded-xl cursor-pointer border transition-all duration-200 ${selectedImageId === img.id ? 'bg-lime-50 border-lime-400 scale-[1.02] shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <img src={img.imageUrl} className="w-10 h-10 object-cover rounded-lg bg-gray-100" />
                       <div className="min-w-0 flex-1">
                         <p className="text-[11px] font-bold truncate text-gray-800">{img.file.name}</p>
                         <p className="text-[9px] font-black uppercase text-gray-400">{img.status === 'analyzing' ? t('analyzing') : img.uploadDate.toLocaleDateString()}</p>
                       </div>
                       {img.status === 'success' && <div className="h-1.5 w-1.5 rounded-full bg-green-500 mt-2"></div>}
                     </div>
                   )) : 
                   productList.map(p => (
                     <button key={p.name} onClick={() => { setSelectedProductName(p.name); setSelectedImageId(null); }} className={`flex justify-between w-full p-3 rounded-xl border text-left transition-all duration-200 ${selectedProductName === p.name ? 'bg-lime-50 border-lime-400 shadow-sm shadow-lime-100' : 'bg-white border-transparent hover:bg-gray-50'}`}>
                       <span className="text-[11px] font-bold truncate pr-2 text-gray-700">{p.name}</span>
                       <span className="text-[11px] font-black text-lime-600 bg-lime-100/50 px-2 py-0.5 rounded-lg">{p.count}</span>
                     </button>
                   ))
                 }
               </div>
               <button onClick={() => setIsImageUploadOverlayOpen(true)} className="w-full py-3 bg-lime-600 text-white rounded-xl text-xs font-black uppercase tracking-widest flex justify-center items-center gap-2 hover:bg-lime-700 transition-all shadow-lg shadow-lime-100"><UploadIcon className="w-4 h-4"/>{t('addMoreImages')}</button>
             </aside>
             <main className="lg:col-span-3 flex flex-col gap-6">
                {!selectedImageId && !selectedProductName && (activeView === 'priceMonitoring' || activeView === 'shelfShare' || activeView === 'promoAlert') && 
                  <BatchSummaryPanel images={images} brandClassifications={brandClassifications} onReset={() => { dispatch({type: 'CLEAR_ALL'}); setActiveAnalysis(null); setActiveView('home'); }} initialView={activeView as any} onOpenMissingPrices={() => setIsMissingPriceModalOpen(true)} />}
                {selectedImageId && images.find(i => i.id === selectedImageId) && <>
                  <ImageAnalysisDisplay imageUrl={images.find(i => i.id === selectedImageId)!.imageUrl} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} highlightedProductName={highlightedProductName} />
                  <ResultsPanel imageId={selectedImageId} analysisResult={images.find(i => i.id === selectedImageId)!.analysisResult} isLoading={images.find(i => i.id === selectedImageId)!.status === 'analyzing'} error={images.find(i => i.id === selectedImageId)!.error} onReset={() => { dispatch({type: 'CLEAR_ALL'}); setActiveAnalysis(null); setActiveView('home'); }} onProductNameUpdate={async (i, pid, o, n) => { await addOrUpdateProductCorrection(o, n); dispatch({type:'RENAME_PRODUCT', payload:{imageId:i, productId:pid, newName:n}}); }} onRetry={() => dispatch({type:'SET_PENDING', payload:selectedImageId})} />
                </>}
                {selectedProductName && <ProductSummaryPanel productName={selectedProductName} images={images} onReset={() => { dispatch({type:'CLEAR_ALL'}); setActiveAnalysis(null); setActiveView('home'); }} onImageSelect={(id, name) => { setSelectedImageId(id); setSelectedProductName(null); setHighlightedProductName(name); }} />}
             </main>
           </div>
          }
        </div>
      </div>
      <div className="modal-root">
        <NewAnalysisModal isOpen={isNewAnalysisModalOpen} onClose={() => setIsNewAnalysisModalOpen(false)} onConfirm={async (n, t, m, f) => { const a = { id: `analysis-${Date.now()}`, name: n, createdAt: new Date().toISOString(), images: [], store: null }; await db.analyses.add(a); setActiveAnalysis(a); setActiveView('priceMonitoring'); handleStartAnalysis(t, m, f); setIsNewAnalysisModalOpen(false); }} initialFiles={pendingFiles} />
        <AnalysisTypeModal isOpen={isAnalysisModalOpen} onClose={() => setIsAnalysisModalOpen(false)} onSelect={async type => { if (pendingFiles) handleStartAnalysis(type, 'gemini-2.5-flash', pendingFiles); setIsAnalysisModalOpen(false); }} />
        <ClearConfirmModal isOpen={isClearConfirmOpen} onClose={() => setIsClearConfirmOpen(false)} onConfirmDelete={() => { dispatch({type:'CLEAR_ALL'}); setActiveAnalysis(null); setActiveView('home'); }} onSaveToArchive={async () => { if(activeAnalysis) { const serializable = await Promise.all(images.map(async i => ({ id: i.id, file: { name: i.file.name, type: i.file.type, lastModified: i.file.lastModified, data: await fileToBase64(i.file) }, imageUrl: '', analysisResult: i.analysisResult, status: i.status, error: i.error, uploadDate: i.uploadDate.toISOString(), analysisType: i.analysisType, retryCount: i.retryCount, assignedStore: i.assignedStore, assignedStoreId: i.assignedStoreId }))); await saveAnalysis({ ...activeAnalysis, images: serializable, brandClassifications }); } dispatch({type:'CLEAR_ALL'}); setActiveAnalysis(null); setActiveView('home'); }} />
        <BrandDefinitionModal isOpen={isBrandModalOpen} onClose={() => setIsBrandModalOpen(false)} onConfirm={c => { setBrandClassifications(c); setIsBrandModalOpen(false); }} allBrands={brandsForClassification} />
        <SearchModal isOpen={isSearchModalOpen} onClose={() => setIsSearchModalOpen(false)} onLoadAnalysis={async (id) => { const a = await loadAnalysis(id); if (a) { setActiveAnalysis(a); const loaded = a.images.map(s => ({ ...s, file: base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified), imageUrl: URL.createObjectURL(base64ToFile(s.file.data, s.file.name, s.file.type, s.file.lastModified)), uploadDate: new Date(s.uploadDate), analysisType: (s.analysisType || 'both') as AnalysisType, retryCount: s.retryCount || 0 })); dispatch({ type: 'CLEAR_ALL' }); dispatch({ type: 'ADD_IMAGES', payload: loaded }); setBrandClassifications(a.brandClassifications || { ourBrands: [], competitorBrands: [] }); setActiveView('priceMonitoring'); setIsSearchModalOpen(false); } }} />
        <MissingPriceModal isOpen={isMissingPriceModalOpen} onClose={() => setIsMissingPriceModalOpen(false)} items={images.flatMap(img => (img.analysisResult?.products || []).filter(p => !p.prices?.length).map(p => ({ imageId: img.id, productId: p.id, name: p.name, imageUrl: img.imageUrl })))} onSave={updates => dispatch({type:'UPDATE_PRICES', payload: updates})} />
        {isImageUploadOverlayOpen && <div className="fixed inset-0 bg-gray-800/75 flex items-center justify-center z-50 p-4 animate-fade-in"><div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl overflow-hidden"><div className="p-6 border-b flex justify-between items-center bg-gray-50"><h2 className="text-sm font-black uppercase tracking-widest flex items-center gap-2 text-gray-700"><UploadIcon className="w-5 h-5 text-lime-600" />{t('uploadMoreImagesTitle')}</h2><button onClick={() => setIsImageUploadOverlayOpen(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-400"><CloseIcon className="w-5 h-5"/></button></div><div className="p-10"><ImageUploader onImageUpload={(f) => { setPendingFiles(f); setIsAnalysisModalOpen(true); setIsImageUploadOverlayOpen(false); }} isLoading={images.some(i => i.status === 'analyzing')} /></div></div></div>}
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect, useRef, useCallback } from 'react';
import type { DetectedProduct, PriceInfo, BrandClassifications, StoreInfo } from '../types';
import type { ImageState } from '../App';
import { getCategoryFromName, findBestMatch, removeDateFromStoreName } from '../utils/helpers';
import { CloseIcon, ChartBarIcon, ChartPieIcon, ArrowDownTrayIcon, TrashIcon, DocumentTextIcon, ShieldExclamationIcon, MagicWandIcon, CpuChipIcon, TagIcon, BoxIcon, SpinnerIcon } from './Icons';
import { FilterControls, Filters } from './FilterControls';
import { ShelfSharePanel } from './ShelfSharePanel';
import { PromoAlertPanel } from './PromoAlertPanel';
import { useTranslation } from '../i18n';
import { exportPriceMonitoringToXLS, exportToPDF } from '../utils/export';

const parsePrice = (priceValue: string): number | null => {
  const cleaned = priceValue.replace(',', '.').replace(/[^\d.]/g, '');
  const value = parseFloat(cleaned);
  return isNaN(value) ? null : value;
};

interface ProductInStore {
    name: string;
    isCorrected?: boolean;
    category: string;
    count: number;
    priceHistory: { price: PriceInfo; date: Date; imageUrl: string }[];
    avgConfidence: number;
    imageUrl?: string;
    catalogProductId?: number;
}

export interface StoreCentricSummary {
    storeName: string;
    storeId?: number;
    products: ProductInStore[];
}

const StoreRow: React.FC<{ store: StoreCentricSummary, onZoom: (url: string) => void, t: any }> = ({ store, onZoom, t }) => {
    const [isVisible, setIsVisible] = useState(false);
    const rowRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting) setIsVisible(true);
        }, { threshold: 0.01, rootMargin: '400px' });
        if (rowRef.current) observer.observe(rowRef.current);
        return () => observer.disconnect();
    }, []);

    return (
        <div ref={rowRef} className={`bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden min-h-[100px] transition-opacity duration-500 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
            {isVisible ? (
                <>
                    <div className="bg-gray-50/80 px-5 py-4 border-b border-gray-100 flex items-center justify-between">
                        <h3 className="font-black text-gray-900 uppercase tracking-tight">{store.storeName}</h3>
                        <span className="bg-white px-2 py-1 rounded-lg border border-gray-100 text-[10px] font-black text-gray-400 uppercase">{store.products.length} SKU</span>
                    </div>
                    <div className="divide-y divide-gray-50">
                        {store.products.map(product => {
                            // Extrakcia unikátnych cien pre zobrazenie v riadku (najnovšie majú prednosť)
                            const uniquePrices = new Map<string, PriceInfo>();
                            [...product.priceHistory].reverse().forEach(h => {
                                if (!uniquePrices.has(h.price.type)) uniquePrices.set(h.price.type, h.price);
                            });

                            const promo = uniquePrices.get('PROMO')?.value;
                            const regular = uniquePrices.get('REGULAR')?.value;

                            return (
                                <div key={product.name} className="flex items-center gap-4 p-4 hover:bg-lime-50/30 transition-colors">
                                    <div className="flex-grow min-w-0">
                                        <p className="text-[10px] text-lime-700 font-black uppercase tracking-tighter mb-0.5">{product.category}</p>
                                        <div className="flex items-center gap-2">
                                            <p className="font-bold text-sm text-gray-800 truncate">{product.name}</p>
                                            {product.isCorrected && <MagicWandIcon className="w-3.5 h-3.5 text-purple-400" />}
                                        </div>
                                    </div>
                                    <div className="flex gap-2 flex-shrink-0 items-center">
                                        {regular && <span className={`px-2 py-1 rounded-lg text-xs font-black ${promo ? 'line-through text-gray-300' : 'bg-gray-100 text-gray-700'}`}>{regular}</span>}
                                        {promo && <span className="px-2 py-1 rounded-lg bg-red-100 text-red-600 text-xs font-black shadow-sm ring-1 ring-red-200">{promo}</span>}
                                    </div>
                                    <div className="w-12 h-12 rounded-xl border border-gray-100 overflow-hidden flex-shrink-0 cursor-zoom-in group relative" onClick={() => product.imageUrl && onZoom(product.imageUrl)}>
                                        {product.imageUrl && <img src={product.imageUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" loading="lazy" />}
                                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center"><BoxIcon className="w-4 h-4 text-white opacity-0 group-hover:opacity-100" /></div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </>
            ) : (
                <div className="p-10 flex justify-center"><SpinnerIcon className="w-6 h-6 text-gray-100 animate-spin" /></div>
            )}
        </div>
    );
};

interface BatchSummaryPanelProps {
    images: ImageState[];
    brandClassifications: BrandClassifications;
    onReset: () => void;
    initialView: 'priceMonitoring' | 'shelfShare' | 'promoAlert' | 'home' | 'productCatalog' | 'analyses' | 'stores' | 'costs';
    onOpenMissingPrices: () => void;
}

export const BatchSummaryPanel: React.FC<BatchSummaryPanelProps> = ({ images, brandClassifications, onReset, initialView, onOpenMissingPrices }) => {
  const [zoomedImage, setZoomedImage] = useState<string | null>(null);
  const [view, setView] = useState<'priceAnalysis' | 'shelfShare' | 'promoAlert' | 'rawData'>('priceAnalysis');
  const [filters, setFilters] = useState<Filters>({ searchTerm: '', minPrice: '', maxPrice: '', confidence: 0, category: '', chain: '' });
  const { t } = useTranslation();
  const unassignedCategory = t('unassignedCategory');
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (initialView === 'priceMonitoring') setView('priceAnalysis');
    else if (initialView === 'shelfShare') setView('shelfShare');
    else if (initialView === 'promoAlert') setView('promoAlert');
    else if (initialView === 'costs') setView('rawData'); 
  }, [initialView]);

  const rawGroupedData = useMemo(() => {
    const unknownStore = t('unknownStore');
    const storeMap = new Map<string | number, { name: string, items: any[] }>();
    const successful = images.filter(img => img.status === 'success');

    successful.forEach(img => {
        if (!img.analysisResult) return;
        const storeKey = img.assignedStoreId || (img.analysisResult.storeInfo ? removeDateFromStoreName(img.analysisResult.storeInfo.chain) + (img.analysisResult.storeInfo.address || '') : unknownStore);
        if (!storeMap.has(storeKey)) {
            let displayName = unknownStore;
            if (img.assignedStore) displayName = [img.assignedStore.name, img.assignedStore.city].filter(Boolean).join(', ');
            else if (img.analysisResult.storeInfo) displayName = [img.analysisResult.storeInfo.chain, img.analysisResult.storeInfo.address].filter(Boolean).join(', ');
            storeMap.set(storeKey, { name: displayName, items: [] });
        }
        img.analysisResult.products.forEach(p => {
            if (p?.name) storeMap.get(storeKey)!.items.push({ ...p, uploadDate: img.uploadDate, imageUrl: img.imageUrl });
        });
    });

    return Array.from(storeMap.entries()).map(([key, data]): StoreCentricSummary => {
        const productGrouping = new Map<string, any[]>();
        const nameToKey = new Map<string, string>();

        data.items.forEach(p => {
            let groupKey = p.catalogProductId ? `ID_${p.catalogProductId}` : null;
            if (!groupKey) {
                const normName = p.name.trim();
                // Pokročilý fuzzy match pre zhlukovanie v rámci predajne
                const existingKeys = Array.from(productGrouping.keys()).filter(k => !k.startsWith('ID_'));
                const match = findBestMatch(normName, existingKeys);
                groupKey = match || normName;
            }
            if (!productGrouping.has(groupKey)) productGrouping.set(groupKey, []);
            productGrouping.get(groupKey)!.push(p);
        });

        return {
            storeName: data.name,
            storeId: typeof key === 'number' ? key : undefined,
            products: Array.from(productGrouping.values()).map(occ => ({
                name: occ[0].name,
                isCorrected: occ.some(o => o.isCorrected),
                category: getCategoryFromName(occ[0].name, unassignedCategory),
                count: occ.length,
                avgConfidence: occ.reduce((a, b) => a + b.confidence, 0) / occ.length,
                imageUrl: occ[occ.length - 1].imageUrl,
                priceHistory: occ.flatMap(o => (o.prices || []).map(pr => ({ price: pr, date: o.uploadDate, imageUrl: o.imageUrl }))).sort((a, b) => a.date.getTime() - b.date.getTime())
            }))
        };
    });
  }, [images, t, unassignedCategory]);

  const { storeData, allCategories, allChains } = useMemo(() => {
    const filtered = rawGroupedData.map(store => {
        if (filters.chain && store.storeName !== filters.chain) return null;
        const filteredProducts = store.products.filter(p => {
            if (filters.searchTerm && !p.name.toLowerCase().includes(filters.searchTerm.toLowerCase())) return false;
            if (filters.category && p.category !== filters.category) return false;
            if (p.avgConfidence * 100 < filters.confidence) return false;
            return true;
        });
        return filteredProducts.length > 0 ? { ...store, products: filteredProducts } : null;
    }).filter(Boolean) as StoreCentricSummary[];
    return {
      storeData: filtered,
      allCategories: Array.from(new Set(rawGroupedData.flatMap(s => s.products.map(p => p.category)))).sort(),
      allChains: Array.from(new Set(rawGroupedData.map(s => s.storeName))).sort()
    };
  }, [rawGroupedData, filters]);

  return (
    <div ref={panelRef} className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 h-full flex flex-col printable-content animate-fade-in">
      {zoomedImage && (
        <div className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center p-4 cursor-zoom-out" onClick={() => setZoomedImage(null)}>
            <img src={zoomedImage} className="max-w-[90vw] max-h-[90vh] object-contain rounded-lg shadow-2xl" alt="Zoom" />
            <button className="absolute top-6 right-6 text-white bg-black/50 p-3 rounded-full hover:bg-black transition-colors"><CloseIcon className="w-6 h-6" /></button>
        </div>
      )}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-900">{t('batchSummary')}</h2>
        <div className="flex gap-4">
            <div className="text-center"><p className="text-xl font-black text-lime-600">{images.length}</p><p className="text-[10px] text-gray-400 uppercase font-black">{t('imagesCount')}</p></div>
            <div className="text-center"><p className="text-xl font-black text-purple-600">{rawGroupedData.reduce((acc, s) => acc + s.products.length, 0)}</p><p className="text-[10px] text-gray-400 uppercase font-black">{t('uniqueProducts')}</p></div>
        </div>
      </div>
      <div className="flex border-b border-gray-200 mb-6 no-print overflow-x-auto scrollbar-hide">
          {[
              { id: 'priceAnalysis', label: t('priceAnalysis'), icon: ChartBarIcon },
              { id: 'shelfShare', label: t('shelfShare'), icon: ChartPieIcon },
              { id: 'promoAlert', label: t('promoAlert'), icon: ShieldExclamationIcon },
              { id: 'rawData', label: t('rawData'), icon: CpuChipIcon }
          ].map(tab => (
            <button key={tab.id} onClick={() => setView(tab.id as any)} className={`-mb-px px-6 py-3 text-sm font-bold transition-all flex items-center gap-2 border-b-2 whitespace-nowrap ${view === tab.id ? 'border-lime-500 text-lime-600 bg-lime-50/30' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
                <tab.icon className="w-4 h-4" /> {tab.label}
            </button>
          ))}
      </div>
      <div className="flex-grow min-h-0">
        {view === 'priceAnalysis' && (
          <div className="h-full flex flex-col">
            <FilterControls filters={filters} onFilterChange={setFilters} searchPlaceholder={t('searchProduct')} categories={allCategories} chains={allChains} />
            <div className="flex justify-end gap-2 mb-4 no-print">
                <button onClick={() => exportPriceMonitoringToXLS(storeData, t)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-white border border-gray-200 text-gray-700 hover:bg-gray-50 shadow-sm transition-all"><ArrowDownTrayIcon className="w-4 h-4 text-green-600" /> XLS</button>
                <button onClick={() => exportToPDF(panelRef.current)} className="flex items-center gap-2 px-4 py-2 text-xs font-black uppercase rounded-xl bg-gray-900 text-white hover:bg-black shadow-lg transition-all"><DocumentTextIcon className="w-4 h-4" /> PDF</button>
            </div>
            <div className="space-y-6 overflow-y-auto pr-2 custom-scrollbar">
                {storeData.map(store => (
                    <StoreRow key={store.storeName} store={store} t={t} onZoom={setZoomedImage} />
                ))}
            </div>
          </div>
        )}
        {view === 'shelfShare' && <ShelfSharePanel images={images} />}
        {view === 'promoAlert' && <PromoAlertPanel images={images} brandClassifications={brandClassifications} />}
        {view === 'rawData' && <div className="bg-gray-900 text-lime-400 p-6 rounded-2xl overflow-x-auto font-mono text-xs max-h-full"><pre>{JSON.stringify(images, null, 2)}</pre></div>}
      </div>
       <div className="mt-8 pt-6 border-t border-gray-100 no-print">
        <button onClick={onReset} className="w-full bg-red-600 hover:bg-red-700 text-white font-black py-4 px-8 rounded-2xl transition-all flex items-center justify-center gap-3 uppercase tracking-widest text-sm shadow-xl shadow-red-100 hover:scale-[1.01] active:scale-95">
          <TrashIcon className="w-5 h-5" /> {t('endVisit')}
        </button>
      </div>
    </div>
  );
};

