                        <BoxIcon className="w-6 h-6 text-purple-600" />
                    </div>
                    <p className="text-2xl font-black text-gray-900">{totals.products.toLocaleString()}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">{t('products')}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <div className="bg-lime-50 w-12 h-12 rounded-2xl flex items-center justify-center mx-auto mb-3">
                        <CircleStackIcon className="w-6 h-6 text-lime-600" />
                    </div>
                    <p className="text-xl font-black text-gray-900">{formatTokens(totals.input)}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Vstupy (In)</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <div className="bg-fuchsia-50 w-12 h-12 rounded-2xl flex items-center justify-center mx-auto mb-3">
                        <CircleStackIcon className="w-6 h-6 text-fuchsia-600" />
                    </div>
                    <p className="text-xl font-black text-gray-900">{formatTokens(totals.output)}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Výstupy (Out)</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border-2 border-lime-500 text-center bg-lime-50/30">
                    <div className="bg-lime-100 w-12 h-12 rounded-2xl flex items-center justify-center mx-auto mb-3">
                        <TagIcon className="w-6 h-6 text-lime-600" />
                    </div>
                    <p className="text-2xl font-black text-lime-600">${totals.cost.toFixed(4)}</p>
                    <p className="text-[10px] text-lime-700 uppercase font-black tracking-widest">{t('grandTotal')}</p>
                </div>
            </div>

            {/* History Table */}
            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="p-6 border-b border-gray-50 bg-gray-50/50 flex justify-between items-center">
                    <h3 className="font-black text-gray-700 uppercase tracking-widest text-sm">Detailné náklady podľa analýz</h3>
