export const CostPanel: React.FC = () => {
    const { t } = useTranslation();
    const [inputRate, setInputRate] = useState(0.15); 
    const [outputRate, setOutputRate] = useState(0.60); 
    const [analyses, setAnalyses] = useState<Analysis[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isUpdating, setIsUpdating] = useState(false);

    const loadData = async () => {
        setIsLoading(true);
        const savedInput = await getSetting('inputTokenRate', 0.15);
        const savedOutput = await getSetting('outputTokenRate', 0.60);
        setInputRate(savedInput);
        setOutputRate(savedOutput);

        const allAnalyses = await getAnalyses();
        setAnalyses(allAnalyses);
        setIsLoading(false);
    };

    useEffect(() => {
        loadData();
    }, []);

    const handleSaveAndRecalculate = async () => {
        setIsUpdating(true);
        await setSetting('inputTokenRate', inputRate);
        await setSetting('outputTokenRate', outputRate);
        await recalculateAllCosts(inputRate, outputRate);
        const updatedAnalyses = await getAnalyses();
        setAnalyses(updatedAnalyses);
        setIsUpdating(false);
    };

    const handleResetToStandard = async () => {
        setIsUpdating(true);
        await setSetting('inputTokenRate', undefined);
        await setSetting('outputTokenRate', undefined);
        setInputRate(0.15);
        setOutputRate(0.60);
        await recalculateAllCosts(); 
        const updatedAnalyses = await getAnalyses();
        setAnalyses(updatedAnalyses);
        setIsUpdating(false);
    };

    const formatTokens = (num: number) => {
        if (num >= 1000) return (num / 1000).toFixed(1) + 'k';
        return num.toString();
    };

    const totals = React.useMemo(() => {
        return analyses.reduce((acc, a) => {
            if (a.costInfo) {
                acc.input += a.costInfo.inputTokens || 0;
                acc.output += a.costInfo.outputTokens || 0;
                acc.cost += a.costInfo.cost || 0;
            }
            acc.images += a.images?.length || 0;
            acc.products += a.images?.reduce((sum, img) => sum + (img.analysisResult?.products?.length || 0), 0) || 0;
            return acc;
        }, { input: 0, output: 0, cost: 0, images: 0, products: 0 });
    }, [analyses]);

    if (isLoading) {
        return (
            <div className="flex justify-center items-center h-full">
                <SpinnerIcon className="w-12 h-12 text-lime-500 animate-spin" />
            </div>
        );
    }

    return (
        <div className="space-y-6 max-w-7xl mx-auto pb-20 animate-fade-in">
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
                <h2 className="text-xl font-black text-gray-900 flex items-center gap-3 mb-6">
                    <div className="p-2 bg-lime-100 rounded-xl">
                        <CalculatorIcon className="w-6 h-6 text-lime-600" />
                    </div>
                    {t('analysisCosts')}
                </h2>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{t('inputTokenRate')} ($ / 1M)</label>
                        <input 
                            type="number" 
                            className="block w-full rounded-xl border-gray-200 bg-gray-50 text-gray-900 shadow-sm focus:border-lime-500 focus:ring-lime-500 sm:text-sm p-3 font-bold"
                            value={inputRate}
                            onChange={e => setInputRate(parseFloat(e.target.value))}
                        />
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">{t('outputTokenRate')} ($ / 1M)</label>
                        <input 
                            type="number" 
                            className="block w-full rounded-xl border-gray-200 bg-gray-50 text-gray-900 shadow-sm focus:border-lime-500 focus:ring-lime-500 sm:text-sm p-3 font-bold"
                            value={outputRate}
                            onChange={e => setOutputRate(parseFloat(e.target.value))}
                        />
                    </div>
                    <button 
                        onClick={handleSaveAndRecalculate}
                        disabled={isUpdating}
                        className="flex items-center justify-center gap-3 px-6 py-3 bg-lime-600 text-white rounded-xl hover:bg-lime-700 font-bold transition-all shadow-lg shadow-lime-100 active:scale-95 disabled:opacity-50"
                    >
                        {isUpdating ? <SpinnerIcon className="w-5 h-5" /> : <SaveIcon className="w-5 h-5" />}
                        {t('saveAndRecalculate')}
                    </button>
                    <button 
                        onClick={handleResetToStandard}
                        disabled={isUpdating}
                        className="flex items-center justify-center gap-3 px-6 py-3 bg-gray-100 text-gray-600 rounded-xl hover:bg-gray-200 font-bold transition-all active:scale-95 disabled:opacity-50"
                    >
                        <ArrowPathIcon className="w-5 h-5" />
                        {t('reset')}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <p className="text-2xl font-black text-gray-900">{totals.images}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">{t('images')}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <p className="text-2xl font-black text-gray-900">{totals.products}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">{t('products')}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <p className="text-xl font-black text-lime-600">{formatTokens(totals.input)}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">In (Tokens)</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 text-center">
                    <p className="text-xl font-black text-fuchsia-600">{formatTokens(totals.output)}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-black tracking-widest">Out (Tokens)</p>
                </div>
                <div className="bg-white p-6 rounded-3xl shadow-sm border-2 border-lime-500 text-center bg-lime-50/30">
                    <p className="text-2xl font-black text-lime-600">${totals.cost.toFixed(4)}</p>
                    <p className="text-[10px] text-lime-700 uppercase font-black tracking-widest">{t('grandTotal')}</p>
                </div>
            </div>

            <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-100">
                        <thead className="bg-gray-50/30">
                            <tr>
                                <th className="px-6 py-4 text-left text-[10px] font-black text-gray-400 uppercase tracking-widest">{t('date')}</th>
                                <th className="px-6 py-4 text-left text-[10px] font-black text-gray-400 uppercase tracking-widest">{t('analysisName')}</th>
                                <th className="px-6 py-4 text-center text-[10px] font-black text-gray-400 uppercase tracking-widest">In (Tokens)</th>
                                <th className="px-6 py-4 text-center text-[10px] font-black text-gray-400 uppercase tracking-widest">Out (Tokens)</th>
                                <th className="px-6 py-4 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">{t('totalCost')}</th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-100">
                            {analyses.map(analysis => (
                                <tr key={analysis.id} className="hover:bg-gray-50 transition-colors">
                                    <td className="px-6 py-4 whitespace-nowrap text-xs text-gray-500 font-medium">
                                        {new Date(analysis.createdAt).toLocaleDateString()}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-gray-800">
                                        {analysis.name}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-center">
                                        <span className="text-xs font-bold text-lime-600 bg-lime-50 px-2 py-1 rounded-lg">
                                            {formatTokens(analysis.costInfo?.inputTokens || 0)}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-center">
                                        <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">
                                            {formatTokens(analysis.costInfo?.outputTokens || 0)}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-black text-lime-600">
                                        ${analysis.costInfo?.cost?.toFixed(4) || '0.0000'}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

